INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('240b153c-4327-58ae-bf77-6e402cbe9dc6', 'The human heart is a four-chambered organ. Which two chambers pump blood to the lungs and the rest of the body respectively?', NULL, 'The RIGHT VENTRICLE pumps deoxygenated blood to the lungs via the pulmonary artery (pulmonary circulation). The LEFT VENTRICLE pumps oxygenated blood to the body via the aorta (systemic circulation). Atria receive blood — left atrium from lungs (pulmonary veins), right atrium from body (vena cavae) — but atria don''t pump to the aorta or pulmonary artery; that''s the ventricles'' job.', 'EASY', 'Biology', 'Human Circulatory System & Blood', 'BIO_CIRCULATION', '[{"option_text": "Left atrium (to lungs) and right ventricle (to body)", "is_correct": false}, {"option_text": "Right ventricle (to lungs) and left ventricle (to body)", "is_correct": true}, {"option_text": "Right atrium (to lungs) and left atrium (to body)", "is_correct": false}, {"option_text": "Both ventricles pump to lungs; atria pump to body", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d4d06449-8f74-5938-bbe8-be167c093737', 'Which blood group is called the ''universal donor''?', NULL, 'O negative (O−) blood has NO A, B, or Rh antigens — so it can be transfused to any recipient without triggering an immune reaction. It is thus the UNIVERSAL DONOR. AB+ is the UNIVERSAL RECIPIENT (has all antigens, no anti-A/anti-B antibodies). O+ can donate to all Rh+ recipients but not Rh−, making it a partial donor. In true emergencies, O− is preferred when the recipient''s blood type is unknown.', 'EASY', 'Biology', 'Human Circulatory System & Blood', 'BIO_CIRCULATION', '[{"option_text": "A+", "is_correct": false}, {"option_text": "B−", "is_correct": false}, {"option_text": "AB+", "is_correct": false}, {"option_text": "O−", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b57bd1a2-ed54-588f-8008-96b9a6dab40c', 'Which of the following is NOT a component of blood plasma?', NULL, 'Blood plasma is the LIQUID portion of blood, containing water (~90%), proteins (albumin, globulin, fibrinogen), electrolytes, hormones, nutrients, and waste products. Erythrocytes (RBCs), leukocytes (WBCs), and thrombocytes (platelets) are the CELLULAR components — they are SUSPENDED in plasma but not part of it. Plasma constitutes ~55% of blood volume; the cells are the other ~45%.', 'MEDIUM', 'Biology', 'Human Circulatory System & Blood', 'BIO_CIRCULATION', '[{"option_text": "Water (~90%)", "is_correct": false}, {"option_text": "Proteins (albumin, globulin, fibrinogen)", "is_correct": false}, {"option_text": "Erythrocytes (RBCs)", "is_correct": true}, {"option_text": "Electrolytes (Na⁺, K⁺, Cl⁻)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c1e31c21-f69b-5139-9a12-23fd28b42015', 'What is the normal range of a healthy adult''s resting heart rate?', NULL, 'The normal RESTING heart rate for a healthy adult is 60–100 BPM (beats per minute). Below 60 = bradycardia (sometimes normal in athletes). Above 100 = tachycardia. Newborns have much higher rates (120–160 BPM); children''s rates decrease with age. Elite endurance athletes can have resting rates as low as 40 BPM without being pathological.', 'EASY', 'Biology', 'Human Circulatory System & Blood', 'BIO_CIRCULATION', '[{"option_text": "40–60 beats per minute", "is_correct": false}, {"option_text": "60–100 beats per minute", "is_correct": true}, {"option_text": "80–120 beats per minute", "is_correct": false}, {"option_text": "100–140 beats per minute", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('18e78adf-47a4-5e76-9b27-9bee9790600f', 'Which of the following carries oxygen in the red blood cells?', NULL, 'HEMOGLOBIN is the iron-containing protein in RBCs that binds oxygen in the lungs and releases it in tissues. Each Hb molecule has 4 subunits (2α + 2β chains), each with a haem group containing Fe²⁺. Myoglobin is the oxygen-storage protein in MUSCLE tissue (not RBCs). Cytochrome is a mitochondrial electron-transport protein. Chlorophyll is the PLANT photosynthetic pigment (Mg²⁺-based, not Fe-based).', 'EASY', 'Biology', 'Human Circulatory System & Blood', 'BIO_CIRCULATION', '[{"option_text": "Myoglobin", "is_correct": false}, {"option_text": "Hemoglobin", "is_correct": true}, {"option_text": "Cytochrome", "is_correct": false}, {"option_text": "Chlorophyll", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7f984db4-6b4d-5439-a63c-62d0d64066ec', 'The ''pacemaker'' of the heart is:', NULL, 'The SA (sinoatrial) node, located in the RIGHT ATRIUM, initiates each heartbeat by generating electrical impulses at ~60–100 per minute. It''s called the natural pacemaker. The AV node receives the SA impulse, delays it slightly (to allow atrial contraction), and then passes it to the Bundle of His, which divides into Purkinje fibres that trigger ventricular contraction. Artificial cardiac pacemakers REPLACE the SA node when it fails.', 'MEDIUM', 'Biology', 'Human Circulatory System & Blood', 'BIO_CIRCULATION', '[{"option_text": "AV node (atrioventricular node)", "is_correct": false}, {"option_text": "SA node (sinoatrial node)", "is_correct": true}, {"option_text": "Purkinje fibres", "is_correct": false}, {"option_text": "Bundle of His", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2ed8223b-6f14-50bd-be80-4b912b2edf78', 'Which of the following diseases is caused by an abnormality of hemoglobin?', NULL, 'Sickle-cell anaemia is a genetic disorder caused by a single-point mutation in the HBB gene (Glu → Val at position 6 of β-chain), producing abnormal HbS. Under low oxygen, HbS polymerises, distorting RBCs into sickle shapes — blocking capillaries and causing crises. Diabetes = insulin/pancreas issue. Scurvy = Vitamin C deficiency. Rickets = Vitamin D deficiency. Thalassemia is another Hb disorder (reduced α/β-chain synthesis).', 'MEDIUM', 'Biology', 'Human Circulatory System & Blood', 'BIO_CIRCULATION', '[{"option_text": "Diabetes mellitus", "is_correct": false}, {"option_text": "Sickle-cell anaemia", "is_correct": true}, {"option_text": "Scurvy", "is_correct": false}, {"option_text": "Rickets", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('022d4943-cf20-57de-b61a-4bfbc93893bc', 'William Harvey, in 1628, published findings that established which of the following?', NULL, 'William Harvey''s 1628 book ''De Motu Cordis'' (On the Motion of the Heart) established the THEORY OF CIRCULATION — that blood circulates in a closed loop pumped by the heart, rather than being continuously produced by the liver (as Galen had taught for 1400 years). ABO blood groups were discovered by Karl Landsteiner (1901). Hemoglobin''s role in O2 transport was identified by Felix Hoppe-Seyler (1864). Platelets in clotting were characterized in the 19th–20th c.', 'MEDIUM', 'Biology', 'Human Circulatory System & Blood', 'BIO_CIRCULATION', '[{"option_text": "Humans have 4 blood groups (A, B, AB, O)", "is_correct": false}, {"option_text": "Blood circulates in a closed loop through the body, pumped by the heart", "is_correct": true}, {"option_text": "Red blood cells carry oxygen via hemoglobin", "is_correct": false}, {"option_text": "Blood clotting requires platelets", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('92b9ae44-4d69-5efb-a1bc-c3b2bc801748', 'Which of the following correctly describes the function of valves in the human heart?', NULL, 'The heart has four valves that prevent backflow: TRICUSPID (between right atrium & right ventricle), PULMONARY (right ventricle → pulmonary artery), MITRAL/BICUSPID (left atrium & left ventricle), AORTIC (left ventricle → aorta). The ''lub-dub'' heart sound is produced by valve closure (lub = AV valves closing, dub = semilunar valves closing). Faulty valves cause murmurs or regurgitation.', 'MEDIUM', 'Biology', 'Human Circulatory System & Blood', 'BIO_CIRCULATION', '[{"option_text": "Valves separate arteries and veins", "is_correct": false}, {"option_text": "Valves prevent backflow of blood between heart chambers and into the ventricles from the pulmonary artery/aorta", "is_correct": true}, {"option_text": "Valves manufacture blood cells", "is_correct": false}, {"option_text": "Valves regulate body temperature", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5e5bfe3c-f6ba-5d6c-935e-7cb0b24f6d77', 'What is the average lifespan of a human red blood cell?', NULL, 'Mature erythrocytes (RBCs) circulate for approximately 120 days (about 4 months) before being broken down by macrophages in the spleen and liver. During this time they travel ~400 km in the bloodstream. New RBCs are produced in the RED BONE MARROW at ~2 million per second. Platelets live ~7–10 days (distractor A); WBC lifespan varies from hours (neutrophils) to years (memory lymphocytes).', 'MEDIUM', 'Biology', 'Human Circulatory System & Blood', 'BIO_CIRCULATION', '[{"option_text": "7 days", "is_correct": false}, {"option_text": "30 days", "is_correct": false}, {"option_text": "120 days", "is_correct": true}, {"option_text": "1 year", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('253fe440-d11d-5801-b1d9-84ab75778b6f', 'Which of the following is NOT a function of blood?', NULL, 'Blood transports (O₂, CO₂, nutrients, hormones, waste), regulates (pH, temperature, fluid balance), and protects (immune response, clotting). Protein DIGESTION happens in the STOMACH (HCl + pepsin) and small intestine (trypsin, chymotrypsin, peptidases) — secreted by pancreas and gastric cells. Absorbed amino acids then enter blood via portal circulation, but the digestion itself is NOT a blood function.', 'MEDIUM', 'Biology', 'Human Circulatory System & Blood', 'BIO_CIRCULATION', '[{"option_text": "Transport of oxygen, nutrients, and hormones", "is_correct": false}, {"option_text": "Maintenance of body temperature via heat distribution", "is_correct": false}, {"option_text": "Immune defence via white blood cells and antibodies", "is_correct": false}, {"option_text": "Digestion of proteins into amino acids", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ec488db1-2cd1-5a26-bbd1-897506a6f895', 'Tuberculosis (TB) is caused by which pathogen?', NULL, 'TB is caused by Mycobacterium tuberculosis (discovered by Robert Koch in 1882, ''Koch''s Bacillus''). Primarily affects the lungs (pulmonary TB) but can affect any organ (extra-pulmonary TB). Spread via airborne droplets. VACCINE: BCG (Bacillus Calmette-Guérin), given at birth in India. World TB Day: 24 March. Current treatment: DOTS (Directly Observed Treatment, Short-course) — a 6-month multi-drug regimen. India has the world''s highest TB burden (~28% of global cases). National TB Elimination Programme targets 2025 for elimination. Mycobacterium leprae causes leprosy; C. diphtheriae causes diphtheria; V. cholerae causes cholera.', 'EASY', 'Biology', 'Human Diseases - Bacterial & Viral', 'BIO_DIS_BACTERIAL_VIRAL', '[{"option_text": "Mycobacterium leprae", "is_correct": false}, {"option_text": "Mycobacterium tuberculosis", "is_correct": true}, {"option_text": "Corynebacterium diphtheriae", "is_correct": false}, {"option_text": "Vibrio cholerae", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7dba3d53-0f44-5c89-a0a7-daedb1be5fd6', 'Which disease is caused by the bacterium Vibrio cholerae, typically spread through contaminated water?', NULL, 'Cholera is caused by Vibrio cholerae (discovered by Robert Koch, 1884; actually first identified by Filippo Pacini 1854 though unrecognised at the time). Transmitted via faecally-contaminated water/food; causes severe watery diarrhoea (''rice water stools'') and rapid dehydration. Treatment: ORS (Oral Rehydration Solution — life-saving intervention discovered 1970s). Vaccines: oral killed (Shanchol) and live attenuated. Pandemic history: seven distinct cholera pandemics since 1817 — the 7th (current) started 1961. Typhoid = Salmonella typhi; Tetanus = Clostridium tetani; Plague = Yersinia pestis.', 'EASY', 'Biology', 'Human Diseases - Bacterial & Viral', 'BIO_DIS_BACTERIAL_VIRAL', '[{"option_text": "Typhoid", "is_correct": false}, {"option_text": "Cholera", "is_correct": true}, {"option_text": "Tetanus", "is_correct": false}, {"option_text": "Plague", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2afaa52b-409e-5f8c-af5c-523affd222c4', 'Malaria is caused by which type of pathogen?', NULL, 'Malaria is caused by the PROTOZOAN PARASITE Plasmodium (5 species infect humans: P. falciparum — most deadly, P. vivax — most widespread in India, P. ovale, P. malariae, P. knowlesi). Transmitted by the bite of infected FEMALE Anopheles mosquitoes. Life cycle involves liver stage (exo-erythrocytic) and blood stage (erythrocytic). Sir RONALD ROSS (British, working in Secunderabad India) proved in 1897 that mosquitoes transmit malaria — Nobel Prize 1902; first India-based discovery to win a Nobel. World Malaria Day: 25 April. Treatment: Chloroquine (resistance growing), Artemisinin-based combination therapy (ACT). Vaccine: RTS,S and R21/Matrix-M approved recently. Malaria ≠ bacterial/viral — a common student error.', 'MEDIUM', 'Biology', 'Human Diseases - Bacterial & Viral', 'BIO_DIS_BACTERIAL_VIRAL', '[{"option_text": "Bacteria", "is_correct": false}, {"option_text": "Virus", "is_correct": false}, {"option_text": "Protozoan parasite (Plasmodium)", "is_correct": true}, {"option_text": "Fungus", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d3ed25d6-a39b-5004-a03a-0a281c3113bd', 'Dengue fever is primarily transmitted by which mosquito?', NULL, 'Dengue virus (DEN-1, 2, 3, 4 serotypes — infection with one provides lifelong immunity to THAT serotype but not to others, hence ''Dengue Hemorrhagic Fever'' on second infection) is transmitted by Aedes aegypti (primary) and A. albopictus (secondary). Aedes bites during the DAY (unlike Anopheles which bites at night — why bed nets alone don''t prevent dengue). Key identifying feature: Aedes has black-and-white striped legs. Aedes also transmits CHIKUNGUNYA, YELLOW FEVER, ZIKA. Anopheles = malaria. Culex = filariasis, Japanese encephalitis, West Nile. Mansonia = lymphatic filariasis (rural India).', 'MEDIUM', 'Biology', 'Human Diseases - Bacterial & Viral', 'BIO_DIS_BACTERIAL_VIRAL', '[{"option_text": "Anopheles stephensi", "is_correct": false}, {"option_text": "Culex pipiens", "is_correct": false}, {"option_text": "Aedes aegypti (and A. albopictus)", "is_correct": true}, {"option_text": "Mansonia uniformis", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('48158b5b-d606-58d4-af7b-39a68c771af4', 'HIV (Human Immunodeficiency Virus) specifically targets which type of immune cells?', NULL, 'HIV is a RETROVIRUS (uses reverse transcriptase enzyme to convert its RNA to DNA, discovered by David Baltimore & Howard Temin — Nobel 1975). It specifically infects CD4+ T-helper lymphocytes (which coordinate the immune response), gradually depleting them. Normal CD4 count: 500-1500 cells/mm³; below 200 = AIDS (Acquired Immunodeficiency Syndrome). Transmitted via blood, sexual contact, mother-to-child. Treatment: ART (Antiretroviral Therapy — combination of 3+ drugs, available free in India via NACO). World AIDS Day: 1 December. HIV discovered by Luc Montagnier & Françoise Barré-Sinoussi (French) and Robert Gallo (US) — Nobel 2008 to the French duo (controversial not to include Gallo). First identified 1981, officially named 1986.', 'MEDIUM', 'Biology', 'Human Diseases - Bacterial & Viral', 'BIO_DIS_BACTERIAL_VIRAL', '[{"option_text": "B-lymphocytes", "is_correct": false}, {"option_text": "CD4+ T-helper lymphocytes", "is_correct": true}, {"option_text": "Neutrophils", "is_correct": false}, {"option_text": "Erythrocytes", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b558d6bf-1e6d-5d05-be40-2792eec19a22', 'Which disease is caused by the virus transmitted through the bite of an infected dog?', NULL, 'Rabies is caused by the Rabies lyssavirus (Rhabdoviridae family), transmitted through saliva when an infected animal (dog primarily in India; also bats, foxes, jackals, mongoose) bites or licks broken skin. Affects the central nervous system; once symptoms appear, it is almost 100% FATAL — but preventable with post-exposure prophylaxis (wound washing + vaccine ± immunoglobulin) given promptly. Louis Pasteur developed the first rabies vaccine (1885, successfully treating 9-year-old Joseph Meister). World Rabies Day: 28 September. India accounts for ~36% of global rabies deaths. NEGRI BODIES (named after Adelchi Negri) in brain neurons are diagnostic.', 'EASY', 'Biology', 'Human Diseases - Bacterial & Viral', 'BIO_DIS_BACTERIAL_VIRAL', '[{"option_text": "Swine flu", "is_correct": false}, {"option_text": "Rabies", "is_correct": true}, {"option_text": "Japanese encephalitis", "is_correct": false}, {"option_text": "Hepatitis B", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('306a7bbe-071d-54fd-a886-70b3527c3990', 'Filariasis (Elephantiasis), causing severe swelling of limbs, is caused by which parasite?', NULL, 'Lymphatic filariasis / Elephantiasis is caused by nematode worms — primarily Wuchereria bancrofti (90% of cases globally), also Brugia malayi, Brugia timori. Transmitted by Culex mosquitoes (W. bancrofti), Mansonia (Brugia). Adult worms live in lymphatic vessels, blocking lymph flow and causing massive swelling (elephantiasis) of legs, arms, scrotum. WHO aims to ELIMINATE LF as a public health problem — India launched Mass Drug Administration (MDA) with DEC + Albendazole + Ivermectin in endemic districts. Plasmodium = malaria (protozoan). Leishmania = kala-azar. Trypanosoma = African sleeping sickness (not in India).', 'HARD', 'Biology', 'Human Diseases - Bacterial & Viral', 'BIO_DIS_BACTERIAL_VIRAL', '[{"option_text": "Plasmodium vivax", "is_correct": false}, {"option_text": "Wuchereria bancrofti", "is_correct": true}, {"option_text": "Leishmania donovani", "is_correct": false}, {"option_text": "Trypanosoma brucei", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d87c6cd5-b574-50d0-a197-474c5fd5caeb', 'Kala-azar (Visceral Leishmaniasis) is spread by which vector?', NULL, 'Kala-azar / Visceral Leishmaniasis is caused by Leishmania donovani (protozoan parasite) and transmitted by the bite of an infected SANDFLY (Phlebotomus argentipes in India, Lutzomyia elsewhere). Affects spleen, liver, bone marrow; symptoms: prolonged fever, weight loss, hepatosplenomegaly, blackening of skin (hence ''kala-azar'' = ''black fever''). Endemic in Bihar, Jharkhand, WB, UP. India aimed to ELIMINATE kala-azar as a public health problem (<1 case/10,000) and as of 2023 has achieved this in most endemic blocks. Tsetse fly = African sleeping sickness. Rat flea (Xenopsylla) = plague.', 'HARD', 'Biology', 'Human Diseases - Bacterial & Viral', 'BIO_DIS_BACTERIAL_VIRAL', '[{"option_text": "Anopheles mosquito", "is_correct": false}, {"option_text": "Sandfly (Phlebotomus argentipes in India)", "is_correct": true}, {"option_text": "Tsetse fly", "is_correct": false}, {"option_text": "Rat flea", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('621abbe5-276a-5ea7-bad8-bd722cdc5764', 'The only disease to be declared eradicated globally by WHO was:', NULL, 'SMALLPOX (Variola major virus) became the FIRST and ONLY HUMAN disease globally eradicated — declared by WHO on 8 May 1980 after a massive vaccination campaign. The last natural case was Ali Maow Maalin of Somalia in October 1977. Edward Jenner invented the first vaccine in 1796 using cowpox (the word ''vaccine'' comes from ''vacca'' = cow in Latin). RINDERPEST (cattle plague) was the second disease eradicated (2011), but it affects animals not humans. POLIO is close to eradication — India was declared polio-free in March 2014. Guinea worm (Dracunculiasis) nearly eradicated (<15 cases/year globally). India has eliminated yaws, maternal-neonatal tetanus.', 'EASY', 'Biology', 'Human Diseases - Bacterial & Viral', 'BIO_DIS_BACTERIAL_VIRAL', '[{"option_text": "Polio", "is_correct": false}, {"option_text": "Smallpox (declared eradicated 1980)", "is_correct": true}, {"option_text": "Measles", "is_correct": false}, {"option_text": "Guinea worm disease", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a0194e88-f23a-508b-af07-5e970e716557', 'Which of the following diseases is NOT caused by a virus?', NULL, 'Tetanus is caused by the BACTERIUM Clostridium tetani (Gram-positive, anaerobic, spore-forming), which produces the tetanospasmin toxin causing muscle spasms (''lockjaw''). Spores live in soil, rusty metal. Entry via deep puncture wounds. Prevented by DPT vaccine (Diphtheria, Pertussis, Tetanus) / DT / TT booster. The other three are VIRAL: Japanese encephalitis (Flavivirus, Culex transmitted), Chickenpox (Varicella-zoster — same virus causes shingles on reactivation), Mumps (Paramyxovirus — causes parotitis, part of MMR vaccine). Knowing pathogen TYPE (bacterial vs viral vs parasite) for common diseases is a frequent SSC/Banking question.', 'MEDIUM', 'Biology', 'Human Diseases - Bacterial & Viral', 'BIO_DIS_BACTERIAL_VIRAL', '[{"option_text": "Japanese encephalitis", "is_correct": false}, {"option_text": "Chickenpox", "is_correct": false}, {"option_text": "Tetanus", "is_correct": true}, {"option_text": "Mumps", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('deff58bd-cdce-5156-a557-54a30a4ef3c5', 'Which of the following is the largest part of the human brain?', NULL, 'The CEREBRUM is the largest part of the human brain (~85% of total brain mass); divided into left and right HEMISPHERES by the LONGITUDINAL FISSURE and connected by the CORPUS CALLOSUM. Each hemisphere has 4 LOBES: Frontal (movement, speech-Broca''s area, personality), Parietal (touch, spatial awareness), Temporal (hearing, memory, speech-Wernicke''s area), Occipital (vision). CEREBELLUM (''little brain'' — ~10%): balance, coordination, fine motor. MEDULLA OBLONGATA: autonomic control (breathing, heartbeat, BP) — damage = instant death. Between brain-stem and cerebellum is the PONS. The BRAINSTEM = midbrain + pons + medulla.', 'EASY', 'Biology', 'Human Nervous System & Brain', 'BIO_NERVOUS', '[{"option_text": "Cerebellum", "is_correct": false}, {"option_text": "Cerebrum", "is_correct": true}, {"option_text": "Medulla oblongata", "is_correct": false}, {"option_text": "Hypothalamus", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('df27257e-069f-5513-ae1d-8188faf7a05c', 'Which part of the brain is responsible for maintaining balance, posture, and coordinating voluntary movements?', NULL, 'The CEREBELLUM (located at the back of the brain, below the occipital lobe) is the ''little brain'' — it fine-tunes voluntary movements, maintains BALANCE & POSTURE, coordinates gait, and learns motor skills (e.g., riding a bicycle). Damage to cerebellum = ATAXIA (unsteady gait, tremor, inability to perform rapid alternating movements). Frontal lobe = planning, movement (motor cortex), speech. Medulla = involuntary autonomic (breathing, heartbeat). Pituitary = endocrine ''master gland'' (not coordination). Parkinson''s affects the SUBSTANTIA NIGRA in the midbrain (dopamine production).', 'EASY', 'Biology', 'Human Nervous System & Brain', 'BIO_NERVOUS', '[{"option_text": "Frontal lobe of cerebrum", "is_correct": false}, {"option_text": "Cerebellum", "is_correct": true}, {"option_text": "Medulla oblongata", "is_correct": false}, {"option_text": "Pituitary gland", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b04e4469-7118-552d-b738-acd4fd547e6e', 'A typical human has how many pairs of spinal nerves?', NULL, 'Humans have 31 PAIRS OF SPINAL NERVES: 8 CERVICAL (C1-C8), 12 THORACIC (T1-T12), 5 LUMBAR (L1-L5), 5 SACRAL (S1-S5), 1 COCCYGEAL. Each pair emerges through intervertebral foramina. In contrast, humans have 12 PAIRS OF CRANIAL NERVES arising from the brain/brainstem (I=Olfactory, II=Optic, III=Oculomotor, IV=Trochlear, V=Trigeminal, VI=Abducens, VII=Facial, VIII=Vestibulocochlear, IX=Glossopharyngeal, X=Vagus [wanderer, longest], XI=Accessory, XII=Hypoglossal). Mnemonic: ''Oh Oh Oh To Touch And Feel Very Green Vegetables AH''. Vagus nerve (X) is the longest cranial nerve and a key parasympathetic conductor.', 'MEDIUM', 'Biology', 'Human Nervous System & Brain', 'BIO_NERVOUS', '[{"option_text": "12 pairs", "is_correct": false}, {"option_text": "31 pairs", "is_correct": true}, {"option_text": "24 pairs", "is_correct": false}, {"option_text": "33 pairs", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5ff7d27d-02a0-5cc0-a097-4b4b47101f03', 'Parkinson''s disease is caused by the degeneration of neurons producing which neurotransmitter?', NULL, 'PARKINSON''S DISEASE is caused by the progressive death of DOPAMINERGIC NEURONS in the SUBSTANTIA NIGRA (midbrain) — depleting dopamine, leading to tremor, rigidity, bradykinesia (slow movement), postural instability. Treatment: Levodopa (converted to dopamine in brain). First described by James Parkinson (1817, ''An Essay on the Shaking Palsy''). ALZHEIMER''S: loss of ACETYLCHOLINE neurons (→ memory loss); treatment: donepezil (AChE inhibitor). DEPRESSION: low serotonin (SSRIs increase it). HUNTINGTON''S: autosomal dominant genetic, affects GABAergic neurons in striatum. EPILEPSY: abnormal electrical discharges. MYASTHENIA GRAVIS: autoimmune attack on acetylcholine receptors at neuromuscular junction.', 'HARD', 'Biology', 'Human Nervous System & Brain', 'BIO_NERVOUS', '[{"option_text": "Serotonin", "is_correct": false}, {"option_text": "Dopamine", "is_correct": true}, {"option_text": "Acetylcholine", "is_correct": false}, {"option_text": "GABA", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('41e901ff-3a77-5980-95f1-307c7fbb5cb6', 'A ''reflex action'' like pulling the hand away from a hot object is controlled by which part of the nervous system?', NULL, 'A REFLEX ACTION is an involuntary, automatic response mediated by a REFLEX ARC in the spinal cord — NOT the brain. The pathway: RECEPTOR (skin thermal receptor) → AFFERENT (sensory) neuron → DORSAL ROOT of spinal cord → INTERNEURON → EFFERENT (motor) neuron via VENTRAL ROOT → EFFECTOR (muscle contracts, hand withdrawn). The brain gets the information AFTER the action (feels the pain). Speed is crucial for safety — reflex typically completes in <0.1 second. Deep tendon reflexes (knee jerk, patellar) are monosynaptic (no interneuron). Polysynaptic reflexes include withdrawal and crossed-extensor reflexes.', 'MEDIUM', 'Biology', 'Human Nervous System & Brain', 'BIO_NERVOUS', '[{"option_text": "Cerebrum (conscious decision)", "is_correct": false}, {"option_text": "Spinal cord (via reflex arc)", "is_correct": true}, {"option_text": "Cerebellum", "is_correct": false}, {"option_text": "Hypothalamus", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('168aa733-18f3-58e8-9a9d-023e3cc1feaa', 'The HYPOTHALAMUS in the human brain is primarily associated with regulating:', NULL, 'The HYPOTHALAMUS (deep in the diencephalon, below the thalamus) is the master regulator of HOMEOSTASIS. It controls: (1) BODY TEMPERATURE (thermostat); (2) HUNGER (feeding centre) and SATIETY; (3) THIRST (osmoreceptors); (4) SLEEP-WAKE cycle (suprachiasmatic nucleus = master clock); (5) EMOTIONAL responses; (6) SEXUAL behaviour; (7) ANS (autonomic nervous system) control; (8) HORMONAL SECRETIONS via the pituitary — produces releasing hormones (TRH, CRH, GnRH, GHRH, somatostatin, dopamine) and direct hormones (oxytocin, ADH stored in posterior pituitary). Long-term memory = HIPPOCAMPUS. Conscious movement = primary motor cortex (frontal lobe). Vision = occipital lobe.', 'MEDIUM', 'Biology', 'Human Nervous System & Brain', 'BIO_NERVOUS', '[{"option_text": "Conscious movement", "is_correct": false}, {"option_text": "Body temperature, hunger, thirst, sleep, and hormonal functions", "is_correct": true}, {"option_text": "Long-term memory formation", "is_correct": false}, {"option_text": "Vision and visual processing", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6ae29ec9-7075-50cc-84e1-5f347a6834ee', 'The BROCA''s area of the brain is responsible for:', NULL, 'BROCA''s area — in the FRONTAL LOBE (typically left hemisphere; inferior frontal gyrus) — controls SPEECH PRODUCTION. Damage (Broca''s aphasia / expressive aphasia) → patient understands language but cannot form fluent speech (can only speak telegraphically). Discovered by French physician Paul Broca 1861. WERNICKE''s area — in the TEMPORAL LOBE (posterior superior temporal gyrus, left) — handles LANGUAGE COMPREHENSION. Wernicke''s aphasia / receptive aphasia → patient speaks fluently but the words are meaningless gibberish; can''t understand others. Both connected by the ARCUATE FASCICULUS (damage → conduction aphasia). 90%+ of right-handers have language in left hemisphere; ~70% of left-handers too.', 'HARD', 'Biology', 'Human Nervous System & Brain', 'BIO_NERVOUS', '[{"option_text": "Comprehending spoken language", "is_correct": false}, {"option_text": "Producing speech (speech formation)", "is_correct": true}, {"option_text": "Visual processing", "is_correct": false}, {"option_text": "Memory consolidation", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bcc960eb-9208-5fcf-8d30-d3e7e9c94816', 'Which of the following is the longest cell in the human body?', NULL, 'NEURONS (nerve cells) are the longest cells in the human body. The longest single neuron — the SCIATIC NERVE axon — can extend from the base of the spine to the big toe, a distance of ~1 metre in an adult. Each neuron has: DENDRITES (receive signals), CELL BODY (soma), AXON (transmits signal), MYELIN SHEATH (Schwann cells in PNS, oligodendrocytes in CNS — enable saltatory conduction, up to 120 m/s), AXON TERMINAL (synapse). Human brain has ~86 BILLION neurons. RBCs (smallest, no nucleus, 7-8 μm). Ovum is the LARGEST cell (~0.1 mm, visible to naked eye). Smallest nucleated human cell: granule cells of cerebellum (~5 μm).', 'MEDIUM', 'Biology', 'Human Nervous System & Brain', 'BIO_NERVOUS', '[{"option_text": "Red blood cell", "is_correct": false}, {"option_text": "Nerve cell (neuron)", "is_correct": true}, {"option_text": "Muscle cell", "is_correct": false}, {"option_text": "Liver cell (hepatocyte)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5dd4c261-3cf2-561b-975e-668d472389d3', 'Which of the following correctly pairs the vitamin with its IUPAC-recognised chemical name?', NULL, 'Correct: B₁₂ = Cyanocobalamin. Common confusions exposed by the distractors: B₁ is THIAMINE (not riboflavin — that''s B₂). C is ASCORBIC ACID (calciferol is vitamin D). K is PHYLLOQUINONE/K₁ or MENAQUINONE/K₂ (retinol is vitamin A). Knowing the 13 vitamin-to-chemical-name pairings outright is the single highest-ROI memorisation in Biology GK.', 'EASY', 'Biology', 'Vitamins — Deficiencies, Sources & Chemistry', 'BIO_VITAMINS_DEFICIENCIES', '[{"option_text": "Vitamin B₁ — Riboflavin", "is_correct": false}, {"option_text": "Vitamin B₁₂ — Cyanocobalamin", "is_correct": true}, {"option_text": "Vitamin C — Calciferol", "is_correct": false}, {"option_text": "Vitamin K — Retinol", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('50c0f718-dec8-52e1-9af2-b1944f889262', 'The deficiency disease PELLAGRA, characterised by the three D''s (Diarrhoea, Dermatitis, Dementia), is caused by a prolonged lack of:', NULL, 'Pellagra = deficiency of vitamin B₃ (Niacin / Nicotinic acid). Symptom mnemonic ''3 Ds'' (plus eventually a 4th D — death, if untreated). Niacin can also be synthesised by the body from the amino acid tryptophan, so pellagra is more common in populations whose diet is maize-heavy (maize is tryptophan-poor). B₂ deficiency = cheilosis/glossitis; B₆ = peripheral neuropathy; B₁₂ = pernicious/megaloblastic anaemia — each distinct from pellagra.', 'MEDIUM', 'Biology', 'Vitamins — Deficiencies, Sources & Chemistry', 'BIO_VITAMINS_DEFICIENCIES', '[{"option_text": "Vitamin B₂ (Riboflavin)", "is_correct": false}, {"option_text": "Vitamin B₃ (Niacin)", "is_correct": true}, {"option_text": "Vitamin B₆ (Pyridoxine)", "is_correct": false}, {"option_text": "Vitamin B₁₂ (Cyanocobalamin)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ed60a8b0-681a-5342-950d-590ec1017102', 'Which of the following vitamins are FAT-SOLUBLE?', NULL, 'Fat-soluble vitamins are A, D, E, K — mnemonic ''ADEK''. All others (B-complex and C) are water-soluble. Fat-soluble vitamins are stored in liver/adipose tissue (so deficiency develops slowly but toxicity is possible); water-soluble vitamins are not stored (deficiency develops faster but toxicity is rare — the body excretes excess in urine). Knowing this split affects both exam Qs and real-life clinical reasoning.', 'EASY', 'Biology', 'Vitamins — Deficiencies, Sources & Chemistry', 'BIO_VITAMINS_DEFICIENCIES', '[{"option_text": "Vitamins A, B, C, D", "is_correct": false}, {"option_text": "Vitamins A, D, E, K", "is_correct": true}, {"option_text": "Vitamins B, C, E, K", "is_correct": false}, {"option_text": "Vitamins A, C, E, K", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c88fe9a5-b23a-52c7-9ec5-52352d528142', 'Which vitamin plays a critical role in BLOOD CLOTTING by enabling the carboxylation of specific glutamate residues on clotting factors II, VII, IX, X?', NULL, 'Vitamin K — the ''K'' comes from the German ''Koagulation'' — is the cofactor for γ-glutamyl carboxylase, which post-translationally modifies clotting factors II (prothrombin), VII, IX, and X. Without K, these factors cannot bind calcium and clotting fails. Newborns get a prophylactic vitamin K shot for this reason. Vitamin E is an antioxidant; C is needed for collagen synthesis (hence scurvy affects wound healing); B₁₂ supports erythropoiesis and neural myelin — all different mechanisms.', 'MEDIUM', 'Biology', 'Vitamins — Deficiencies, Sources & Chemistry', 'BIO_VITAMINS_DEFICIENCIES', '[{"option_text": "Vitamin E (Tocopherol)", "is_correct": false}, {"option_text": "Vitamin K (Phylloquinone)", "is_correct": true}, {"option_text": "Vitamin B₁₂ (Cyanocobalamin)", "is_correct": false}, {"option_text": "Vitamin C (Ascorbic acid)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3bbf34cd-7b00-59f0-9dfb-c251c089f9ea', 'Match the following deficiency diseases with the vitamin whose deficiency causes them, and choose the correct pairing:
(i) Scurvy — Vitamin C
(ii) Rickets — Vitamin D
(iii) Beri-beri — Vitamin B₁ (Thiamine)
(iv) Night blindness — Vitamin A', NULL, 'All FOUR pairings are correct — this 4-way match is the ''canonical'' set every student should memorise cold: Scurvy↔C (gum bleeding, skin hemorrhage), Rickets↔D (children''s bone deformity), Beri-beri↔B₁ (wet = cardiovascular, dry = peripheral neuropathy), Night blindness↔A (xerophthalmia progresses to corneal damage). A paper-setter using this 4-pair matcher expects students to confidently answer ''All four'' — hesitation signals fragile recall.', 'EASY', 'Biology', 'Vitamins — Deficiencies, Sources & Chemistry', 'BIO_VITAMINS_DEFICIENCIES', '[{"option_text": "Only (i) and (ii) are correctly paired", "is_correct": false}, {"option_text": "Only (i), (ii), and (iii) are correctly paired", "is_correct": false}, {"option_text": "All four (i), (ii), (iii) and (iv) are correctly paired", "is_correct": true}, {"option_text": "Only (iii) and (iv) are correctly paired", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('43ead53f-279d-5ce3-b522-c578719b4a0e', 'Vitamin D is unique among vitamins because:', NULL, 'Vitamin D is endogenously synthesised when UV-B (290-320 nm) strikes 7-dehydrocholesterol in the skin, producing cholecalciferol (D₃), which is then hydroxylated in the liver (→ 25-OH-D) and kidney (→ 1,25-(OH)₂-D, the active form). This is why it''s sometimes called the ''sunshine vitamin'' and also why it''s technically a PROHORMONE rather than a classical vitamin. A is wrong (vitamin K₂ and biotin are also gut-microbially produced). C is wrong (D is fat-soluble, not water-soluble). D is incorrect — K₂ is gut-microbial but D is skin-synthesised.', 'HARD', 'Biology', 'Vitamins — Deficiencies, Sources & Chemistry', 'BIO_VITAMINS_DEFICIENCIES', '[{"option_text": "It is the only vitamin humans CANNOT synthesise endogenously", "is_correct": false}, {"option_text": "It is synthesised in human skin from 7-dehydrocholesterol upon exposure to UV-B radiation", "is_correct": true}, {"option_text": "It is the only vitamin that is water-soluble but stored in the liver", "is_correct": false}, {"option_text": "It is produced exclusively by the gut microbiota in humans", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('34c218a8-4188-5954-be01-e8e4d9c56b29', 'Pernicious anaemia — characterised by failed erythropoiesis and neurological symptoms like tingling, ataxia, and memory loss — is the classic presentation of deficiency of which vitamin?', NULL, 'Pernicious anaemia is the megaloblastic anaemia caused by B₁₂ deficiency, typically due to failed intrinsic factor production (autoimmune atrophic gastritis). The KEY distinction from B₉/folic-acid-deficiency anaemia is the NEUROLOGICAL involvement: B₁₂ deficiency causes subacute combined degeneration of the spinal cord (tingling, ataxia), whereas folate deficiency doesn''t hit the nervous system. ''Pernicious'' means ''highly destructive'' — reflecting its pre-treatment mortality. Supplementing folate alone in a B₁₂-deficient patient can mask the anaemia while letting the neurology worsen — a classic clinical trap.', 'MEDIUM', 'Biology', 'Vitamins — Deficiencies, Sources & Chemistry', 'BIO_VITAMINS_DEFICIENCIES', '[{"option_text": "Folic acid (B₉)", "is_correct": false}, {"option_text": "Cyanocobalamin (B₁₂)", "is_correct": true}, {"option_text": "Biotin (B₇)", "is_correct": false}, {"option_text": "Niacin (B₃)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('12d92e9a-4081-523d-ba9a-04a52e24c8f0', 'Which vitamin deficiency is MOST directly associated with NEURAL TUBE DEFECTS (e.g. spina bifida, anencephaly) in newborns, prompting worldwide recommendations for supplementation in pregnancy planning?', NULL, 'Peri-conceptional folic acid intake (400 μg/day, ideally from 1 month before conception through the first trimester) reduces neural-tube defects by ~70%. Folate is essential for DNA synthesis and cell division — the developing neural tube (closes by Day 28 post-conception) is especially vulnerable. India''s ''Iron and Folic Acid'' (IFA) supplementation programme for women of reproductive age and pregnant women is based on this evidence. Vitamin A TOXICITY (not deficiency) causes teratogenicity; D and K deficiencies don''t primarily affect neural-tube closure.', 'MEDIUM', 'Biology', 'Vitamins — Deficiencies, Sources & Chemistry', 'BIO_VITAMINS_DEFICIENCIES', '[{"option_text": "Vitamin A (Retinol)", "is_correct": false}, {"option_text": "Folic acid / Folate (Vitamin B₉)", "is_correct": true}, {"option_text": "Vitamin D (Calciferol)", "is_correct": false}, {"option_text": "Vitamin K (Phylloquinone)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('65a2e115-95ba-54e1-a922-06a00abeceba', 'The term ''vitamine'' was first coined by Casimir Funk in 1912 while studying a disease that he cured with rice polishings. Which disease and vitamin did Funk''s work directly concern?', NULL, 'Casimir Funk''s 1912 paper isolating a curative factor from rice polishings (against beri-beri) led him to coin ''vitamine'' (vital + amine — he believed all such factors were amines; the ''e'' was later dropped when other non-amine vitamins were found). Beri-beri was rampant among populations eating polished white rice, which removes the thiamine-rich husk. Christiaan Eijkman had earlier (1890s, Nobel 1929) connected the disease to polished rice in chickens. Scurvy-vitamin C was isolated by Szent-Györgyi (Nobel 1937) well after Funk''s coinage; Pellagra-B₃ was elucidated by Joseph Goldberger in the 1910s-20s; Rickets-D was linked by Mellanby (1919) and Elmer McCollum.', 'HARD', 'Biology', 'Vitamins — Deficiencies, Sources & Chemistry', 'BIO_VITAMINS_DEFICIENCIES', '[{"option_text": "Scurvy — Vitamin C", "is_correct": false}, {"option_text": "Beri-beri — Vitamin B₁ (Thiamine)", "is_correct": true}, {"option_text": "Pellagra — Vitamin B₃ (Niacin)", "is_correct": false}, {"option_text": "Rickets — Vitamin D", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2b888734-6444-5cfb-ac06-f03adf683db5', 'Which of the following is the RICHEST natural food source of Vitamin C among the options listed?', NULL, 'Amla (Phyllanthus emblica / Indian Gooseberry) contains approximately 600-800 mg of Vitamin C per 100 g — one of the world''s highest concentrations, eclipsing citrus fruits (oranges: ~50 mg/100 g), guava (~228 mg), and kiwi. In India-specific GK, amla is the textbook answer for ''richest Vitamin C source''. Cow''s milk has essentially no Vitamin C; white rice loses C during polishing; egg yolk is rich in fat-soluble vitamins (A, D, E, K) but not C — which is water-soluble and mostly plant-derived.', 'EASY', 'Biology', 'Vitamins — Deficiencies, Sources & Chemistry', 'BIO_VITAMINS_DEFICIENCIES', '[{"option_text": "Cow''s milk", "is_correct": false}, {"option_text": "Amla (Indian Gooseberry)", "is_correct": true}, {"option_text": "White rice", "is_correct": false}, {"option_text": "Boiled egg yolk", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9e792b16-95cc-53f9-bfe1-7985f149979b', 'A patient presents with cheilosis (angular cracks at the corners of the mouth), magenta-coloured tongue (glossitis), and dermatitis around the nose. Which vitamin deficiency is MOST likely?', NULL, 'The triad cheilosis + glossitis + seborrheic dermatitis is classically ariboflavinosis — B₂ / Riboflavin deficiency. Riboflavin is a precursor of FAD/FMN, so deficiency impairs redox metabolism in high-turnover tissues (skin, mucosa). B₁ deficiency = beri-beri (neurological / cardiac); B₆ deficiency = peripheral neuropathy + seborrheic dermatitis + sideroblastic anaemia; B₁₂ deficiency = megaloblastic anaemia + subacute combined degeneration (no cheilosis as presenting feature). The ''magenta tongue'' is a dead-giveaway for riboflavin.', 'MEDIUM', 'Biology', 'Vitamins — Deficiencies, Sources & Chemistry', 'BIO_VITAMINS_DEFICIENCIES', '[{"option_text": "Vitamin B₁ (Thiamine)", "is_correct": false}, {"option_text": "Vitamin B₂ (Riboflavin)", "is_correct": true}, {"option_text": "Vitamin B₆ (Pyridoxine)", "is_correct": false}, {"option_text": "Vitamin B₁₂ (Cyanocobalamin)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7175d8bb-e9f3-5b4a-89c8-7ec657b7801f', 'Osteomalacia — softening of bones in ADULTS — and Rickets — the same pathology in CHILDREN — both stem from a deficiency of:', NULL, 'Rickets (children, before epiphyseal plate closure — bowing of legs, rachitic rosary, widened wrists) and osteomalacia (adults, with already-closed epiphyses — diffuse bone pain, pseudo-fractures) are the SAME underlying deficiency — Vitamin D — expressed at different ages. Low D reduces intestinal calcium absorption and renal calcium reabsorption, so bones demineralise despite adequate calcium intake. Pure dietary calcium deficiency can cause similar symptoms in extreme cases but is rare because dairy and leafy greens supply enough; the exam''s canonical answer is D. B₁₂ and iron cause anaemia, not bone-softening syndromes.', 'MEDIUM', 'Biology', 'Vitamins — Deficiencies, Sources & Chemistry', 'BIO_VITAMINS_DEFICIENCIES', '[{"option_text": "Calcium alone, regardless of vitamin status", "is_correct": false}, {"option_text": "Vitamin D (and consequent impaired calcium absorption)", "is_correct": true}, {"option_text": "Vitamin B₁₂", "is_correct": false}, {"option_text": "Iron", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ea68533b-dd16-5fd4-8e67-0daa538d5ed4', 'Which pair of vitamins functions PRIMARILY as an ANTIOXIDANT in the human body?', NULL, 'Vitamin C (ascorbic acid, water-soluble) and Vitamin E (tocopherol, lipid-soluble) are the two principal dietary antioxidants — they neutralise free radicals in the aqueous and lipid compartments respectively. Vitamin C specifically regenerates oxidised vitamin E back to its active form, so they work synergistically. Vitamin A has antioxidant-like activity through beta-carotene but its primary role is vision (retinal function) and epithelial maintenance. D''s role is calcium-phosphate homeostasis; K is clotting. Thiamine (B₁) is a cofactor for decarboxylase enzymes — not antioxidant.', 'EASY', 'Biology', 'Vitamins — Deficiencies, Sources & Chemistry', 'BIO_VITAMINS_DEFICIENCIES', '[{"option_text": "Vitamin A and Vitamin E", "is_correct": false}, {"option_text": "Vitamin C and Vitamin E", "is_correct": true}, {"option_text": "Vitamin B₁ and Vitamin C", "is_correct": false}, {"option_text": "Vitamin D and Vitamin K", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b70b105d-86e8-54f1-8814-595d9503a462', 'Which of the following statements regarding vitamin storage and requirement is INCORRECT?', NULL, 'Statement D is INCORRECT — vitamin C is water-soluble with modest body reserves (~2-3 months), and SHIP-bound sailors developed full-blown scurvy within 2-3 months of leaving port without citrus. Even 1 month of near-zero intake can trigger subclinical symptoms in undernourished individuals. Statements A, B, and C are all true: fat-soluble vitamins can reach hypervitaminosis (A and D are the commonest culprits); water-soluble require near-daily intake; B₁₂''s hepatic reserve is unusually large (3-5 years), which is why post-gastrectomy patients can go years before pernicious anaemia manifests.', 'HARD', 'Biology', 'Vitamins — Deficiencies, Sources & Chemistry', 'BIO_VITAMINS_DEFICIENCIES', '[{"option_text": "Fat-soluble vitamins (A, D, E, K) are stored in the liver/adipose tissue and can reach toxic levels", "is_correct": false}, {"option_text": "Water-soluble vitamins (B-complex, C) are excreted in urine and require regular dietary intake", "is_correct": false}, {"option_text": "Vitamin B₁₂ is stored in the liver for 3-5 years, so deficiency develops slowly", "is_correct": false}, {"option_text": "Vitamin C has a large body reserve, so a single month without C will not cause scurvy", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('774f288d-669c-5169-bae2-f8217a06026b', 'The pH scale ranges from 0 to 14. A solution with pH = 7 is:', NULL, 'At 25°C, pure water has pH = 7 — exactly neutral. pH < 7 is acidic (lower = more acidic); pH > 7 is basic (higher = more basic). The pH scale is LOGARITHMIC (base 10): a pH 4 solution has 10x more H⁺ ions than pH 5. Each unit change = 10-fold change in [H⁺]. Strong acids like HCl have pH ~0-1; strong bases like NaOH have pH ~13-14. Lemon juice pH ~2; stomach acid ~1.5; blood ~7.4.', 'EASY', 'Chemistry', 'Acids, Bases & pH', 'CHE_ACIDS_BASES', '[{"option_text": "Strongly acidic", "is_correct": false}, {"option_text": "Neutral (neither acidic nor basic)", "is_correct": true}, {"option_text": "Strongly basic", "is_correct": false}, {"option_text": "Weakly acidic", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5bab2682-58dd-5cd1-91aa-c0036ededf6d', 'Which of the following is NOT a property of acids?', NULL, 'Turning RED litmus BLUE is a property of BASES, not acids. Acid properties: (1) sour taste (lemon, vinegar); (2) turn BLUE litmus RED; (3) react with active metals (Zn, Mg) to release H₂ gas; (4) react with bases to form salt + water (neutralization); (5) react with carbonates to release CO₂. Bases: bitter taste, slippery, turn red litmus blue, feel soapy.', 'EASY', 'Chemistry', 'Acids, Bases & pH', 'CHE_ACIDS_BASES', '[{"option_text": "Sour taste", "is_correct": false}, {"option_text": "Turn blue litmus red", "is_correct": false}, {"option_text": "React with metals to release hydrogen gas", "is_correct": false}, {"option_text": "Turn red litmus blue", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('92758e48-2dcf-5102-8f29-8009de138182', 'According to the Arrhenius definition, an acid is a substance that:', NULL, 'Three definitions of acid/base: (1) ARRHENIUS (1884): acid produces H⁺ in water, base produces OH⁻. (2) BRØNSTED-LOWRY (1923): acid donates H⁺ (proton); base accepts H⁺. (3) LEWIS (1923): acid accepts electron pair; base donates electron pair. Arrhenius is the narrowest (restricted to aqueous solutions); Lewis is the most general (covers non-proton reactions). Answer is B per Arrhenius. Option A describes a Brønsted base. Option C describes a Lewis acid.', 'MEDIUM', 'Chemistry', 'Acids, Bases & pH', 'CHE_ACIDS_BASES', '[{"option_text": "Accepts a proton (H⁺)", "is_correct": false}, {"option_text": "Produces H⁺ ions in aqueous solution", "is_correct": true}, {"option_text": "Accepts a pair of electrons", "is_correct": false}, {"option_text": "Donates a pair of electrons", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ac408a97-0cfe-56a0-ab07-cdbefda5b835', 'If the pH of a solution is 3, its hydrogen ion concentration [H⁺] is:', NULL, 'Definition: pH = −log₁₀[H⁺]. So [H⁺] = 10⁻ᵖᴴ. For pH = 3: [H⁺] = 10⁻³ M = 0.001 M. Common error: pH 3 DOES NOT mean [H⁺] = 3 M; the pH is a logarithmic measure. Similarly, pOH = −log[OH⁻], and at 25°C: pH + pOH = 14. So a pH-3 solution has [OH⁻] = 10⁻¹¹ M — highly acidic.', 'MEDIUM', 'Chemistry', 'Acids, Bases & pH', 'CHE_ACIDS_BASES', '[{"option_text": "3 M", "is_correct": false}, {"option_text": "10⁻³ M", "is_correct": true}, {"option_text": "10³ M", "is_correct": false}, {"option_text": "3 × 10⁻¹ M", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e335c5d6-90dd-53f2-ab7e-278705a139ba', 'Which of the following salts would give a basic aqueous solution?', NULL, 'Salt hydrolysis rules: (1) strong acid + strong base salt → NEUTRAL (e.g., NaCl from HCl+NaOH, Na₂SO₄ from H₂SO₄+NaOH); (2) strong base + weak acid salt → BASIC (e.g., Na₂CO₃ from NaOH+H₂CO₃ weak); (3) strong acid + weak base salt → ACIDIC (e.g., NH₄Cl from HCl+NH₃ weak). Sodium carbonate (washing soda) solution is basic (pH ~11-12) — used historically as a cleaning agent for this reason.', 'HARD', 'Chemistry', 'Acids, Bases & pH', 'CHE_ACIDS_BASES', '[{"option_text": "Sodium chloride (NaCl)", "is_correct": false}, {"option_text": "Ammonium chloride (NH₄Cl)", "is_correct": false}, {"option_text": "Sodium carbonate (Na₂CO₃)", "is_correct": true}, {"option_text": "Sodium sulphate (Na₂SO₄)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('731abaea-f995-5ed8-84b0-3ed4a8afcffb', 'Acid rain is caused primarily by the presence of which gases in the atmosphere?', NULL, 'ACID RAIN forms when SO₂ (sulphur dioxide, from coal burning) and NO_x (nitrogen oxides, from vehicle exhaust) react with atmospheric water: SO₂ + H₂O → H₂SO₃; further oxidised to H₂SO₄ (sulphuric acid). NO₂ + H₂O → HNO₃ (nitric acid). These acids return to Earth as rain with pH ~4-5 (normal rain is pH ~5.6 due to dissolved CO₂ — not classified as acid rain unless <5). Effects: damage to aquatic ecosystems, forests, monuments (e.g., Taj Mahal).', 'EASY', 'Chemistry', 'Acids, Bases & pH', 'CHE_ACIDS_BASES', '[{"option_text": "CO₂ and CH₄", "is_correct": false}, {"option_text": "SO₂ and NO₂", "is_correct": true}, {"option_text": "O₃ and N₂O", "is_correct": false}, {"option_text": "CFC and H₂O", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2b3f88e0-bbc6-523c-8c77-bc48fc3932e8', 'Which of the following acids is found in ant stings and nettle leaves?', NULL, 'Common biological acids and their sources: FORMIC ACID (HCOOH) — ants, bees, nettle leaves (genus Formica gave the name). ACETIC ACID (CH₃COOH) — vinegar (dilute). CITRIC ACID — citrus fruits. TARTARIC ACID — tamarind, grapes. LACTIC ACID — curd, muscle during anaerobic respiration. OXALIC ACID — spinach, rhubarb. ASCORBIC ACID — Vitamin C. MALIC ACID — apples. Formic acid''s Latin name ''acidum formicum'' comes from ''formica'' (Latin for ant).', 'EASY', 'Chemistry', 'Acids, Bases & pH', 'CHE_ACIDS_BASES', '[{"option_text": "Acetic acid", "is_correct": false}, {"option_text": "Formic acid", "is_correct": true}, {"option_text": "Oxalic acid", "is_correct": false}, {"option_text": "Lactic acid", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('99da3c62-6c6e-5234-8ab1-a865612d2bee', 'Neutralization reaction between an acid and a base produces:', NULL, 'NEUTRALIZATION: Acid + Base → Salt + Water. Example: HCl + NaOH → NaCl + H₂O. The reaction is EXOTHERMIC (releases heat). In terms of ions, it reduces to H⁺ + OH⁻ → H₂O. Acid + metal → salt + H₂ gas (not the same as neutralization). Acid + carbonate → salt + water + CO₂ gas.', 'EASY', 'Chemistry', 'Acids, Bases & pH', 'CHE_ACIDS_BASES', '[{"option_text": "Hydrogen gas and water", "is_correct": false}, {"option_text": "Salt and water", "is_correct": true}, {"option_text": "Carbon dioxide and water", "is_correct": false}, {"option_text": "Only salt", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6119537b-12b6-5fe7-8e40-3e6b2cc7e681', 'Which of the following is a common indicator used in acid-base titrations?', NULL, 'Common acid-base indicators: PHENOLPHTHALEIN (colourless in acid, pink in base; turnover pH ~8.2-10); METHYL ORANGE (red in acid, yellow in base; pH 3.1-4.4); METHYL RED (red in acid, yellow in base; pH 4.4-6.2); LITMUS (red/blue, pH 5.0-8.0); BROMOTHYMOL BLUE (yellow/blue, pH 6.0-7.6). Silver nitrate is used in HALIDE detection; hydrogen peroxide is an oxidant; sodium thiosulphate is used for iodine titrations (not acid-base).', 'EASY', 'Chemistry', 'Acids, Bases & pH', 'CHE_ACIDS_BASES', '[{"option_text": "Phenolphthalein", "is_correct": true}, {"option_text": "Silver nitrate", "is_correct": false}, {"option_text": "Hydrogen peroxide", "is_correct": false}, {"option_text": "Sodium thiosulphate", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('85e76725-ec43-5950-bb48-88ce24d4f69c', 'Which is the ONLY liquid metal at room temperature (25°C)?', NULL, 'MERCURY (Hg, atomic number 80) is the ONLY metal liquid at standard room temperature (~25°C). Melting point: −38.83°C. Also called ''quicksilver''. Used in thermometers, barometers, fluorescent lamps — but toxic, so being phased out (Minamata Convention 2013). GALLIUM (Ga, mp 29.76°C) — melts in your warm hand but SOLID at 25°C. CESIUM (mp 28.44°C) and RUBIDIUM (mp 39.31°C) also melt just above room temp but are SOLID at 25°C — and they''re highly reactive alkali metals. FRANCIUM (mp ~27°C estimated; highly radioactive). Among NON-METALS, BROMINE is the only element liquid at room temp (mp −7°C). So the other LIQUID element at RT is BROMINE (non-metal).', 'EASY', 'Chemistry', 'Metals & Properties', 'CHE_METALS', '[{"option_text": "Gallium", "is_correct": false}, {"option_text": "Mercury (Hg)", "is_correct": true}, {"option_text": "Cesium", "is_correct": false}, {"option_text": "Rubidium", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('55f8a565-d6e5-5d44-acf4-cc631a3c65d2', 'Brass is an alloy of:', NULL, 'Key alloys with compositions: BRASS = Cu (~70%) + Zn (~30%). BRONZE = Cu + Sn (tin) — the oldest alloy (Bronze Age ~3300 BCE). STEEL = Fe + C (< 2%). STAINLESS STEEL = Fe + Cr (11%+) + Ni. CAST IRON = Fe + C (2-4%). WROUGHT IRON = Fe + C (<0.2%). SOLDER = Pb + Sn (historically). PEWTER = Sn + Sb + Cu. DURALUMIN = Al + Cu + Mg + Mn (aircraft). MAGNALIUM = Al + Mg (light). NICHROME = Ni + Cr + Fe (heating elements). GERMAN SILVER (despite name, no silver) = Cu + Ni + Zn. MONEL = Ni + Cu. AMALGAM = any metal + Hg (dental fillings: Hg + Ag + Sn + Cu). WHITE GOLD = Au + Pd or Au + Ni. ROSE GOLD = Au + Cu.', 'EASY', 'Chemistry', 'Metals & Properties', 'CHE_METALS', '[{"option_text": "Copper and tin", "is_correct": false}, {"option_text": "Copper and zinc", "is_correct": true}, {"option_text": "Iron and carbon", "is_correct": false}, {"option_text": "Aluminium and magnesium", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a7097164-ad23-5843-a6a2-0caf328919cd', 'Which metal is extracted from the ore BAUXITE?', NULL, 'Metal-ore mapping: ALUMINIUM from BAUXITE (Al₂O₃·2H₂O) via Hall-Héroult electrolysis after Bayer process refining. IRON from HAEMATITE (Fe₂O₃, 70% Fe — main ore), MAGNETITE (Fe₃O₄), LIMONITE, SIDERITE (FeCO₃) — extracted in BLAST FURNACE. COPPER from CHALCOPYRITE (CuFeS₂ — main), COPPER PYRITES, MALACHITE (green Cu carbonate), AZURITE. ZINC from SPHALERITE / ZINC BLENDE (ZnS), CALAMINE (ZnCO₃), ZINCITE (ZnO). LEAD from GALENA (PbS). MERCURY from CINNABAR (HgS). TIN from CASSITERITE (SnO₂). SILVER from ARGENTITE (Ag₂S) + byproduct of Pb extraction. GOLD: native, in quartz veins. MAGNESIUM from DOLOMITE (MgCO₃·CaCO₃), MAGNESITE, seawater. URANIUM from PITCHBLENDE / URANINITE (UO₂), MONAZITE (also Th).', 'MEDIUM', 'Chemistry', 'Metals & Properties', 'CHE_METALS', '[{"option_text": "Copper", "is_correct": false}, {"option_text": "Aluminium", "is_correct": true}, {"option_text": "Zinc", "is_correct": false}, {"option_text": "Iron", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e2386703-ea96-584c-b234-45b848d26d4f', 'Galvanisation is a process in which iron is coated with which metal to prevent rusting?', NULL, 'GALVANISATION = coating iron with ZINC to prevent rusting. Zinc is more reactive than iron — acts as SACRIFICIAL PROTECTION (even if the zinc layer scratches, Zn corrodes preferentially). Hot-dip (most common) or electroplating. Used for GI sheets, pipes, nails, water tanks. TINNING = iron coated with TIN (less reactive, forms barrier; used for food cans — tin doesn''t react with most foods). Comparison corrosion protection methods: (1) GALVANISATION (Zn coat); (2) TINNING (Sn coat); (3) PAINTING / ENAMELLING; (4) ELECTROPLATING (Cu, Cr, Ni); (5) ALLOYING (stainless steel = Fe + Cr); (6) CATHODIC PROTECTION with a more reactive sacrificial anode (Mg bars on ship hulls).', 'EASY', 'Chemistry', 'Metals & Properties', 'CHE_METALS', '[{"option_text": "Copper", "is_correct": false}, {"option_text": "Zinc", "is_correct": true}, {"option_text": "Tin", "is_correct": false}, {"option_text": "Nickel", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('92399fbf-16ea-5dd9-a11a-20448df76900', 'Which metal has the HIGHEST electrical conductivity at room temperature?', NULL, 'Electrical conductivity (highest to lower among common metals): SILVER (Ag — highest), COPPER (Cu — 2nd, widely used due to lower cost), GOLD (Au — 3rd, used in fine electronics for corrosion resistance), ALUMINIUM (Al — lighter, used in overhead power lines), TUNGSTEN, ZINC, NICKEL. Heat conductivity has a similar order (Wiedemann-Franz law). Diamond (non-metal) actually has the highest THERMAL conductivity, but is an electrical INSULATOR. Among metals, silver is also the most REFLECTIVE (mirrors historically used silver backing). Superconductors (like Hg below 4.2K, YBa2Cu3O7 above 77K ''high-Tc'') have ZERO electrical resistance below critical temp.', 'MEDIUM', 'Chemistry', 'Metals & Properties', 'CHE_METALS', '[{"option_text": "Copper", "is_correct": false}, {"option_text": "Silver", "is_correct": true}, {"option_text": "Gold", "is_correct": false}, {"option_text": "Aluminium", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('20fe9023-8864-5e59-b431-18d766b8fa87', 'Stainless steel is primarily an alloy of iron with which two other metals?', NULL, 'STAINLESS STEEL = Fe + Chromium (≥ 10.5%) + Nickel (often 8%+) + small C. The chromium forms a passive Cr₂O₃ layer that prevents rusting — this is the ''stainless'' property. Discovered 1913 by Harry Brearley (Sheffield, UK). Grades: 304 (18-8 — most common, 18% Cr 8% Ni), 316 (adds Mo for marine corrosion), 410 (cutlery). Mo is sometimes added for acid resistance. Nichrome = Ni + Cr + Fe (heating coils). Invar = Fe + Ni (36% Ni — low thermal expansion, used in precision instruments). Kovar = Fe + Ni + Co (matches borosilicate glass expansion).', 'EASY', 'Chemistry', 'Metals & Properties', 'CHE_METALS', '[{"option_text": "Copper and zinc", "is_correct": false}, {"option_text": "Chromium and nickel", "is_correct": true}, {"option_text": "Aluminium and magnesium", "is_correct": false}, {"option_text": "Tin and lead", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('691170de-32b7-593f-b10e-f575d1b4f637', 'The process of heating an ore in the presence of EXCESS AIR to convert it into an oxide is called:', NULL, 'Metallurgy steps: (1) CRUSHING & GRINDING; (2) CONCENTRATION (froth flotation for sulphides, gravity separation, magnetic separation, leaching); (3) CONVERSION TO OXIDE: • ROASTING = heat in presence of EXCESS AIR (sulphide ores → oxides; e.g., 2ZnS + 3O₂ → 2ZnO + 2SO₂); • CALCINATION = heat in LIMITED / absence of air (carbonate/hydrate ores → oxides; e.g., ZnCO₃ → ZnO + CO₂ or CaCO₃ → CaO + CO₂ or Al₂O₃·xH₂O → Al₂O₃ + H₂O); (4) REDUCTION: • SMELTING (carbon reduction in blast furnace — for Fe, Cu, Zn, Pb); • ALUMINOTHERMIC (for Mn, Cr); • ELECTROLYSIS (for reactive metals — Al, Mg, Na); (5) REFINING (liquation, poling, electrolytic — Cu, Zn, Al, Ag, Au).', 'MEDIUM', 'Chemistry', 'Metals & Properties', 'CHE_METALS', '[{"option_text": "Calcination", "is_correct": false}, {"option_text": "Roasting", "is_correct": true}, {"option_text": "Smelting", "is_correct": false}, {"option_text": "Refining", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('85800b6a-6390-585e-b582-0b0a35cba4d4', 'The modern periodic table is arranged by:', NULL, 'DMITRI MENDELEEV (1869) first arranged elements by ATOMIC MASS — his periodic table had anomalies like Ar-K, Co-Ni, Te-I pairs where mass order didn''t match chemical behaviour. Henry MOSELEY (1913) discovered that arranging by ATOMIC NUMBER (Z — number of protons) resolves ALL such anomalies — formulated the ''Periodic Law'': physical and chemical properties are periodic functions of atomic number. Modern periodic table has 118 confirmed elements (last 4 — Nh Nihonium 113, Mc Moscovium 115, Ts Tennessine 117, Og Oganesson 118 — added Nov 2016). 7 PERIODS (rows) and 18 GROUPS (columns). s-block (Gp 1-2), p-block (Gp 13-18), d-block (Gp 3-12, transition metals), f-block (lanthanides + actinides).', 'EASY', 'Chemistry', 'Periodic Table & Periodicity', 'CHE_PERIODIC_TABLE', '[{"option_text": "Atomic mass (as Mendeleev originally proposed)", "is_correct": false}, {"option_text": "Atomic number (the Moseley arrangement)", "is_correct": true}, {"option_text": "Valency alone", "is_correct": false}, {"option_text": "Density", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('01424dbe-3514-5a0b-857f-1b8ac4fc36f5', 'The ''Noble Gases'' (Group 18) are characterised by:', NULL, 'NOBLE GASES (Group 18 / VIIIA / Inert gases): Helium, Neon, Argon, Krypton, Xenon, Radon (radioactive), Oganesson (super-heavy). Fully filled valence shell (He has 2 electrons — 1s²; others have 8 — ns² np⁶). Octet rule → extremely stable → inert under normal conditions. HIGHEST ionisation energy in each period. Abundance in air: N₂ (78%) > O₂ (21%) > ARGON (~0.93% — most abundant noble gas in air) > CO₂ (0.04%) > Ne + He + Kr + Xe (trace). Uses: HELIUM (balloons, MRI, low-temp cooling — non-flammable unlike hydrogen); NEON (advertising signs, red-orange colour); ARGON (inert gas shield for welding, light bulb filament filling); KRYPTON (runway lighting); XENON (car headlights, xenon arc lamps); RADON (health hazard in basements). Though ''inert'', Xe can form XeF₂, XeF₄, XeF₆ etc. under specific conditions (discovered 1962 by Bartlett).', 'EASY', 'Chemistry', 'Periodic Table & Periodicity', 'CHE_PERIODIC_TABLE', '[{"option_text": "Extreme reactivity", "is_correct": false}, {"option_text": "Full outer electron shell → very low chemical reactivity", "is_correct": true}, {"option_text": "Low ionisation energy", "is_correct": false}, {"option_text": "Strong metallic character", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('97513562-b436-5266-95c1-0b779360795d', 'Moving LEFT TO RIGHT across a period in the periodic table, which of the following GENERALLY INCREASES?', NULL, 'Periodic trends — across a PERIOD (left to right): (a) Atomic number ↑ (trivially); (b) ATOMIC RADIUS ↓ (effective nuclear charge increases, pulls electrons closer); (c) IONISATION ENERGY ↑ (harder to remove valence electron); (d) ELECTRONEGATIVITY ↑ (F is most electronegative, 3.98 on Pauling scale; noble gases excluded from scale); (e) ELECTRON AFFINITY ↑ (Cl has highest); (f) METALLIC CHARACTER ↓ (metal to non-metal transition); (g) Non-metallic character ↑; (h) Oxidation number ↑; (i) Number of shells UNCHANGED within a period. Down a GROUP: atomic radius ↑, metallic character ↑, ionisation energy ↓, electronegativity ↓.', 'MEDIUM', 'Chemistry', 'Periodic Table & Periodicity', 'CHE_PERIODIC_TABLE', '[{"option_text": "Atomic radius", "is_correct": false}, {"option_text": "Electronegativity and ionisation energy", "is_correct": true}, {"option_text": "Metallic character", "is_correct": false}, {"option_text": "Number of electron shells", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1ea3d576-20b9-5d87-919f-ccec306f0468', 'Which element has the HIGHEST electronegativity on the Pauling scale?', NULL, 'Electronegativity order (Pauling scale): F (3.98) > O (3.44) > Cl (3.16) ≈ N (3.04) > Br (2.96) > I (2.66) > S (2.58) > C (2.55) > H (2.20). FLUORINE is the MOST ELECTRONEGATIVE element (top-right, just before Ne). It''s also the smallest halogen with highest electron affinity in practice (Cl has numerically higher electron affinity due to F''s small size causing repulsion). LOWEST electronegativity: FRANCIUM (0.7) in Group 1 (bottom-left — most metallic, largest atom of stable elements). Noble gases (He, Ne, Ar) are generally not assigned electronegativities on the Pauling scale as they don''t commonly form bonds. Trend mnemonic: ''FONCL BrISCH'' for top-9 most electronegative.', 'MEDIUM', 'Chemistry', 'Periodic Table & Periodicity', 'CHE_PERIODIC_TABLE', '[{"option_text": "Chlorine", "is_correct": false}, {"option_text": "Fluorine", "is_correct": true}, {"option_text": "Oxygen", "is_correct": false}, {"option_text": "Nitrogen", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0bbfb572-71cf-544f-b9b9-dfbd51611e26', 'The LANTHANIDES (rare earth elements) occupy which positions in the periodic table?', NULL, 'LANTHANIDES (also called ''rare earths'' though not actually rare in Earth''s crust) — 15 elements from LANTHANUM (La, atomic number 57) to LUTETIUM (Lu, Z=71). Technically 14 + La = 15. Placed SEPARATELY at the bottom to avoid stretching the main table. f-block elements — their 4f orbitals are being filled. Part of Period 6. ACTINIDES (Z=89 Ac to 103 Lr) are the corresponding f-block Period 7 — all RADIOACTIVE, includes Uranium (Z=92), Plutonium (Z=94). Transuranic = beyond U (synthetic). India''s significant rare-earth reserves: KERALA beach monazite sands (Th, LREE) — one of the world''s richest. IREL (India Rare Earths Ltd) extracts these. Rare-earths critical for magnets (Nd-Fe-B), phosphors, batteries, EVs.', 'HARD', 'Chemistry', 'Periodic Table & Periodicity', 'CHE_PERIODIC_TABLE', '[{"option_text": "Group 3, Period 4 (4th row)", "is_correct": false}, {"option_text": "The separate bottom row (Period 6), elements 57 (La) to 71 (Lu)", "is_correct": true}, {"option_text": "Group 18 (Noble gases)", "is_correct": false}, {"option_text": "Period 7, bottom row", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8aea58e6-dad1-5c41-be7e-c496e9001b4d', 'Which element is named after India — the first chemical element named after an Asian country?', NULL, 'INDIUM (In, atomic number 49, Group 13) was discovered in 1863 by German chemists Ferdinand Reich and Hieronymous Theodor Richter at Freiberg. Named after the INDIGO (deep blue) colour line in its atomic emission spectrum — indirectly named after ''India''. Uses: transparent conductive indium tin oxide (ITO — used in all LCD/OLED screens, smartphones), low-melting alloys, solders. Other country-origin element names: GERMANIUM (Germany, Winkler 1886), GALLIUM (Gallia = Latin for France, Boisbaudran 1875), POLONIUM (Poland — Marie Curie named after her homeland, 1898), FRANCIUM (France — Marguerite Perey 1939), AMERICIUM (Americas), CALIFORNIUM (California), RUTHENIUM (Rus — Russia), EUROPIUM, COPERNICIUM, FLEROVIUM, DUBNIUM, TENNESSINE, NIHONIUM (Japan), MOSCOVIUM. Person-named: EINSTEINIUM, FERMIUM, MENDELEVIUM, BOHRIUM, SEABORGIUM, RUTHERFORDIUM etc.', 'HARD', 'Chemistry', 'Periodic Table & Periodicity', 'CHE_PERIODIC_TABLE', '[{"option_text": "Einsteinium", "is_correct": false}, {"option_text": "Indium", "is_correct": true}, {"option_text": "Gallium", "is_correct": false}, {"option_text": "Mendelevium", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a7bbc764-4a85-51bf-a160-920b0cc14c44', 'Which element has the symbol ''Au'' and atomic number 79?', NULL, 'GOLD — symbol Au (from Latin ''aurum'' = shining dawn), atomic number 79. Transition metal (Group 11, Period 6). Latin-origin element symbols students must know: Au (Aurum — Gold), Ag (Argentum — Silver), Cu (Cuprum — Copper), Fe (Ferrum — Iron), Pb (Plumbum — Lead), Sn (Stannum — Tin), Hg (Hydrargyrum — Mercury, ''liquid silver''), K (Kalium — Potassium), Na (Natrium — Sodium), Sb (Stibium — Antimony), W (Wolfram — Tungsten). Greek-origin: many. Trivia: Gold is the most malleable/ductile metal — 1 gram can be drawn into 2.4 km of wire, or hammered into 1 m² sheet.', 'EASY', 'Chemistry', 'Periodic Table & Periodicity', 'CHE_PERIODIC_TABLE', '[{"option_text": "Silver", "is_correct": false}, {"option_text": "Gold", "is_correct": true}, {"option_text": "Aluminium", "is_correct": false}, {"option_text": "Argon", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e3a5acc0-a193-536e-a524-4e724e030a9b', 'After the April 2020 PSU bank merger, how many Public Sector Banks remain in India?', NULL, 'Post April 2020 mega-merger, India has 12 Public Sector Banks (PSBs): (1) SBI, (2) PNB, (3) BoB, (4) Canara, (5) Union Bank of India, (6) Indian Bank, (7) Bank of India, (8) Bank of Maharashtra, (9) Central Bank of India, (10) Indian Overseas Bank, (11) Punjab & Sind Bank, (12) UCO Bank. The April 2020 round merged: PNB+OBC+United → PNB; Canara+Syndicate → Canara; Union+Andhra+Corp → Union; Indian+Allahabad → Indian. Earlier consolidations: SBI+5 associates+BMB (2017), BoB+Vijaya+Dena (2019).', 'EASY', 'Economics', 'Commercial Banking System & NPAs', 'ECO_BANKING', '[{"option_text": "10", "is_correct": false}, {"option_text": "12", "is_correct": true}, {"option_text": "14", "is_correct": false}, {"option_text": "17", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('dd587aa0-bfd3-51b3-b518-5b2799ccd4ea', 'A loan account is classified as a Non-Performing Asset (NPA) in India if interest or principal remains overdue for more than:', NULL, 'Per RBI''s Prudential Norms on Income Recognition, Asset Classification and Provisioning (IRAC), an account becomes NPA if interest/principal remains overdue for MORE THAN 90 DAYS for term loans (was 180 days before 2004; aligned with international norms). For agricultural loans, 2 crop seasons for short-duration crops / 1 for long-duration. Sub-categories: Sub-standard (NPA up to 12 months), Doubtful (NPA > 12 months), Loss asset (unrecoverable). Recognised GROSS NPA minus provisions = NET NPA. Total NPAs fell from 11.2% in 2018 to ~2.6% in 2024 (lowest in a decade).', 'EASY', 'Economics', 'Commercial Banking System & NPAs', 'ECO_BANKING', '[{"option_text": "30 days", "is_correct": false}, {"option_text": "60 days", "is_correct": false}, {"option_text": "90 days", "is_correct": true}, {"option_text": "180 days", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bddbeb33-a0e5-5d85-a4d5-b5e7bdf65a24', 'The Insolvency and Bankruptcy Code (IBC) was enacted in which year and what is the target resolution period?', NULL, 'IBC 2016 (effective 28 May 2016) unified India''s bankruptcy laws. Under Corporate Insolvency Resolution Process (CIRP): 180-day initial period + one-time 90-day extension = MAX 270 days (extended to 330 days by 2019 amendment, including litigation time). Key institutions: IBBI (regulator), NCLT (adjudicating authority for corporates), NCLAT (appellate), IPAs (Insolvency Professional Agencies), Information Utilities. Notable cases: Essar Steel (resolved), Bhushan Steel (Tata took over), DHFL (Piramal bought).', 'HARD', 'Economics', 'Commercial Banking System & NPAs', 'ECO_BANKING', '[{"option_text": "2013; 180+180 days", "is_correct": false}, {"option_text": "2016; 180+90 days (total 270 days)", "is_correct": true}, {"option_text": "2017; 360 days max", "is_correct": false}, {"option_text": "2018; 120 days", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a0fc28da-3933-5355-9bda-f1be8ca6dc88', 'Under Basel III norms implemented in India, what is the minimum Capital Adequacy Ratio (CRAR) required for a Scheduled Commercial Bank (SCB)?', NULL, 'Basel III (global regulatory framework, implemented in India from 2013 onwards by RBI) prescribes MINIMUM CAR/CRAR = 9% for SCBs (higher than Basel''s own 8% — India applied a stricter buffer). Additional requirement: Capital Conservation Buffer of 2.5% (so effective minimum 11.5%) + Counter-Cyclical Capital Buffer 0-2.5%. Tier 1 + Tier 2 capital / Risk Weighted Assets. For SFBs: 15% (with Tier 1 ≥ 7.5%). For UCBs: 9% (Tier 1) + 12% (Total, for Tier-2/3/4).', 'MEDIUM', 'Economics', 'Commercial Banking System & NPAs', 'ECO_BANKING', '[{"option_text": "8%", "is_correct": false}, {"option_text": "9%", "is_correct": true}, {"option_text": "11.5%", "is_correct": false}, {"option_text": "12%", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('dbf80c9f-ce04-5438-b2ee-9c3d41f4390c', 'Which of the following is NOT a Small Finance Bank (SFB) in India?', NULL, 'Bandhan Bank was initially an NBFC-MFI, became a UNIVERSAL COMMERCIAL BANK (not an SFB) when it received a banking license in 2015 — technically a Private Sector Bank. The 10 SFBs in India (original 10 licensees, 2015): AU, Capital, Equitas, ESAF, Fincare, Jana, North East, Suryoday, Ujjivan, Utkarsh. Shivalik Small Finance Bank became the 11th when it transitioned in 2021. Unity Small Finance Bank became the 12th (acquired PMC Bank in 2022). SFBs must lend 75% to priority sector (vs 40% for commercial banks) and 50% loans must be ≤ ₹25 lakh.', 'HARD', 'Economics', 'Commercial Banking System & NPAs', 'ECO_BANKING', '[{"option_text": "AU Small Finance Bank", "is_correct": false}, {"option_text": "Equitas Small Finance Bank", "is_correct": false}, {"option_text": "Ujjivan Small Finance Bank", "is_correct": false}, {"option_text": "Bandhan Bank", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5035b166-1229-5eb4-a82e-1eace9484997', 'The SARFAESI Act, 2002, empowers banks to recover bad loans WITHOUT court intervention. What does SARFAESI stand for?', NULL, 'SARFAESI = Securitisation and Reconstruction of Financial Assets and Enforcement of Security Interest Act, 2002. Allows banks/FIs to: (1) securitise assets; (2) set up Asset Reconstruction Companies (ARCs); (3) enforce security interest WITHOUT court intervention — attach and sell defaulter''s mortgaged assets after 60-day notice. Applies to loans above ₹1 lakh (now ₹20 lakh by 2021 amendment). Not applicable to: agricultural land, loans ≤ ₹1 lakh, and where 80% of loan is repaid. Critical tool alongside IBC 2016 for NPA resolution.', 'HARD', 'Economics', 'Commercial Banking System & NPAs', 'ECO_BANKING', '[{"option_text": "Securities and Reconstruction of Financial Assets & Enforcement of Security Interest", "is_correct": true}, {"option_text": "State Audit and Recovery Finance Act for Enforcement of Secured Instruments", "is_correct": false}, {"option_text": "Secured Assets Recovery and Financial Enforcement of Special Instruments", "is_correct": false}, {"option_text": "Scheduled Accounts Recovery by Financial Establishments & Secured Interest", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('08544e07-fc83-56d5-ad7a-40d22b26008c', 'The Narasimham Committee (I, 1991), whose recommendations reshaped Indian banking in the 1990s, was headed by:', NULL, 'M. Narasimham (1927-2021) — 13th RBI Governor (1977) and later Finance Secretary — chaired: (1) Narasimham Committee I (1991, post-BoP crisis) → recommended reducing SLR to 25%, CRR to 3-8%, phased interest rate deregulation, ending ''directed credit'', prudential NPA norms, and phased banking deregulation; (2) Narasimham Committee II (1998) → further reforms: mergers of strong banks, restructured boards, asset reconstruction, Basel II. He is called the ''Father of Indian Banking Reforms''. ''Father of Economic Reforms'' is Manmohan Singh as FM 1991-96.', 'HARD', 'Economics', 'Commercial Banking System & NPAs', 'ECO_BANKING', '[{"option_text": "M. Narasimha Rao (former PM)", "is_correct": false}, {"option_text": "M. Narasimham (former RBI Governor)", "is_correct": true}, {"option_text": "N. Narasimhan (former Cabinet Secretary)", "is_correct": false}, {"option_text": "PVN Narasimhan (first NABARD chairman)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b2ba079a-d807-54d8-bdcd-b979b04c05ef', 'Which Indian bank was the first to be established and is considered the oldest surviving bank?', NULL, 'SBI''s family tree: Bank of Calcutta (2 June 1806) → renamed Bank of Bengal (1809) → merged with Bank of Bombay (1840) and Bank of Madras (1843) to form Imperial Bank of India (1921) → nationalised as STATE BANK OF INDIA by SBI Act 1955. So SBI is the OLDEST surviving bank via Bank of Calcutta (1806). Bank of Hindustan (1770) was EARLIER but defunct by 1832. Allahabad Bank (1865) was India''s first FULLY INDIAN-MANAGED joint-stock bank; it merged into Indian Bank in 2020. Punjab National Bank (1894) — first bank fully managed by Indians.', 'HARD', 'Economics', 'Commercial Banking System & NPAs', 'ECO_BANKING', '[{"option_text": "State Bank of India", "is_correct": false}, {"option_text": "Bank of Hindustan", "is_correct": false}, {"option_text": "Allahabad Bank (1865)", "is_correct": false}, {"option_text": "State Bank of India via its predecessor Bank of Calcutta (1806)", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a7f53985-37f7-5fad-ac40-516e7b19a6a5', 'Bank nationalisation in India happened in two phases. Which year did the SECOND phase of bank nationalisation occur?', NULL, 'FIRST phase: 19 July 1969 — Indira Gandhi nationalised 14 major private banks (those with deposits > ₹50 crore) via the Banking Companies Ordinance 1969. Banks included: Central BoI, BoI, PNB, BoB, UCO, Canara, Dena, Syndicate, Union, Allahabad, Indian, Indian Overseas, BoM, United Bank. SECOND phase: 15 April 1980 — 6 more private banks with deposits > ₹200 crore nationalised (Andhra Bank, Corporation, New Bank of India merged later with PNB, Oriental Bank, Punjab & Sind, Vijaya). Result: ~91% of banking system became public sector by 1980. Liberalisation in 1991 allowed new private banks (HDFC, ICICI, Axis etc.).', 'MEDIUM', 'Economics', 'Commercial Banking System & NPAs', 'ECO_BANKING', '[{"option_text": "1969", "is_correct": false}, {"option_text": "1980", "is_correct": true}, {"option_text": "1991", "is_correct": false}, {"option_text": "1993", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ee20051a-2003-5e1c-a21d-bb355652b122', 'Which of the following is a regulator of NBFCs in India?', NULL, 'NBFCs (Non-Banking Financial Companies) are regulated by RBI. Scale-Based Regulation (SBR) framework (effective Oct 2022) classifies NBFCs into 4 layers: (1) BASE Layer — smaller NBFCs (<₹1000 Cr assets) — minimum NOF ₹10 Cr by March 2027; (2) MIDDLE Layer; (3) UPPER Layer (identified by RBI as systemically important); (4) TOP Layer (reserved for extreme systemic risk cases). Types: AFC (Asset Finance), LC (Loan), ICC (Investment & Credit), IFC (Infrastructure Finance), MGC (Mortgage Guarantee), MFI (MicroFinance), HFC (Housing Finance — now regulated by RBI from NHB since 2019). SEBI regulates mutual funds/stock markets; IRDAI regulates insurance; PFRDA regulates pensions.', 'MEDIUM', 'Economics', 'Commercial Banking System & NPAs', 'ECO_BANKING', '[{"option_text": "SEBI", "is_correct": false}, {"option_text": "RBI", "is_correct": true}, {"option_text": "IRDAI", "is_correct": false}, {"option_text": "PFRDA", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d8e22460-919e-5173-b0fc-abd4dc3ad196', 'The Balance of Payments (BoP) of a country records all economic transactions between residents of the country and the rest of the world over a specified period. The two principal accounts of the BoP are:', NULL, 'Balance of Payments has TWO principal accounts: (1) CURRENT ACCOUNT — records trade in goods and services plus primary income (investment income, compensation of employees) and secondary income (current transfers, remittances); (2) CAPITAL ACCOUNT / FINANCIAL ACCOUNT — records transactions in financial assets/liabilities (FDI, FPI, loans, reserves). Option D is close but ''Trade Account'' (goods only) and ''Invisibles Account'' are SUB-PARTS of the Current Account, not the principal accounts themselves. ''Revenue Account'' (option A) is a budget/government-accounting term, not BoP. Option C conflates fiscal vs monetary policy — different concept entirely.', 'EASY', 'Economics', 'Balance of Payments (BoP)', 'ECO_BOP', '[{"option_text": "Revenue Account and Capital Account", "is_correct": false}, {"option_text": "Current Account and Capital Account", "is_correct": true}, {"option_text": "Fiscal Account and Monetary Account", "is_correct": false}, {"option_text": "Trade Account and Invisibles Account", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0b206a9d-df85-5045-8219-ea94f59977ad', 'In India''s Balance of Payments accounting, which of the following is recorded under the CURRENT ACCOUNT (not the Capital Account)?', NULL, 'Remittances (private transfers) are classified under the Current Account''s SECONDARY INCOME (also called Current Transfers) sub-heading — they don''t create any claim or liability, so they aren''t capital-account items. FDI (option A) creates an ownership stake → capital account. ECB (option C) creates a debt liability → capital account. Sale of overseas real estate (option D) is a disposal of an asset → capital account. India is historically the world''s largest recipient of remittances (~USD 125 billion in recent years from migrant workers in Gulf, USA, UK) — a crucial BoP cushion.', 'MEDIUM', 'Economics', 'Balance of Payments (BoP)', 'ECO_BOP', '[{"option_text": "Foreign Direct Investment (FDI) inflow", "is_correct": false}, {"option_text": "Remittances sent by an NRI in the USA to family in India", "is_correct": true}, {"option_text": "External Commercial Borrowings (ECB) taken by an Indian company", "is_correct": false}, {"option_text": "Sale of a real-estate property abroad by an Indian resident", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('798de2d2-b858-553e-9ba0-4f21a6c2c0df', 'India''s MERCHANDISE TRADE DEFICIT (goods imports > goods exports) is persistently financed by which category of Current-Account INFLOWS?', NULL, 'India structurally runs a MERCHANDISE (goods) trade deficit — roughly USD 250 bn/year in recent years, driven by crude-oil imports. The deficit is LARGELY financed by strong NET INVISIBLES EARNINGS (services + remittances): (i) IT/BPM services exports (~USD 200 bn/year); (ii) remittances (~USD 125 bn); (iii) tourism. Combined, these offset most of the goods deficit and keep the overall Current Account Deficit (CAD) manageable (~1-2 % of GDP in normal years). FDI (option A) is Capital Account, not Current. Option C is a Capital Account transaction. Option D is a domestic instrument — not a BoP item.', 'MEDIUM', 'Economics', 'Balance of Payments (BoP)', 'ECO_BOP', '[{"option_text": "FDI inflows only", "is_correct": false}, {"option_text": "Net INVISIBLES — primarily remittances, software services exports, and tourism earnings", "is_correct": true}, {"option_text": "RBI''s sale of government securities to foreign buyers", "is_correct": false}, {"option_text": "Sovereign gold bonds floated domestically", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('09c13cd6-e8ea-54da-8dd6-d2987918d499', 'If India''s Current Account Deficit (CAD) + Capital Account Surplus = positive overall balance, the RBI typically responds by:', NULL, 'BoP identity: Current Account + Capital Account = 0 (when you include the official reserve transactions). If CAD (−) is MORE THAN OFFSET by Capital Account Surplus (+), there''s a net dollar inflow into the economy. To prevent excessive INR appreciation, RBI INTERVENES by BUYING the excess USD from the market, accumulating forex reserves. The reverse happens when CAD exceeds inflows — RBI sells reserves to protect the INR. India''s forex reserves crossed USD 650 bn in 2024, among the world''s largest. Option A is the opposite response. Option C describes naive monetary expansion — RBI sterilises such INR creation via OMOs. Option D is not a policy tool.', 'HARD', 'Economics', 'Balance of Payments (BoP)', 'ECO_BOP', '[{"option_text": "Selling foreign exchange reserves to tighten forex supply", "is_correct": false}, {"option_text": "Buying foreign exchange from the market, ADDING to its forex reserves", "is_correct": true}, {"option_text": "Printing INR to match the dollar inflow", "is_correct": false}, {"option_text": "Mandating all Indian exporters to convert to INR immediately", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b865bd33-6dc2-5030-805e-3a12cb2745bb', 'Which of the following transactions would IMPROVE (increase the surplus / reduce the deficit of) India''s CURRENT account?', NULL, 'Services exports = Current Account CREDIT (inflow of foreign exchange for services rendered) → improves CAD. Option A is a merchandise import → Current Account DEBIT → WORSENS the deficit. Options C and D are CAPITAL Account transactions (bond purchases and loans create liabilities) → don''t directly affect the Current Account (though they finance it). The Current Account cares about ''real'' flows — goods, services, income, transfers. Capital Account cares about changes in asset positions.', 'EASY', 'Economics', 'Balance of Payments (BoP)', 'ECO_BOP', '[{"option_text": "An Indian auto company imports machinery from Germany", "is_correct": false}, {"option_text": "An Indian software firm exports services to a US client", "is_correct": true}, {"option_text": "Foreign investors buy Indian government bonds", "is_correct": false}, {"option_text": "The government takes a loan from the IMF", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('009d1118-b6c3-53dd-b466-c215e5f43daa', 'Match each BoP sub-component with the correct principal account and pick the correct pairing:
(i) Merchandise trade — Current Account
(ii) Software services exports — Current Account
(iii) Foreign Portfolio Investment (FPI) — Capital Account
(iv) NRI remittances — Current Account', NULL, 'ALL four pairings are correct. CURRENT Account: merchandise trade (goods), services (incl. software exports), primary income (compensation, investment income), secondary income (remittances, grants). CAPITAL Account (or Financial Account in IMF terminology): FDI, FPI, External Commercial Borrowings, loans, banking capital, changes in reserves. Memorising ''which side of the BoP does X go on'' is the #1 drill for Economics GK in Bank exams. Classic confusion: remittances feel like money transfer (capital-ish), but they''re UNREQUITED transfers with no asset-liability creation, so Current Account.', 'HARD', 'Economics', 'Balance of Payments (BoP)', 'ECO_BOP', '[{"option_text": "Only (i) and (ii) correctly paired", "is_correct": false}, {"option_text": "Only (i), (ii), (iii) correctly paired", "is_correct": false}, {"option_text": "All four (i), (ii), (iii), (iv) correctly paired", "is_correct": true}, {"option_text": "Only (iii) correctly paired", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d236cf95-23f5-5f58-b2df-8223a9129a58', 'The term ''TWIN DEFICIT'' — a recurring concern in Indian macroeconomic discussions — refers to simultaneous:', NULL, 'TWIN DEFICIT = FISCAL DEFICIT + CURRENT ACCOUNT DEFICIT occurring together. The concern: a government running a fiscal deficit borrows → if borrowing is large and savings are low, the economy has to attract foreign capital → pressures INR → can push the CAD up. Worst case: a ''spiral'' where both deficits self-reinforce. Notable Indian episodes: 1991 BoP crisis, 2013 ''taper tantrum'' crisis. Option B is rare/impossible structurally — a CAD is typically FINANCED by a Capital Account Surplus, so they''re usually opposite signs. Options C and D describe other fiscal-terminology deficits.', 'HARD', 'Economics', 'Balance of Payments (BoP)', 'ECO_BOP', '[{"option_text": "Fiscal deficit (Revenue + Capital expenditure > Revenue receipts + non-debt capital receipts) AND Current Account Deficit", "is_correct": true}, {"option_text": "Current Account Deficit AND Capital Account Deficit", "is_correct": false}, {"option_text": "Trade Deficit AND Invisibles Deficit", "is_correct": false}, {"option_text": "Primary Deficit AND Revenue Deficit", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('dcd29f9f-42de-5b7d-af4e-4785f56cb6f8', 'In the IMF''s BoP Manual (BPM6) — which India follows — the CAPITAL ACCOUNT and the FINANCIAL ACCOUNT are treated as:', NULL, 'Under IMF BPM6 (used by the RBI): CAPITAL ACCOUNT is narrow — it covers (a) capital transfers like debt forgiveness, migrants'' transfers, government-to-government grants; (b) non-produced non-financial assets (e.g. patents sold to a foreign party). FINANCIAL ACCOUNT is much larger — FDI, FPI, External Debt, Banking Capital, Rupee Debt Service, Other Capital, and changes in RBI Reserves. Many Indian textbooks (pre-BPM6) used ''Capital Account'' loosely to mean what is now ''Financial Account'' — this is a common exam trap. RBI''s monthly BoP release uses the modern BPM6 definitions.', 'HARD', 'Economics', 'Balance of Payments (BoP)', 'ECO_BOP', '[{"option_text": "Completely identical terms used interchangeably", "is_correct": false}, {"option_text": "Distinct — ''Capital Account'' covers capital transfers (e.g. debt forgiveness) and non-produced non-financial assets; ''Financial Account'' covers financial asset/liability transactions (FDI, FPI, loans, reserves)", "is_correct": true}, {"option_text": "''Capital Account'' was renamed to ''Current Transfer Account'' in BPM6", "is_correct": false}, {"option_text": "''Financial Account'' refers to purely domestic banking", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f722c2ce-f3ed-5193-8b04-2dd9b2c9f329', 'The 1991 BALANCE OF PAYMENTS CRISIS in India was famously resolved after the government pledged GOLD to secure a short-term loan from which international authority?', NULL, 'In 1991, India''s forex reserves had crashed to ~USD 1.2 bn (about 2 weeks of imports). The Chandra Shekhar government (May 1991) pledged 47 tonnes of gold to the Bank of England; the subsequent Rao-Manmohan Singh government (July 1991) pledged another 20 tonnes to the Bank of Japan — raising ~USD 600 mn to avert default. The crisis triggered the 1991 economic reforms (LPG — Liberalisation, Privatisation, Globalisation). The IMF ALSO provided a Stand-By Arrangement but the short-term gold-pledge was the immediate rescue. World Bank and ADB gave longer-term project finance but weren''t the emergency bridge. This episode is a GA staple — memorise 1991, gold, and ''LPG reforms''.', 'MEDIUM', 'Economics', 'Balance of Payments (BoP)', 'ECO_BOP', '[{"option_text": "The World Bank", "is_correct": false}, {"option_text": "The Bank of England (and later the Bank of Japan) against a physical gold pledge", "is_correct": true}, {"option_text": "The Asian Development Bank", "is_correct": false}, {"option_text": "The Federal Reserve Bank of the United States", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0cd0617b-14d7-5a8a-a685-ab512fb23afb', 'Which of the following is the CORRECT definition of ''BoP SURPLUS'' under a floating exchange-rate regime like India''s?', NULL, 'Conceptually the BoP is split into AUTONOMOUS (voluntary, profit-motivated) transactions and ACCOMMODATING (balancing, via official reserves) transactions. A ''BoP surplus'' is informally the excess of autonomous inflows over outflows — which the central bank accommodates by buying forex and INCREASING reserves. Technically, when reserves are included, the BoP sums to zero (accounting identity). Option A confuses the identity with economic meaning. Option C conflates fiscal policy with BoP. Option D describes balanced trade, not BoP surplus (services, transfers, capital flows all matter too).', 'HARD', 'Economics', 'Balance of Payments (BoP)', 'ECO_BOP', '[{"option_text": "An ACCOUNTING impossibility — BoP always balances to zero by construction", "is_correct": false}, {"option_text": "The situation where total autonomous transactions produce a net inflow, leading to RESERVE ACCUMULATION by the central bank", "is_correct": true}, {"option_text": "The situation where the government runs a fiscal surplus", "is_correct": false}, {"option_text": "The situation where exports exactly equal imports", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9c3665cb-5f2d-5275-a6cf-aa6ff8e39967', 'Which of the following Indian authorities PUBLISHES the quarterly Balance of Payments data and the annual India''s External Debt Status Report?', NULL, 'RBI publishes BoP data QUARTERLY in its Development in India''s BoP release. India''s External Debt Status Report is published QUARTERLY jointly by the Ministry of Finance (Economic Affairs Dept.) and RBI — the latter maintains the external-debt database. These releases are public, freely downloadable, and are the canonical source for all macro analysis of India''s external accounts. Option A undersells RBI''s role. Options C and D describe authorities with no direct role in BoP accounting.', 'MEDIUM', 'Economics', 'Balance of Payments (BoP)', 'ECO_BOP', '[{"option_text": "Ministry of Finance only", "is_correct": false}, {"option_text": "Reserve Bank of India (BoP data) and Ministry of Finance (External Debt Report jointly with RBI)", "is_correct": true}, {"option_text": "Ministry of Commerce and NITI Aayog", "is_correct": false}, {"option_text": "SEBI and IRDAI", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('af304be7-689f-56c5-86b9-c175cd1d3739', 'Which of the following is NOT a determinant typically used to assess if a country''s Current Account Deficit is ''SUSTAINABLE''?', NULL, 'The three canonical sustainability tests for CAD: (i) CAD as % of GDP — below 3 % is considered manageable in emerging markets; (ii) QUALITY of financing — stable FDI (long-term, equity) better than FPI (short-term, ''hot money'' that can reverse suddenly); (iii) Forex reserve adequacy — reserves covering 6-9 months of imports provide a cushion. Unemployment of PhDs (option D) has NO direct BoP-sustainability linkage — pure distractor. India''s CAD was 1.2 % of GDP in FY24, financed largely by stable FDI + remittances — currently comfortable.', 'MEDIUM', 'Economics', 'Balance of Payments (BoP)', 'ECO_BOP', '[{"option_text": "CAD as % of GDP (commonly safe threshold < 3 %)", "is_correct": false}, {"option_text": "Composition of deficit financing (FDI preferred over ''hot money'' FPI)", "is_correct": false}, {"option_text": "Stock of forex reserves (months of imports covered)", "is_correct": false}, {"option_text": "The domestic unemployment rate among PhD holders", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0d94094a-dc47-5542-b7b5-3507948ed067', 'Which of the following best defines inflation?', NULL, 'Inflation is a SUSTAINED rise in the GENERAL price level — not a one-off change or a sectoral change. It erodes the purchasing power of money: the same rupee buys fewer goods over time. Measured via indices like CPI and WPI. A single commodity''s price rise (e.g., tomatoes in monsoon) is NOT inflation if average prices are stable. An increase in nominal currency value is the opposite (deflation/currency strengthening).', 'EASY', 'Economics', 'Inflation & Business Cycle', 'ECO_INFLATION', '[{"option_text": "A one-time increase in the price of a single commodity", "is_correct": false}, {"option_text": "A sustained rise in the general price level of goods and services in an economy", "is_correct": true}, {"option_text": "A decrease in the production of goods", "is_correct": false}, {"option_text": "An increase in the nominal value of currency", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('540b43a8-060e-57f4-975d-539fc1165d71', 'In India, which of the following is the primary inflation index used by the RBI for its monetary policy decisions?', NULL, 'Since 2014 (Urjit Patel Committee + 2016 Monetary Policy Framework Agreement), the RBI targets HEADLINE CPI-Combined (released by NSO/MoSPI) with a central target of 4% ± 2%. WPI (Office of Economic Adviser, DPIIT) is used for deflating GDP at constant prices and tracking producer prices, but NOT as the RBI''s policy target. CPI-IW (Labour Bureau) is used for DA calculations for govt employees, not RBI targeting.', 'MEDIUM', 'Economics', 'Inflation & Business Cycle', 'ECO_INFLATION', '[{"option_text": "WPI (Wholesale Price Index)", "is_correct": false}, {"option_text": "CPI-Combined (Consumer Price Index)", "is_correct": true}, {"option_text": "CPI-IW (Industrial Workers)", "is_correct": false}, {"option_text": "IIP (Index of Industrial Production)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('408aaba2-0343-5b9f-8f2d-413894d2499c', 'Which of the following is an example of ''cost-push'' inflation?', NULL, 'COST-PUSH inflation arises when input costs (raw materials, wages, fuel) rise and producers pass this on to consumers. Classic example: oil shocks (1973 OPEC crisis, 2008 oil spike). DEMAND-PULL inflation arises when aggregate demand exceeds supply (option A — festival demand surge). Excess money printing is typically classified as demand-pull/monetary inflation (option C). A stock rally is asset-price inflation, not general inflation.', 'MEDIUM', 'Economics', 'Inflation & Business Cycle', 'ECO_INFLATION', '[{"option_text": "A boom in consumer demand during a festival", "is_correct": false}, {"option_text": "A sharp increase in crude oil prices raising transport and production costs", "is_correct": true}, {"option_text": "Government printing excess money", "is_correct": false}, {"option_text": "A stock market rally", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c385d32d-e5d0-574c-b913-9b0ecc3b8c40', 'What is the current inflation target band set for the RBI under the Monetary Policy Framework Agreement?', NULL, 'The RBI''s flexible inflation targeting framework sets a MEDIUM-TERM target of 4% CPI-Combined, with a tolerance band of ±2 percentage points (lower bound 2%, upper bound 6%). This was first set in 2016 (initial 5-year review) and was retained at the March 2021 review for another 5 years (2021-26). If inflation breaches the band for three consecutive quarters, the RBI must report to the government explaining reasons and remedial actions.', 'MEDIUM', 'Economics', 'Inflation & Business Cycle', 'ECO_INFLATION', '[{"option_text": "2% ± 1% (i.e., 1% to 3%)", "is_correct": false}, {"option_text": "4% ± 2% (i.e., 2% to 6%)", "is_correct": true}, {"option_text": "5% ± 3% (i.e., 2% to 8%)", "is_correct": false}, {"option_text": "6% (hard ceiling)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('dadb98a1-b508-5061-98bc-8d41579e7690', 'Galloping inflation refers to inflation of:', NULL, 'Inflation categories: (1) Creeping/Mild — <3%; (2) Walking/Trotting — 3-10%; (3) GALLOPING/Running — 10-1000%; (4) Hyperinflation — >1000% per year (e.g., Weimar Germany 1923, Zimbabwe 2008, Venezuela 2018). Galloping inflation disrupts business planning and wage contracts. Deflation is NEGATIVE inflation (falling prices) and is generally considered a warning sign of slump.', 'HARD', 'Economics', 'Inflation & Business Cycle', 'ECO_INFLATION', '[{"option_text": "0 to 3% annually", "is_correct": false}, {"option_text": "3 to 10% annually", "is_correct": false}, {"option_text": "10 to 1000% annually", "is_correct": true}, {"option_text": "Below 0% (deflation)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ba792cb6-dd6f-5eea-929e-da61a306299f', 'Which of the following is a MONETARY POLICY tool that the RBI uses to control inflation?', NULL, 'MONETARY policy tools are used by the CENTRAL BANK (RBI). Key tools: Repo Rate, Reverse Repo Rate, MSF, Bank Rate, CRR, SLR, OMO (Open Market Operations). Changing Repo Rate (lending rate for banks to RBI) influences bank interest rates → consumer borrowing/saving → aggregate demand → inflation. Income Tax is a FISCAL POLICY tool (Finance Ministry). Government bonds are fiscal. MSP is set by Cabinet on CACP recommendation — neither monetary nor a direct fiscal tool.', 'EASY', 'Economics', 'Inflation & Business Cycle', 'ECO_INFLATION', '[{"option_text": "Raising or lowering Income Tax rates", "is_correct": false}, {"option_text": "Changing the Repo Rate", "is_correct": true}, {"option_text": "Issuing Union Government bonds", "is_correct": false}, {"option_text": "Adjusting MSP for agricultural commodities", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a56b52c0-de9b-5908-8c23-411c346f5fd9', '''Stagflation'' refers to which economic condition?', NULL, 'STAGFLATION = STAGnation + inFLATION. It is the coexistence of (1) slow/zero economic growth, (2) high inflation, and (3) elevated unemployment. It challenges the classical Phillips-curve view that inflation and unemployment trade off. Famous example: US in 1970s during oil shocks. Policymakers face a dilemma: tightening money controls inflation but worsens unemployment; loosening controls does the opposite.', 'MEDIUM', 'Economics', 'Inflation & Business Cycle', 'ECO_INFLATION', '[{"option_text": "High growth with rising prices", "is_correct": false}, {"option_text": "Low/stagnant growth accompanied by high inflation and unemployment", "is_correct": true}, {"option_text": "Declining prices with rising output", "is_correct": false}, {"option_text": "Stable prices combined with zero unemployment", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d106ab57-ce95-5b9b-b9dc-70b6215e9d79', 'The business cycle typically consists of four phases. Which phase is characterized by declining output, rising unemployment, and falling prices?', NULL, 'Business cycle phases: (1) EXPANSION — GDP rising, employment up, prices rising modestly; (2) PEAK — growth at maximum, economy overheated; (3) CONTRACTION/RECESSION — GDP falling, unemployment rising, prices falling or rising slowly; (4) TROUGH — economy at its bottom before recovery. A recession is technically defined as TWO consecutive quarters of negative real GDP growth (NBER uses broader criteria). Great Depression (1929-33) was a severe contraction.', 'EASY', 'Economics', 'Inflation & Business Cycle', 'ECO_INFLATION', '[{"option_text": "Expansion", "is_correct": false}, {"option_text": "Peak", "is_correct": false}, {"option_text": "Contraction/Recession", "is_correct": true}, {"option_text": "Trough", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('71a879bf-2ac3-54dc-8b0e-1ceda9a1dce6', 'Which of the following best describes ''core inflation''?', NULL, 'CORE INFLATION strips out volatile items (food and fuel) from headline CPI to reveal underlying inflation trends driven by broader demand-supply conditions. Food/fuel are excluded because they swing due to monsoons, crude shocks, etc. — noise that obscures the inflation signal. Central banks watch core inflation closely since it responds more predictably to monetary policy. In India, core is often quoted alongside headline in RBI bi-monthly reviews.', 'MEDIUM', 'Economics', 'Inflation & Business Cycle', 'ECO_INFLATION', '[{"option_text": "Inflation in all goods and services", "is_correct": false}, {"option_text": "Inflation excluding food and fuel (i.e., non-volatile components)", "is_correct": true}, {"option_text": "Inflation only in essential commodities", "is_correct": false}, {"option_text": "Inflation faced by rural consumers only", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cc314c8c-c3f5-592b-a9e7-e4e94548bc45', 'Who chairs the RBI''s Monetary Policy Committee (MPC), which decides the repo rate?', NULL, 'The Monetary Policy Committee (MPC) has 6 members: 3 from RBI (Governor, Deputy Governor in charge of monetary policy, one officer nominated by RBI Central Board) + 3 external members (nominated by the Government of India for 4-year terms). The RBI Governor CHAIRS the MPC and has a CASTING VOTE in case of a tie. The MPC meets at least 4 times a year (usually 6) and decisions are made by majority vote. The PM and FM have no direct vote.', 'EASY', 'Economics', 'Inflation & Business Cycle', 'ECO_INFLATION', '[{"option_text": "The Prime Minister", "is_correct": false}, {"option_text": "The Finance Minister", "is_correct": false}, {"option_text": "The Governor of the RBI", "is_correct": true}, {"option_text": "The Chief Economic Advisor", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('830aafee-597f-5c0d-8854-a89830c69df7', 'The Reserve Bank of India was established under the Reserve Bank of India Act in which year, and nationalised in which year?', NULL, 'RBI was established under the RBI ACT, 1934 — commenced operations on 1 April 1935 (original HQ: Calcutta; moved to Mumbai 1937). Initial paid-up capital: ₹5 crore. Based on the HILTON YOUNG COMMISSION recommendations (1926). RBI was a private shareholders'' bank until NATIONALISATION on 1 January 1949 (under RBI Transfer to Public Ownership Act 1948). First Indian Governor: CD Deshmukh (3rd overall; 1943-49; later Finance Minister). First Governor: Sir Osborne Smith (1935-37 — only Governor who didn''t sign any currency notes).', 'EASY', 'Economics', 'RBI & its Functions', 'ECO_RBI', '[{"option_text": "Established 1935, nationalised 1949", "is_correct": true}, {"option_text": "Established 1947, nationalised 1969", "is_correct": false}, {"option_text": "Established 1925, nationalised 1935", "is_correct": false}, {"option_text": "Established 1949, nationalised 1969", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('39ccd750-a491-5ace-9f41-9de2b39abe49', 'The Monetary Policy Committee (MPC) of the RBI, constituted under the RBI Act amendment of 2016, has how many members?', NULL, 'The MPC (formed 2016 post-Urjit Patel Committee; statutory body under amended Sec 45ZB of RBI Act) has 6 members: 3 INTERNAL (RBI Governor — Chairperson ex-officio; Deputy Governor in charge of monetary policy; an officer nominated by the RBI Central Board) + 3 EXTERNAL (appointed by GoI for 4-year non-renewable terms). Decisions by majority; RBI Governor has a CASTING VOTE on ties. Meets at least 4 times a year (typically 6 bi-monthly meetings). Primary objective (per Monetary Policy Framework Agreement 2016): price stability — CPI inflation TARGET of 4% ± 2%, reviewed every 5 years.', 'MEDIUM', 'Economics', 'RBI & its Functions', 'ECO_RBI', '[{"option_text": "4 members (all from RBI)", "is_correct": false}, {"option_text": "6 members (3 from RBI + 3 external, nominated by GoI)", "is_correct": true}, {"option_text": "9 members (5 external + 4 RBI)", "is_correct": false}, {"option_text": "12 members (all appointed by President)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('11415a6f-fdb9-5450-a2f6-2e9dd923e1e3', 'Which of the following is NOT one of the core functions of the RBI?', NULL, 'The SECURITIES MARKET (stocks, mutual funds, IPOs) is regulated by SEBI (Securities and Exchange Board of India, statutory body since 1992), NOT RBI. RBI''s core functions: (1) ISSUER of currency — all notes except ₹1 (issued by Ministry of Finance, signed by Finance Secretary, not RBI Governor); (2) BANKER TO GOVERNMENT (maintains accounts of Central & State govts, manages public debt); (3) BANKER''S BANK (lender of last resort); (4) REGULATOR of banks + NBFCs + payment systems (UPI, NEFT, RTGS, IMPS through NPCI); (5) CONTROLLER OF CREDIT (monetary policy — repo, CRR, SLR); (6) FOREIGN EXCHANGE manager (under FEMA 1999); (7) DEVELOPMENTAL functions (financial inclusion, priority sector lending). Insurance: IRDAI. Pensions: PFRDA. Commodity markets: SEBI (post 2015).', 'MEDIUM', 'Economics', 'RBI & its Functions', 'ECO_RBI', '[{"option_text": "Issuer of currency notes (except ₹1 notes, which are issued by Ministry of Finance)", "is_correct": false}, {"option_text": "Banker to the Government and to commercial banks", "is_correct": false}, {"option_text": "Regulator of the securities market (stocks, mutual funds)", "is_correct": true}, {"option_text": "Controller of credit through monetary policy tools", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('09c03f8f-1996-5455-a4b3-4f546e8ee98e', 'The Cash Reserve Ratio (CRR) in India refers to:', NULL, 'CRR = % of bank''s Net Demand and Time Liabilities (NDTL = deposits + borrowings less inter-bank liabilities) that it must keep as CASH RESERVES WITH THE RBI — earns NO interest. Currently ~4.5% (since May 2022). Purpose: controls liquidity; raising CRR reduces lending capacity, tightens money supply. SLR (Statutory Liquidity Ratio, Sec 24 of Banking Regulation Act) = different % kept as LIQUID ASSETS (G-secs, gold, approved securities) — currently ~18%; this earns interest. Banks must maintain BOTH CRR and SLR. Higher CRR/SLR = tighter monetary policy. Repo Rate = interest on short-term borrowing from RBI. Reverse Repo = interest RBI pays on overnight deposits from banks.', 'MEDIUM', 'Economics', 'RBI & its Functions', 'ECO_RBI', '[{"option_text": "Portion of banks'' deposits kept as gold reserves", "is_correct": false}, {"option_text": "Percentage of banks'' Net Demand and Time Liabilities (NDTL) to be held as cash reserves WITH THE RBI", "is_correct": true}, {"option_text": "Amount banks can borrow from the RBI overnight", "is_correct": false}, {"option_text": "Reserves banks keep in foreign currencies", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3537dd0e-ac23-55c9-9e1b-eb575345a794', 'Who signs Indian currency notes of denominations ₹2 to ₹2000?', NULL, 'All Indian currency notes from ₹2 up to ₹2000 are signed by the RBI GOVERNOR (currently Sanjay Malhotra, succeeding Shaktikanta Das in Dec 2024). The ₹1 NOTE — issued by the Ministry of Finance, Government of India (per Coinage Act) — bears the signature of the FINANCE SECRETARY (not the RBI Governor). Also: ₹1 note was REINTRODUCED in 2015 after being discontinued in 1994. ₹2000 notes were DEMONETISED in May 2023 (though still legal tender). Currency notes are printed at 4 presses: Nashik (RBI''s Security Printing), Dewas (MP), Mysuru (KA), Salboni (WB). Coins minted at 4 mints: Mumbai, Kolkata, Hyderabad, Noida.', 'MEDIUM', 'Economics', 'RBI & its Functions', 'ECO_RBI', '[{"option_text": "The President of India", "is_correct": false}, {"option_text": "The Governor of the Reserve Bank of India", "is_correct": true}, {"option_text": "The Union Finance Minister", "is_correct": false}, {"option_text": "The Finance Secretary", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bf9430e8-1f26-5e72-acf2-8e88529862db', 'Which of the following is a ''quantitative'' (general) credit control tool of the RBI?', NULL, 'Credit control tools fall into two categories: QUANTITATIVE (general, affect ALL credit): (1) Bank Rate; (2) Open Market Operations (OMO — RBI buys/sells G-secs to inject/absorb liquidity); (3) CRR; (4) SLR; (5) Repo & Reverse Repo; (6) MSF. QUALITATIVE (selective, target specific sectors): (1) Margin requirements (% down-payment for specific-purpose loans); (2) Moral suasion (informal persuasion — ''please lend more to priority sector''); (3) Consumer credit controls; (4) Direct action (penalties on errant banks); (5) Credit rationing (ceilings on specific sectors); (6) Publicity. OMO is the most MARKET-BASED tool, actively used in the US Fed too.', 'HARD', 'Economics', 'RBI & its Functions', 'ECO_RBI', '[{"option_text": "Margin requirements", "is_correct": false}, {"option_text": "Open Market Operations (OMO)", "is_correct": true}, {"option_text": "Consumer credit controls", "is_correct": false}, {"option_text": "Moral suasion", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fe1f479f-d698-5dbe-a891-56f378afda5f', 'The RBI''s ''Liberalised Remittance Scheme (LRS)'' allows resident individuals to remit abroad up to what annual limit (as of 2024)?', NULL, 'LRS (Liberalised Remittance Scheme, introduced Feb 2004) allows Indian resident individuals to freely remit up to USD 250,000 per financial year (April-March) for any permitted capital or current account transaction — studies abroad, travel, gifts, investments in foreign securities, immovable property, etc. Initial limit was $25,000 (2004) → raised progressively to $250,000 (2015). TCS (Tax Collected at Source) rules apply: 20% TCS on most LRS remittances > ₹7 lakh (effective Oct 2023) — except medical, education. Not available to HUFs/corporates/partnership firms. Can''t be used for trading in forex abroad, lottery, margin trading, or sending funds to FATF-flagged countries.', 'HARD', 'Economics', 'RBI & its Functions', 'ECO_RBI', '[{"option_text": "US$ 25,000 per year", "is_correct": false}, {"option_text": "US$ 2,50,000 per financial year", "is_correct": true}, {"option_text": "US$ 10,00,000 per year", "is_correct": false}, {"option_text": "US$ 5,000 per trip only", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e92c4676-d657-5620-9229-0b2fad3808d2', 'RBI''s ''Payments Vision 2025'' is built around FIVE anchor goals. Which among the following is NOT one of them?', NULL, 'Payments Vision 2025 (released June 2022) articulates RBI''s roadmap with FIVE ''I'' anchors: (1) INTEGRITY; (2) INCLUSION; (3) INNOVATION; (4) INSTITUTIONALISATION; (5) INTERNATIONALISATION. ''Infrastructure'' is NOT one of the five (it is part of the foundation but not a named anchor). Key targets: triple digital payments, raise the number of digital payment transactions from ~100 Cr/day to ~270 Cr/day, roll out UPI internationally, CBDC (e₹ — retail and wholesale pilot from Dec 2022), rupee-denominated global payments (via RTGS linking with other countries). Earlier iterations: Payments Vision 2018, 2021-25 mid-point review.', 'HARD', 'Economics', 'RBI & its Functions', 'ECO_RBI', '[{"option_text": "Integrity", "is_correct": false}, {"option_text": "Inclusion", "is_correct": false}, {"option_text": "Infrastructure", "is_correct": true}, {"option_text": "Innovation", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('98c042da-0905-56f6-b0a8-89b24bd168c9', 'Who were the first three recipients of the Bharat Ratna in 1954?', NULL, 'The Bharat Ratna was instituted on 2 January 1954 by President Dr. Rajendra Prasad. The FIRST three awardees (1954) were: (1) C. Rajagopalachari — last Governor-General of India; (2) Dr. Sarvepalli Radhakrishnan — philosopher, later 2nd President; (3) Sir C. V. Raman — physicist, 1930 Nobel. Mahatma Gandhi never received the Bharat Ratna despite multiple nominations. Nehru received it in 1955 (in office — by himself, controversial). Sardar Patel was posthumously awarded in 1991. Dr. Ambedkar received it posthumously in 1990. NO BR between 1992-2008 due to an SC case challenging its ''medal'' status (resolved by a 1995 judgment).', 'MEDIUM', 'General Knowledge', 'Important Awards & Honors (History & Static)', 'GK_AWARDS_STATIC', '[{"option_text": "Jawaharlal Nehru, Mahatma Gandhi, Sardar Patel", "is_correct": false}, {"option_text": "C. Rajagopalachari, Dr. S. Radhakrishnan, C. V. Raman", "is_correct": true}, {"option_text": "Rajendra Prasad, Lal Bahadur Shastri, B. R. Ambedkar", "is_correct": false}, {"option_text": "Subhas Chandra Bose, Mother Teresa, Morarji Desai", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('20d1e9a3-ab65-5418-a5a7-f0a5db1b82aa', 'In February 2024, the Government of India conferred Bharat Ratna on five personalities — an exceptional number. Which of the following was NOT among them?', NULL, 'The five 2024 Bharat Ratnas announced Jan-Feb 2024 were: (1) KARPOORI THAKUR (posthumous — former Bihar CM, socialist leader); (2) L. K. ADVANI — former Deputy PM, BJP veteran; (3) CHAUDHARY CHARAN SINGH (posthumous — former PM, Jat leader); (4) P. V. NARASIMHA RAO (posthumous — former PM, architect of 1991 reforms); (5) M. S. SWAMINATHAN (posthumous — Father of India''s Green Revolution, agricultural scientist). The most Bharat Ratnas announced in a single year. Manmohan Singh (10th PM, architect of 1991 reforms as FM) was NOT awarded (and passed away Dec 2024). Total Bharat Ratnas to date: 53.', 'MEDIUM', 'General Knowledge', 'Important Awards & Honors (History & Static)', 'GK_AWARDS_STATIC', '[{"option_text": "Karpoori Thakur (posthumously)", "is_correct": false}, {"option_text": "L. K. Advani", "is_correct": false}, {"option_text": "M. S. Swaminathan (posthumously)", "is_correct": false}, {"option_text": "Dr. Manmohan Singh", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5d065a47-627a-5eab-a99b-23fdf4c6697b', 'How many Nobel Prizes have been won by persons of Indian origin or Indian citizens, and who was the FIRST?', NULL, 'Indians/Indian-origin Nobel Laureates (9 total): (1) Rabindranath TAGORE — Lit 1913 — FIRST Asian Nobel Laureate; (2) C.V. RAMAN — Physics 1930 — Raman Effect; (3) Hargobind KHORANA — Medicine 1968 — genetic code (born India, then US citizen); (4) MOTHER TERESA — Peace 1979 — Indian citizen; (5) Subrahmanyan CHANDRASEKHAR — Physics 1983 — stellar structure (born Lahore undivided India, US citizen); (6) Amartya SEN — Econ 1998 — welfare economics; (7) V. RAMAKRISHNAN — Chem 2009 — ribosome (born Chidambaram, US/UK citizen); (8) Kailash SATYARTHI — Peace 2014 — child rights; (9) Abhijit BANERJEE — Econ 2019 — poverty experiments (born Kolkata, US citizen). V. S. Naipaul (Lit 2001, Trinidad-born Indian origin) is sometimes counted as 10th.', 'HARD', 'General Knowledge', 'Important Awards & Honors (History & Static)', 'GK_AWARDS_STATIC', '[{"option_text": "5 Indian + OCI combined; Rabindranath Tagore 1913 (Literature)", "is_correct": false}, {"option_text": "9 total (5 Indian citizens + 4 OCI/foreign-naturalised); Rabindranath Tagore 1913 (Literature)", "is_correct": true}, {"option_text": "12 total; C. V. Raman 1930 (Physics)", "is_correct": false}, {"option_text": "6 total; Mother Teresa 1979 (Peace)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('910614db-c346-5419-a953-2a844996a86b', 'The Jnanpith Award, India''s highest literary award, is given by whom and for writing in which languages?', NULL, 'The Jnanpith Award is instituted by the Bharatiya Jnanpith Trust (established 1944 by the Sahu Jain family), given annually since 1965 for literary work in any of the 22 Scheduled Languages + English. Prize: ₹11 lakh + bronze Saraswati statue + citation. First recipient: G. Sankara Kurup (Malayalam, 1965). First woman: Ashapoorna Devi (Bengali, 1976). First in English: Amitav Ghosh (2018). Odia didn''t have a Jnanpith winner till 1973 (Gopinath Mohanty). Hindi has most winners. Distinct from Sahitya Akademi awards (which are by genre in each language each year). Saraswati Samman is another major literary award (KK Birla Foundation since 1991).', 'MEDIUM', 'General Knowledge', 'Important Awards & Honors (History & Static)', 'GK_AWARDS_STATIC', '[{"option_text": "Sahitya Akademi; only English", "is_correct": false}, {"option_text": "Bharatiya Jnanpith Trust; 22 scheduled languages + English", "is_correct": true}, {"option_text": "Ministry of Culture; Hindi only", "is_correct": false}, {"option_text": "Indian Council for Cultural Relations; any Indian language", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4afd0feb-5e92-5566-9903-e76592a70d32', 'The Dadasaheb Phalke Award for lifetime achievement in Indian cinema is named after whom?', NULL, 'Dhundiraj Govind Phalke (1870-1944), known as ''Dadasaheb'' Phalke, is regarded as the Father of Indian Cinema. He directed India''s FIRST feature film RAJA HARISHCHANDRA (1913, silent, black-and-white) — the actual release was on 3 May 1913 at Coronation Cinematograph, Mumbai. He made 95 films and 27 shorts. The Dadasaheb Phalke Award was instituted in 1969 (his birth centenary year); first recipient: Devika Rani. Prize: Swarna Kamal (Golden Lotus), ₹10 lakh, shawl. National Film Awards are separately given. India''s national cinema day: 3 May.', 'EASY', 'General Knowledge', 'Important Awards & Honors (History & Static)', 'GK_AWARDS_STATIC', '[{"option_text": "The first Indian film actor", "is_correct": false}, {"option_text": "The ''Father of Indian Cinema'' — who made India''s first feature film ''Raja Harishchandra'' (1913)", "is_correct": true}, {"option_text": "The founder of Filmfare Awards", "is_correct": false}, {"option_text": "The first Indian to win an Oscar", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7779833b-b5e0-559d-b28a-50ae3dc5db14', 'Which Indian-origin scientist won the Nobel Prize in Chemistry in 2009 for his work on the structure and function of the ribosome?', NULL, 'Venkatraman ''Venki'' Ramakrishnan (born 1952, Chidambaram, Tamil Nadu; US/UK citizen) won the 2009 Chemistry Nobel (shared with Thomas A. Steitz and Ada E. Yonath) ''for studies of the structure and function of the ribosome''. Served as President of the Royal Society, UK (2015-20). Khorana won Medicine 1968 (genetic code); Chandrasekhar won Physics 1983 (stellar structure — Chandrasekhar limit); Banerjee won Economics 2019 (poverty experiments, with Esther Duflo and Michael Kremer). Tagore (Literature 1913), Raman (Physics 1930), Mother Teresa (Peace 1979), Sen (Economics 1998), Satyarthi (Peace 2014) complete the list of Indian-linked Nobels.', 'MEDIUM', 'General Knowledge', 'Important Awards & Honors (History & Static)', 'GK_AWARDS_STATIC', '[{"option_text": "Hargobind Khorana", "is_correct": false}, {"option_text": "Venkatraman Ramakrishnan", "is_correct": true}, {"option_text": "Subrahmanyan Chandrasekhar", "is_correct": false}, {"option_text": "Abhijit Banerjee", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fda70af6-76c5-5791-b459-c2f37730c418', 'The Magsaysay Award is often called the ''Asian Nobel Prize''. It is named after a former President of which country?', NULL, 'Named after Ramon Magsaysay, the 7th President of the Philippines (1953-57), who died in an air crash 1957. The Award was instituted in 1957 by the Rockefeller Brothers Fund to honour his memory. Given since 1958 in categories like government service, public service, community leadership, journalism/literature/creative arts, international understanding, emergent leadership. Indian recipients include: Vinoba Bhave (1958, first Indian), Mother Teresa (1962, pre-Nobel), Satyajit Ray (1967), Ela Bhatt, Baba Amte, Mahasweta Devi, Kiran Bedi, Arvind Kejriwal, TM Krishna, Bezwada Wilson, Anshu Gupta, Ravish Kumar (2019 last Indian so far). The Emergent Leadership category was discontinued in 2020; 2020-21 awards skipped due to COVID.', 'MEDIUM', 'General Knowledge', 'Important Awards & Honors (History & Static)', 'GK_AWARDS_STATIC', '[{"option_text": "Thailand", "is_correct": false}, {"option_text": "Philippines", "is_correct": true}, {"option_text": "Indonesia", "is_correct": false}, {"option_text": "South Korea", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f9fbe387-bc50-58f2-b9a3-1a0dfa4c3f29', 'The Param Vir Chakra (PVC) is India''s highest military gallantry award. Who was the FIRST recipient, posthumously awarded?', NULL, 'The Param Vir Chakra (PVC) was instituted on 26 January 1950, retrospectively effective from 15 August 1947. The first PVC was awarded POSTHUMOUSLY to Major Somnath Sharma (4th Battalion, Kumaon Regiment) for his leadership in the Battle of Badgam (3 November 1947) during the First Kashmir War. Only 21 PVCs have been awarded (14 posthumous). Other notable recipients: Major Shaitan Singh (Rezang La 1962), Lance Naik Albert Ekka (1971), Second Lt Arun Khetarpal (1971), Capt Vikram Batra (Kargil 1999), Capt Manoj Pandey (Kargil 1999). India''s second-highest military honour is Maha Vir Chakra (MVC), third is Vir Chakra. In PEACETIME, the corresponding highest is Ashoka Chakra.', 'HARD', 'General Knowledge', 'Important Awards & Honors (History & Static)', 'GK_AWARDS_STATIC', '[{"option_text": "Major Somnath Sharma", "is_correct": true}, {"option_text": "Havildar Abdul Hamid", "is_correct": false}, {"option_text": "Subedar Joginder Singh", "is_correct": false}, {"option_text": "Captain Vikram Batra", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('360d2144-c43d-57d5-8de1-58dce9ad4a09', 'The Major Dhyan Chand Khel Ratna (India''s highest sporting honour) was originally known as what, and is given by which ministry?', NULL, 'Originally the ''Rajiv Gandhi Khel Ratna'' (instituted 1991-92), RENAMED in August 2021 to ''MAJOR DHYAN CHAND KHEL RATNA AWARD'' (after the legendary hockey player and 3-time Olympic gold medalist, 1928/1932/1936). First Khel Ratna awardee: Viswanathan Anand (1991-92). Given by the Ministry of Youth Affairs & Sports. National Sports Awards hierarchy: (1) Dhyan Chand Khel Ratna (top, for outstanding performance over 4 years); (2) Arjuna Award (consistent excellence for 4 years); (3) Dronacharya Award (for coaches); (4) Dhyan Chand Award (for lifetime contribution — different from Khel Ratna). Awarded every year on 29 August (National Sports Day, Dhyan Chand''s birthday).', 'HARD', 'General Knowledge', 'Important Awards & Honors (History & Static)', 'GK_AWARDS_STATIC', '[{"option_text": "Arjuna Award; Ministry of Culture", "is_correct": false}, {"option_text": "Rajiv Gandhi Khel Ratna; Ministry of Youth Affairs & Sports", "is_correct": true}, {"option_text": "Dronacharya Award; Ministry of Home Affairs", "is_correct": false}, {"option_text": "National Sports Award; Ministry of Education", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('61281aa1-e2ee-59d6-917b-8afcf525b6f7', 'The parliament of Israel is known as:', NULL, 'Each country''s parliament has a distinctive name — commonly tested: KNESSET (Israel, unicameral 120 members), DIET (Japan — National Diet; Germany called its lower house the ''Bundestag'' but Imperial Germany used ''Reichstag'' = ''Diet of the Empire''), MAJLIS (Iran and several Arab states), SEJM (Poland, lower house), DUMA (Russia lower house, State Duma; upper = Federation Council), BUNDESTAG (Germany lower house, Bundesrat upper), CORTES (Spain), SHURA (Saudi Arabia consultative), RIKSDAG (Sweden), STORTING (Norway), FOLKETING (Denmark), ALTHING (Iceland — world''s oldest, est. 930 AD), NATIONAL PEOPLE''S CONGRESS (China), CONGRESS (USA — Senate + House of Rep), PARLIAMENT (UK, India). ', 'EASY', 'General Knowledge', 'Countries, Capitals, Currencies & Parliaments', 'GK_COUNTRIES', '[{"option_text": "Diet", "is_correct": false}, {"option_text": "Knesset", "is_correct": true}, {"option_text": "Majlis", "is_correct": false}, {"option_text": "Sejm", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('15ffc2b9-d128-5495-ac84-184d12150206', 'The currency of which country is the ''Ngultrum''?', NULL, 'NGULTRUM (BTN) is Bhutan''s currency, pegged at par with the Indian Rupee. Indian Rupee is also accepted freely in Bhutan. Neighbours: Nepal = Nepalese Rupee (NPR, also pegged to INR at ~1.6 NPR = 1 INR); Sri Lanka = Sri Lankan Rupee (LKR); Myanmar = Kyat (MMK); Bangladesh = Taka (BDT); Pakistan = Pakistani Rupee (PKR); Maldives = Rufiyaa (MVR); Afghanistan = Afghani (AFN). Often-confused currencies: Renminbi/Yuan (China), Yen (Japan), Won (Korea), Riyal (Saudi/Qatar/Oman/Yemen), Dinar (Kuwait/Bahrain/Jordan/Algeria/Iraq/Libya/Tunisia), Dirham (UAE/Morocco).', 'MEDIUM', 'General Knowledge', 'Countries, Capitals, Currencies & Parliaments', 'GK_COUNTRIES', '[{"option_text": "Nepal", "is_correct": false}, {"option_text": "Bhutan", "is_correct": true}, {"option_text": "Myanmar", "is_correct": false}, {"option_text": "Sri Lanka", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1b50c670-01dc-57a4-a85f-dd4de4286898', 'South Africa has three capitals. Which of the following is NOT one of them?', NULL, 'South Africa uniquely has THREE constitutional capitals representing different branches: PRETORIA = Executive (seat of President, Cabinet); CAPE TOWN = Legislative (Parliament sits here); BLOEMFONTEIN = Judicial (Supreme Court of Appeal). Johannesburg — though the largest, richest city and financial hub — is NOT a capital. Other multi-capital countries: Netherlands (Amsterdam constitutional + The Hague seat of govt), Sri Lanka (Colombo commercial + Sri Jayawardenepura Kotte legislative), Bolivia (Sucre constitutional + La Paz seat of govt), Malaysia (Kuala Lumpur official + Putrajaya administrative), Chile (Santiago executive + Valparaiso legislative).', 'HARD', 'General Knowledge', 'Countries, Capitals, Currencies & Parliaments', 'GK_COUNTRIES', '[{"option_text": "Pretoria (Executive)", "is_correct": false}, {"option_text": "Cape Town (Legislative)", "is_correct": false}, {"option_text": "Bloemfontein (Judicial)", "is_correct": false}, {"option_text": "Johannesburg (Financial)", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a17e5b2d-28fb-53c6-add3-27bdfb52f4a1', 'Which landlocked country is completely surrounded by South Africa?', NULL, 'LESOTHO is one of only 3 countries in the world ENTIRELY ENCLAVED by another single country (completely surrounded by South Africa). The other two enclaved states: VATICAN CITY (inside Rome, Italy) and SAN MARINO (inside Italy). Eswatini (formerly Swaziland) is almost surrounded by SA but has a short border with Mozambique. Capital of Lesotho: Maseru. Currency: Loti (LSL, pegged to ZAR). Landlocked African countries to know: Burkina Faso, Burundi, CAR, Chad, Ethiopia, Malawi, Mali, Niger, Rwanda, South Sudan, Uganda, Zambia, Zimbabwe. Largest landlocked country globally: Kazakhstan.', 'HARD', 'General Knowledge', 'Countries, Capitals, Currencies & Parliaments', 'GK_COUNTRIES', '[{"option_text": "Botswana", "is_correct": false}, {"option_text": "Lesotho", "is_correct": true}, {"option_text": "Swaziland (Eswatini)", "is_correct": false}, {"option_text": "Zimbabwe", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('31b2db6b-0cc6-5058-b815-670223b47c93', 'The currency ''Dong'' belongs to which country?', NULL, 'DONG (VND) is Vietnam''s currency. SE Asian currencies: Thailand = Baht; Cambodia = Riel; Laos = Kip; Indonesia = Rupiah; Philippines = Peso; Malaysia = Ringgit; Singapore = Singapore Dollar; Brunei = Brunei Dollar; Myanmar = Kyat; East Timor = US Dollar; S Korea = Won; N Korea = Won (different); Japan = Yen; China = Yuan/Renminbi; Taiwan = New Taiwan Dollar; Mongolia = Tugrik. Vietnamese capital: Hanoi (not Ho Chi Minh City — that''s the largest city).', 'MEDIUM', 'General Knowledge', 'Countries, Capitals, Currencies & Parliaments', 'GK_COUNTRIES', '[{"option_text": "South Korea", "is_correct": false}, {"option_text": "Vietnam", "is_correct": true}, {"option_text": "Thailand", "is_correct": false}, {"option_text": "Cambodia", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8e472c86-a20f-5ff1-9769-dd99320292d5', 'The ''Storting'' is the parliament of which country?', NULL, 'STORTING = Norway. Nordic parliaments: NORWAY = Storting (unicameral, 169 members, Oslo); SWEDEN = Riksdag (unicameral, 349 members, Stockholm); DENMARK = Folketing (unicameral, 179 members, Copenhagen); FINLAND = Eduskunta (unicameral, 200 members, Helsinki); ICELAND = Althing/Alþingi (unicameral, 63 members, Reykjavik) — world''s OLDEST surviving parliament, founded 930 AD by the Vikings at Þingvellir. Memorise at least 15 world parliament names for exam-level preparation.', 'HARD', 'General Knowledge', 'Countries, Capitals, Currencies & Parliaments', 'GK_COUNTRIES', '[{"option_text": "Sweden", "is_correct": false}, {"option_text": "Norway", "is_correct": true}, {"option_text": "Denmark", "is_correct": false}, {"option_text": "Finland", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('53991316-68c8-5791-97fb-b624c0699363', 'Abuja is the capital of which African country, known for having replaced Lagos as capital in 1991?', NULL, 'Nigeria shifted its capital from Lagos (coastal, overcrowded, southern) to Abuja (central, purpose-built) on 12 December 1991 for geographical centrality and ethno-religious neutrality. Similar capital shifts: Brazil (Rio → Brasilia 1960), Pakistan (Karachi → Islamabad 1960-67), Kazakhstan (Almaty → Astana/Nur-Sultan/Astana 1997 — renamed back), Myanmar (Yangon → Naypyidaw 2006), Egypt (Cairo → New Administrative Capital, under construction), Indonesia (Jakarta → Nusantara, planned 2024+). African capitals worth knowing: Addis Ababa (Ethiopia, HQ of African Union), Accra (Ghana), Nairobi (Kenya), Kampala (Uganda), Dar es Salaam (Tanzania''s commercial capital; Dodoma is official), Kigali (Rwanda), Luanda (Angola).', 'MEDIUM', 'General Knowledge', 'Countries, Capitals, Currencies & Parliaments', 'GK_COUNTRIES', '[{"option_text": "Ghana", "is_correct": false}, {"option_text": "Nigeria", "is_correct": true}, {"option_text": "Kenya", "is_correct": false}, {"option_text": "Ethiopia", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bacad043-52e7-5f4b-8238-b4783f2949d5', 'The currency of which country is ''Shekel''?', NULL, 'Israeli NEW SHEKEL (ILS) — Israel. Middle East currencies: Lebanon = Lebanese Pound/Lira; Jordan = Jordanian Dinar (JOD — one of the strongest currencies); Iran = Iranian Rial; Iraq = Iraqi Dinar; Saudi = Riyal; UAE = Dirham; Bahrain = Dinar; Kuwait = Kuwaiti Dinar (strongest currency globally by exchange rate against USD); Qatar = Riyal; Oman = Omani Rial (3rd strongest); Yemen = Yemeni Rial; Syria = Syrian Pound; Turkey = Turkish Lira. The name ''Shekel'' (שקל) dates back to ancient biblical times; the NEW shekel replaced the old shekel (1985) at 1000:1.', 'MEDIUM', 'General Knowledge', 'Countries, Capitals, Currencies & Parliaments', 'GK_COUNTRIES', '[{"option_text": "Lebanon", "is_correct": false}, {"option_text": "Israel", "is_correct": true}, {"option_text": "Jordan", "is_correct": false}, {"option_text": "Iran", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b18dda47-8a0d-5ef7-bcb0-c72c0eb020e0', 'Which country was formerly known as ''Siam'', changed its name in 1939?', NULL, 'Siam was renamed THAILAND (= ''land of the free'') in 1939 under PM Plaek Phibunsongkhram. Notable country renamings: Burma → Myanmar (1989, military junta); Ceylon → Sri Lanka (1972); Kampuchea ↔ Cambodia (1975 Khmer Rouge renamed to Kampuchea; reverted 1989); Persia → Iran (1935); Abyssinia → Ethiopia (1940s); Rhodesia → Zimbabwe (1980 independence); Upper Volta → Burkina Faso (1984); Zaire → Democratic Republic of the Congo (1997); Swaziland → Eswatini (2018); Turkey → Türkiye (official 2022). Cities: Bombay → Mumbai (1995), Madras → Chennai (1996), Calcutta → Kolkata (2001), Bangalore → Bengaluru (2014), Peking → Beijing (1979).', 'MEDIUM', 'General Knowledge', 'Countries, Capitals, Currencies & Parliaments', 'GK_COUNTRIES', '[{"option_text": "Cambodia (from Kampuchea)", "is_correct": false}, {"option_text": "Thailand (from Siam)", "is_correct": true}, {"option_text": "Myanmar (from Burma)", "is_correct": false}, {"option_text": "Sri Lanka (from Ceylon)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('096cf155-601c-515e-86ab-fec4af160bbe', 'Who was the first woman President of India?', NULL, 'Pratibha Devisingh Patil — 12th President of India (2007-2012) — was the FIRST WOMAN President of India. Droupadi Murmu — 15th President (2022-present) — is the SECOND woman AND the first tribal (Santhal) President. Sarojini Naidu was the first woman GOVERNOR of UP (1947-49) and first woman president of INC (1925). Indira Gandhi was first woman PM (1966-77, 1980-84) — never President.', 'EASY', 'General Knowledge', 'Firsts in India (Male/Female/Misc)', 'GK_FIRSTS_INDIA', '[{"option_text": "Indira Gandhi", "is_correct": false}, {"option_text": "Pratibha Patil", "is_correct": true}, {"option_text": "Sarojini Naidu", "is_correct": false}, {"option_text": "Droupadi Murmu", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('49287a7e-11e7-50fc-95cd-8cbace0afa5f', 'Who was the first woman Chief Minister of an Indian state?', NULL, 'SUCHETA KRIPLANI (wife of J.B. Kriplani) was the FIRST woman CM of any Indian state — Chief Minister of UTTAR PRADESH from 2 October 1963 to 13 March 1967. Freedom fighter, INC member, Constituent Assembly member. Sung ''Vande Mataram'' in the Constituent Assembly on the night of 14-15 August 1947. First woman CM AFTER her: Nandini Satpathy (Odisha, 1972), Shashikala Kakodkar (Goa, 1973), Anwara Taimur (Assam, 1980), Sheila Dikshit (Delhi, 1998), Jayalalithaa (TN, 1991), Mayawati (UP, 1995), Rabri Devi (Bihar, 1997), Uma Bharti (MP, 2003), Vasundhara Raje (Raj, 2003), Mamata Banerjee (WB, 2011), Anandiben Patel (Guj, 2014), Mehbooba Mufti (J&K, 2016). India has had ~16 women CMs.', 'MEDIUM', 'General Knowledge', 'Firsts in India (Male/Female/Misc)', 'GK_FIRSTS_INDIA', '[{"option_text": "Sucheta Kriplani (UP, 1963)", "is_correct": true}, {"option_text": "Jayalalithaa (TN, 1991)", "is_correct": false}, {"option_text": "Mamata Banerjee (WB, 2011)", "is_correct": false}, {"option_text": "Sushma Swaraj (Delhi, 1998)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2a86d45d-cfbd-5755-994c-29e5825ae714', 'Who was India''s first Chief Election Commissioner?', NULL, 'SUKUMAR SEN (ICS officer) served as India''s first Chief Election Commissioner from 21 March 1950 to 19 December 1958 — conducted the first and second Lok Sabha elections (1951-52 and 1957). T. N. SESHAN (10th CEC, 1990-96) — reformed ECI''s functioning, earning the popular title ''Tyrant''. K. V. K. Sundaram was the 2nd CEC (1958-67). James Michael Lyngdoh (12th CEC, 2001-04) — presided over contentious Gujarat 2002 elections; Magsaysay Award 2003. Current CEC (as of early 2025): Rajiv Kumar. The ECI is a constitutional body under Article 324 — originally 1 CEC, now 3 (1 CEC + 2 ECs) since 1993.', 'HARD', 'General Knowledge', 'Firsts in India (Male/Female/Misc)', 'GK_FIRSTS_INDIA', '[{"option_text": "T. N. Seshan", "is_correct": false}, {"option_text": "Sukumar Sen", "is_correct": true}, {"option_text": "K. V. K. Sundaram", "is_correct": false}, {"option_text": "James Michael Lyngdoh", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e60cb6dd-f932-5dbe-b88d-59c5c54001ca', 'Who was the first woman judge of the Supreme Court of India?', NULL, 'Justice M. FATHIMA BEEVI (1927-2023) became the FIRST woman judge of the Supreme Court of India in 1989 (served till 1992). She was also the first Muslim woman judge in any high court in India (Kerala HC, 1983) and later Governor of Tamil Nadu (1997-2001). ANNA CHANDY was India''s first woman HIGH COURT judge (Kerala HC, 1959) — not SC. Leila Seth — first woman CHIEF JUSTICE of a High Court (HP HC, 1991) and first woman judge of Delhi HC. Justice Indu Malhotra (2018-2021) — first woman appointed directly from the Bar to SC. By Sept 2021, the SC had a record 4 women judges simultaneously (Hima Kohli, BV Nagarathna, Bela Trivedi — appointed together; Indira Banerjee was already serving).', 'MEDIUM', 'General Knowledge', 'Firsts in India (Male/Female/Misc)', 'GK_FIRSTS_INDIA', '[{"option_text": "Anna Chandy", "is_correct": false}, {"option_text": "Justice M. Fathima Beevi", "is_correct": true}, {"option_text": "Leila Seth", "is_correct": false}, {"option_text": "Justice Indu Malhotra", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('faf9fbd2-1762-5d2d-8b9c-7019f2b4d201', 'Which was the first Indian-made fully indigenous supersonic fighter aircraft, inducted into the IAF in 2016?', NULL, 'HAL TEJAS (Light Combat Aircraft, LCA) — 4.5-generation single-engine multirole fighter — was formally inducted into the IAF on 1 July 2016 (No. 45 Squadron ''Flying Daggers''). Designed by ADA (Aeronautical Development Agency) + HAL. Project started 1983 to replace MiG-21s; first flight 2001; full operational clearance 2019. Tejas Mk-1A on order (83 aircraft, Feb 2021). HAL MARUT (HF-24) was India''s first indigenous fighter (1961-85) — but subsonic-to-transonic, not truly supersonic. Su-30MKI is imported (Russian, license-built in India). HAL PRACHAND (Light Combat Helicopter, 2022) — indigenous attack helicopter. ARJUN MBT is indigenous main battle tank.', 'MEDIUM', 'General Knowledge', 'Firsts in India (Male/Female/Misc)', 'GK_FIRSTS_INDIA', '[{"option_text": "HAL Marut", "is_correct": false}, {"option_text": "HAL Tejas (LCA)", "is_correct": true}, {"option_text": "Sukhoi Su-30MKI", "is_correct": false}, {"option_text": "HAL Prachand (LCH)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2ebed132-dfe1-5959-85b5-e0997b1f8531', 'The first INC session was held at Bombay in 1885. Who presided over it as its first President?', NULL, 'The Indian National Congress''s FIRST session (28-31 December 1885 at Gokuldas Tejpal Sanskrit College, Bombay) was presided by Womesh Chandra BONNERJEE (Kolkata barrister). 72 delegates. A. O. Hume (British, retired ICS) was the FOUNDER/organiser — called the ''father of INC'' but never its President. DADABHAI NAOROJI (Grand Old Man of India) presided 3 times (1886, 1893, 1906 — where the Swaraj demand was first articulated). SURENDRANATH BANERJEE — founded earlier Indian National Association (1876), twice INC president (1895, 1902). First woman INC president: Annie Besant (1917 Calcutta). First Indian woman: Sarojini Naidu (1925 Kanpur). Youngest INC President: Jawaharlal Nehru (1929 Lahore — ''Purna Swaraj'' declaration).', 'MEDIUM', 'General Knowledge', 'Firsts in India (Male/Female/Misc)', 'GK_FIRSTS_INDIA', '[{"option_text": "Allan Octavian Hume", "is_correct": false}, {"option_text": "Womesh Chandra Bonnerjee", "is_correct": true}, {"option_text": "Dadabhai Naoroji", "is_correct": false}, {"option_text": "Surendranath Banerjee", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('012cc09f-3237-55be-8d11-f056caae8caa', 'Who was the first Indian to go to space?', NULL, 'Wing Commander Rakesh Sharma (IAF pilot) became the FIRST Indian in space on 3 April 1984 aboard the Soviet Soyuz T-11 to Salyut 7 space station — spent 7 days 21 hours. When PM Indira Gandhi asked him how India looked from space, he famously replied ''Saare Jahan Se Achha'' (a line from Iqbal''s poem). KALPANA CHAWLA (Karnal, Haryana; naturalised US citizen) was the FIRST woman of Indian origin in space (STS-87, Nov 1997) and died in the Columbia disaster on 1 Feb 2003 (STS-107 re-entry). SUNITA WILLIAMS (Indian-American) — multiple ISS missions; holds records for spacewalks by a woman. India''s GAGANYAAN manned mission target: 2026. Shubhanshu Shukla expected to be India''s 2nd astronaut.', 'EASY', 'General Knowledge', 'Firsts in India (Male/Female/Misc)', 'GK_FIRSTS_INDIA', '[{"option_text": "Rakesh Sharma (1984, Soyuz T-11)", "is_correct": true}, {"option_text": "Kalpana Chawla (1997, STS-87)", "is_correct": false}, {"option_text": "Sunita Williams (2006, STS-116)", "is_correct": false}, {"option_text": "Rakesh Malhotra (1980)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1d6a6058-ea14-5711-9920-9c00af4d25f9', 'Bihu is the most important festival and dance form of which Indian state?', NULL, 'Bihu is Assam''s principal festival, celebrated in three forms each year: (1) RONGALI/BOHAG BIHU (April, New Year, spring harvest) — the biggest, with the vibrant Bihu dance; (2) KONGALI/KATI BIHU (October, bereft, austere — diyas lit in paddy fields); (3) BHOGALI/MAGH BIHU (January, harvest, community feasting). The Bihu dance features high-energy hip movements, ''pepa'' (buffalo horn flute), ''dhol'' (drum), ''gogona'' (reed instrument).', 'EASY', 'General Knowledge', 'Folk Dances & Festivals of India', 'GK_FOLK_DANCES_FESTIVALS', '[{"option_text": "Manipur", "is_correct": false}, {"option_text": "Assam", "is_correct": true}, {"option_text": "Meghalaya", "is_correct": false}, {"option_text": "Arunachal Pradesh", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c3715c36-1d40-53ec-ab9b-0f6383395caf', 'The Hornbill Festival, a vibrant showcase of tribal culture, is celebrated every December in which state?', NULL, 'The Hornbill Festival is held every year 1-10 December at Kisama Heritage Village near Kohima, Nagaland. Named after the Indian hornbill bird revered by Naga tribes. Showcases all 17 recognised Naga tribes (Ao, Angami, Konyak, Lotha, Sema, Chakhesang, Rengma, etc.) — their dances, music, traditional sports (Naga wrestling), handicrafts, and cuisine. Started in 2000 by the State Government to promote inter-tribal interaction. Often called the ''Festival of Festivals''.', 'EASY', 'General Knowledge', 'Folk Dances & Festivals of India', 'GK_FOLK_DANCES_FESTIVALS', '[{"option_text": "Meghalaya", "is_correct": false}, {"option_text": "Mizoram", "is_correct": false}, {"option_text": "Nagaland", "is_correct": true}, {"option_text": "Manipur", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('77365c59-3ad9-59ff-a7d3-6a2c50258f4b', 'Chapchar Kut, a spring festival marking the end of jungle-clearing for jhum cultivation, is celebrated in which state?', NULL, 'Chapchar Kut is the most important festival of the Mizo people of Mizoram, celebrated in March after the jungle clearing (''jhum'' or slash-and-burn) phase for the new planting season. Features the famous CHERAW (Bamboo Dance) — performed by women stepping between bamboo poles clapped in rhythm by men. Also includes Khuallam, Sarlamkai, Solakia, Chheihlam dances. Other Mizo festivals: Mim Kut (maize harvest, Aug-Sept), Pawl Kut (winter harvest, Dec-Jan).', 'MEDIUM', 'General Knowledge', 'Folk Dances & Festivals of India', 'GK_FOLK_DANCES_FESTIVALS', '[{"option_text": "Tripura", "is_correct": false}, {"option_text": "Mizoram", "is_correct": true}, {"option_text": "Nagaland", "is_correct": false}, {"option_text": "Meghalaya", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c063a474-eaae-517a-9cef-4b50b5ee6957', 'Nongkrem is the most important religious festival of which tribal community of which state?', NULL, 'Nongkrem is the 5-day harvest thanksgiving festival of the Khasi people of Meghalaya, held in November at Smit, Khasi Hills — the seat of the Syiem (traditional head). Features the sacred Pomblang ritual (goat sacrifice) and the Nongkrem dance — unmarried women in traditional dress with gold ornaments dance in a circle while men with swords and flywhisks dance around them. The Garos'' corresponding major festival is WANGALA (''100 Drums Festival'') in November, post-harvest. Apatani: Dree festival.', 'HARD', 'General Knowledge', 'Folk Dances & Festivals of India', 'GK_FOLK_DANCES_FESTIVALS', '[{"option_text": "Garo tribe of Meghalaya", "is_correct": false}, {"option_text": "Khasi tribe of Meghalaya", "is_correct": true}, {"option_text": "Apatani tribe of Arunachal", "is_correct": false}, {"option_text": "Bodo tribe of Assam", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a8df9faa-48dd-5eed-aec7-04e590a4b081', 'Losoong (also called Sonam Lochar) is the new year harvest festival of which Sikkimese community?', NULL, 'Losoong (Tibetan New Year / harvest festival) is celebrated by the Bhutia community of Sikkim in December (10th month of Tibetan calendar). The similar Namsoong is celebrated by the Lepcha community. Saga Dawa (May-June) commemorates Buddha''s birth, enlightenment, and parinirvana — observed by all Sikkimese Buddhists. Other Sikkim festivals: Tihar/Diwali (Nepali), Bhumchu (water festival at Tashiding monastery), Pang Lhabsol (Mt Khangchendzonga worship).', 'HARD', 'General Knowledge', 'Folk Dances & Festivals of India', 'GK_FOLK_DANCES_FESTIVALS', '[{"option_text": "Lepcha", "is_correct": false}, {"option_text": "Bhutia", "is_correct": true}, {"option_text": "Nepali", "is_correct": false}, {"option_text": "Limbu", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b7a4a91d-808f-501d-8aad-2d9e68956406', 'Lai Haraoba and Ras Leela are the traditional dance-drama forms of which Indian state?', NULL, 'Lai Haraoba (''Merry-making of the gods'') is the oldest ritual dance of Manipur, predating Vaishnavism, honouring the indigenous Meitei deities (Umang Lai). Manipuri Ras Leela, developed under King Bhagyachandra (18th c.), depicts Radha-Krishna''s divine love. Manipuri is one of the 8 classical dances of India — characterised by graceful, gentle movements, unique ball-shaped ''pung'' drum accompaniment, and elaborate skirted ''Kumil'' costumes (the female dancer moves almost like a spinning top).', 'MEDIUM', 'General Knowledge', 'Folk Dances & Festivals of India', 'GK_FOLK_DANCES_FESTIVALS', '[{"option_text": "Assam", "is_correct": false}, {"option_text": "Manipur", "is_correct": true}, {"option_text": "West Bengal", "is_correct": false}, {"option_text": "Odisha", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ebbc7a34-acde-532d-bd42-dd3243db83fa', 'Bagurumba is a famous butterfly-mimic folk dance of which community of Assam?', NULL, 'Bagurumba (the ''Butterfly Dance'') is the signature folk dance of the Bodo tribal community of Assam and parts of NE. Performed primarily by women during festivals (especially Baisagu — the Bodo new year in April), with graceful wing-like arm movements imitating butterflies. Accompanying instruments: Kham (drum), Siphung (flute), Serja (violin-like), Jotha (cymbals). Other Assamese tribal dances: Ali Ai Ligang (Mishing spring dance), Rongker (Karbi), Baidima (Dimasa).', 'HARD', 'General Knowledge', 'Folk Dances & Festivals of India', 'GK_FOLK_DANCES_FESTIVALS', '[{"option_text": "Ahom", "is_correct": false}, {"option_text": "Bodo", "is_correct": true}, {"option_text": "Karbi", "is_correct": false}, {"option_text": "Dimasa", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7252b66c-58a8-5438-89ec-cc91d304b10d', 'Solung, Mopin, and Dree are festivals of different tribes in which state?', NULL, 'Arunachal has 26 major tribes, each with its own festival: SOLUNG (Adi tribe — Aug-Sept, agricultural), MOPIN (Galo tribe — April, harvest, rice powder smearing), DREE (Apatani tribe — July, agricultural thanksgiving), LOSAR (Monpa, Sherdukpen Buddhist — Feb), NYOKUM (Nyishi tribe — Feb, earth goddess), BOORI BOOT (Hill Miris — Feb), REH (Idu Mishmi). Arunachal is the land of ''dawn-lit mountains''; its tribes speak over 50 languages/dialects.', 'HARD', 'General Knowledge', 'Folk Dances & Festivals of India', 'GK_FOLK_DANCES_FESTIVALS', '[{"option_text": "Meghalaya", "is_correct": false}, {"option_text": "Arunachal Pradesh", "is_correct": true}, {"option_text": "Nagaland", "is_correct": false}, {"option_text": "Sikkim", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3cb34900-6566-5de2-bb8f-859d4f71fe6c', 'Garia and Hojagiri are popular folk dances of which NE state?', NULL, 'GARIA is a Tripura folk dance of the Tripuri community celebrating the deity Garia (god of wealth/fertility) during the April Garia Puja festival — dancers form a chain around a bamboo pole. HOJAGIRI is the acrobatic dance of the Reang (Bru) tribe — women balance on earthen pitchers while performing intricate upper-body movements with bottles/lamps on their head (one of India''s most visually distinctive dances). Bizu (end-of-Chaitra festival) is the Chakma community''s equivalent.', 'HARD', 'General Knowledge', 'Folk Dances & Festivals of India', 'GK_FOLK_DANCES_FESTIVALS', '[{"option_text": "Tripura", "is_correct": true}, {"option_text": "Manipur", "is_correct": false}, {"option_text": "Mizoram", "is_correct": false}, {"option_text": "Meghalaya", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1832bfa6-a380-548a-9810-11eab1bb121d', 'Ghoomar, Kalbeliya, and Terah Tali are traditional folk dances of which state?', NULL, 'GHOOMAR: graceful women''s dance in flowing ghaghra, originally Bhil then adopted by royal Rajput courts (gained global fame via 2018 Padmaavat film). KALBELIYA: the ''Snake Charmer Dance'' of the Kalbeliya (Sapera) nomadic community — UNESCO Intangible Heritage (2010); fluid twirling movements in black swirling skirts. TERAH TALI: a sit-down dance of the Kamad community for Baba Ramdev, where women strike 13 tiny cymbals tied to their bodies. Other Rajasthani: Gair (men), Chakri, Bhavai (balancing pots), Kachhi Ghodi (mock horse).', 'MEDIUM', 'General Knowledge', 'Folk Dances & Festivals of India', 'GK_FOLK_DANCES_FESTIVALS', '[{"option_text": "Rajasthan", "is_correct": true}, {"option_text": "Gujarat", "is_correct": false}, {"option_text": "Madhya Pradesh", "is_correct": false}, {"option_text": "Haryana", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1d6d6a15-a687-516b-98cb-52f76413df41', 'Chhau is a semi-classical dance form performed in which three states?', NULL, 'Chhau, inscribed on UNESCO''s Intangible Cultural Heritage list in 2010, has three distinct schools: (1) PURULIA CHHAU (West Bengal — most ornate, big colorful masks); (2) SERAIKELLA CHHAU (Jharkhand — masks, refined movements); (3) MAYURBHANJ CHHAU (Odisha — NO masks, most acrobatic/martial). Themes are from Ramayana, Mahabharata, tribal lore. Performed primarily during the Chaitra Parva festival in spring. Roots in martial arts (Phari-Khanda) and tribal dance.', 'MEDIUM', 'General Knowledge', 'Folk Dances & Festivals of India', 'GK_FOLK_DANCES_FESTIVALS', '[{"option_text": "Bihar, Jharkhand, Uttar Pradesh", "is_correct": false}, {"option_text": "West Bengal, Jharkhand, Odisha", "is_correct": true}, {"option_text": "Odisha, Andhra Pradesh, Telangana", "is_correct": false}, {"option_text": "Sikkim, Arunachal, Nagaland", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cc31de90-7ea6-504c-8c55-1cbc0d79e4fe', 'Theyyam, a ritualistic dance where the performer embodies a deity, is performed in which state?', NULL, 'Theyyam (also Kaliyattam, Tira) is a sacred ritual dance-drama of North Malabar (Kannur, Kasaragod districts) of Kerala. Over 400 distinct Theyyam forms exist; the performer, after elaborate makeup and costume (often spanning 8-10 hours to don), is believed to become the deity itself — devotees seek blessings directly from ''the god''. Associated with Kaavu (sacred groves) and the Dravidian pre-Hindu pantheon. Other Kerala dances: Kathakali (classical), Mohiniyattam (classical), Padayani, Koodiyattam (UNESCO 2001), Ottamthullal.', 'MEDIUM', 'General Knowledge', 'Folk Dances & Festivals of India', 'GK_FOLK_DANCES_FESTIVALS', '[{"option_text": "Karnataka", "is_correct": false}, {"option_text": "Kerala", "is_correct": true}, {"option_text": "Tamil Nadu", "is_correct": false}, {"option_text": "Andhra Pradesh", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6e0c9ed0-22d4-533b-b894-f96013382712', 'Lavani and Tamasha are folk performing arts most associated with which state?', NULL, 'LAVANI is Maharashtra''s famous women''s dance performed to the beats of the Dholki drum; ''lavanya'' means beauty. Popularised during 18th-19th c. Peshwa era; often features in Tamasha. TAMASHA is the popular folk-theatre form of Maharashtra combining dance, drama, and music, traditionally performed by the Kolhati and Mahar communities. Other Maharashtra folk: Gondhal (ritual dance-song for Devi), Lezim (martial stick dance), Dhangari Gaja (shepherd tribe), Povadas (heroic ballads on Shivaji).', 'EASY', 'General Knowledge', 'Folk Dances & Festivals of India', 'GK_FOLK_DANCES_FESTIVALS', '[{"option_text": "Gujarat", "is_correct": false}, {"option_text": "Maharashtra", "is_correct": true}, {"option_text": "Karnataka", "is_correct": false}, {"option_text": "Madhya Pradesh", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cc42dbc9-7de9-5e0f-9df2-32d7a432c7c5', 'The Konyak tribe''s Aoling festival and the Ao tribe''s Moatsu Mong are celebrated in which state?', NULL, 'Nagaland has 17 recognised tribes, each with signature festivals: AOLING (Konyaks — April, spring, new year); MOATSU MONG (Aos — May, post-sowing); TULUNI (Sumis — July, abundance); SEKRENYI (Angamis — Feb, purification); TOKHU EMONG (Lothas — Nov, post-harvest); BUSHU JIBA (Kacharis); NGADA (Rengmas); MIMKUT (not to be confused with Mizo — Kukis have one too). Konyaks are historically known as the ''Headhunter'' tribe (the practice ceased 1960s). Know at least 5-6 tribe-festival pairings.', 'HARD', 'General Knowledge', 'Folk Dances & Festivals of India', 'GK_FOLK_DANCES_FESTIVALS', '[{"option_text": "Manipur", "is_correct": false}, {"option_text": "Nagaland", "is_correct": true}, {"option_text": "Assam", "is_correct": false}, {"option_text": "Arunachal Pradesh", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f709086e-d0c9-57cf-a165-8d9f9195d743', 'Which of the following is the harvest festival celebrated in Tamil Nadu in January?', NULL, 'PONGAL is Tamil Nadu''s 4-day harvest festival in mid-January (Thai month): Day 1 BHOGI (discarding old), Day 2 THAI (Surya) PONGAL (cooking the Pongal dish — sweet rice overflowing the pot signals prosperity), Day 3 MATTU PONGAL (honouring cattle), Day 4 KAANUM PONGAL (family reunion). Coincides with Makar Sankranti / Lohri (Punjab) / Uttarayan (Guj) / Magh Bihu (Assam) / Pedda Panduga (AP). Onam = Kerala (Aug-Sept Malayalam new year harvest). Ugadi = Karnataka/AP/Telangana (Chaitra new year).', 'EASY', 'General Knowledge', 'Folk Dances & Festivals of India', 'GK_FOLK_DANCES_FESTIVALS', '[{"option_text": "Onam", "is_correct": false}, {"option_text": "Pongal", "is_correct": true}, {"option_text": "Baisakhi", "is_correct": false}, {"option_text": "Ugadi", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0bd59062-d890-53a9-93f8-75762e8cc7f9', 'The United Nations was established in 1945. Where is its headquarters located?', NULL, 'The UN was established on 24 October 1945 (after 50 founding members ratified the Charter). HQ is in New York City (extraterritorial status — not under US jurisdiction). Other major UN centres: Geneva (UNHCR, WHO, ILO, UNCTAD, WIPO, WTO), Vienna (IAEA, UNIDO, UNODC), Nairobi (UNEP, UN-Habitat), The Hague (ICJ + ICC separate from UN). Six principal organs: General Assembly, Security Council (5 P + 10 non-P), Economic & Social Council, Trusteeship (suspended 1994), Secretariat, ICJ. India is a founding member; never permanent SC member (aspires to reform).', 'EASY', 'General Knowledge', 'International Organizations & Headquarters', 'GK_INTL_ORG', '[{"option_text": "Geneva, Switzerland", "is_correct": false}, {"option_text": "New York City, USA", "is_correct": true}, {"option_text": "The Hague, Netherlands", "is_correct": false}, {"option_text": "Paris, France", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2d73e266-9a10-510f-a744-887c5600bf1f', 'Match HQ to organisation: (I) Geneva (II) Washington DC (III) Paris (IV) Rome', NULL, 'GENEVA: WHO, ILO, WTO, UNHCR, UNCTAD, WIPO, ITU. NEW YORK: UN HQ, UNICEF, UNDP, UN Women, UNFPA. WASHINGTON DC: IMF, World Bank, IFC. PARIS: UNESCO, OECD. ROME: FAO (Food and Agriculture Organization), WFP (World Food Programme), IFAD. VIENNA: IAEA, UNIDO, UNODC, OPEC. NAIROBI: UNEP, UN-Habitat. THE HAGUE: ICJ (UN''s judicial organ), ICC (independent). BRUSSELS: EU, NATO. BASEL: BIS. Memorise the top-20 HQ-org mappings — very high-hit-rate on exams.', 'HARD', 'General Knowledge', 'International Organizations & Headquarters', 'GK_INTL_ORG', '[{"option_text": "(I) WHO (II) IMF & World Bank (III) UNESCO (IV) FAO", "is_correct": true}, {"option_text": "(I) WTO (II) ILO (III) UNICEF (IV) WHO", "is_correct": false}, {"option_text": "(I) UNESCO (II) WTO (III) IMF (IV) IAEA", "is_correct": false}, {"option_text": "(I) IAEA (II) UNIDO (III) UNESCO (IV) IMF", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6f52d901-3fd8-55fa-afa2-748ef79d4e8e', 'The International Court of Justice (ICJ) is located in which city?', NULL, 'The ICJ — principal judicial organ of the UN — is headquartered at the Peace Palace in The Hague, Netherlands. The ONLY principal UN organ NOT in New York. Succeeded the Permanent Court of International Justice (1920). 15 judges, 9-year terms. India''s Justice Dalveer Bhandari (elected 2012, re-elected 2017 till 2027). Other courts at The Hague: INTERNATIONAL CRIMINAL COURT (ICC — 2002, for individuals; not a UN body), Permanent Court of Arbitration (1899). Geneva has WTO Dispute Settlement (not a court).', 'MEDIUM', 'General Knowledge', 'International Organizations & Headquarters', 'GK_INTL_ORG', '[{"option_text": "New York", "is_correct": false}, {"option_text": "The Hague, Netherlands", "is_correct": true}, {"option_text": "Geneva", "is_correct": false}, {"option_text": "Brussels", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c7738ca8-14a7-54f4-99d4-053535fffd8d', 'OPEC (Organisation of Petroleum Exporting Countries) is headquartered in which city?', NULL, 'OPEC was founded in 1960 at the Baghdad Conference (Iraq, Iran, Kuwait, Saudi Arabia, Venezuela — the 5 founders). HQ initially in Geneva (1960-65), moved to VIENNA in 1965 (where it remains). Current members: 12 (after Qatar left 2019, Ecuador 2020, Angola 2023). Most recent: Equatorial Guinea, Congo, Gabon joined. OPEC+ refers to OPEC plus 10 non-OPEC (led by Russia) that cooperates on output. OPEC controls ~40% of global oil production and ~80% of proven reserves. Saudi Arabia is the de facto leader. Meetings in Vienna twice yearly.', 'MEDIUM', 'General Knowledge', 'International Organizations & Headquarters', 'GK_INTL_ORG', '[{"option_text": "Riyadh, Saudi Arabia", "is_correct": false}, {"option_text": "Vienna, Austria", "is_correct": true}, {"option_text": "Tehran, Iran", "is_correct": false}, {"option_text": "Dubai, UAE", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9597ecd3-8de4-5349-a313-3ff1f1a2fb13', 'Which Indian city hosts the headquarters of the International Solar Alliance (ISA), launched by India and France in 2015?', NULL, 'The International Solar Alliance (ISA) is headquartered at GURUGRAM, Haryana — India''s first treaty-based international intergovernmental organisation. Launched at COP21 Paris 2015 by PM Modi & President Hollande. Treaty entered force 2017. HQ inaugurated by PM Modi & UN SG Antonio Guterres in 2018. Target: 1 TW of solar capacity by 2030 and mobilise $1 trillion investment. Originally open only to countries between the Tropics of Cancer and Capricorn; expanded in 2020 to all UN member states. 119 members and signatories. DG: Ajay Mathur (till 2024), succeeded by Dr. B.N. Satpathy.', 'HARD', 'General Knowledge', 'International Organizations & Headquarters', 'GK_INTL_ORG', '[{"option_text": "Mumbai", "is_correct": false}, {"option_text": "Gurugram (Haryana)", "is_correct": true}, {"option_text": "Bengaluru", "is_correct": false}, {"option_text": "Hyderabad", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('154beefd-ca21-53cb-8a93-fce2f95581fd', 'The BRICS grouping, formed in 2009 (BRIC) and expanded to BRICS with South Africa''s entry in 2010, was further expanded in January 2024 with which new members?', NULL, 'Original BRIC (2009): Brazil, Russia, India, China. South Africa joined 2010 → BRICS. At the 15th Summit (Johannesburg, Aug 2023), BRICS invited Argentina, Egypt, Ethiopia, Iran, Saudi Arabia, UAE — to join from 1 Jan 2024. Argentina DECLINED (after Milei came to power). Saudi Arabia''s status is ''invited but deferred''. So effective Jan 2024: 9 members — Brazil, Russia, India, China, South Africa + Egypt, Ethiopia, Iran, UAE. Indonesia formally joined Jan 2025 as the 10th member. HQ: New Development Bank in Shanghai; Contingent Reserve Arrangement. India''s 16th BRICS summit hosted at Kazan, Russia, Oct 2024.', 'HARD', 'General Knowledge', 'International Organizations & Headquarters', 'GK_INTL_ORG', '[{"option_text": "Egypt, Ethiopia, Iran, UAE (4 new members)", "is_correct": true}, {"option_text": "Saudi Arabia, Argentina, Mexico, Nigeria", "is_correct": false}, {"option_text": "Indonesia, Vietnam, Turkey, Bangladesh", "is_correct": false}, {"option_text": "Pakistan, Malaysia, Thailand, South Korea", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('187bdc3d-9229-50eb-a3cc-df9cfdc081dc', 'The World Trade Organization (WTO) was established in 1995, replacing which earlier agreement?', NULL, 'The WTO was established on 1 January 1995 following the Marrakesh Agreement (1994) that concluded the Uruguay Round of GATT (General Agreement on Tariffs and Trade, 1947) negotiations. WTO REPLACES GATT as a formal institution but retains GATT as one of its covered agreements (for goods). Other WTO covered agreements: GATS (services), TRIPS (intellectual property), DSU (dispute settlement understanding). HQ: Geneva. Current DG: Dr. Ngozi Okonjo-Iweala (Nigeria — first woman and first African, appointed March 2021). 164 members. India has been challenging many WTO decisions on agricultural subsidies, digital trade, MSP. The ''Appellate Body'' is currently dysfunctional due to US blocking new appointments since 2019.', 'MEDIUM', 'General Knowledge', 'International Organizations & Headquarters', 'GK_INTL_ORG', '[{"option_text": "International Trade Organization (ITO)", "is_correct": false}, {"option_text": "General Agreement on Tariffs and Trade (GATT)", "is_correct": true}, {"option_text": "Bretton Woods Agreement", "is_correct": false}, {"option_text": "Marshall Plan", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9f277ba3-a258-5c9a-9036-3a3d28066c2e', 'The Asian Development Bank (ADB) is headquartered in which city?', NULL, 'Asian Development Bank (ADB) was established 1966; HQ at MANILA, Philippines. 68 member economies (49 from Asia-Pacific + 19 from outside). Current President: Masatsugu Asakawa (Japan, since 2020 — all ADB Presidents since founding have been Japanese). Largest ADB-funded countries: China, India, Indonesia, Pakistan, Bangladesh. In contrast: AIIB (Asian Infrastructure Investment Bank, 2016) — HQ at BEIJING, China; President Jin Liqun (Chinese). India is ADB''s 4th-largest shareholder but a NON-FOUNDING member of AIIB (joined as 2nd-largest shareholder). NDB (New Development Bank / BRICS Bank) — HQ at SHANGHAI, first President KV Kamath (India, 2015-20).', 'HARD', 'General Knowledge', 'International Organizations & Headquarters', 'GK_INTL_ORG', '[{"option_text": "Tokyo, Japan", "is_correct": false}, {"option_text": "Manila, Philippines", "is_correct": true}, {"option_text": "Bangkok, Thailand", "is_correct": false}, {"option_text": "Beijing, China", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c99a48d9-ac50-54cf-b4c2-f87445d9bf85', 'SAARC has how many member countries and where is its secretariat located?', NULL, 'SAARC (South Asian Association for Regional Cooperation) was founded in Dhaka on 8 December 1985 with 7 members. Afghanistan joined 2007 as 8th member. Current members (8): Afghanistan, Bangladesh, Bhutan, India, Maldives, Nepal, Pakistan, Sri Lanka. HQ: Kathmandu, Nepal. Current Secretary-General: Golam Sarwar (Bangladesh, from March 2023). Observer states: Australia, China, EU, Iran, Japan, Myanmar, S. Korea, US, Mauritius. SAARC summits have been stalled since the 18th (Kathmandu 2014); 19th scheduled Islamabad 2016 was boycotted by India, Bangladesh, Bhutan, Afghanistan after Uri attack. Effective successor: BIMSTEC (since 1997) — includes Bay of Bengal countries, HQ Dhaka.', 'EASY', 'General Knowledge', 'International Organizations & Headquarters', 'GK_INTL_ORG', '[{"option_text": "7 members; Secretariat in Islamabad", "is_correct": false}, {"option_text": "8 members; Secretariat in Kathmandu", "is_correct": true}, {"option_text": "6 members; Secretariat in Colombo", "is_correct": false}, {"option_text": "9 members; Secretariat in Dhaka", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('17efeb91-e328-5b42-9bb6-0149f05baaa8', 'The Tabla is classified under which category of Indian musical instruments?', NULL, 'Indian instruments are classified into 4 categories (Natya Shastra by Bharat Muni): (1) TATA VADYA = string (Sitar, Sarod, Veena, Sarangi, Santoor); (2) SUSHIR VADYA = wind (Bansuri, Shehnai, Nadaswaram, Shankh); (3) AVANADDHA VADYA = percussion with stretched membrane (Tabla, Mridangam, Dholak, Pakhawaj); (4) GHANA VADYA = solid/self-sounding, no strings or membrane (Manjira, Ghatam, Kartal, Jaltarang). Tabla was developed in the 18th c., reportedly by Amir Khusrau''s disciple — hence it''s relatively recent compared to Pakhawaj.', 'EASY', 'General Knowledge', 'Indian Music & Musical Instruments', 'GK_MUSIC_INSTRUMENTS', '[{"option_text": "Tata Vadya (string)", "is_correct": false}, {"option_text": "Sushir Vadya (wind)", "is_correct": false}, {"option_text": "Avanaddha Vadya (percussion/membrane)", "is_correct": true}, {"option_text": "Ghana Vadya (solid/self-sounding)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8beb1c38-c914-5478-b7d9-873949187314', 'The Shehnai, associated with Ustad Bismillah Khan, is what type of instrument?', NULL, 'The Shehnai is a SUSHIR (wind/reed) instrument — a double-reed oboe-family instrument made of wood with a metal flared bell. Traditionally played at weddings, temples, and on auspicious occasions in North India; considered a symbol of auspiciousness (''mangal vadya''). The legendary Ustad BISMILLAH KHAN (1916-2006) — Bharat Ratna 2001 — was the Shehnai''s greatest modern exponent; he played at Red Fort on 15 August 1947. South Indian counterpart: NADASWARAM (longer, louder, always played outdoors).', 'EASY', 'General Knowledge', 'Indian Music & Musical Instruments', 'GK_MUSIC_INSTRUMENTS', '[{"option_text": "Percussion (Avanaddha)", "is_correct": false}, {"option_text": "Wind/Reed (Sushir)", "is_correct": true}, {"option_text": "String (Tata)", "is_correct": false}, {"option_text": "Self-sounding (Ghana)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c6437668-d722-50bc-98b6-df2c7efcba8b', 'Who among the following was the world-famous SANTOOR exponent from Jammu & Kashmir, awarded the Padma Vibhushan?', NULL, 'Pandit Shivkumar Sharma (1938-2022) single-handedly elevated the Santoor — a Kashmiri folk trapezoidal string instrument played with mallets, with 100 strings — to the status of an Indian classical concert instrument. Padma Shri 1991, Padma Vibhushan 2001. Known for the ''Shiv-Hari'' duo with Hariprasad Chaurasia (composed music for Silsila, Chandni, Lamhe). Ravi Shankar = Sitar, Zakir Hussain = Tabla, Hariprasad Chaurasia = Bansuri (bamboo flute).', 'MEDIUM', 'General Knowledge', 'Indian Music & Musical Instruments', 'GK_MUSIC_INSTRUMENTS', '[{"option_text": "Pandit Ravi Shankar", "is_correct": false}, {"option_text": "Pandit Shivkumar Sharma", "is_correct": true}, {"option_text": "Ustad Zakir Hussain", "is_correct": false}, {"option_text": "Pandit Hariprasad Chaurasia", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2c34f5a1-16d2-5475-a415-8704b7d3a6c2', 'The Mridangam is the principal percussion instrument of which classical music tradition?', NULL, 'The Mridangam is the primary percussion instrument of Carnatic classical music (South India) — a barrel-shaped two-headed drum played horizontally, with the right head higher pitched (valanthalai) and left lower (thoppi). Its counterpart in Hindustani (North India) classical music is the PAKHAWAJ (from which the Mridangam evolved). The Mridangam''s Carnatic equivalents: Ghatam (clay pot), Kanjira (tambourine), Morsing (jaw harp). Palghat Mani Iyer, TK Murthy, Umayalpuram Sivaraman are legendary exponents.', 'MEDIUM', 'General Knowledge', 'Indian Music & Musical Instruments', 'GK_MUSIC_INSTRUMENTS', '[{"option_text": "Hindustani", "is_correct": false}, {"option_text": "Carnatic", "is_correct": true}, {"option_text": "Rabindra Sangeet", "is_correct": false}, {"option_text": "Odissi music", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a7d48ee7-287f-5b7c-88ce-f7e14ce804bb', 'The Trinity of Carnatic Music refers to which three 18th-century composers?', NULL, 'The Carnatic Trinity are three composer-saints — all contemporaries born in Tiruvarur (Tamil Nadu) in the 18th c.: (1) TYAGARAJA (1767-1847) — composed 700+ kritis in Telugu; Aradhana celebrated at Thiruvaiyaru; (2) MUTHUSWAMI DIKSHITAR (1775-1835) — Sanskrit kritis, Navagraha kritis on planets; (3) SHYAMA SHASTRI (1762-1827) — Telugu/Sanskrit works, specialist of the Swarajathi form. Purandara Dasa (~1484-1564) is called the ''Sangeet Pitamaha'' (father of Carnatic) — separate, earlier figure.', 'HARD', 'General Knowledge', 'Indian Music & Musical Instruments', 'GK_MUSIC_INSTRUMENTS', '[{"option_text": "Purandara Dasa, Kanakadasa, Swati Tirunal", "is_correct": false}, {"option_text": "Tyagaraja, Muthuswami Dikshitar, Shyama Shastri", "is_correct": true}, {"option_text": "Mysore Vasudevacharya, GN Balasubramaniam, MS Subbulakshmi", "is_correct": false}, {"option_text": "Tansen, Haridas, Baiju Bawra", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('29efe002-4681-580a-a4b3-573016b6c2eb', 'The Pena (a bowed, single-stringed folk instrument with a coconut shell resonator) is a cultural symbol of which state?', NULL, 'The PENA (also called Bana or Tingtelia) is a traditional single-stringed bowed chordophone of Manipur, made of a coconut-shell resonator covered with dry leather and a bamboo neck. Central to the Meitei people''s cultural repertoire — especially accompanying the narration of the Khamba-Thoibi legend. Pena artists are called ''Pena Asheiba''. Other state-specific folk instruments worth knowing: PEPA (buffalo-horn flute — Assam''s Bihu), GOGONA (reed-jaw harp — Assam), DHOL (Assam, Punjab etc.), BIHU DHOL, SUMUI (Manipur flute), DIMSA & RABAB (tribal).', 'HARD', 'General Knowledge', 'Indian Music & Musical Instruments', 'GK_MUSIC_INSTRUMENTS', '[{"option_text": "Mizoram", "is_correct": false}, {"option_text": "Manipur", "is_correct": true}, {"option_text": "Nagaland", "is_correct": false}, {"option_text": "Sikkim", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c24ebb1c-0fa8-5f25-b50a-523bc8c3a5d7', 'Amir Khusrau is credited with inventing which two Indian musical instruments?', NULL, 'Amir Khusrau (1253-1325), the court poet-musician of the Delhi Sultanate, is traditionally credited with having developed or popularised the SITAR (from the Persian ''seh-tar'' = three-stringed — evolved from Veena + Persian tanbur) and — per one tradition — the TABLA (though codification of modern tabla is by Siddhar Khan, 18th c., disciple of Khusrau''s lineage). Khusrau also developed the Qawwali and Khayal genres, ragas like Yaman, Aiman, Bahar, Sanam. He is called ''Tuti-e-Hind'' (Parrot of India).', 'MEDIUM', 'General Knowledge', 'Indian Music & Musical Instruments', 'GK_MUSIC_INSTRUMENTS', '[{"option_text": "Santoor and Rabab", "is_correct": false}, {"option_text": "Sitar and Tabla (partly attributed)", "is_correct": true}, {"option_text": "Sarangi and Shehnai", "is_correct": false}, {"option_text": "Veena and Mridangam", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8c8458ac-0235-5da1-b762-b9c31dbfdba9', 'Which Hindustani gharana is the OLDEST traditional gharana of classical vocal music?', NULL, 'The GWALIOR gharana is the oldest school of Hindustani khayal singing, traced to Natthan Pir Baksh (late 18th c.) and the Haddu-Hassu brothers. Known for pure raga-based khayal, clear enunciation. Other major gharanas: AGRA (Ustad Faiyaz Khan — blend of khayal with dhrupad), JAIPUR-ATRAULI (Alladiya Khan — rare ragas, complex tans), KIRANA (Abdul Karim Khan, Bhimsen Joshi, Gangubai Hangal — emphasis on swara and mood), PATIALA (Bade Ghulam Ali Khan — thumri + khayal), RAMPUR-SAHASWAN (Mushtaq Husain Khan), BHENDIBAZAAR (Mumbai — influenced by Agra). Tabla has its own gharanas: Delhi, Lucknow, Ajrada, Farrukhabad, Benaras, Punjab.', 'HARD', 'General Knowledge', 'Indian Music & Musical Instruments', 'GK_MUSIC_INSTRUMENTS', '[{"option_text": "Kirana Gharana", "is_correct": false}, {"option_text": "Gwalior Gharana", "is_correct": true}, {"option_text": "Patiala Gharana", "is_correct": false}, {"option_text": "Agra Gharana", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('39c2ebf9-0f8c-563b-b2d7-04346973cb06', 'Sarod is an adaptation of which Central Asian instrument, brought to India and evolved?', NULL, 'The Sarod is a modified descendant of the Afghan RABAB, brought by Afghan warriors and refined in Gwalior during the 19th c. Unlike the wooden-fretted sitar, the Sarod has a fretless fingerboard covered with a steel plate and uses a coconut-shell resonator — giving it a deep, meditative tone. The GHULAM ALI KHAN / ALI AKBAR KHAN / AMJAD ALI KHAN lineage and the MAIHAR gharana (Ustad Allauddin Khan) are principal exponents. The original Afghan Rabab is also played in Kashmiri music; Sitar evolved from Persian Tanbur/Setar.', 'MEDIUM', 'General Knowledge', 'Indian Music & Musical Instruments', 'GK_MUSIC_INSTRUMENTS', '[{"option_text": "Tanbur", "is_correct": false}, {"option_text": "Rabab", "is_correct": true}, {"option_text": "Setar", "is_correct": false}, {"option_text": "Ney", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fbf20248-67db-5907-9e2e-efc973c410a5', 'Which of the following is NOT a Ghana Vadya (self-sounding) instrument?', NULL, 'GHANA VADYA = self-sounding (idiophones): MANJIRA (small cymbals), GHATAM (clay pot, Carnatic), GHUNGROO (ankle bells), KHARTAL (wooden clappers), CHIMTA (metal tongs), JALTARANG (tuned bowls of water). SARANGI is a TATA VADYA (bowed string) — played with a bow; main accompaniment for Hindustani vocal music and Kathak. Its smaller bamboo cousin, the DILRUBA & ESRAJ, are also strings. Students often confuse Sarangi with Sarod (plucked) and the wind instruments — these are distinct classifications.', 'MEDIUM', 'General Knowledge', 'Indian Music & Musical Instruments', 'GK_MUSIC_INSTRUMENTS', '[{"option_text": "Manjira", "is_correct": false}, {"option_text": "Ghatam", "is_correct": false}, {"option_text": "Ghungroo", "is_correct": false}, {"option_text": "Sarangi", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('36b2025e-58d6-5125-b240-c0f9bedc7bcb', 'Which is the oldest National Park in India, established in 1936?', NULL, 'Jim Corbett NP (Uttarakhand) was established in 1936 as Hailey National Park — India''s first — renamed in 1957 after the famous hunter-conservationist Jim Corbett. It is also where Project Tiger was launched in 1973. Spread over 520 sq km in the Nainital district. Known for its high density of Bengal tigers, Indian elephants, gharials in the Ramganga river.', 'EASY', 'General Knowledge', 'National Parks, Wildlife Sanctuaries & Biosphere Reserves', 'GK_NATIONAL_PARKS', '[{"option_text": "Kaziranga National Park", "is_correct": false}, {"option_text": "Jim Corbett National Park", "is_correct": true}, {"option_text": "Gir National Park", "is_correct": false}, {"option_text": "Bandipur National Park", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d8c7b0c5-f0f9-5b0d-b3ec-653fba497b4c', 'Kaziranga National Park, famous for the one-horned rhinoceros, is located in which state and is inscribed on which UNESCO list?', NULL, 'Kaziranga NP (Assam) was inscribed as a UNESCO Natural World Heritage Site in 1985. Home to two-thirds of the world''s population of Indian one-horned rhinoceroses (Rhinoceros unicornis). It hosts the ''Big Five'' of Kaziranga: one-horned rhino, Bengal tiger, Asian elephant, wild water buffalo, and swamp deer (eastern barasingha). Also a tiger reserve (2006) and Important Bird Area. Spans floodplains of the Brahmaputra.', 'EASY', 'General Knowledge', 'National Parks, Wildlife Sanctuaries & Biosphere Reserves', 'GK_NATIONAL_PARKS', '[{"option_text": "Arunachal Pradesh; Cultural Heritage", "is_correct": false}, {"option_text": "Assam; Natural World Heritage", "is_correct": true}, {"option_text": "Meghalaya; Biosphere Reserve only", "is_correct": false}, {"option_text": "Nagaland; Ramsar Site", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('873f37c4-f981-5244-8e9b-20b9af149144', 'Namdapha National Park, India''s fourth largest NP and home to four species of big cats (Tiger, Leopard, Clouded Leopard, Snow Leopard), is located in which state?', NULL, 'Namdapha NP (Changlang district, Arunachal Pradesh) is the 4th largest NP in India (1985 sq km) and the northernmost lowland evergreen rainforest in the world. Unique distinction: it is the ONLY park in the world where all four big cat species coexist — Bengal tiger, common leopard, clouded leopard, and snow leopard. Also home to red panda, hoolock gibbon (India''s only ape), and the recently discovered Namdapha flying squirrel.', 'HARD', 'General Knowledge', 'National Parks, Wildlife Sanctuaries & Biosphere Reserves', 'GK_NATIONAL_PARKS', '[{"option_text": "Sikkim", "is_correct": false}, {"option_text": "Arunachal Pradesh", "is_correct": true}, {"option_text": "Himachal Pradesh", "is_correct": false}, {"option_text": "Uttarakhand", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('acaf76b3-e25f-5191-9e70-78758cd366af', 'Which National Park is the only natural habitat of the Asiatic Lion (Panthera leo persica)?', NULL, 'Gir NP (Junagadh, Gujarat) is the ONLY place in the world where the Asiatic Lion survives in the wild, after having once been on the verge of extinction (only 20 lions in 1913). Current population ~674 (2020 census); projected higher in 2025 census. Historically lived from Syria to Bengal. Gir also houses leopards, chinkara, chausingha (four-horned antelope), pangolin, and 300+ bird species. Adjacent Barda and Mitiyala sanctuaries serve as extended habitat.', 'EASY', 'General Knowledge', 'National Parks, Wildlife Sanctuaries & Biosphere Reserves', 'GK_NATIONAL_PARKS', '[{"option_text": "Ranthambore, Rajasthan", "is_correct": false}, {"option_text": "Gir, Gujarat", "is_correct": true}, {"option_text": "Bandipur, Karnataka", "is_correct": false}, {"option_text": "Corbett, Uttarakhand", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('53bd6fe7-a043-5053-bdf2-1d99b06a4dcb', 'Sundarbans, home to the Royal Bengal Tiger and one of the largest mangrove forests in the world, is located at the delta of which rivers?', NULL, 'Sundarbans NP (West Bengal) covers the Indian part of the Sundarbans delta formed by the Ganga, Brahmaputra, and Meghna rivers meeting the Bay of Bengal. It is: (a) UNESCO World Heritage Site (1987), (b) a Biosphere Reserve (1989), (c) a Tiger Reserve, (d) a Ramsar wetland (2019). Known for the ''swimming tigers'' of Sundarbans — the local Bengal tigers are excellent swimmers, adapted to tidal waters. Habitat for saltwater crocodile, king cobra, Gangetic dolphin.', 'MEDIUM', 'General Knowledge', 'National Parks, Wildlife Sanctuaries & Biosphere Reserves', 'GK_NATIONAL_PARKS', '[{"option_text": "Godavari and Krishna", "is_correct": false}, {"option_text": "Ganga, Brahmaputra and Meghna", "is_correct": true}, {"option_text": "Mahanadi and Brahmani", "is_correct": false}, {"option_text": "Krishna and Pennar", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('dd4ed9fd-f6b2-55eb-84d2-0fbd1fc8a331', 'Which of the following was the FIRST Biosphere Reserve established in India (1986)?', NULL, 'The Nilgiri Biosphere Reserve (TN/Karnataka/Kerala tri-junction) was established in 1986 — India''s FIRST of 18 biosphere reserves. It covers Mudumalai, Bandipur, Nagarhole, Wayanad, Mukurthi, Silent Valley. Of the 18 Indian BRs, 12 are recognised under UNESCO''s Man and the Biosphere (MAB) Programme. The Gulf of Mannar was the first marine biosphere reserve. Kachchh is the largest by area; Nokrek (Meghalaya) is the smallest.', 'MEDIUM', 'General Knowledge', 'National Parks, Wildlife Sanctuaries & Biosphere Reserves', 'GK_NATIONAL_PARKS', '[{"option_text": "Nanda Devi", "is_correct": false}, {"option_text": "Nilgiri", "is_correct": true}, {"option_text": "Sundarbans", "is_correct": false}, {"option_text": "Gulf of Mannar", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3066ccb0-d27b-530c-94b2-0329f4755fc7', 'Which was the FIRST Ramsar wetland designated in India in 1981?', NULL, 'Chilika Lake (Odisha — largest brackish-water lagoon in Asia) and Keoladeo NP (Rajasthan — formerly Bharatpur Bird Sanctuary) were BOTH designated as India''s first Ramsar sites on 1 October 1981. As of 2024, India has 85+ Ramsar sites — the highest in Asia (Tamil Nadu leads with ~16 sites). The Ramsar Convention on Wetlands (1971, Iran) aims to conserve wetlands of international importance. World Wetlands Day: 2 February.', 'HARD', 'General Knowledge', 'National Parks, Wildlife Sanctuaries & Biosphere Reserves', 'GK_NATIONAL_PARKS', '[{"option_text": "Keoladeo (Bharatpur, Rajasthan) ONLY", "is_correct": false}, {"option_text": "Chilika (Odisha) AND Keoladeo (Rajasthan) — designated together", "is_correct": true}, {"option_text": "Wular Lake (J&K)", "is_correct": false}, {"option_text": "Loktak (Manipur)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0b83bb62-9cc9-54b5-9d16-2b9d4fbe4823', 'Kuno National Park, where cheetahs were reintroduced to India in September 2022 after 70 years of extinction, is located in which state?', NULL, 'Kuno NP (Sheopur district, Madhya Pradesh) saw the arrival of 8 cheetahs from Namibia on 17 Sept 2022 (PM Modi''s birthday) under ''Project Cheetah'' — the world''s first inter-continental cheetah translocation. A second batch of 12 came from South Africa in Feb 2023. Cheetahs were declared extinct in India in 1952 (last one in Chhattisgarh''s Koriya district). MP is sometimes called India''s ''Tiger State'' but is now also its ''Cheetah State''. Kuno was earlier developed as an alternative lion habitat.', 'EASY', 'General Knowledge', 'National Parks, Wildlife Sanctuaries & Biosphere Reserves', 'GK_NATIONAL_PARKS', '[{"option_text": "Rajasthan", "is_correct": false}, {"option_text": "Madhya Pradesh", "is_correct": true}, {"option_text": "Gujarat", "is_correct": false}, {"option_text": "Maharashtra", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('99f9c61d-8d7d-54ed-8199-96cddd364a3c', 'Which Indian state has the highest number of National Parks (11)?', NULL, 'Madhya Pradesh has the MOST national parks (11): Kanha, Bandhavgarh, Pench, Satpura, Panna, Madhav, Van Vihar, Sanjay (Dubri), Kuno, Fossil (Mandla), Dinosaur Fossil (Dhar). MP is also called the ''Tiger State'' based on tiger numbers (785 tigers per 2022 census — highest in India). Andhra Pradesh + Telangana together have 6. Maharashtra has 6. Uttarakhand 6. Karnataka 5. Kerala 6.', 'MEDIUM', 'General Knowledge', 'National Parks, Wildlife Sanctuaries & Biosphere Reserves', 'GK_NATIONAL_PARKS', '[{"option_text": "Uttarakhand", "is_correct": false}, {"option_text": "Madhya Pradesh", "is_correct": true}, {"option_text": "Maharashtra", "is_correct": false}, {"option_text": "Karnataka", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c3b6348e-1382-5b67-bbd9-0f13ed0ed5ff', 'Project Tiger was launched in India in which year and from which National Park?', NULL, 'Project Tiger was launched on 1 April 1973 from Jim Corbett NP during Indira Gandhi''s premiership, in response to alarming tiger declines (India had ~40,000 tigers in 1900, dropped to ~1,827 by 1972). Initially 9 tiger reserves; now 54 (most recent: Kaudia TR in UP in 2024). NTCA (National Tiger Conservation Authority) is the statutory body under Wildlife Protection Act (2006 amendment). 2022 census: 3,682 tigers (up from 2,967 in 2018) — India has ~75% of the world''s wild tigers.', 'MEDIUM', 'General Knowledge', 'National Parks, Wildlife Sanctuaries & Biosphere Reserves', 'GK_NATIONAL_PARKS', '[{"option_text": "1970; Kanha, Madhya Pradesh", "is_correct": false}, {"option_text": "1973; Jim Corbett, Uttarakhand", "is_correct": true}, {"option_text": "1975; Ranthambore, Rajasthan", "is_correct": false}, {"option_text": "1983; Bandipur, Karnataka", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('20200db3-e286-5aab-a259-1fe384201eb2', 'Which National Park is known as the ''Valley of Flowers'', a UNESCO World Heritage Site?', NULL, 'Valley of Flowers NP (Chamoli district, Uttarakhand) was designated a UNESCO World Heritage Site in 2005 and combines with the adjacent Nanda Devi NP for joint WHS status. The valley bursts into bloom during the short summer (July-September) with 600+ flower species — including the blue Himalayan poppy (Meconopsis), cobra lily, saussurea, orchids. British mountaineer Frank Smythe stumbled upon it in 1931 and wrote ''The Valley of Flowers'' (1938). Also mentioned in the Ramayana as the place where Hanuman fetched the Sanjeevani herb for Lakshmana.', 'EASY', 'General Knowledge', 'National Parks, Wildlife Sanctuaries & Biosphere Reserves', 'GK_NATIONAL_PARKS', '[{"option_text": "Dachigam, J&K", "is_correct": false}, {"option_text": "Valley of Flowers, Uttarakhand", "is_correct": true}, {"option_text": "Great Himalayan, Himachal Pradesh", "is_correct": false}, {"option_text": "Khangchendzonga, Sikkim", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9fec9b06-e35c-5e53-b2fc-88e85b2b94bb', 'The National Emblem of India is an adaptation of which ancient sculpture?', NULL, 'The National Emblem of India is based on the LION CAPITAL OF ASHOKA at Sarnath (UP) — a sculpture atop an Ashokan pillar (~250 BCE) commemorating Buddha''s first sermon. The original capital shows FOUR ADDORSED LIONS standing on an abacus (carrying four animals — lion, elephant, galloping horse, bull — separated by chakras), all on an inverted lotus. In the emblem, only 3 lions are visible (4th is hidden behind). Motto: ''SATYAMEVA JAYATE'' (Truth alone triumphs) from the Mundaka Upanishad (not visible in the original sculpture — added to the emblem). Adopted on 26 January 1950. The original Sarnath sculpture is housed in the Sarnath Museum. A much larger recreation was installed atop the new Parliament building in July 2022.', 'EASY', 'General Knowledge', 'National Symbols of India', 'GK_NAT_SYMBOLS', '[{"option_text": "The Nataraja of the Chola period", "is_correct": false}, {"option_text": "The Lion Capital of Ashoka at Sarnath", "is_correct": true}, {"option_text": "The Nandi bull from Thanjavur", "is_correct": false}, {"option_text": "The Kailasa temple sculpture at Ellora", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fda30fef-5c45-5b2f-9f2d-c39a14029160', 'The Indian National Anthem ''Jana Gana Mana'' was composed by Rabindranath Tagore. In which year was it officially adopted by the Constituent Assembly?', NULL, '''Jana Gana Mana'' — written by Rabindranath Tagore originally in Bengali (titled ''Bharoto Bhagyo Bidhata'', 1911); first sung at INC''s Calcutta session on 27 December 1911 — was officially adopted as the NATIONAL ANTHEM by the Constituent Assembly on 24 JANUARY 1950 (two days before the Constitution came into force). Full anthem: 5 stanzas; only the FIRST stanza is the national anthem. Duration: 52 seconds (full) or 20 seconds (short version). Composition tune: ''Raga Alhaiya Bilawal''. Same author also wrote Bangladesh''s national anthem ''Amar Shonar Bangla'' (1906). India''s NATIONAL SONG ''Vande Mataram'' (from Bankim Chandra''s novel Anandamath 1882) — also adopted 24 Jan 1950 with EQUAL status to the anthem — famously sung at 1896 Calcutta INC session by Tagore himself.', 'MEDIUM', 'General Knowledge', 'National Symbols of India', 'GK_NAT_SYMBOLS', '[{"option_text": "15 August 1947", "is_correct": false}, {"option_text": "24 January 1950", "is_correct": true}, {"option_text": "26 January 1950", "is_correct": false}, {"option_text": "13 December 1911", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('75bb9da2-48c9-56fd-bf7a-53d37dbbf45a', 'Who designed the Indian National Flag (its final 3-colour horizontal tricolour form adopted in 1947)?', NULL, 'PINGALI VENKAYYA (1876-1963, Andhra Pradesh) — an Indian freedom fighter, agriculturist, and Gandhian — designed the basic pattern of the Indian national flag. The final tricolour (saffron-white-green with the Ashoka Chakra in navy blue at centre) was ADOPTED on 22 JULY 1947 by the Constituent Assembly. Earlier flag versions: MADAM BHIKAJI CAMA unfurled an early tricolour on 22 Aug 1907 at Stuttgart (Germany, Intl Socialist Congress) — 1st ''Indian'' flag on foreign soil. Gandhi''s 1921 design had red (later saffron), white, green with a charkha. Nandalal Bose — illustrator of the Constitution''s manuscript. Colour meanings: Saffron = courage/sacrifice; White = peace/truth; Green = faith/fertility; Chakra = Dharma/motion. Ratio 2:3. BIS standard for hand-spun khadi only.', 'EASY', 'General Knowledge', 'National Symbols of India', 'GK_NAT_SYMBOLS', '[{"option_text": "Mahatma Gandhi", "is_correct": false}, {"option_text": "Pingali Venkayya", "is_correct": true}, {"option_text": "Madam Bhikaji Cama", "is_correct": false}, {"option_text": "Nandalal Bose", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('17dde61e-4255-5035-b875-2f3e31eeeaa1', 'India''s National Aquatic Animal is:', NULL, 'GANGETIC RIVER DOLPHIN (Platanista gangetica, locally ''Susu'' / ''Soons'' in Bihar) was declared India''s National Aquatic Animal on 5 October 2009 by PM Dr. Manmohan Singh. Found in Ganga-Brahmaputra-Meghna-Karnaphuli river systems. Endangered (IUCN). Blind — navigates via echolocation. Population ~3500. Project Dolphin launched 2020 (like Project Tiger). Full set of Indian national symbols (remember at least 13): FLAG, EMBLEM, ANTHEM, SONG, ANIMAL = Bengal Tiger (declared 1972), HERITAGE ANIMAL = Indian Elephant (2010), BIRD = Indian Peafowl (1963), AQUATIC ANIMAL = Gangetic Dolphin (2009), REPTILE = King Cobra, FLOWER = Lotus, TREE = Banyan, FRUIT = Mango, RIVER = Ganga (declared 2008), CURRENCY SYMBOL ₹ (Udaya Kumar, adopted 2010), CALENDAR = Saka Samvat (from 22 March 1957).', 'MEDIUM', 'General Knowledge', 'National Symbols of India', 'GK_NAT_SYMBOLS', '[{"option_text": "Blue whale", "is_correct": false}, {"option_text": "Gangetic river dolphin (Platanista gangetica)", "is_correct": true}, {"option_text": "Olive Ridley turtle", "is_correct": false}, {"option_text": "Saltwater crocodile", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('299c5c6d-cfe2-5c74-a098-6330e00430b9', 'Who designed the Indian rupee symbol ''₹'', and in which year was it officially adopted by the Government of India?', NULL, 'D. UDAYA KUMAR (IIT Guwahati faculty member, native of Kallakurichi TN) designed the rupee symbol ''₹'' — selected from ~3000 entries in a 2009 competition. Officially adopted on 15 JULY 2010 by the Union Cabinet. The symbol combines Devanagari ''र'' (Ra) and Roman capital ''R'' without the vertical line — featuring two parallel horizontal strokes on top (signifying India''s tricolour or the ''='' of equality). Before 2010, India used ''Rs.'' Unicode code point U+20B9. India joined other major currencies with symbols: $ USD, € Euro, £ GBP, ¥ Yen, ₩ Won, ₹ Rupee (Sri Lanka and Nepal use their own). Thousand-separator: Indian system uses lakhs/crores (1,00,000 = 1 lakh, 10,00,00,000 = 10 crore); the Western system uses thousands/millions.', 'MEDIUM', 'General Knowledge', 'National Symbols of India', 'GK_NAT_SYMBOLS', '[{"option_text": "Nandalal Bose; 1950", "is_correct": false}, {"option_text": "D. Udaya Kumar; 2010", "is_correct": true}, {"option_text": "Pingali Venkayya; 1947", "is_correct": false}, {"option_text": "Satyajit Ray; 1982", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1afc0028-0550-5ec3-be90-c62b931320e8', 'India''s National Calendar is based on which calendar, effective since 22 March 1957?', NULL, 'India''s NATIONAL CALENDAR is the SAKA CALENDAR (Saka Samvat), adopted on 22 March 1957 based on the Calendar Reform Committee report (1952, chaired by Meghnad Saha). Year 1 of Saka era = 78 CE (commemorating Kanishka''s coronation per one theory). First month = CHAITRA (starts 22 March, 21 March in leap year). Second month = VAISHAKHA, etc. Used officially for Gazette, AIR broadcasts, official calendars, some government communications. Current year: Saka 1946/47 (depending on month in 2024-25). Other Indian calendars: VIKRAM SAMVAT (year 1 = 57 BCE, still popular in Hindu tradition, 57 years ahead of CE), KALIYUGA era (3102 BCE start), Bengali calendar (Bongabdo), Tamil calendar, Malayalam (Kollam era), Saka-Kaliyug. International standards: Gregorian (civil/official), ISO 8601.', 'HARD', 'General Knowledge', 'National Symbols of India', 'GK_NAT_SYMBOLS', '[{"option_text": "Vikrami Samvat", "is_correct": false}, {"option_text": "Saka Samvat (Saka Era)", "is_correct": true}, {"option_text": "Hijri (Islamic) Calendar", "is_correct": false}, {"option_text": "Gregorian Calendar", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9f3ec1e9-5ee2-5988-8319-e00a65e937ca', 'When was the Ganga declared India''s National River, and during which anniversary was the declaration?', NULL, 'The GANGA was declared India''s NATIONAL RIVER on 4 November 2008 by the Union Cabinet, led by PM Manmohan Singh — and on the same day, the National Ganga River Basin Authority (NGRBA) was constituted under the Environment Protection Act 1986 to clean the river. Later, the NATIONAL MISSION FOR CLEAN GANGA (NMCG, 2011) and the broader NAMAMI GANGE programme (2014, ₹20,000 Cr initial allocation) have been key initiatives. The Ganga flows ~2525 km through 5 states: Uttarakhand (Bhagirathi from Gangotri Glacier + Alaknanda → union at Devprayag → ''Ganga'' thereafter), UP, Bihar, Jharkhand, WB. Enters Bangladesh as Padma → Jamuna (Brahmaputra) → Meghna → Bay of Bengal. Ganga + Yamuna basin covers 25% of India''s land and supports 40%+ of the population.', 'MEDIUM', 'General Knowledge', 'National Symbols of India', 'GK_NAT_SYMBOLS', '[{"option_text": "2004 — 50th anniversary of Republic Day", "is_correct": false}, {"option_text": "2008 — declared by the Union Cabinet", "is_correct": true}, {"option_text": "2014 — 125th birth anniversary of Gandhi", "is_correct": false}, {"option_text": "2019 — 70th anniversary of Constitution adoption", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('50c78c73-56cf-598b-b866-8607afd09c6d', 'Madhubani paintings originate from which region of India?', NULL, 'Madhubani (also called Mithila) painting originates from the Mithila region of Bihar (and parts of Nepal''s Janakpur). Traditionally practised by women on walls of homes during festivals; now on paper/canvas. Characterised by double-outline figures, geometric patterns, natural dyes, and themes from Hindu mythology. GI-tagged in 2007. Five distinct styles: Bharni, Kachni, Tantrik, Godna, Kohbar.', 'EASY', 'General Knowledge', 'Paintings, Martial Arts & Crafts of India', 'GK_PAINTINGS_MARTIAL', '[{"option_text": "Santiniketan region of West Bengal", "is_correct": false}, {"option_text": "Mithila region of Bihar", "is_correct": true}, {"option_text": "Kumaon region of Uttarakhand", "is_correct": false}, {"option_text": "Kutch region of Gujarat", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('97fb4a56-46d7-5927-97f4-205276be892a', 'Warli painting, known for its simple white geometric patterns on a brown/red background, is a tribal art form of:', NULL, 'Warli painting belongs to the Warli tribe of northern Maharashtra (Thane, Palghar districts) and southern Gujarat. Uses rice paste on mud walls — circles (sun, moon), triangles (mountains, trees), squares (human settlements), and a central ''chauk'' for wedding murals. Jivya Soma Mashe (1934–2018) brought Warli to global attention. Contrast: Saora (Odisha) — similar tribal style but different motifs; Gond (MP/Chhattisgarh) — coloured dot-and-line style popularised by Jangarh Singh Shyam.', 'EASY', 'General Knowledge', 'Paintings, Martial Arts & Crafts of India', 'GK_PAINTINGS_MARTIAL', '[{"option_text": "Odisha (Saora tribe)", "is_correct": false}, {"option_text": "Maharashtra (Warli tribe)", "is_correct": true}, {"option_text": "Madhya Pradesh (Gond tribe)", "is_correct": false}, {"option_text": "Chhattisgarh (Gond tribe)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('607a1166-4353-5742-883f-cc6a2b22009a', 'Pattachitra, a traditional cloth-based scroll painting, is associated with which two Indian states?', NULL, 'Pattachitra (patta = cloth, chitra = picture) is practised in Odisha (focused on Jagannath of Puri — stylised eyes, bright colours) and West Bengal (narrative scrolls by Patua community of Medinipur). Odisha''s version is GI-tagged. The art uses natural colours from minerals and plants; artists are known as ''Chitrakars''. Raghurajpur in Puri district is a heritage Pattachitra village.', 'MEDIUM', 'General Knowledge', 'Paintings, Martial Arts & Crafts of India', 'GK_PAINTINGS_MARTIAL', '[{"option_text": "Odisha and West Bengal", "is_correct": true}, {"option_text": "Andhra Pradesh and Karnataka", "is_correct": false}, {"option_text": "Bihar and Jharkhand", "is_correct": false}, {"option_text": "Tamil Nadu and Kerala", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fda0db82-0c0f-59af-83b8-a2e3013eddaa', 'Tanjore (Thanjavur) painting is characterised by which distinctive feature?', NULL, 'Tanjore painting originated in the 16th–18th c. under the Nayak and Maratha rulers of Thanjavur (Tamil Nadu). Distinguished by: (1) gold foil overlay (22-carat real gold leaf on raised gesso base); (2) embedded glass beads / semi-precious stones / cut-glass; (3) deities — mostly Krishna (infant Balakrishna especially) and other Hindu gods; (4) wooden plank base. GI-tagged in 2007–08. Not to be confused with Mysore painting, which lacks heavy gesso/gem work.', 'MEDIUM', 'General Knowledge', 'Paintings, Martial Arts & Crafts of India', 'GK_PAINTINGS_MARTIAL', '[{"option_text": "Black-and-white charcoal sketches on cloth", "is_correct": false}, {"option_text": "Gold foil work, glass/gem embellishments, and religious themes", "is_correct": true}, {"option_text": "Tribal stick figures with mud-based pigments", "is_correct": false}, {"option_text": "Calligraphic Arabic verses in gold script", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('04a321f9-88b6-5f90-a0f6-763723f5c729', 'The Kangra school of miniature painting flourished primarily in which state?', NULL, 'Kangra painting, a sub-school of Pahari miniature painting, flourished in the Kangra valley of Himachal Pradesh under Raja Sansar Chand (1775–1823). Known for lyrical depictions of Radha-Krishna themes, Gita Govinda illustrations, and delicate feminine faces with almond eyes. Pahari schools include Basohli, Guler, Kangra, Chamba, Mandi, Kulu — all in HP except Basohli (J&K). Rajasthani schools (Mewar, Marwar, Jaipur, Kishangarh, Bundi) are distinct.', 'MEDIUM', 'General Knowledge', 'Paintings, Martial Arts & Crafts of India', 'GK_PAINTINGS_MARTIAL', '[{"option_text": "Jammu & Kashmir", "is_correct": false}, {"option_text": "Himachal Pradesh", "is_correct": true}, {"option_text": "Uttarakhand", "is_correct": false}, {"option_text": "Rajasthan", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d71784ad-3b02-58a0-a887-c8686cf07898', 'Kalamkari, a hand-painted or block-printed cotton textile art, has two famous styles. Which two?', NULL, 'Kalamkari (kalam = pen, kari = craft) comes from Andhra Pradesh/Telangana. The two styles: (1) SRIKALAHASTI style (Chittoor, AP) — purely hand-drawn with a bamboo pen, Hindu mythology themes; (2) MACHILIPATNAM style (Krishna district, AP) — block-printed patterns, Persian-influenced motifs. Uses natural dyes from plants + iron and mordants. GI-tagged. Vegetable block-printing survived under the Deccan Sultanate and Mughal patronage.', 'HARD', 'General Knowledge', 'Paintings, Martial Arts & Crafts of India', 'GK_PAINTINGS_MARTIAL', '[{"option_text": "Jaipur and Jodhpur", "is_correct": false}, {"option_text": "Srikalahasti and Machilipatnam", "is_correct": true}, {"option_text": "Kanchipuram and Madurai", "is_correct": false}, {"option_text": "Patan and Ahmedabad", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d9b185c0-856d-5922-9daa-f93a968665d5', 'Phad painting, a narrative scroll painting traditionally of folk deities like Pabuji and Devnarayan, is from which state?', NULL, 'Phad (or Pad) is a 700-year-old scroll painting from the Bhilwara region of Rajasthan, created on cloth (''phad'' means scroll). Bhopas (traditional priest-singers) carry them village-to-village, unrolling while singing tales of local heroes Pabuji and Devnarayan. The Joshi family of Bhilwara is the hereditary custodian of the art. Uses natural dyes; dominant colour is red-orange. GI-tagged.', 'HARD', 'General Knowledge', 'Paintings, Martial Arts & Crafts of India', 'GK_PAINTINGS_MARTIAL', '[{"option_text": "Gujarat", "is_correct": false}, {"option_text": "Rajasthan", "is_correct": true}, {"option_text": "Madhya Pradesh", "is_correct": false}, {"option_text": "Haryana", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('32155f25-8eb2-50fe-b177-2ccd33cf1221', 'Gond painting, now globally recognised, originated as a tribal art form in which state?', NULL, 'Gond painting comes from the Gond tribal community spread across Madhya Pradesh (Mandla, Dindori, Balaghat districts) and neighbouring regions, but is predominantly associated with MP. Characterised by intricate patterns of dots and dashes forming bright, rhythmically-filled shapes of flora, fauna, and mythology. The late Jangarh Singh Shyam (1962–2001), a Pardhan Gond from Patangarh (MP), pioneered the contemporary ''Jangarh Kalam'' style and brought Gond art international recognition.', 'MEDIUM', 'General Knowledge', 'Paintings, Martial Arts & Crafts of India', 'GK_PAINTINGS_MARTIAL', '[{"option_text": "Chhattisgarh", "is_correct": false}, {"option_text": "Madhya Pradesh", "is_correct": true}, {"option_text": "Odisha", "is_correct": false}, {"option_text": "Jharkhand", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('732a240e-e02e-5251-aaf7-d90120044d9b', 'Which is the oldest martial art in the world, originating in Kerala?', NULL, 'Kalaripayattu, from Kerala (dating to ~3rd c. BCE per legend; codified documentation from 13th c. CE), is widely acknowledged as one of the world''s oldest surviving martial arts. ''Kalari'' = training arena; ''Payattu'' = fight/exercise. Four stages: Meithari (body), Kolthari (wooden weapons), Ankathari (metal weapons), Verumkai (empty hand). Three regional styles: Northern (Vadakkan), Southern (Thekkan), and Central (Madhya) — differ in stance, footwork, philosophy. Sage Parashurama is considered the mythical originator. Silambam (TN, bamboo staff), Gatka (Punjab, Sikh warrior art), Mardani Khel (Maharashtra, Maratha art) are younger.', 'EASY', 'General Knowledge', 'Paintings, Martial Arts & Crafts of India', 'GK_PAINTINGS_MARTIAL', '[{"option_text": "Silambam", "is_correct": false}, {"option_text": "Kalaripayattu", "is_correct": true}, {"option_text": "Gatka", "is_correct": false}, {"option_text": "Mardani Khel", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('051fd701-4120-56b5-a91d-945adf8f8f5a', 'Thang-Ta and Huyen Langlon are martial art traditions of which Indian state?', NULL, 'Thang-Ta (''Thang'' = sword, ''Ta'' = spear) and its broader philosophical framework Huyen Langlon (''method of safeguarding life'') are the traditional martial arts of the Meitei people of Manipur. Practised for centuries as both warfare and ritual; revived as cultural heritage after a British ban in 1891 post the Anglo-Manipur war. Includes sword, spear, unarmed combat (Sarit Sarak), and spiritual practices. Recognised by SANG (sports body). Manipur also has Mukna (indigenous wrestling).', 'MEDIUM', 'General Knowledge', 'Paintings, Martial Arts & Crafts of India', 'GK_PAINTINGS_MARTIAL', '[{"option_text": "Nagaland", "is_correct": false}, {"option_text": "Manipur", "is_correct": true}, {"option_text": "Mizoram", "is_correct": false}, {"option_text": "Assam", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d97803e6-a6ff-5467-a5c9-2ef19aa4df3c', 'Gatka is a traditional martial art associated with which community and state?', NULL, 'Gatka is the traditional weapon-based martial art of the Sikhs of Punjab, codified under Guru Hargobind (6th Sikh Guru, 17th c.) and refined by Guru Gobind Singh (10th Guru). It uses the ''gatka'' (wooden stick simulating sword), shield, and the Khanda. Practised prominently during Hola Mohalla at Anandpur Sahib every Holi. It is both a spiritual discipline and combat system — the Nihang warrior order keeps the tradition alive. Mardani Khel is the Maratha equivalent; Chavittu Kali is another Kerala martial dance distinct from Kalaripayattu.', 'EASY', 'General Knowledge', 'Paintings, Martial Arts & Crafts of India', 'GK_PAINTINGS_MARTIAL', '[{"option_text": "Rajput warriors of Rajasthan", "is_correct": false}, {"option_text": "Sikh warriors of Punjab", "is_correct": true}, {"option_text": "Ahom warriors of Assam", "is_correct": false}, {"option_text": "Maratha warriors of Maharashtra", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('defaeca6-aea2-5da8-a61f-095872407f43', 'Silambam, a stick-fighting martial art using bamboo staffs, originates in which state?', NULL, 'Silambam originates in Tamil Nadu; ''silambu'' refers to the sound of the bamboo staff. It is one of the oldest South Indian martial arts (references in Sangam literature, c. 1st-4th c. CE). Used primarily the 5-6 feet bamboo stick as weapon. Kuttu Varisai is the unarmed counterpart. Today it is a recognised tournament sport under the Silambam Asia Federation. Not to be confused with Kalaripayattu (Kerala), though both are Dravidian systems.', 'EASY', 'General Knowledge', 'Paintings, Martial Arts & Crafts of India', 'GK_PAINTINGS_MARTIAL', '[{"option_text": "Tamil Nadu", "is_correct": true}, {"option_text": "Kerala", "is_correct": false}, {"option_text": "Karnataka", "is_correct": false}, {"option_text": "Andhra Pradesh", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a362530b-60de-5ae1-a2d8-bc8fd3462514', 'Mallakhamb is a traditional gymnastic sport/martial art most famously from which state?', NULL, 'Mallakhamb (''malla'' = wrestler/strong man, ''khamb'' = pole) is a Maharashtrian traditional gymnastic/martial sport where the practitioner performs yoga postures and aerial feats on a vertical wooden pole (Mallakhamb), a hanging rope (Rope Mallakhamb), or a cane (Cane Mallakhamb). Mentioned in the Manasollasa text (12th c. Chalukya). Declared Maharashtra''s state sport in 2013. World Mallakhamb Championships are held in Mumbai. MP is the #2 Mallakhamb state.', 'MEDIUM', 'General Knowledge', 'Paintings, Martial Arts & Crafts of India', 'GK_PAINTINGS_MARTIAL', '[{"option_text": "Gujarat", "is_correct": false}, {"option_text": "Maharashtra", "is_correct": true}, {"option_text": "Madhya Pradesh", "is_correct": false}, {"option_text": "Goa", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bbd9726e-593c-5664-9a71-dd40211321e7', 'Match the martial art to its state of origin: (1) Inbuan – (2) Sqay – (3) Cheibi Gadga – (4) Musti Yuddha', NULL, 'INBUAN (Mizoram — belt-wrestling, similar to Kushti but on a 15-ft grass circle), SQAY (Kashmir — sword-shield fencing with leather-covered swords; internationally organised as World Sqay Federation), CHEIBI GADGA (Manipur — sword-and-shield martial art), MUSTI YUDDHA (Varanasi region of UP — ancient empty-hand boxing mentioned in the Mahabharata and Brahmanda Purana). Knowing niche state-linked martial arts is a classic SSC differentiator question.', 'HARD', 'General Knowledge', 'Paintings, Martial Arts & Crafts of India', 'GK_PAINTINGS_MARTIAL', '[{"option_text": "(1) Mizoram (2) Kashmir (3) Manipur (4) Varanasi", "is_correct": true}, {"option_text": "(1) Nagaland (2) Punjab (3) Meghalaya (4) Lucknow", "is_correct": false}, {"option_text": "(1) Tripura (2) Ladakh (3) Mizoram (4) Hyderabad", "is_correct": false}, {"option_text": "(1) Assam (2) J&K (3) Nagaland (4) Bihar", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('43dd297d-ce2a-5308-afee-9b0147b17917', 'Bidri (Bidriware), a metal handicraft with silver inlay on a zinc-copper alloy, has its GI tag associated with which state?', NULL, 'Bidriware gets its name from Bidar, a city in Karnataka (formerly capital of the Bahmani Sultanate). The craft originated under the Bahmani kings in the 14th c. It is made of a zinc-copper alloy (95% Zn + 5% Cu) blackened with a paste containing soil unique to Bidar fort, then inlaid with pure silver wire. GI-tagged in 2006 (one of India''s early GIs). Items: hookahs, vases, trays, jewellery boxes. Moradabad is known for brassware, not Bidri; Warangal and Kondapalli are distinct crafts.', 'HARD', 'General Knowledge', 'Paintings, Martial Arts & Crafts of India', 'GK_PAINTINGS_MARTIAL', '[{"option_text": "Uttar Pradesh (Moradabad)", "is_correct": false}, {"option_text": "Karnataka (Bidar)", "is_correct": true}, {"option_text": "Telangana (Warangal)", "is_correct": false}, {"option_text": "Andhra Pradesh (Kondapalli)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('43842ed5-cb45-5998-b7b3-d61619c014cd', 'Channapatna toys, known for their bright lacquer-coated wooden craft, are GI-tagged to which state?', NULL, 'Channapatna, a small town in Karnataka''s Ramanagara district, is famously known as ''Gombegala Ooru'' (toy town). The craft, nearly 200 years old, uses ivory wood (Wrightia tinctoria or ''Aale mara'' in Kannada), turned on lathes and lacquered with vegetable dyes. GI-tagged in 2006. Tipu Sultan invited Persian artisans who introduced the lacquer technique. Kondapalli (AP) and Thanjavur (TN) are distinct toy traditions.', 'MEDIUM', 'General Knowledge', 'Paintings, Martial Arts & Crafts of India', 'GK_PAINTINGS_MARTIAL', '[{"option_text": "Tamil Nadu", "is_correct": false}, {"option_text": "Karnataka", "is_correct": true}, {"option_text": "Kerala", "is_correct": false}, {"option_text": "Andhra Pradesh", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('beea19c1-4b4c-5b00-a802-479bd0f9a4bd', 'The Ranji Trophy, the premier domestic first-class cricket tournament in India, is named after which cricketer?', NULL, 'The Ranji Trophy (started 1934-35) is named after Kumar Shri RANJITSINHJI (1872-1933), Jam Saheb of Nawanagar — first Indian to play Test cricket (for England, 1896). Innovator of the leg glance. The Duleep Trophy (started 1961-62) is named after his nephew K.S. DULEEPSINHJI. VIJAY HAZARE TROPHY (List A one-day, started 2002-03) named after Vijay Hazare, captain of India''s first Test win (1952). IRANI TROPHY (since 1959-60) between Ranji champion + Rest of India, named after Z.R. Irani (BCCI treasurer). Col. C.K. NAYUDU was independent India''s first Test captain (1932, England series). DEODHAR TROPHY (List A, zonal) named after D.B. Deodhar.', 'MEDIUM', 'General Knowledge', 'Sports - Terms, Trophies, Cups & Stadiums', 'GK_SPORTS_STATIC', '[{"option_text": "Duleepsinhji", "is_correct": false}, {"option_text": "K.S. Ranjitsinhji (Jam Saheb of Nawanagar)", "is_correct": true}, {"option_text": "Vijay Hazare", "is_correct": false}, {"option_text": "C.K. Nayudu", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1ef2793f-8ab0-5d99-b2a2-fccc3b2784c5', 'The Thomas Cup and Uber Cup are international team trophies in which sport?', NULL, 'BADMINTON: Thomas Cup (men''s team world championship since 1949, held every 2 years) + Uber Cup (women''s team world championship since 1957). INDIA WON THOMAS CUP for the FIRST TIME in 2022 (Bangkok) — historic achievement (Lakshya Sen, K. Srikanth, Chirag Shetty, Satwiksairaj Rankireddy, Prannoy). TENNIS team trophies: Davis Cup (men), Billie Jean King Cup (women). TABLE TENNIS: Swaythling Cup (men), Corbillon Cup (women). CHESS: Chess Olympiad''s Hamilton-Russell Cup. CRICKET: World Cup ODI + T20. HOCKEY: World Cup, FIH Pro League. FOOTBALL: FIFA World Cup. Other cups: Durand Cup (football, India''s oldest since 1888; third-oldest in world after FA Cup 1871 and Scottish Cup 1873), Santosh Trophy (football interstate).', 'EASY', 'General Knowledge', 'Sports - Terms, Trophies, Cups & Stadiums', 'GK_SPORTS_STATIC', '[{"option_text": "Tennis", "is_correct": false}, {"option_text": "Badminton", "is_correct": true}, {"option_text": "Table tennis", "is_correct": false}, {"option_text": "Squash", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3c803fa0-6e0d-5698-8a60-d5a2e49fd8a8', 'The largest cricket stadium in the world by seating capacity is:', NULL, 'NARENDRA MODI STADIUM at Motera (Ahmedabad, Gujarat) — reopened Feb 2021 — seats 1,32,000 (1.32 lakh), surpassing the previous record held by Melbourne Cricket Ground (~100,000). Originally the Sardar Patel Stadium (1983-2020), renamed after PM Modi by the GCA. Hosted India-Pakistan 2023 World Cup match (130k+ attendance — set cricket world record). MCG (Australia) is now 2nd; Eden Gardens (Kolkata) 3rd at ~68,000; Lord''s (''Home of Cricket'') ~30,000. Other large Indian stadiums: Rajiv Gandhi Intl Stadium Hyderabad (55k), M Chinnaswamy Bengaluru (40k), Wankhede Mumbai (33k), M.A. Chidambaram (Chepauk) Chennai (38k), Arun Jaitley Stadium Delhi (41k).', 'MEDIUM', 'General Knowledge', 'Sports - Terms, Trophies, Cups & Stadiums', 'GK_SPORTS_STATIC', '[{"option_text": "Melbourne Cricket Ground (MCG)", "is_correct": false}, {"option_text": "Eden Gardens, Kolkata", "is_correct": false}, {"option_text": "Narendra Modi Stadium, Motera, Ahmedabad", "is_correct": true}, {"option_text": "Lord''s Cricket Ground, London", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e23feceb-9a93-5b55-b18f-41a8230c1649', 'In which sport is the term ''Chinaman'' used?', NULL, 'CRICKET: ''Chinaman'' refers to a left-arm unorthodox spin bowler (left-arm wrist-spinner) — effectively the mirror of a right-arm leg-spinner. Named after West Indian Ellis ''Puss'' Achong (1930s), of Chinese descent. Famous exponents: Brad Hogg (Australia), Kuldeep Yadav (India), Paul Adams (South Africa). Cricket has MANY specific terms: BOUNCER, YORKER, BEAMER, DOOSRA (off-spinner bowling leg-spin), TEESRA, CARROM BALL (fingerspin — Sunil Narine), DILSCOOP, RAMP SHOT, DLS method, POWERPLAY, NIGHTWATCHMAN. Other sport-specific terms: Deuce/Advantage/Break (Tennis), Birdie/Eagle/Albatross/Bogey (Golf), Grand Slam (Tennis/Cricket), Hat-trick (Cricket/Football/Hockey), Double fault (Tennis).', 'MEDIUM', 'General Knowledge', 'Sports - Terms, Trophies, Cups & Stadiums', 'GK_SPORTS_STATIC', '[{"option_text": "Billiards", "is_correct": false}, {"option_text": "Cricket", "is_correct": true}, {"option_text": "Chess", "is_correct": false}, {"option_text": "Badminton", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7f6f1aca-90d7-5c81-b5bf-0d53a8b8dd35', 'The Duleep Trophy in Indian cricket is a competition between:', NULL, 'DULEEP TROPHY (since 1961-62) is an Indian first-class zonal cricket tournament — traditionally between India''s 5 cricket zones (North, South, East, West, Central). Since 2022-23 season, replaced with 3-4 teams format: India A, B, C, D (no longer strictly zonal). Named after K.S. DULEEPSINHJI (nephew of Ranjitsinhji), who played for England. The IRANI CUP (since 1959-60) is between the Ranji champion + Rest of India (as named in option A). VIJAY HAZARE TROPHY = List A one-day inter-state. SYED MUSHTAQ ALI TROPHY = T20 inter-state. CK NAYUDU TROPHY = Under-25 first-class. COOCH BEHAR TROPHY = Under-19. VIJAY MERCHANT TROPHY = Under-16.', 'HARD', 'General Knowledge', 'Sports - Terms, Trophies, Cups & Stadiums', 'GK_SPORTS_STATIC', '[{"option_text": "State Ranji champion + Rest of India", "is_correct": false}, {"option_text": "Five zonal teams (North, South, East, West, Central)", "is_correct": true}, {"option_text": "Under-19 teams", "is_correct": false}, {"option_text": "Teams from SAARC countries", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('11711d61-e78a-5178-818e-707de8661087', 'The Agha Khan Cup, one of the oldest trophies in Indian sports, is associated with which sport?', NULL, 'Hockey trophies: AGHA KHAN CUP (started 1896 in Bombay — one of the OLDEST field hockey tournaments in the world), Beighton Cup (Calcutta, 1895), Obaidullah Gold Cup (Bhopal), Bombay Gold Cup, Dhyan Chand Trophy. Also: Azlan Shah Cup (Malaysia-hosted international invitational). Football trophies: Durand Cup (1888 — oldest football tournament in Asia, 3rd oldest in the world), Santosh Trophy, Federation Cup, DCM Trophy. Cricket: Ranji Trophy, Irani Cup, Duleep Trophy. Polo: Ezra Cup (oldest polo trophy in India — Kolkata), IPA (Indian Polo Association) Championship.', 'HARD', 'General Knowledge', 'Sports - Terms, Trophies, Cups & Stadiums', 'GK_SPORTS_STATIC', '[{"option_text": "Football", "is_correct": false}, {"option_text": "Hockey", "is_correct": true}, {"option_text": "Polo", "is_correct": false}, {"option_text": "Cricket", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('34110ac7-7644-51a0-9e7c-c4fc77b4d0bb', 'The Wankhede Stadium, home ground of Mumbai Cricket Association, is located in which city?', NULL, 'Stadium-city mapping (Indian major cricket venues): Wankhede Stadium = Mumbai (MCA); Eden Gardens = Kolkata (CAB — India''s oldest cricket ground, 1864); Feroz Shah Kotla / Arun Jaitley Stadium = Delhi (DDCA); M.A. Chidambaram Stadium (Chepauk) = Chennai (TNCA); M. Chinnaswamy Stadium = Bengaluru (KSCA); Rajiv Gandhi Intl Stadium = Hyderabad (HCA); Narendra Modi Stadium (Motera) = Ahmedabad (GCA); Punjab Cricket Assoc IS Bindra Stadium = Mohali; Sawai Mansingh Stadium = Jaipur; Barabati Stadium = Cuttack; JSCA Stadium = Ranchi; Holkar Stadium = Indore; Vidarbha CA Stadium = Nagpur; Greenfield Stadium = Thiruvananthapuram.', 'EASY', 'General Knowledge', 'Sports - Terms, Trophies, Cups & Stadiums', 'GK_SPORTS_STATIC', '[{"option_text": "Delhi", "is_correct": false}, {"option_text": "Mumbai", "is_correct": true}, {"option_text": "Kolkata", "is_correct": false}, {"option_text": "Chennai", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8e5d631b-78c0-5e6b-a79f-75d80fe564c7', 'The ''Indian Grand Prix'' of Formula 1 was held from 2011 to 2013 at which Indian circuit?', NULL, 'BUDDH INTERNATIONAL CIRCUIT (BIC) in Greater Noida, UP, hosted the Indian Grand Prix (F1) for three seasons: 2011, 2012, 2013. Designed by Hermann Tilke. Length: 5.125 km. Cancelled in 2014 due to tax disputes + declining organiser interest. Sebastian Vettel won all three editions. BIC now hosts MotoGP Bharat since 2023. Kari Motor Speedway (Coimbatore) and MMRT (Irungattukottai near Chennai) are other Indian tracks. India does NOT currently have an active F1 GP. The F1 India tour added MotoGP contract under FMSCI.', 'HARD', 'General Knowledge', 'Sports - Terms, Trophies, Cups & Stadiums', 'GK_SPORTS_STATIC', '[{"option_text": "Madras Motor Race Track, Chennai", "is_correct": false}, {"option_text": "Buddh International Circuit, Greater Noida", "is_correct": true}, {"option_text": "Kari Motor Speedway, Coimbatore", "is_correct": false}, {"option_text": "MMRT, Irungattukottai", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f97fb48d-2c2f-5413-a278-145afc8ceb40', 'As of 2024, how many UNESCO World Heritage Sites are located in India?', NULL, 'India has 42 UNESCO World Heritage Sites as of 2024: 34 Cultural + 7 Natural + 1 Mixed (Khangchendzonga NP). Recent additions: Santiniketan (2023, cultural), Sacred Ensembles of the Hoysalas — Belur, Halebid, Somanathapura (2023, cultural), Moidams of Ahom (2024 — first natural/cultural site from NE). India ranks 6th globally in number of sites (Italy #1 with 59). Italy and China competing for #1; France, Germany, Spain round out top-5.', 'MEDIUM', 'General Knowledge', 'Famous Temples, Monuments & Places in India', 'GK_TEMPLES_MONUMENTS', '[{"option_text": "32", "is_correct": false}, {"option_text": "38", "is_correct": false}, {"option_text": "42", "is_correct": true}, {"option_text": "50", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('199e81a1-49e7-568c-b38e-424fd8caef93', 'Which was India''s FIRST UNESCO World Heritage Site, inscribed in 1983?', NULL, 'India''s FIRST batch of 4 UNESCO WHS inscriptions happened in 1983: (1) Ajanta Caves (Maharashtra — Buddhist caves, 2nd c. BCE-6th c. CE), (2) Ellora Caves (Maharashtra — Buddhist/Hindu/Jain), (3) Agra Fort (UP), (4) Taj Mahal (UP — Shah Jahan for Mumtaz Mahal, completed ~1653). In 1984, Sun Temple Konark and Mahabalipuram group were added. Khajuraho and Goa churches came in 1986. Red Fort was inscribed in 2007 — fairly late.', 'HARD', 'General Knowledge', 'Famous Temples, Monuments & Places in India', 'GK_TEMPLES_MONUMENTS', '[{"option_text": "Taj Mahal", "is_correct": false}, {"option_text": "Ajanta Caves, Ellora Caves, Agra Fort and Taj Mahal — all inscribed in 1983", "is_correct": true}, {"option_text": "Red Fort, Delhi", "is_correct": false}, {"option_text": "Khajuraho temples", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f184c8c3-065b-5b99-85fd-08bf058ccf62', 'The Kailash Temple (Cave 16) at Ellora, the world''s largest monolithic rock-cut structure, was commissioned by which king?', NULL, 'The Kailash Temple (Cave 16, Ellora, Maharashtra) is a monolith carved top-down from a single basalt rock by the Rashtrakuta king KRISHNA I (r. 756-774 CE). Dedicated to Shiva, modelled after Mount Kailash. Covers 2x the area of the Parthenon in Athens and is 1.5x its height. An estimated 200,000 tonnes of rock were removed. One of the greatest engineering and artistic achievements in human history. Ellora overall has 34 caves: 12 Buddhist (600-700 CE, south), 17 Hindu (600-900 CE, middle), 5 Jain (800-1000 CE, north) — a unique coexistence.', 'HARD', 'General Knowledge', 'Famous Temples, Monuments & Places in India', 'GK_TEMPLES_MONUMENTS', '[{"option_text": "Pulakeshin II of Chalukya", "is_correct": false}, {"option_text": "Krishna I of Rashtrakuta", "is_correct": true}, {"option_text": "Rajendra Chola I of Chola", "is_correct": false}, {"option_text": "Dhruva of Rashtrakuta", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5a837bf9-46cb-5fb5-8cb7-0c3cff3e850a', 'The Brihadeshwara Temple at Thanjavur, a UNESCO WHS, was built by which Chola emperor?', NULL, 'The Brihadeshwara (Peruvudaiyar, RajaRajeshwaram) Temple at Thanjavur (Tamil Nadu) was built by RAJA RAJA CHOLA I between 1003-1010 CE. It is one of the ''Great Living Chola Temples'' (UNESCO WHS 1987, extended 2004). Features: the main vimana (tower) is ~216 ft high, one of the tallest of any Indian temple; crowned by a 80-tonne single-stone kalash on top; the massive Nandi bull statue at the entrance weighs 20 tonnes. Other Living Chola Temples: Gangaikondacholapuram (Rajendra I, 1035 CE), Airavatesvara at Darasuram (Rajaraja II, 12th c.).', 'MEDIUM', 'General Knowledge', 'Famous Temples, Monuments & Places in India', 'GK_TEMPLES_MONUMENTS', '[{"option_text": "Rajendra Chola I", "is_correct": false}, {"option_text": "Raja Raja Chola I", "is_correct": true}, {"option_text": "Kulothunga Chola I", "is_correct": false}, {"option_text": "Vijayalaya Chola", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0ef8a851-9be8-5e96-86b6-026593d526d5', 'The Sun Temple at Konark was built in the 13th century by which king of which dynasty?', NULL, 'The Sun Temple at Konark (Odisha) was built by King NARASIMHADEVA I of the Eastern Ganga dynasty around 1250 CE — to commemorate his military victory over Muslim invaders. Designed in the form of a gigantic CHARIOT with 12 pairs of intricately carved wheels (representing 12 months/zodiac signs) and 7 running horses (representing days of the week or the Sun god''s chariot). UNESCO WHS 1984. The main shikhara collapsed long ago; only the jagmohan (audience hall) and the dance hall remain. Called the ''Black Pagoda'' by European sailors (as a navigation landmark).', 'MEDIUM', 'General Knowledge', 'Famous Temples, Monuments & Places in India', 'GK_TEMPLES_MONUMENTS', '[{"option_text": "Kharavela of Mahameghavahana", "is_correct": false}, {"option_text": "Narasimhadeva I of Eastern Ganga", "is_correct": true}, {"option_text": "Anantavarman Chodaganga", "is_correct": false}, {"option_text": "Pratap Rudra Dev of Gajapati", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a8da5874-60d3-5a63-9fc0-26f5ef336a7a', 'The Khajuraho Group of Monuments, famous for their erotic sculptures and Nagara-style temples, were built by which dynasty?', NULL, 'The Khajuraho temples (MP) were built by the Chandela Rajputs between 950-1050 CE — originally 85 temples; only 25 survive today (20 Hindu + 5 Jain). Most famous: Kandariya Mahadev (tallest, 31m, dedicated to Shiva), Lakshmana, Vishwanath, Devi Jagadambi, Chitragupta. UNESCO WHS 1986. The erotic sculptures (only ~10% of total sculptures) represent the temple''s tantric associations, or celebrate life / Kama (one of the 4 purusharthas). The temples were ''rediscovered'' by British officer T.S. Burt in 1838 after being hidden by jungle for centuries. Classical example of Nagara architecture.', 'MEDIUM', 'General Knowledge', 'Famous Temples, Monuments & Places in India', 'GK_TEMPLES_MONUMENTS', '[{"option_text": "Pratihara", "is_correct": false}, {"option_text": "Chandela", "is_correct": true}, {"option_text": "Paramara", "is_correct": false}, {"option_text": "Rashtrakuta", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1f279867-8d8b-50fe-a4e8-4a8d2d501024', 'Hampi, a UNESCO WHS, was the capital of which medieval empire?', NULL, 'Hampi (Karnataka, on the Tungabhadra river) was the capital of the VIJAYANAGARA Empire (1336-1565/1646 CE). Founded by Harihara I and Bukka Raya I of the Sangama dynasty in 1336 under sage Vidyaranya''s blessing. At its peak under Krishnadevaraya (1509-29), Hampi was one of the world''s largest cities (500,000 people). Destroyed after the Battle of Talikota (1565) when the Deccan Sultanates combined to rout the Vijayanagara army. Key monuments: Virupaksha Temple (active since 7th c.), Vittala Temple (musical stone pillars, stone chariot), Lotus Mahal, Elephant Stables, Hazara Rama Temple. UNESCO WHS 1986.', 'MEDIUM', 'General Knowledge', 'Famous Temples, Monuments & Places in India', 'GK_TEMPLES_MONUMENTS', '[{"option_text": "Bahmani Sultanate", "is_correct": false}, {"option_text": "Vijayanagara Empire", "is_correct": true}, {"option_text": "Hoysala Empire", "is_correct": false}, {"option_text": "Western Chalukya Empire", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3aca2542-8fae-59e9-9448-6d7235b59255', 'Which is the ONLY mixed (natural + cultural) UNESCO World Heritage Site in India?', NULL, 'Khangchendzonga National Park (Sikkim) — inscribed in 2016 — is India''s ONLY MIXED UNESCO WHS (both natural AND cultural criteria). Natural: includes Mt Khangchendzonga (8,586m — world''s 3rd-highest peak, and sacred to Sikkimese Buddhists), glaciers, lakes, diverse flora/fauna. Cultural: sacred landscapes of the indigenous Lepcha people and Sikkimese Buddhists — Khangchendzonga is revered as ''Mount Kinchinjonga'' by locals and worshipped. Globally, only ~40 mixed WHS exist. Sundarbans, Western Ghats, Nanda Devi & VoF are all pure-natural.', 'HARD', 'General Knowledge', 'Famous Temples, Monuments & Places in India', 'GK_TEMPLES_MONUMENTS', '[{"option_text": "Sundarbans National Park", "is_correct": false}, {"option_text": "Khangchendzonga National Park, Sikkim", "is_correct": true}, {"option_text": "Western Ghats", "is_correct": false}, {"option_text": "Nanda Devi & Valley of Flowers", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d8083e23-37c1-53de-a084-73b111bfd13e', 'The Jagannath Temple of Puri and the annual Rath Yatra are associated with which deity form?', NULL, 'The Jagannath Temple at Puri (Odisha) is dedicated to Lord Jagannath (''Lord of the Universe'' — a form of Vishnu/Krishna), along with his elder brother BALABHADRA and sister SUBHADRA. Built in the 12th c. by Anantavarman Chodaganga Deva of the Eastern Ganga dynasty. One of the CHAR DHAM of Hinduism (Puri + Rameswaram + Dwarka + Badrinath). The RATH YATRA (annual chariot festival, June-July) is world-famous — three huge wooden chariots (Nandighosha, Taladhwaja, Darpadalana) pull the deities the 3 km journey to Gundicha Temple and back. The English word ''juggernaut'' derives from Jagannath. NOT a UNESCO WHS yet but on tentative list.', 'EASY', 'General Knowledge', 'Famous Temples, Monuments & Places in India', 'GK_TEMPLES_MONUMENTS', '[{"option_text": "Shiva", "is_correct": false}, {"option_text": "Vishnu (Krishna as Jagannath, with Balabhadra and Subhadra)", "is_correct": true}, {"option_text": "Devi Durga", "is_correct": false}, {"option_text": "Surya", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f7449a69-953d-5282-95ad-283bca7491d6', 'Dholavira, one of the five largest Harappan sites and a 2021 UNESCO WHS, is located in which state?', NULL, 'Dholavira is located on Khadir Bet island in the Great Rann of Kutch, Gujarat. Discovered 1968, excavated 1989-2005 by RS Bisht (ASI). Features: a tripartite layout (Citadel, Middle Town, Lower Town), an ingenious water harvesting system with 16 reservoirs, and a famous 10-character ''Dholavira Signboard'' — possibly the oldest signboard in the world. Inscribed as India''s 40th UNESCO WHS on 27 July 2021. OTHER KEY HARAPPAN SITES: Mohenjo-daro (now Pakistan), Harappa (Pakistan), Lothal (Gujarat — world''s earliest dockyard), Rakhigarhi (Haryana — largest), Kalibangan (Rajasthan — ploughed field, fire altars), Banawali (Haryana), Surkotada (Gujarat — horse remains).', 'MEDIUM', 'General Knowledge', 'Famous Temples, Monuments & Places in India', 'GK_TEMPLES_MONUMENTS', '[{"option_text": "Haryana", "is_correct": false}, {"option_text": "Gujarat (Kutch region)", "is_correct": true}, {"option_text": "Rajasthan", "is_correct": false}, {"option_text": "Punjab", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('415900ee-95ff-5842-904b-a494eec148c5', 'The Apatani tribe, famous for their nose-plug tradition and sustainable rice-fish farming, inhabits which state?', NULL, 'The Apatani (or Tanw) live in the Ziro Valley of Lower Subansiri district, Arunachal Pradesh. Famous for: (1) the facial ''Yapping Hulo'' tradition (now discontinued — older Apatani women had large nose plugs and facial tattoos, done historically to make them ''unattractive'' to raiding tribes); (2) sustainable wet-rice and fish (paddy-cum-pisciculture) farming on valley floors without using any animal power or wheel — a UNESCO candidate site for cultural landscape; (3) the Dree festival (July). The Apatani language belongs to the Tani branch of Sino-Tibetan.', 'MEDIUM', 'General Knowledge', 'Major Tribes of India & World', 'GK_TRIBES', '[{"option_text": "Meghalaya", "is_correct": false}, {"option_text": "Arunachal Pradesh (Ziro valley)", "is_correct": true}, {"option_text": "Nagaland", "is_correct": false}, {"option_text": "Manipur", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2eaf389e-3332-5752-92ea-d46522cd4d0f', 'The Khasi, Jaintia, and Garo are the three major indigenous tribes of which state?', NULL, 'Meghalaya (''abode of clouds'') has three major tribes inhabiting three hill regions: KHASI (central Khasi Hills — language is Khasian, an Austroasiatic language unique in NE), JAINTIA (eastern Jaintia Hills), and GARO (western Garo Hills — Tibeto-Burman language). All three are MATRILINEAL societies (inheritance through the mother''s line — one of the largest surviving matrilineal societies in the world). The Khasis and Jaintias consider themselves ''Hynñiewtrep'' (seven huts); the Garos call themselves ''A·chik''.', 'EASY', 'General Knowledge', 'Major Tribes of India & World', 'GK_TRIBES', '[{"option_text": "Nagaland", "is_correct": false}, {"option_text": "Meghalaya", "is_correct": true}, {"option_text": "Mizoram", "is_correct": false}, {"option_text": "Tripura", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6be8e706-9deb-509b-b95b-097f98ff6ef0', 'The term PVTG (Particularly Vulnerable Tribal Group) was introduced in India during which period, and how many PVTGs are officially recognised?', NULL, 'PVTGs were first recognised in 1975 (under the Dhebar Commission recommendation) as ''Primitive Tribal Groups'' (PTGs); renamed PARTICULARLY VULNERABLE TRIBAL GROUPS in 2006. Currently 75 PVTGs are officially listed across 18 states + A&N Islands. Criteria for PVTG status: (a) pre-agricultural technology; (b) stagnant/declining population; (c) low literacy; (d) economic backwardness. Odisha has the MOST PVTGs (13), followed by Andhra Pradesh. Among PVTGs: Great Andamanese, Jarawa, Onge, Sentinelese (all A&N); Birhor, Saura, Korwa; Chenchu (AP); Toda (TN); Bhil-Koli; Sahariya.', 'HARD', 'General Knowledge', 'Major Tribes of India & World', 'GK_TRIBES', '[{"option_text": "1975 (as ''Primitive Tribal Groups''); 52 PVTGs", "is_correct": false}, {"option_text": "1975 (as PTGs, renamed PVTGs in 2006); 75 PVTGs", "is_correct": true}, {"option_text": "1991; 100 PVTGs", "is_correct": false}, {"option_text": "2011 Census; 45 PVTGs", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('25d74617-e2ca-52f7-a343-d0c1c69aa872', 'The Toda tribe, known for their distinctive barrel-vaulted huts and buffalo-centric culture, inhabits which hill region?', NULL, 'The Toda (or Todar) are a small pastoral community of the Nilgiri Hills (Tamil Nadu), famous for: (1) half-barrel ''munds'' (thatched huts without doors or windows; entry through a small opening); (2) sacred buffalo-based culture and associated dairy rituals; (3) intricate embroidered ''Pugur'' shawls (GI-tagged). Population is tiny (~1500). Recognised as a PVTG. The Badaga, Kota, Irula, and Kurumba also inhabit the Nilgiris — studied extensively by anthropologists.', 'MEDIUM', 'General Knowledge', 'Major Tribes of India & World', 'GK_TRIBES', '[{"option_text": "Aravalli Hills, Rajasthan", "is_correct": false}, {"option_text": "Nilgiri Hills, Tamil Nadu", "is_correct": true}, {"option_text": "Sahyadri Hills, Maharashtra", "is_correct": false}, {"option_text": "Shevaroy Hills, Tamil Nadu", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('16ede1ac-7124-555b-ba81-b1297fbb0266', 'The Sentinelese, one of the world''s last uncontacted tribes, inhabit which island?', NULL, 'The Sentinelese live on North Sentinel Island (Andaman & Nicobar Islands). One of the world''s last uncontacted peoples — they hostilely reject all outside contact. The Indian government protects them under the Andaman and Nicobar Islands (PATR) Regulation, 1956, which prohibits approach within 5 km of the island. Population: ~50-100 (estimated). Speak a language unrelated to any other known; classified a PVTG. Other Andaman PVTGs: Jarawa (South & Middle Andaman), Onge (Little Andaman), Great Andamanese (Strait Island). Shompen (Great Nicobar) is a Nicobarese PVTG.', 'EASY', 'General Knowledge', 'Major Tribes of India & World', 'GK_TRIBES', '[{"option_text": "Car Nicobar Island", "is_correct": false}, {"option_text": "North Sentinel Island (Andaman)", "is_correct": true}, {"option_text": "Great Nicobar Island", "is_correct": false}, {"option_text": "Little Andaman Island", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('48d92e16-2e0e-510b-9831-b3912c20a010', 'The Bhil tribe, one of India''s largest tribal communities, is primarily concentrated in which states?', NULL, 'The Bhil are India''s third-largest tribe (after Gonds and Santhals), concentrated in the Aravalli-Vindhya-Satpura region — MP, Rajasthan, Gujarat, Maharashtra, and parts of Tripura. Historically known as fierce archers (the Mahabharata mentions Eklavya as a Bhil prince). Bhil Pithora paintings are their cultural art. Famous Bhil personalities: Jhalkari Bai (Rani of Jhansi''s general), Tantya Bhil (freedom fighter, called ''Indian Robin Hood''). Largest Indian tribes by population (2011 Census): 1. Gond, 2. Santhal (Santal), 3. Bhil, 4. Mina, 5. Oraon.', 'MEDIUM', 'General Knowledge', 'Major Tribes of India & World', 'GK_TRIBES', '[{"option_text": "Chhattisgarh, Jharkhand, Odisha", "is_correct": false}, {"option_text": "Madhya Pradesh, Rajasthan, Gujarat, Maharashtra", "is_correct": true}, {"option_text": "Andhra Pradesh, Telangana, Karnataka", "is_correct": false}, {"option_text": "Assam, Arunachal Pradesh, Nagaland", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3635aacc-f83a-5717-b1e3-409bef3c4e0f', 'The Konyak Nagas, formerly known for the now-extinct practice of headhunting, primarily inhabit which region?', NULL, 'The Konyaks are the largest Naga tribe, concentrated in Mon district, northern Nagaland, straddling the Myanmar border. Until the mid-20th c., Konyaks were feared headhunters; the practice ended in the 1960s after Christianisation. Distinctive features: elaborate face tattoos (historically marking successful warriors), pipe smoking by both genders, brass skulls on necklaces. Their festival is AOLING (spring). Major Naga tribes (17 officially): Angami, Ao, Chakhesang, Chang, Konyak, Lotha, Phom, Pochury, Rengma, Sangtam, Sema (Sumi), Yimchungru, Zeliang, Khiamniungan, Kuki, Kachari, Garo.', 'HARD', 'General Knowledge', 'Major Tribes of India & World', 'GK_TRIBES', '[{"option_text": "Western Nagaland (Wokha district)", "is_correct": false}, {"option_text": "Northern Nagaland (Mon district, bordering Myanmar)", "is_correct": true}, {"option_text": "Southern Nagaland (Phek district)", "is_correct": false}, {"option_text": "Central Nagaland (Kohima district)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('71ab0d15-9556-517f-bb61-856d9802e8c5', 'The Gond tribe, India''s largest tribal community, primarily speaks which language family?', NULL, 'The Gonds are India''s largest tribe (population ~13 million per 2011 Census) — primarily in MP, Chhattisgarh, Maharashtra, Telangana, AP, Odisha. Their language GONDI belongs to the Dravidian family (not Indo-Aryan, despite the central-Indian geography) — a reminder that Dravidian languages once extended much further north than today. Gondwana region is named after them. Ruled several kingdoms between the 10th-18th c. (Gond Kingdoms of Garha Katanga, Chanda, Deogarh, Mandla). Famous Gond queen: Rani Durgavati of Gondwana (d. 1564 fighting Akbar).', 'HARD', 'General Knowledge', 'Major Tribes of India & World', 'GK_TRIBES', '[{"option_text": "Indo-Aryan", "is_correct": false}, {"option_text": "Dravidian (Gondi)", "is_correct": true}, {"option_text": "Tibeto-Burman", "is_correct": false}, {"option_text": "Austroasiatic", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('05763582-57be-5d95-b568-9da0a528b56f', 'The Santhals, India''s second-largest tribe, speak a language belonging to which family?', NULL, 'The Santhals (or Santal) speak Santali, an Austroasiatic language of the Munda branch — one of India''s oldest language families, surviving only in pockets (Santali, Mundari, Ho, Kharia, Kurku, Khasi). Santali was added to the 8th Schedule by the 92nd Amendment (2003). Uses the OL CHIKI script (invented by Pandit Raghunath Murmu in 1925). Largest concentration: Jharkhand, WB, Odisha, Bihar. Famous Santhal leaders: Sidhu and Kanhu Murmu (led the 1855 Santhal Rebellion / ''Santhal Hul'' against British and zamindars). Santhal Hul Day: 30 June.', 'HARD', 'General Knowledge', 'Major Tribes of India & World', 'GK_TRIBES', '[{"option_text": "Indo-Aryan", "is_correct": false}, {"option_text": "Dravidian", "is_correct": false}, {"option_text": "Austroasiatic (Munda branch)", "is_correct": true}, {"option_text": "Tibeto-Burman", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('862034cf-0988-553a-ab9b-ec1a41be5367', 'The Jarawa and Onge tribes are PVTGs inhabiting which islands?', NULL, 'JARAWAS live in the western forested areas of Middle and South Andaman; population ~400 (2011) — up from a low of <300 in the 1990s. Recognised a PVTG. Historically hostile to outsiders until a peaceful contact breakthrough in 1998. ONGE live on Little Andaman; population ~120 — a declining PVTG. They are hunter-gatherers. All four ''Negrito'' Andamanese tribes (Great Andamanese, Jarawa, Onge, Sentinelese) speak related languages unrelated to any mainland language. Nicobarese (Shompen, Nicobarese) are Mongoloid and ethnically/linguistically distinct from Andamanese.', 'MEDIUM', 'General Knowledge', 'Major Tribes of India & World', 'GK_TRIBES', '[{"option_text": "Lakshadweep Islands", "is_correct": false}, {"option_text": "Andaman & Nicobar Islands", "is_correct": true}, {"option_text": "Majuli Island, Assam", "is_correct": false}, {"option_text": "Island of Sikkim", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ffc94df2-09f8-52e2-9ca9-8a78018f28e4', 'The Himalayas are divided into three main parallel ranges from north to south. Which range is the HIGHEST and contains Mount Everest?', NULL, 'The Himalayas have three longitudinal divisions (from N to S): (1) GREATER HIMALAYAS (Himadri/Inner/Central) — tallest, contains Everest (8,848m), Kanchenjunga (8586m — 3rd highest), Makalu, Cho Oyu, Dhaulagiri; perennial snow; source of major rivers. (2) LESSER HIMALAYAS (Himachal/Middle) — ranges like Pir Panjal, Dhauladhar, Mussoorie, Nag Tibba, Mahabharat; hill stations (Shimla, Mussoorie, Nainital, Darjeeling); avg 3500-5000m. (3) SHIVALIK (Outer/Sub-Himalayas) — 900-1200m, youngest range; covered with dense forests; famous for Siwalik fossils. TRANS-HIMALAYAS (Karakoram, Ladakh, Zaskar) lie NORTH of the Greater Himalayas — K2 (8611m — 2nd highest globally) is in Karakoram.', 'EASY', 'Geography', 'India - Himalayas & Northern Mountains', 'GEO_IND_HIMALAYAS', '[{"option_text": "Shivalik (outer)", "is_correct": false}, {"option_text": "Middle Himalayas / Himachal / Lesser Himalayas", "is_correct": false}, {"option_text": "Greater Himalayas / Himadri / Inner Himalayas", "is_correct": true}, {"option_text": "Trans-Himalayas", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a1199dc0-0ac4-582c-a35a-b9ab3078a2c8', 'Which is India''s HIGHEST mountain peak (in Indian territory)?', NULL, 'KANCHENJUNGA (8,586m, Sikkim) is India''s highest peak within undisputed Indian territory — also the world''s 3rd highest mountain after Everest and K2. MOUNT EVEREST (8848m) is on the Nepal-Tibet (China) border, NOT Indian. K2 (8611m, world''s 2nd highest) is in the Pakistan-Occupied Kashmir region (disputed but claimed by both India and Pakistan; practically accessed via Pakistan) — NOT counted as Indian by most authorities. NANDA DEVI (7816m, Uttarakhand) is the 2nd-highest peak within India''s actual jurisdiction. Kanchenjunga is sacred to Sikkimese Buddhists — climbers traditionally stop just short of the summit as a mark of respect.', 'MEDIUM', 'Geography', 'India - Himalayas & Northern Mountains', 'GEO_IND_HIMALAYAS', '[{"option_text": "Mount Everest", "is_correct": false}, {"option_text": "Kanchenjunga (Sikkim, 8,586 m)", "is_correct": true}, {"option_text": "Nanda Devi (Uttarakhand, 7,816 m)", "is_correct": false}, {"option_text": "K2 (Karakoram)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('048f5d04-d967-5c51-9b83-d1ad9df715e2', 'Which Himalayan pass connects Srinagar with Leh and remains closed for 4-6 months in winter?', NULL, 'ZOJI LA (3528m) in Ladakh connects Srinagar (Kashmir Valley) to Leh via Kargil — the critical road link for Ladakh, closed by snow Dec-May. ZOJILA TUNNEL (under construction as of 2024, India''s longest road tunnel at 14.1 km) will make it all-weather. Other key Himalayan passes: BANIHAL (Jawahar Tunnel, Jammu-Srinagar); ROHTANG (Manali-Leh, HP — also being replaced by Atal Tunnel since 2020, 9 km, world''s longest at 10000ft altitude); KHARDUNG LA (Leh-Nubra, was claimed ''world''s highest motorable'' at 5359m — now superseded by Umling La, Ladakh at 5883m — world''s highest motorable road since 2021); CHANG LA (Leh-Pangong); NATHULA (Sikkim-Tibet, trade); JELEP LA (Sikkim); BOMDILA + BUM LA (Arunachal-Tibet); LIPULEKH (Uttarakhand-Tibet, pilgrimage to Kailash); SHIPKI LA (HP-Tibet, Sutlej).', 'MEDIUM', 'Geography', 'India - Himalayas & Northern Mountains', 'GEO_IND_HIMALAYAS', '[{"option_text": "Banihal Pass", "is_correct": false}, {"option_text": "Zoji La", "is_correct": true}, {"option_text": "Khardung La", "is_correct": false}, {"option_text": "Rohtang Pass", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('36fe7977-54a2-59bf-a832-91a7d0abe8d6', 'The Siachen Glacier, known as the world''s highest battlefield, is located in which region?', NULL, 'SIACHEN GLACIER (~76 km long, 2nd longest non-polar glacier after Fedchenko in Tajikistan) lies in the Karakoram Range of eastern Ladakh, between the Saltoro Ridge (west) and the main Karakoram (east). India took control of the entire glacier on 13 April 1984 via OPERATION MEGHDOOT (launched by Lt Gen M. L. Chibber + Colonel Narinder ''Bull'' Kumar), pre-empting a planned Pakistani occupation. Average altitude ~5400m; temperatures as low as −60°C. The tri-junction of India, Pakistan and China is nearby (Indira Col). Longest glacier system entirely in India: GANGOTRI (30 km, Uttarakhand — source of Bhagirathi-Ganga).', 'MEDIUM', 'Geography', 'India - Himalayas & Northern Mountains', 'GEO_IND_HIMALAYAS', '[{"option_text": "Uttarakhand — Gangotri region", "is_correct": false}, {"option_text": "Karakoram Range, Ladakh (India controlled since Operation Meghdoot, 1984)", "is_correct": true}, {"option_text": "Sikkim — Khangchendzonga", "is_correct": false}, {"option_text": "Arunachal Pradesh", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ab4d01fa-5fbf-576e-aa0a-1aed334317b9', 'Nathula Pass, a key India-China trade route at 4310 m in the Eastern Himalayas, is in which state?', NULL, 'NATHULA PASS (4310m) is in Sikkim, on the India-China (Tibet) border, part of the ancient Silk Route branch connecting Lhasa to Kolkata via Kalimpong. Closed after the 1962 Sino-Indian war; REOPENED in 2006 for trade. The area saw Chinese incursions in 1967 (Nathu La clashes — Indian army repulsed). Open for tourists from Indian side May-November. Nearby: JELEP LA (4267m, historically more important than Nathula) — also in Sikkim. DOKLAM plateau (tri-junction India-Bhutan-China) lies south of Nathula — site of 2017 India-China standoff.', 'MEDIUM', 'Geography', 'India - Himalayas & Northern Mountains', 'GEO_IND_HIMALAYAS', '[{"option_text": "Arunachal Pradesh", "is_correct": false}, {"option_text": "Sikkim", "is_correct": true}, {"option_text": "West Bengal (Darjeeling)", "is_correct": false}, {"option_text": "Uttarakhand", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('89038594-b1be-5fc2-856b-ca69ba767961', 'The Karakoram Pass, historically a key trade route between India (Leh) and Yarkand (China''s Xinjiang), lies in which state/UT?', NULL, 'KARAKORAM PASS (5540m), in the Ladakh UT on the India-China border, is one of the highest passes in the world — named the ''Pass of Black Gravel''. Historically part of the Silk Route linking Leh to Kashgar and Yarkand. Now closed for civilian crossing; lies near the Siachen region. Other Ladakh/J&K passes: SASER LA, KHARDUNG LA, CHANG LA, MARSIMIK LA, PEMZAL LA. Umling La (5883m, Ladakh) became the world''s highest motorable in 2021 (BRO built). Main Karakoram range features K2 (8611m), Gasherbrum I & II, Broad Peak (all in Pak-occupied Gilgit-Baltistan).', 'HARD', 'Geography', 'India - Himalayas & Northern Mountains', 'GEO_IND_HIMALAYAS', '[{"option_text": "Himachal Pradesh", "is_correct": false}, {"option_text": "Ladakh (UT)", "is_correct": true}, {"option_text": "Uttarakhand", "is_correct": false}, {"option_text": "Arunachal Pradesh", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('93374e6c-ef47-5107-9d4a-46976fe34480', 'Which of the following is NOT among India''s 10+ 7000-metre-plus peaks (in Indian-administered territory)?', NULL, 'ANNAPURNA I (8091m — world''s 10th highest) is in NEPAL, not India. India''s key 7000m+ peaks in undisputed territory: KANCHENJUNGA (8586m, Sikkim — highest in India), NANDA DEVI (7816m, Uttarakhand), KAMET (7756m, Uttarakhand), SALTORO KANGRI (7742m, Ladakh), SASER KANGRI (7672m, Ladakh), MAMOSTONG KANGRI (7516m, Ladakh), MANA (7272m, UK), CHAUKHAMBA (7138m, UK), TRISUL (7120m, UK), KEDARNATH (6940m, UK). India''s high peaks concentrate in the Karakoram (Ladakh), Kumaon-Garhwal (Uttarakhand), and Sikkim Himalayas. Himachal''s highest: Reo Purgyil (6816m).', 'HARD', 'Geography', 'India - Himalayas & Northern Mountains', 'GEO_IND_HIMALAYAS', '[{"option_text": "Nanda Devi (7,816m)", "is_correct": false}, {"option_text": "Kamet (7,756m)", "is_correct": false}, {"option_text": "Annapurna I (8,091m)", "is_correct": true}, {"option_text": "Saltoro Kangri (7,742m)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e04fb1c0-70f3-5883-9e33-3a8b0630abef', 'The Himalayan river system has THREE major rivers originating from Tibet/Himalayas. Which one rises in the TIBETAN PLATEAU and is known there as ''Yarlung Tsangpo''?', NULL, 'BRAHMAPUTRA rises near Lake Manasarovar (Tibet) as the Yarlung Tsangpo, flows EAST across southern Tibet for ~1700 km, takes a sharp ''Great Bend'' around Namcha Barwa, then enters Arunachal Pradesh as the SIANG / DIHANG. Joined by Lohit and Dibang at Sadiya → becomes the BRAHMAPUTRA flowing west through Assam. Enters Bangladesh as JAMUNA, merges with Padma (Ganga) and Meghna before emptying into the Bay of Bengal. INDUS also rises near Manasarovar, flows NW into Ladakh and then PoK. GANGA rises as Bhagirathi from Gangotri Glacier (UK), joined by Alaknanda at Devprayag to officially become the Ganga. Yamuna rises at Yamunotri (UK).', 'MEDIUM', 'Geography', 'India - Himalayas & Northern Mountains', 'GEO_IND_HIMALAYAS', '[{"option_text": "Indus", "is_correct": false}, {"option_text": "Ganga", "is_correct": false}, {"option_text": "Brahmaputra", "is_correct": true}, {"option_text": "Yamuna", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('43f89de0-8a6c-5a1e-881c-08a2c99c4a40', 'Which is the LONGEST Peninsular river of India, flowing through six states and emptying into the Bay of Bengal?', NULL, 'GODAVARI (1465 km) is the LONGEST Peninsular river and 2nd longest in India overall (after the Ganga). Called ''Dakshin Ganga'' (Southern Ganges). Source: Triyambakeshwar (Nashik district, Maharashtra, Western Ghats). Flows E/SE through Maharashtra, Telangana, AP (and touches MP, CG, Odisha in catchment) → Bay of Bengal at Antarvedi (Andhra delta). Tributaries: Manjira, Wainganga, Pranhita, Indravati, Sabari. Rank of peninsular rivers by length: Godavari (1465) > Krishna (1400) > Mahanadi (851) > Cauvery (800) > Narmada (1312 westward) > Tapi (724 westward). Narmada is longer than Cauvery/Mahanadi but flows WESTWARD into the Arabian Sea.', 'MEDIUM', 'Geography', 'India - Peninsular River System', 'GEO_IND_RIVER_PEN', '[{"option_text": "Krishna", "is_correct": false}, {"option_text": "Godavari (''Dakshin Ganga'')", "is_correct": true}, {"option_text": "Cauvery", "is_correct": false}, {"option_text": "Mahanadi", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('96534cad-7697-5377-9e13-ffa954674c1c', 'Which of the following peninsular rivers flows WESTWARD into the Arabian Sea (not eastward into Bay of Bengal)?', NULL, 'Most peninsular rivers flow EASTWARD (due to the gentle eastern slope of the Deccan Plateau) — Mahanadi, Godavari, Krishna, Cauvery. Only a few flow WESTWARD into the Arabian Sea: NARMADA (longest westward-flowing, 1312 km; source Amarkantak MP; flows through a RIFT VALLEY between Vindhya & Satpura ranges; NO delta — forms an estuary at Gulf of Khambhat near Bharuch Gujarat); TAPI / TAPTI (724 km, second-longest westward; source Multai MP; parallel to Narmada; also rift valley through Satpura; estuary at Surat Guj); SABARMATI (Rajasthan→Gujarat, Gandhi''s ashram on its banks at Ahmedabad); MAHI (MP→Guj); LUNI (Thar, ends in Rann of Kutch). Western Ghats coastal streams (Bharatpuzha, Periyar, Netravati) also flow west.', 'EASY', 'Geography', 'India - Peninsular River System', 'GEO_IND_RIVER_PEN', '[{"option_text": "Krishna", "is_correct": false}, {"option_text": "Cauvery", "is_correct": false}, {"option_text": "Narmada", "is_correct": true}, {"option_text": "Mahanadi", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ce4e1925-e7b3-5b47-9b27-d7e954c2093b', 'The Cauvery river originates in which hill range, and which three states does it primarily flow through?', NULL, 'CAUVERY (~800 km) originates at TALAKAVERI in the BRAHMAGIRI HILLS (Western Ghats) in Kodagu (Coorg) district, KARNATAKA. Flows primarily through Karnataka, Tamil Nadu — enters Bay of Bengal near POOMPUHAR (TN) + Karaikal (Puducherry). Small catchment in Kerala (Wayanad) too. Major tributaries: Harangi, Hemavati, Shimsha, Arkavati, Kabini (from Kerala), Bhavani (Nilgiris), Noyyal, Amaravati. Famous dams: Krishna Raja Sagar (KA, near Mysuru), Mettur / Stanley Reservoir (TN). Water dispute (CAUVERY DISPUTE) between KA-TN-Kerala-Puducherry is one of India''s oldest — CWDT 2007 award, SC settlement 2018. Cauvery is sacred; its delta in TN is called the ''Rice Bowl of South India''.', 'MEDIUM', 'Geography', 'India - Peninsular River System', 'GEO_IND_RIVER_PEN', '[{"option_text": "Nilgiri Hills; Kerala, Karnataka, TN", "is_correct": false}, {"option_text": "Brahmagiri Hills (Western Ghats); Karnataka, TN, Puducherry", "is_correct": true}, {"option_text": "Satpura Hills; Maharashtra, MP, AP", "is_correct": false}, {"option_text": "Eastern Ghats; AP, TN, Kerala", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('51863264-d8b8-5467-a3c4-046c0bde9a72', 'The Krishna river originates in Maharashtra (Western Ghats). Its main tributary, the largest by discharge, is:', NULL, 'KRISHNA (~1400 km, 2nd-longest peninsular) originates at MAHABALESHWAR (Maharashtra, Western Ghats) and flows through Maharashtra, Karnataka, Telangana, AP → Bay of Bengal near Vijayawada/Machilipatnam. Major tributaries: TUNGABHADRA (formed by union of Tunga and Bhadra in Karnataka; largest by water volume — joins Krishna at Alampur), BHIMA (longest tributary — rises in Bhimashankar Maha), KOYNA (major dam), GHATAPRABHA, MALAPRABHA, MUSI (flows through Hyderabad), MUSI. Famous dams: Nagarjuna Sagar (Telangana-AP — world''s largest masonry dam; multi-purpose), Srisailam, Almatti (KA), Tungabhadra (KA-AP). Nagarjunasagar-Srisailam is also India''s largest tiger reserve.', 'MEDIUM', 'Geography', 'India - Peninsular River System', 'GEO_IND_RIVER_PEN', '[{"option_text": "Bhima", "is_correct": false}, {"option_text": "Tungabhadra", "is_correct": true}, {"option_text": "Koyna", "is_correct": false}, {"option_text": "Ghataprabha", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a9c57e1a-4b4e-57b8-b979-dc5771f0a9e8', 'The Mahanadi river, with the Hirakud Dam — the world''s LONGEST EARTHEN DAM — flows primarily through which state?', NULL, 'MAHANADI (~851 km) rises at Sihawa, Dhamtari district, CHHATTISGARH, but flows primarily through Odisha (empties into Bay of Bengal via its delta at Paradip). HIRAKUD DAM (Sambalpur district, Odisha, 1956) — built across Mahanadi. Length ~25.8 km (main + dykes) — world''s longest EARTHEN / earth-and-concrete composite dam. Also India''s first major post-independence multi-purpose river valley project. Main Mahanadi tributaries: Seonath, Ong, Jonk, Hasdeo, Ib, Mand, Tel. Mahanadi delta hosts the CHILIKA LAKE (via distributaries) and the BHITARKANIKA mangroves. Historically called ''Mahan'' (great) + ''Nadi'' (river).', 'MEDIUM', 'Geography', 'India - Peninsular River System', 'GEO_IND_RIVER_PEN', '[{"option_text": "Chhattisgarh", "is_correct": false}, {"option_text": "Odisha", "is_correct": true}, {"option_text": "Jharkhand", "is_correct": false}, {"option_text": "Andhra Pradesh", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('05d8fde7-2393-5e7e-8885-cf7f66b77c0f', 'The Narmada and Tapi rivers flow through rift valleys between which two mountain ranges?', NULL, 'Both NARMADA and TAPI flow westward through RIFT VALLEYS — a block faulted down (graben) between two parallel ranges. NARMADA is between the VINDHYA range (north) and SATPURA range (south). TAPI is south of the Satpura range — technically between the Satpura (north) and the Gawilgarh Hills / Ajanta Hills (south). Both rivers flow ~parallel to each other. This rift-valley origin is WHY they DON''T form deltas (rift-valley topography gives straight confined flow) — they form ESTUARIES at the Gulf of Khambhat (Narmada at Bharuch, Tapi at Surat). Vindhya also marks the TRADITIONAL DIVIDE between North and South India.', 'MEDIUM', 'Geography', 'India - Peninsular River System', 'GEO_IND_RIVER_PEN', '[{"option_text": "Himalayas and Vindhya", "is_correct": false}, {"option_text": "Vindhya and Satpura", "is_correct": true}, {"option_text": "Satpura and Western Ghats", "is_correct": false}, {"option_text": "Aravalli and Vindhya", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b88509cd-86d7-52e2-aa40-e149b2d00a49', 'The LUNI river, India''s only river of the arid Thar desert, originates in the Aravalli Hills and ends in which water body?', NULL, 'LUNI (''Lavanavati'' = ''salty river'' due to its saline waters from the region) originates from Pushkar Valley in Ajmer district (Aravalli Hills) at ~550m elevation, flows ~495 km south-west through southern Rajasthan (Pali, Jodhpur, Barmer districts), and DISAPPEARS into the RANN OF KUTCH marshlands (Gujarat) — never reaches the sea. Seasonal/ephemeral flow — heavy during monsoon, dry most of the year. Other Thar desert rivers: GHAGGAR (proposed ancient Saraswati river), Krishnavati, Jojari, Bandi. Sambhar Lake (Raj) is India''s largest inland saline lake — tributaries Mendha, Kharian, Rupangarh drain into it but Luni doesn''t touch Sambhar.', 'HARD', 'Geography', 'India - Peninsular River System', 'GEO_IND_RIVER_PEN', '[{"option_text": "Gulf of Khambhat", "is_correct": false}, {"option_text": "Rann of Kutch (disappears into the marshlands)", "is_correct": true}, {"option_text": "Arabian Sea near Porbandar", "is_correct": false}, {"option_text": "Sambhar Lake", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3e7db550-86d5-5669-9c56-7b49faaa5a38', 'Match each PENINSULAR river to its ORIGIN: (1) Krishna – (2) Godavari – (3) Cauvery – (4) Narmada', NULL, 'Peninsular river sources: KRISHNA → Mahabaleshwar (Maharashtra, Western Ghats, ~1337m); GODAVARI → Triyambakeshwar (Nashik district, Maharashtra, WG, ~1067m); CAUVERY → Talakaveri in Brahmagiri Hills (Kodagu, Karnataka, WG, ~1341m); NARMADA → Amarkantak Plateau (Anuppur district, MP, where Vindhya meets Satpura and Maikal Hills); TAPI → Multai (Betul district, MP, Satpura Hills); MAHANADI → Sihawa (Dhamtari, Chhattisgarh); SABARMATI → Aravalli (Udaipur, Raj); LUNI → Pushkar Valley (Ajmer, Raj). Practice with maps — source identification is a staple exam pattern.', 'HARD', 'Geography', 'India - Peninsular River System', 'GEO_IND_RIVER_PEN', '[{"option_text": "(1) Triyambakeshwar (2) Mahabaleshwar (3) Talakaveri (4) Amarkantak", "is_correct": false}, {"option_text": "(1) Mahabaleshwar (2) Triyambakeshwar (3) Talakaveri/Brahmagiri (4) Amarkantak", "is_correct": true}, {"option_text": "(1) Amarkantak (2) Triyambakeshwar (3) Multai (4) Mahabaleshwar", "is_correct": false}, {"option_text": "(1) Sihawa (2) Multai (3) Brahmagiri (4) Triyambakeshwar", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e536670d-1b2b-557b-b123-1aa29f20d2f8', 'Which of the following pairs a WARM ocean current with its ocean correctly?', NULL, 'The Kuroshio Current (Japanese for ''Black Stream'') is a warm current flowing north along the east coast of Japan in the NORTH PACIFIC — the Pacific analogue of the Gulf Stream. Distractors: Gulf Stream is in the North ATLANTIC (not Pacific); Benguela is a COLD current along South Africa in the South ATLANTIC (not North); Humboldt/Peru Current is a COLD current along South America in the PACIFIC (not Indian). Memorising the big 10-12 ocean currents by name, ocean, and temperature is a high-ROI Geography drill.', 'EASY', 'Geography', 'Oceanography — Currents & Tides', 'GEO_OCEAN_CURRENTS', '[{"option_text": "Gulf Stream — North Pacific Ocean", "is_correct": false}, {"option_text": "Kuroshio Current — North Pacific Ocean", "is_correct": true}, {"option_text": "Benguela Current — North Atlantic Ocean", "is_correct": false}, {"option_text": "Humboldt Current — Indian Ocean", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d031519e-76b7-5f6c-8c00-e3210e50e3e7', 'The Coriolis effect — arising from Earth''s rotation — deflects ocean currents and wind patterns:', NULL, 'Coriolis deflection: RIGHT in the Northern Hemisphere, LEFT in the Southern Hemisphere. This is why gyres (large circular current systems) rotate CLOCKWISE in the N Hemisphere (North Atlantic, North Pacific) and ANTI-CLOCKWISE in the S Hemisphere (South Atlantic, South Pacific, Indian). This effect is stronger at higher latitudes and vanishes at the Equator (where the Coriolis parameter is zero). Useful mnemonic: ''Right-Northern'' — R-N.', 'EASY', 'Geography', 'Oceanography — Currents & Tides', 'GEO_OCEAN_CURRENTS', '[{"option_text": "To the LEFT in the Northern Hemisphere and to the RIGHT in the Southern Hemisphere", "is_correct": false}, {"option_text": "To the RIGHT in the Northern Hemisphere and to the LEFT in the Southern Hemisphere", "is_correct": true}, {"option_text": "To the right in both hemispheres", "is_correct": false}, {"option_text": "Toward the equator in both hemispheres", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d2f933d1-036a-56ea-9c5e-0cac128ed9a3', 'Which of the following is a COLD ocean current flowing along the western coast of South America, known for supporting one of the world''s most productive fisheries due to UPWELLING?', NULL, 'The Peru Current (also called the Humboldt Current, after Alexander von Humboldt) is a COLD current flowing north along the western coast of South America. Easterly trade winds push surface water offshore, triggering upwelling of nutrient-rich deep water — this supports anchovy, sardine, and tuna fisheries. Peru is historically one of the world''s top anchovy producers. During El Niño events, the upwelling weakens and the fishery collapses. Distractors: Brazil Current is a warm current on the EAST coast of South America; Falkland is cold but flows on the East (Atlantic) side too; Canary is off the West African coast.', 'MEDIUM', 'Geography', 'Oceanography — Currents & Tides', 'GEO_OCEAN_CURRENTS', '[{"option_text": "Brazil Current", "is_correct": false}, {"option_text": "Falkland (Malvinas) Current", "is_correct": false}, {"option_text": "Peru (Humboldt) Current", "is_correct": true}, {"option_text": "Canary Current", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('99658ed7-dd9c-5c37-95d6-e5bb2498b137', 'Which of the following regions is known as ''Grand Banks'' — one of the world''s richest fishing grounds — and what oceanographic feature explains its productivity?', NULL, 'The Grand Banks lies off the southeast coast of Newfoundland (Canada), where the warm Gulf Stream meets the cold LABRADOR Current. The temperature contrast creates nutrient mixing + plankton blooms that feed cod, halibut, haddock. The meeting also creates persistent fog (the 1912 Titanic struck an iceberg carried south by the Labrador Current in this zone). Peru supports a productive fishery from upwelling alone (option C), but it''s a different geographic region. Options A and D describe plausible-sounding but incorrect current-pairings.', 'MEDIUM', 'Geography', 'Oceanography — Currents & Tides', 'GEO_OCEAN_CURRENTS', '[{"option_text": "Off the coast of California; meeting of the Alaska and California currents", "is_correct": false}, {"option_text": "Off the coast of Newfoundland; confluence of the warm Gulf Stream and cold Labrador Current", "is_correct": true}, {"option_text": "Off the coast of Peru; Humboldt Current upwelling alone", "is_correct": false}, {"option_text": "Off the Great Australian Bight; meeting of the East Australian and West Australian currents", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('459b0378-7f71-5f9c-bd78-4a32bd5f08e2', 'Five major subtropical ocean gyres exist worldwide. Which of the following lists them CORRECTLY?', NULL, 'The five major subtropical gyres are: North Atlantic, South Atlantic, North Pacific, South Pacific, and Indian Ocean (note: only ONE gyre in the Indian Ocean since it''s bounded to the north by the Asian landmass — no North-Indian gyre as such). Arctic and Southern Oceans have their own circulation patterns but not the classical subtropical gyres. These gyres trap floating debris — the ''Great Pacific Garbage Patch'' forms in the North Pacific Gyre. Knowing the five by name is a Geography GK staple.', 'MEDIUM', 'Geography', 'Oceanography — Currents & Tides', 'GEO_OCEAN_CURRENTS', '[{"option_text": "North Atlantic, South Atlantic, North Pacific, South Pacific, Indian Ocean", "is_correct": true}, {"option_text": "North Atlantic, Arctic, North Pacific, South Pacific, Southern Ocean", "is_correct": false}, {"option_text": "Gulf of Mexico, Caribbean, Mediterranean, Red Sea, Indian Ocean", "is_correct": false}, {"option_text": "North Atlantic, North Pacific, Indian Ocean, Antarctic, Arctic", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('dcdde2ef-2f74-5031-9e24-2e7497631352', 'Match each cold current with the continent whose coast it flows along, and select the correct pairing:
(i) Labrador Current — North America (east coast)
(ii) California Current — North America (west coast)
(iii) Benguela Current — Africa (west coast)
(iv) West Australian Current — Australia (west coast)', NULL, 'ALL four pairings are correct. Cold currents typically flow from the poles towards the equator along WESTERN coasts of continents (with Labrador as an exception — it flows along the NE coast of N. America). Memorisation pattern: Labrador (NA east) + California (NA west) + Peru/Humboldt (SA west) + Benguela (Africa west) + Canary (Africa west, N. hemisphere) + West Australian (Australia west) + Oyashio (east Russia/NE Asia). Pairing them with ''western coast of continent'' gives students a rule rather than rote memorization.', 'HARD', 'Geography', 'Oceanography — Currents & Tides', 'GEO_OCEAN_CURRENTS', '[{"option_text": "Only (i) and (ii)", "is_correct": false}, {"option_text": "Only (i), (ii), and (iii)", "is_correct": false}, {"option_text": "All four (i), (ii), (iii), (iv)", "is_correct": true}, {"option_text": "Only (ii) and (iv)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0f696e04-a8de-5720-beb3-252af104907f', 'The thermohaline circulation — or ''global ocean conveyor belt'' — is driven primarily by variations in:', NULL, '''Thermo-'' (temperature) + ''haline'' (salt content) — the name directly tells you the drivers. Cold, salty water (denser) sinks in polar regions (especially the North Atlantic near Greenland and the Southern Ocean near Antarctica); warm, less-salty water flows to replace it at the surface. This creates a slow (~1000-year cycle) global circulation connecting all the oceans. Wind-driven currents are a DIFFERENT system — they mainly affect the upper ~400m. Tidal and volcanic forces produce local effects but don''t drive the global conveyor. Collapse of this system (e.g. from Arctic ice melt diluting N. Atlantic salinity) is a major climate-change concern.', 'HARD', 'Geography', 'Oceanography — Currents & Tides', 'GEO_OCEAN_CURRENTS', '[{"option_text": "Wind stress alone", "is_correct": false}, {"option_text": "Water temperature (thermo-) and salinity (-haline)", "is_correct": true}, {"option_text": "Tidal forces of the Moon and Sun", "is_correct": false}, {"option_text": "Submarine volcanic activity", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('77b8aad7-bbf2-5ff7-a899-eb78453ebf55', 'The ENGLISH CHANNEL — specifically the Dover Strait — has one of the highest TIDAL RANGES in the world. What oceanographic phenomenon primarily causes this?', NULL, 'Tidal range is amplified where coastal geometry FUNNELS water — the Bay of Fundy (Canada) has the world''s highest tidal range (~16m) for this reason; the English Channel narrowing into the Dover Strait similarly amplifies tides. As the tidal wave''s cross-sectional area shrinks, its amplitude rises to conserve energy. The North Atlantic Drift warms the British Isles but does NOT cause tides. No volcanic activity in the Channel. Coriolis affects the shape of gyres but is not the primary driver of tidal range.', 'MEDIUM', 'Geography', 'Oceanography — Currents & Tides', 'GEO_OCEAN_CURRENTS', '[{"option_text": "The North Atlantic Drift flowing across it at high speed", "is_correct": false}, {"option_text": "The funnel-shape of the Channel that amplifies tidal amplitudes as water is constrained laterally", "is_correct": true}, {"option_text": "Constant submarine volcanic activity beneath the Channel", "is_correct": false}, {"option_text": "The Coriolis effect alone at that latitude", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bd717fd0-b3ae-5224-a39b-c7c155d091d1', 'A SPRING TIDE — with the highest tidal range — occurs when:', NULL, 'Spring tides occur when the Sun, Earth, and Moon are roughly in a straight line — at NEW MOON (syzygy) and FULL MOON. The Sun''s tidal pull ADDS to the Moon''s → higher high tides and lower low tides → maximum tidal range. NEAP tides occur when Sun-Earth-Moon form a right angle (first/third quarter) → solar pull CANCELS part of lunar pull → minimum tidal range. ''Spring'' has nothing to do with the season; it refers to ''jumping up'' (Old English). Apogee is when the Moon is farthest — reduces tidal amplitude (vs perigee, when the Moon is closest, amplifying it — ''perigean spring tides'' are the highest of all).', 'EASY', 'Geography', 'Oceanography — Currents & Tides', 'GEO_OCEAN_CURRENTS', '[{"option_text": "The Sun, Earth, and Moon are in a right angle (first and third quarter)", "is_correct": false}, {"option_text": "The Sun, Earth, and Moon are in alignment (new moon or full moon)", "is_correct": true}, {"option_text": "The Moon is farthest from Earth (apogee)", "is_correct": false}, {"option_text": "Only during the spring equinox (20 March)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('45c68948-260a-59b0-925d-2fdfc30353b1', 'The Sargasso Sea — a unique area of the North Atlantic bounded by CURRENTS (not by land) — is enclosed by:', NULL, 'The Sargasso Sea is bounded entirely by the four currents that make up the North Atlantic Gyre: Gulf Stream (west), North Atlantic Current (north), Canary Current (east), and North Equatorial Current (south). It''s famous for: (i) floating Sargassum seaweed (its namesake); (ii) the spawning ground of Atlantic and European eels — they migrate thousands of km to spawn here; (iii) being the sea without a shore. Option B, C, D list currents from different gyres. Worth memorising as Geography''s prime example of a sea defined by currents alone.', 'HARD', 'Geography', 'Oceanography — Currents & Tides', 'GEO_OCEAN_CURRENTS', '[{"option_text": "The Gulf Stream, North Atlantic Current, Canary Current, and North Equatorial Current", "is_correct": true}, {"option_text": "The Gulf Stream and Labrador Current only", "is_correct": false}, {"option_text": "The Kuroshio and California Currents", "is_correct": false}, {"option_text": "The Agulhas and Benguela Currents", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1175ae5a-ed16-5a9c-927a-ddbf56b6d547', 'UPWELLING zones — where deep, cold, nutrient-rich water rises to the surface — typically occur along:', NULL, 'Coastal upwelling occurs along the WESTERN coasts of continents in the trade-wind belt — Peru, California, Northwest Africa (Canary), Southwest Africa (Benguela), Western Australia. Trade winds (blowing equatorward along these coasts) combined with Ekman transport move surface water offshore, allowing deep cold water to replace it. These become exceptional fisheries and — less happily — are also regions of strong climate variability (El Niño, for instance, disrupts Peruvian upwelling). There ARE polar-ocean upwellings (Southern Ocean), but the classical coastal-upwelling pattern is the trade-wind-belt western-continent pattern.', 'HARD', 'Geography', 'Oceanography — Currents & Tides', 'GEO_OCEAN_CURRENTS', '[{"option_text": "EASTERN coasts of continents in the trade-wind belt", "is_correct": false}, {"option_text": "WESTERN coasts of continents where trade winds push surface water offshore", "is_correct": true}, {"option_text": "Middle of open oceans, far from any coast", "is_correct": false}, {"option_text": "Polar coasts of Antarctica and Greenland only", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b7501455-4be4-52b2-b080-4b0904c8c35d', 'El Niño — the periodic warming of the central/eastern tropical Pacific — DISRUPTS which ocean current, with major fisheries consequences?', NULL, 'El Niño weakens the trade winds that normally drive upwelling along the Peru coast. The Peru/Humboldt Current — usually cold and nutrient-rich — is overlaid by a warm layer, suppressing upwelling and collapsing the anchovy fishery. The name ''El Niño'' (''the boy child'' in Spanish, referring to the Christ child) comes from Peruvian fishermen who noticed the warming usually peaked around Christmas. ''La Niña'' is the opposite — intensified cold upwelling. Kuroshio, Agulhas, and North Atlantic Drift operate in different basins and aren''t the primary El Niño target (though teleconnections exist — e.g. Indian monsoon variability).', 'MEDIUM', 'Geography', 'Oceanography — Currents & Tides', 'GEO_OCEAN_CURRENTS', '[{"option_text": "Kuroshio Current", "is_correct": false}, {"option_text": "Peru (Humboldt) Current", "is_correct": true}, {"option_text": "Agulhas Current", "is_correct": false}, {"option_text": "North Atlantic Drift", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('22b3d21c-4b94-548d-9985-eaf39eb9835a', 'Which of the following warm-water current systems is primarily responsible for the comparatively MILD winters of Northwestern Europe (compared with regions at the same latitude in North America)?', NULL, 'The Gulf Stream carries warm tropical water northward from the Gulf of Mexico; at around 40°N it becomes the North Atlantic Drift/Current, which warms air masses reaching Western Europe. This is why Britain (latitude ~55°N) has winters comparable to much milder latitudes in North America. Labrador (same latitude, eastern Canada) has a frigid winter due to cold Labrador Current. The Kuroshio warms Japan; East Australian warms NZ''s east coast; Agulhas warms SE Africa — all parallel climate effects on their respective continents.', 'EASY', 'Geography', 'Oceanography — Currents & Tides', 'GEO_OCEAN_CURRENTS', '[{"option_text": "Gulf Stream and its extension — the North Atlantic Drift (Current)", "is_correct": true}, {"option_text": "Kuroshio Current", "is_correct": false}, {"option_text": "East Australian Current", "is_correct": false}, {"option_text": "Agulhas Current", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('29b219a9-6190-5555-8ef8-e14c375f07c3', 'Which of the following is INCORRECT about ocean tides?', NULL, 'Statement C is INCORRECT — the tidal bulge does NOT keep perfect alignment with the Moon. Earth rotates faster than the tidal wave can travel (due to continents, friction, ocean depth), causing the bulge to lead the Moon by roughly 12° — this is why high tide often occurs a bit AFTER the Moon''s highest point in the sky. Statements A, B, D are all correct: Sun''s tidal force is ~46% of the Moon''s (this is why spring tides are only ~20% higher than average, not doubled); semi-diurnal tides have a period of 24h 50min = lunar day; Bay of Fundy records 16.3m range — world''s highest.', 'HARD', 'Geography', 'Oceanography — Currents & Tides', 'GEO_OCEAN_CURRENTS', '[{"option_text": "The Sun''s tidal influence is about 46% as strong as the Moon''s", "is_correct": false}, {"option_text": "Most coasts experience TWO high tides and two low tides approximately every 24 hours 50 minutes (semi-diurnal tides)", "is_correct": false}, {"option_text": "The tidal wave moves at exactly the same speed as the Earth''s rotation, maintaining alignment with the Moon at all times", "is_correct": true}, {"option_text": "The Bay of Fundy in Canada records the world''s highest tidal range (~16 m)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('885dc7ce-4584-5da8-97be-c0bd1da93f24', 'The Agulhas Current — flowing along the east coast of southern Africa — is notable in oceanography because it:', NULL, 'The Agulhas Current is a WARM, fast-flowing current along the southeast coast of Africa. It''s famous for ''Agulhas retroflection'' — near the southern tip of Africa, it curves sharply back eastward (rather than continuing into the South Atlantic), and occasionally sheds large eddies called ''Agulhas rings'' that DO cross into the South Atlantic, carrying warm tropical water that contributes to the Atlantic Meridional Overturning Circulation. This is an active research topic for climate models. Options A, C, D are fiction.', 'HARD', 'Geography', 'Oceanography — Currents & Tides', 'GEO_OCEAN_CURRENTS', '[{"option_text": "Is the coldest current in the world", "is_correct": false}, {"option_text": "Retroflects (curves back on itself) near the southern tip of Africa, occasionally shedding warm-water ''Agulhas rings'' into the South Atlantic", "is_correct": true}, {"option_text": "Flows from Antarctica to the Equator continuously without interruption", "is_correct": false}, {"option_text": "Is responsible for the ice cover over Greenland", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cd041205-d9dc-5a5d-9f63-bfb3e64252d3', 'Which of the following is the largest planet in our solar system?', NULL, 'Jupiter is the largest planet — its mass (~1.9×10²⁷ kg) is more than twice the mass of all other planets in the solar system combined. Its diameter (~140,000 km) is about 11 times Earth''s. Saturn is second-largest. Neptune is smaller than both but denser than Saturn. Earth is the fifth-largest planet.', 'EASY', 'Geography', 'Solar System & Planets', 'GEO_SOLAR', '[{"option_text": "Saturn", "is_correct": false}, {"option_text": "Jupiter", "is_correct": true}, {"option_text": "Neptune", "is_correct": false}, {"option_text": "Earth", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('69223bd9-0498-5a3c-940d-8b65f62cb8b1', 'Which planet is known as the ''Morning Star'' and the ''Evening Star''?', NULL, 'Venus is visible shortly before sunrise (Morning Star) or shortly after sunset (Evening Star) because its orbit lies INSIDE Earth''s — meaning it can never be seen at midnight. Its thick sulfuric-acid clouds reflect ~70% of sunlight, making it the 2nd-brightest natural object in the night sky after the Moon. Mercury also has ''Morning Star''/''Evening Star'' visibility but is much dimmer and harder to spot.', 'EASY', 'Geography', 'Solar System & Planets', 'GEO_SOLAR', '[{"option_text": "Mercury", "is_correct": false}, {"option_text": "Venus", "is_correct": true}, {"option_text": "Mars", "is_correct": false}, {"option_text": "Jupiter", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f3161ed2-4091-590f-94b1-2a1a630618b6', 'Which planet has the most number of moons (as of 2024)?', NULL, 'As of 2024, Saturn has ~146 confirmed moons (after a 2023 announcement added 62 new moons), surpassing Jupiter''s ~95. Titan is Saturn''s largest moon (larger than the planet Mercury) and has a thick atmosphere. Jupiter''s Galilean moons (Io, Europa, Ganymede, Callisto) are the most famous. Counts change over time as new small moons are discovered; exam answers use current NASA-certified counts.', 'HARD', 'Geography', 'Solar System & Planets', 'GEO_SOLAR', '[{"option_text": "Jupiter (~95 moons)", "is_correct": false}, {"option_text": "Saturn (~146 moons)", "is_correct": true}, {"option_text": "Uranus (~27 moons)", "is_correct": false}, {"option_text": "Neptune (~14 moons)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a00a28b1-7716-58b4-8a48-82d48b597c73', 'Why is Mercury the hottest planet during the day but not on average?', NULL, 'Mercury has virtually NO atmosphere (exosphere only). So during the day, its surface reaches ~430°C (closer to Sun). At night, without any atmosphere to retain heat, temperatures plunge to ~−180°C. VENUS, despite being farther from the Sun, is the HOTTEST planet on average (surface ~465°C) due to its extreme CO₂ greenhouse effect. Mercury has very slow rotation (1 Mercury-day = 59 Earth-days) exposing each side to extreme temperatures.', 'MEDIUM', 'Geography', 'Solar System & Planets', 'GEO_SOLAR', '[{"option_text": "Because it rotates very slowly, but has no atmosphere to retain heat at night", "is_correct": true}, {"option_text": "Because its orbit is elliptical and it is sometimes very far from the Sun", "is_correct": false}, {"option_text": "Because it has thick clouds that reflect heat away", "is_correct": false}, {"option_text": "Because it is made of ice", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cafbf8e6-8fd7-5731-97a6-c181fd51544d', 'Which of these planets does NOT have a ring system?', NULL, 'All four GAS/ICE GIANTS (Jupiter, Saturn, Uranus, Neptune) have ring systems. Saturn''s rings are the most visible and extensive (made mostly of water ice). Jupiter, Uranus, and Neptune have fainter rings. Earth — a terrestrial planet — has NO rings. Among dwarf planets, Haumea and the centaur Chariklo also have confirmed rings. Mars and Venus have no rings either.', 'MEDIUM', 'Geography', 'Solar System & Planets', 'GEO_SOLAR', '[{"option_text": "Saturn", "is_correct": false}, {"option_text": "Jupiter", "is_correct": false}, {"option_text": "Earth", "is_correct": true}, {"option_text": "Uranus", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('15e9a532-a865-5741-a7ce-b0a6652c3e94', 'When and why was Pluto reclassified as a ''dwarf planet''?', NULL, 'In August 2006, the International Astronomical Union (IAU) established three criteria for PLANET status: (1) orbits the Sun; (2) sufficient mass for hydrostatic equilibrium (spherical); (3) has cleared the neighborhood around its orbit. Pluto satisfies (1) and (2) but NOT (3) — its orbit is dominated by other Kuiper Belt objects, some larger than Pluto (e.g., Eris). It was thus reclassified as a ''dwarf planet''. Other dwarf planets: Eris, Haumea, Makemake, Ceres.', 'MEDIUM', 'Geography', 'Solar System & Planets', 'GEO_SOLAR', '[{"option_text": "In 2006 by IAU, because it failed to clear its orbital neighborhood of other objects", "is_correct": true}, {"option_text": "In 1990 by NASA, because Voyager-2 found no atmosphere", "is_correct": false}, {"option_text": "In 2012 by UN Space Committee, because of its small size alone", "is_correct": false}, {"option_text": "In 2019 by Hubble Space Telescope, because of its elliptical orbit", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1dd4f59b-6681-5f68-802b-1f608a04d99c', 'Which planet has a day (rotation) longer than its year (revolution)?', NULL, 'Venus''s rotation period (sidereal day) is ~243 Earth-days, while its orbital period (year) is ~225 Earth-days. So a VENUSIAN DAY is LONGER than a VENUSIAN YEAR! Venus also rotates RETROGRADE (opposite to most planets) — meaning the Sun rises in the west and sets in the east on Venus. Mercury has a day of 59 Earth-days and year of 88 Earth-days (day < year).', 'HARD', 'Geography', 'Solar System & Planets', 'GEO_SOLAR', '[{"option_text": "Mercury", "is_correct": false}, {"option_text": "Venus", "is_correct": true}, {"option_text": "Mars", "is_correct": false}, {"option_text": "Saturn", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7d767c79-ae03-5a3c-a83a-abfe16a9b058', 'The asteroid belt in our solar system lies between which two planets?', NULL, 'The main ASTEROID BELT lies between the orbits of Mars and Jupiter, at ~2.2–3.2 AU from the Sun. It contains millions of rocky bodies, the largest being Ceres (a dwarf planet). Jupiter''s gravity prevented material in this region from coalescing into a planet. The KUIPER BELT (beyond Neptune) is a separate belt of icy bodies and the OORT CLOUD is a spherical shell of comets far beyond.', 'EASY', 'Geography', 'Solar System & Planets', 'GEO_SOLAR', '[{"option_text": "Earth and Mars", "is_correct": false}, {"option_text": "Mars and Jupiter", "is_correct": true}, {"option_text": "Jupiter and Saturn", "is_correct": false}, {"option_text": "Saturn and Uranus", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('229cadc5-44b3-5d18-a39e-aa0c7c0e87ec', 'Which planet tilts on its side (axial tilt ~98°), causing extreme seasonal variations?', NULL, 'Uranus''s axial tilt is ~98°, meaning its rotation axis is nearly in the plane of its orbit. As a result, each pole receives ~42 years of continuous sunlight followed by ~42 years of darkness — extreme seasons. Hypothesis: a massive early collision may have knocked Uranus on its side. Earth''s tilt is 23.5°; Mars 25°; Saturn 27°; Neptune 28°.', 'MEDIUM', 'Geography', 'Solar System & Planets', 'GEO_SOLAR', '[{"option_text": "Mars", "is_correct": false}, {"option_text": "Neptune", "is_correct": false}, {"option_text": "Uranus", "is_correct": true}, {"option_text": "Saturn", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6c1e024c-1474-52b6-8498-0f5d6b707e5c', 'Gautama Buddha was born at Lumbini in which year (Buddhist tradition)?', NULL, 'Buddhist tradition places Buddha''s birth at 623 BCE at Lumbini (in present-day Nepal) — commemorated internationally as ''Vaishakha Purnima'' or Buddha Purnima. Scholarly estimates vary (some say 563 BCE based on other dating methods). 483 BCE is typically cited as his year of MAHAPARINIRVANA (death) at Kushinagar. The NCERT textbook variant often uses 563 BCE; ISI/ASI and Buddhist sources use 623 BCE.', 'HARD', 'History', 'Buddhism', 'HIS_BUDDHISM', '[{"option_text": "623 BCE", "is_correct": true}, {"option_text": "483 BCE", "is_correct": false}, {"option_text": "563 BCE", "is_correct": false}, {"option_text": "723 BCE", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8a87e626-38dc-5740-9cd8-c9483cc7fb98', 'Where did Gautama Buddha attain enlightenment (Bodhi)?', NULL, 'The Buddha attained enlightenment at BODH GAYA (Bihar) under the Bodhi Tree (a Peepal/Ficus religiosa) at age 35, after 49 days of meditation. Lumbini (Nepal) = birth. Sarnath (UP, near Varanasi) = first sermon (''Dharmachakra Pravartana''). Kushinagar (UP) = death/Mahaparinirvana. These FOUR sites are the main Buddhist pilgrimage circuit (''Char Dham'' of Buddhism).', 'EASY', 'History', 'Buddhism', 'HIS_BUDDHISM', '[{"option_text": "Sarnath", "is_correct": false}, {"option_text": "Bodh Gaya", "is_correct": true}, {"option_text": "Lumbini", "is_correct": false}, {"option_text": "Kushinagar", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('129930ea-9ce9-5f7a-b763-6da86f821d56', 'The Buddha delivered his first sermon at Sarnath. In Buddhist terminology, this event is called:', NULL, 'DHARMACHAKRA PRAVARTANA = ''Setting the Wheel of Dharma in Motion''. The Buddha''s first sermon at the Deer Park (Sarnath) outlined the Four Noble Truths to 5 disciples. PRAVRAJYA = act of going forth (renouncing household life). SAMBODHI/BODHI = enlightenment at Bodh Gaya. MAHAPARINIRVANA = final death at Kushinagar. The Dhamek Stupa at Sarnath marks this event.', 'MEDIUM', 'History', 'Buddhism', 'HIS_BUDDHISM', '[{"option_text": "Mahaparinirvana", "is_correct": false}, {"option_text": "Dharmachakra Pravartana", "is_correct": true}, {"option_text": "Pravrajya", "is_correct": false}, {"option_text": "Sambodhi", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('09f00b6e-c8f5-5869-b54a-20e513ffc745', 'Which of the following is NOT one of the Four Noble Truths?', NULL, 'The FOUR NOBLE TRUTHS (Arya-satyas) are: (1) DUKKHA — suffering exists; (2) SAMUDAYA — cause is craving/tanha; (3) NIRODHA — cessation is possible by extinguishing craving; (4) MAGGA/Marga — the Eightfold Path leads to cessation. KARMA is a general Indian concept of moral causation shared with Hinduism/Jainism, NOT a Noble Truth itself. The Eightfold Path (Magga) has 8 components: right view, intention, speech, action, livelihood, effort, mindfulness, concentration.', 'MEDIUM', 'History', 'Buddhism', 'HIS_BUDDHISM', '[{"option_text": "Dukkha — life is suffering", "is_correct": false}, {"option_text": "Samudaya — cause of suffering is craving (tanha)", "is_correct": false}, {"option_text": "Karma — one reaps what one sows", "is_correct": true}, {"option_text": "Nirodha — cessation of suffering is possible", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c2ea9879-3408-581e-a366-22df82745b6d', 'The Third Buddhist Council was held during the reign of which emperor?', NULL, 'FOUR Buddhist Councils: (1) First — 483 BCE at Rajgriha under Ajatashatru, presided by Mahakassapa; (2) Second — 383 BCE at Vaishali under Kalashoka; (3) THIRD — 250 BCE at Pataliputra under ASHOKA, presided by Moggaliputta Tissa (led to codification of Tripitaka and Buddhist missions abroad); (4) Fourth — ~72 CE at Kundalvana (Kashmir) under Kanishka, marked the Mahayana-Hinayana split. Fifth council (19th c.) and Sixth (1954 Yangon) are modern.', 'MEDIUM', 'History', 'Buddhism', 'HIS_BUDDHISM', '[{"option_text": "Ajatashatru", "is_correct": false}, {"option_text": "Kalashoka", "is_correct": false}, {"option_text": "Ashoka", "is_correct": true}, {"option_text": "Kanishka", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('45affa7a-bda9-538e-8cff-35eb4578f287', 'Which of the following are the ''Three Jewels'' (Triratna) of Buddhism?', NULL, 'The Triratna (Three Jewels / Three Refuges) of Buddhism are: (1) BUDDHA — the enlightened one; (2) DHAMMA/DHARMA — his teachings; (3) SANGHA — the community of monks and nuns. A Buddhist is formally one who takes refuge in all three: ''Buddham saranam gacchami, Dhammam saranam gacchami, Sangham saranam gacchami''. Ashoka adopted this formula in many of his rock edicts.', 'EASY', 'History', 'Buddhism', 'HIS_BUDDHISM', '[{"option_text": "Truth, Non-violence, Compassion", "is_correct": false}, {"option_text": "Buddha, Dhamma, Sangha", "is_correct": true}, {"option_text": "Brahma, Vishnu, Shiva", "is_correct": false}, {"option_text": "Body, Mind, Soul", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('40bd3b2f-4b94-5e64-86d7-53d5ffd676f7', 'Which Buddhist school believed in the Bodhisattva ideal and the worship of Buddha as a deity, and spread to China, Japan, and Korea?', NULL, 'MAHAYANA (''Greater Vehicle''), which emerged in the 1st c. CE (crystallized at Kanishka''s 4th Council), emphasises the Bodhisattva ideal (compassionate enlightened beings postponing own Nirvana to save others) and treats Buddha as divine. Spread to China, Japan, Korea, Vietnam. THERAVADA (formerly ''Hinayana'') is older, more conservative, treats Buddha as a human teacher, uses Pali canon — widespread in Sri Lanka, Thailand, Myanmar. VAJRAYANA (Tibetan/Tantric) is a sub-school of Mahayana. ZEN is a Japanese Mahayana school.', 'MEDIUM', 'History', 'Buddhism', 'HIS_BUDDHISM', '[{"option_text": "Theravada (Hinayana)", "is_correct": false}, {"option_text": "Mahayana", "is_correct": true}, {"option_text": "Vajrayana", "is_correct": false}, {"option_text": "Zen", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7284b4e8-a4c4-5271-9af9-5d2711f0e66b', 'The ''Tripitaka'' — the scriptural canon of Buddhism — consists of three ''baskets''. Which of the following is NOT one of them?', NULL, 'The TRIPITAKA (Pali: Tipitaka) has THREE ''baskets'': (1) VINAYA PITAKA — monastic discipline and rules for monks/nuns; (2) SUTTA PITAKA — the Buddha''s discourses; (3) ABHIDHAMMA PITAKA — systematic philosophical/psychological analysis. ''Avadana'' literature (biographical stories of past lives) DOES exist in Buddhist texts but it is part of the Sutta Pitaka''s Khuddaka Nikaya — NOT a separate pitaka.', 'HARD', 'History', 'Buddhism', 'HIS_BUDDHISM', '[{"option_text": "Vinaya Pitaka (monastic discipline)", "is_correct": false}, {"option_text": "Sutta Pitaka (discourses of the Buddha)", "is_correct": false}, {"option_text": "Abhidhamma Pitaka (philosophical analysis)", "is_correct": false}, {"option_text": "Avadana Pitaka (biographical narratives)", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('647e8d78-3417-5e34-b2f7-5950a8cc4fe2', 'Vasco da Gama landed at which Indian port in May 1498, establishing the first direct sea route from Europe to India?', NULL, 'Vasco da Gama reached CALICUT on 20 May 1498 and was received by the local ruler Zamorin (Samoothiri Raja). Calicut was the preeminent Malabar spice-trade port at the time. Cochin became a later Portuguese stronghold (after Zamorin''s hostility drove them south in 1500). Goa was captured much later (1510) under Albuquerque. Surat became a Mughal port the Portuguese — and later the English — used in the 17th century. The 1498 Calicut landfall is the canonical date that opens modern European–Indian history.', 'EASY', 'History', 'Advent of Europeans in India', 'HIS_EUROPEANS', '[{"option_text": "Cochin (Kochi)", "is_correct": false}, {"option_text": "Calicut (Kozhikode)", "is_correct": true}, {"option_text": "Goa", "is_correct": false}, {"option_text": "Surat", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ba50dce2-754f-5ff7-95e4-f2a6d84de649', 'Who among the following is credited with formulating the ''Blue Water Policy'' (Cartaze system) that aimed at establishing Portuguese control of the Indian Ocean through a passport-permit regime for non-Portuguese ships?', NULL, 'Francisco de Almeida (Viceroy 1505-09) articulated the ''Blue Water Policy'' (Portuguese: ''Política do Mar Azul'') — Portugal''s strength lay in sea-power, not in holding territory on land; command of the sea would let them monopolise the spice trade. The complementary Cartaze system required non-Portuguese merchant ships to buy Portuguese-issued permits to trade in the Indian Ocean. Albuquerque, his successor (1509-15), pivoted to ''blue-water-plus-strategic-land-bases'' — capturing Goa (1510), Malacca (1511), Hormuz (1515). Vasco da Gama was the navigator, not an administrator. Nino da Cunha moved the Portuguese capital from Cochin to Goa (1530).', 'HARD', 'History', 'Advent of Europeans in India', 'HIS_EUROPEANS', '[{"option_text": "Vasco da Gama", "is_correct": false}, {"option_text": "Francisco de Almeida", "is_correct": true}, {"option_text": "Afonso de Albuquerque", "is_correct": false}, {"option_text": "Nino da Cunha", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7449f280-69a2-500e-ae56-6878e3848329', 'Arrange the following European trading companies in India in the correct CHRONOLOGICAL order of their FOUNDING (not of their arrival in India):
(i) French East India Company (La Compagnie des Indes orientales)
(ii) English East India Company
(iii) Dutch East India Company (VOC)
(iv) Portuguese Estado da Índia', NULL, 'Correct order: (iv) Portuguese Estado da Índia — 1505 (Almeida appointed first Viceroy); (ii) English East India Company — 31 Dec 1600 (Queen Elizabeth I''s charter); (iii) Dutch East India Company (VOC) — 20 Mar 1602 (Dutch States-General charter, only 15 months after the English); (i) French East India Company — 1664 (under Jean-Baptiste Colbert, Louis XIV''s finance minister). Despite Dutch and English founding dates being only ~15 months apart, English is first. The Portuguese didn''t have a joint-stock company structure — the ''Estado da Índia'' was a royal government apparatus.', 'HARD', 'History', 'Advent of Europeans in India', 'HIS_EUROPEANS', '[{"option_text": "(iv) → (ii) → (iii) → (i)", "is_correct": true}, {"option_text": "(iv) → (iii) → (ii) → (i)", "is_correct": false}, {"option_text": "(ii) → (iii) → (iv) → (i)", "is_correct": false}, {"option_text": "(iii) → (ii) → (iv) → (i)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('67812d17-8efa-5a5a-8062-6f898e6f6757', 'Sir Thomas Roe''s diplomatic mission (1615-18) to secure trading rights for the English East India Company was sent to the court of which Mughal Emperor?', NULL, 'Sir Thomas Roe was dispatched by James I of England to the court of JAHANGIR (r. 1605-27) at Ajmer and later Agra. Roe secured a royal firman permitting English factories at Surat and other Mughal ports — a diplomatic coup. His memoirs (published as ''The Embassy of Sir Thomas Roe to India'') remain a primary source for Jahangir''s court. Akbar died in 1605, before the mission; Shah Jahan reigned 1628-58; Aurangzeb 1658-1707 — Roe met neither. (An EARLIER English envoy, William Hawkins, had been at Jahangir''s court 1609-11 without securing firm concessions.)', 'MEDIUM', 'History', 'Advent of Europeans in India', 'HIS_EUROPEANS', '[{"option_text": "Akbar", "is_correct": false}, {"option_text": "Jahangir", "is_correct": true}, {"option_text": "Shah Jahan", "is_correct": false}, {"option_text": "Aurangzeb", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('48b5093c-33f3-51db-b204-b08631058a16', 'The three Carnatic Wars (1744-48, 1749-54, 1758-63) decided the colonial fate of South India. Which war effectively settled the Anglo-French struggle in India, with the decisive Battle of Wandiwash?', NULL, 'The THIRD Carnatic War (1758-63) — a sideshow to the global Seven Years'' War — was the decisive British victory. At Wandiwash (22 Jan 1760) Eyre Coote crushed the French under Comte de Lally. The subsequent Treaty of Paris (1763) restored French factories to France but STRIPPED them of the right to fortify — thereby ending French ambitions to compete as a political power in India. The First Carnatic War saw French gains (capture of Madras) later returned via the Treaty of Aix-la-Chapelle; the Second was inconclusive. Option D refers to the Second Mysore War (1780-84) — different theatre.', 'HARD', 'History', 'Advent of Europeans in India', 'HIS_EUROPEANS', '[{"option_text": "First Carnatic War (1744-48), ended by the Treaty of Aix-la-Chapelle", "is_correct": false}, {"option_text": "Second Carnatic War (1749-54), ended by the Treaty of Pondicherry", "is_correct": false}, {"option_text": "Third Carnatic War (1758-63), ended by the Treaty of Paris", "is_correct": true}, {"option_text": "A fourth war fought separately in 1780-84", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0953438e-2217-52dd-84cd-88cec203ab1b', 'The Battle of Plassey (23 June 1757) was fought between the forces of Robert Clive and:', NULL, 'Plassey (Palashi in Bengali) pitted Clive against SIRAJ-ud-DAULA, Nawab of Bengal (who had captured Calcutta from the British in 1756, causing the ''Black Hole'' incident). Clive''s victory — aided by Mir Jafar''s betrayal of Siraj — was the foundational moment of British territorial power in India. Mir Qasim was a later Nawab (installed then deposed by the British) — he lost the Battle of Buxar in 1764. Shuja-ud-Daula was Awadh''s Nawab, also defeated at Buxar. Haider Ali of Mysore was an entirely different theatre (Mysore Wars 1767-1799).', 'EASY', 'History', 'Advent of Europeans in India', 'HIS_EUROPEANS', '[{"option_text": "Shuja-ud-Daula, Nawab of Awadh", "is_correct": false}, {"option_text": "Siraj-ud-Daula, Nawab of Bengal", "is_correct": true}, {"option_text": "Mir Qasim, Nawab of Bengal", "is_correct": false}, {"option_text": "Haider Ali of Mysore", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('889dcf43-9fc0-56f8-b20c-5cecedb8ed2d', 'The Treaty of Allahabad (1765), signed between Robert Clive and the Mughal Emperor Shah Alam II, transferred which crucial right to the British East India Company?', NULL, 'The Treaty of Allahabad (signed after British victory at Buxar 1764) granted the Company the DIWANI of Bengal, Bihar, and Orissa — the right to collect land revenue — in exchange for an annual payment of 26 lakh rupees to the emperor. This marked the TRANSITION of the Company from ''traders'' to a ''territorial power'' with a steady revenue source (₹30+ million annually by the 1770s). The Nizamat (criminal and police administration) was initially left with the Nawab of Bengal but became a puppet office — Warren Hastings formally combined Diwani + Nizamat under Company control in 1772. Options C and D describe events that never happened under this treaty.', 'MEDIUM', 'History', 'Advent of Europeans in India', 'HIS_EUROPEANS', '[{"option_text": "The office of Nizamat (criminal administration) of Bengal", "is_correct": false}, {"option_text": "The Diwani (revenue collection rights) of Bengal, Bihar, and Orissa", "is_correct": true}, {"option_text": "Ownership of the city of Delhi", "is_correct": false}, {"option_text": "Permission to mint coins in the name of the British Crown", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a9a18769-5df7-53ba-8e62-922a7d8e9b53', 'Which of the following European powers established its first Indian factory at TRANQUEBAR (on the Coromandel coast) in 1620 and later sold all its Indian possessions to the British in 1845?', NULL, 'The DANISH East India Company (Dansk Ostindisk Kompagni, 1616) operated from Tranquebar (Tharangambadi, Tamil Nadu) and Serampore (West Bengal). Denmark''s Indian presence was always modest — never a major political force — and after financial troubles, Denmark sold Tranquebar and Serampore to the British in 1845. The Dutch had factories further south (Nagapattinam, Pulicat) and dominated Cochin — they lost most holdings to the British by the 1780s-90s. The Swedish East India Company (1731) traded with Canton but didn''t establish lasting Indian factories. The French had Pondicherry, Chandernagore, Mahé, Karaikal, Yanam — all retained until 1954 (de facto).', 'HARD', 'History', 'Advent of Europeans in India', 'HIS_EUROPEANS', '[{"option_text": "Dutch", "is_correct": false}, {"option_text": "Danish", "is_correct": true}, {"option_text": "Swedish", "is_correct": false}, {"option_text": "French", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('60acc83c-eb4d-53a5-83ec-c5546dc6080e', 'Joseph François Dupleix — who famously envisioned a French empire in India through intervention in local succession disputes — served as the Governor-General of which French Indian enclave?', NULL, 'Joseph François Dupleix was Governor-General of French India (1742-54), based at PONDICHERRY (Puducherry). He pioneered the strategy of training sepoys on European lines and backing local claimants to the Nawabi of Carnatic and the Nizamate of Hyderabad — a tactic Robert Clive later turned against him. Dupleix was eventually recalled to France in 1754 and died in 1763 in poverty and disgrace, ironic given his Indian ambitions. Chandernagore was a French factory but never their capital. Mahé was a minor French enclave. Surat was a Mughal/English port — never French.', 'MEDIUM', 'History', 'Advent of Europeans in India', 'HIS_EUROPEANS', '[{"option_text": "Chandernagore (Bengal)", "is_correct": false}, {"option_text": "Pondicherry", "is_correct": true}, {"option_text": "Mahé (Kerala coast)", "is_correct": false}, {"option_text": "Surat", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2dc749ca-da04-5e31-8f97-f0319513f850', 'The Battle of Colachel (1741) — a rare and decisive DEFEAT of a European colonial power by an Indian kingdom — was won by Maharaja Marthanda Varma of Travancore against which European power?', NULL, 'Colachel (31 July 1741) was fought between Travancore and the DUTCH East India Company. Marthanda Varma''s forces captured Dutch commander Captain Eustachius De Lannoy (who subsequently served as Travancore''s military chief — ''Valiya Kapitaan'' — and modernised its army). This battle is often highlighted in UPSC/state-PSC answer keys as the ''first European defeat by an Indian kingdom'' — though Portuguese defeats by local Zamorin forces had occurred earlier in the 16th century. After Colachel, Dutch power in the Malabar never recovered; by 1795 their last holdings fell to the British.', 'HARD', 'History', 'Advent of Europeans in India', 'HIS_EUROPEANS', '[{"option_text": "Portuguese", "is_correct": false}, {"option_text": "Dutch", "is_correct": true}, {"option_text": "French", "is_correct": false}, {"option_text": "British", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('32641a29-d2d7-53ba-a72a-1cfae30ac133', 'Bombay was transferred to the English East India Company in 1668 by which English monarch, having received the islands as part of the dowry of his Portuguese queen?', NULL, 'When Charles II of England married Catherine of Braganza (daughter of King John IV of Portugal) in 1661, the Portuguese dowry included Bombay (7 small islands). Charles II, finding the islands hard to administer, leased them to the EIC in 1668 for a nominal rent of £10 per year. The EIC rapidly developed Bombay as a fortified port, and by the late 17th century it had eclipsed Surat as the Company''s western headquarters. Elizabeth I died in 1603 — before the dowry event. James I was on the throne when Sir Thomas Roe went to Jahangir''s court but died in 1625. George III came much later (r. 1760-1820).', 'MEDIUM', 'History', 'Advent of Europeans in India', 'HIS_EUROPEANS', '[{"option_text": "Queen Elizabeth I", "is_correct": false}, {"option_text": "King James I", "is_correct": false}, {"option_text": "King Charles II", "is_correct": true}, {"option_text": "King George III", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('300702c0-1788-5407-b53c-4b0075db802b', 'Which of the following is the CORRECT chronological order of the establishment of EIC ''Presidency'' headquarters in India?
(i) Madras  (ii) Bombay  (iii) Calcutta  (iv) Surat', NULL, 'Correct order: (iv) SURAT was the first EIC factory (1613, after Thomas Best''s 1612 Swally battle) — served as the western headquarters initially. (i) MADRAS was founded 1639-40 when Francis Day obtained Madrasapatnam from the Vijayanagara viceroy — Fort St. George built there. (ii) BOMBAY was leased to EIC in 1668 (dowry from Charles II''s Portuguese marriage), displacing Surat as the western headquarters by 1687. (iii) CALCUTTA (Fort William) was established 1690 by Job Charnock. So: Surat → Madras → Bombay → Calcutta. Knowing the decade of each presidency is a high-ROI memorisation.', 'HARD', 'History', 'Advent of Europeans in India', 'HIS_EUROPEANS', '[{"option_text": "(iv) → (i) → (ii) → (iii)", "is_correct": true}, {"option_text": "(i) → (ii) → (iii) → (iv)", "is_correct": false}, {"option_text": "(iv) → (ii) → (i) → (iii)", "is_correct": false}, {"option_text": "(i) → (iv) → (ii) → (iii)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1be4a887-a3da-5e21-9cad-fbba602b63fa', 'Who was appointed as the FIRST Governor of Bengal under the Regulating Act of 1773, and subsequently became the first Governor-General of Bengal (with supervisory authority over Madras and Bombay)?', NULL, 'Warren Hastings was already Governor of Bengal when the Regulating Act 1773 elevated the Bengal governorship to ''Governor-General of Bengal'' — with authority to oversee (but not directly govern) Madras and Bombay presidencies. The post carried a 4-member council (initially hostile to him under Philip Francis). Hastings served 1773-85. Clive''s role was earlier — he was Governor of Bengal twice (1757-60, 1765-67) but predated the Regulating Act and never held the ''Governor-General'' title. Cornwallis (1786-93) succeeded Hastings and pushed the Permanent Settlement. Wellesley (1798-1805) pushed Subsidiary Alliances.', 'MEDIUM', 'History', 'Advent of Europeans in India', 'HIS_EUROPEANS', '[{"option_text": "Robert Clive", "is_correct": false}, {"option_text": "Warren Hastings", "is_correct": true}, {"option_text": "Lord Cornwallis", "is_correct": false}, {"option_text": "Lord Wellesley", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bc8755a0-3f49-574a-9923-934dcc9cc9ee', 'Afonso de Albuquerque — often called the ''founder of the Portuguese empire in the East'' — captured which three strategic cities during his governorship (1509-15)?', NULL, 'Albuquerque''s strategic trifecta: GOA (1510, from Bijapur — made Portugal''s Asian capital), MALACCA (1511, from the Malay Sultanate — controlling the Strait and spice route east), HORMUZ (1515, controlling the Persian Gulf trade). He tried and failed at Aden. Calicut was never conquered — only unsuccessfully besieged. Macau was acquired in 1557, decades after his death. Colombo came to Portuguese control later through negotiation with Kotte. Knowing GOA-MALACCA-HORMUZ as Albuquerque''s signature conquests is the canonical answer.', 'MEDIUM', 'History', 'Advent of Europeans in India', 'HIS_EUROPEANS', '[{"option_text": "Goa, Calicut, Colombo", "is_correct": false}, {"option_text": "Goa, Malacca, Hormuz", "is_correct": true}, {"option_text": "Bombay, Malacca, Macau", "is_correct": false}, {"option_text": "Cochin, Hormuz, Aden", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d6216af8-c673-55cf-9227-5b7918f53ffb', 'The Pitt''s India Act of 1784 established the Board of Control to oversee the EIC in London. This Board was chaired by which official of the British Government?', NULL, 'Pitt''s India Act (1784) created a DUAL system: the EIC retained commercial control, but political/military decisions came under a Board of Control composed of 6 Cabinet members, headed by a ''President of the Board of Control'' — a Cabinet-rank minister. This post, reorganised by the Government of India Act 1858 after the 1857 Revolt, became the ''Secretary of State for India'' reporting to Parliament. So answer B is correct. The PM did NOT directly chair the Board; the King had a ceremonial role but not operational chairmanship. The Archbishop has no role here — pure distractor.', 'HARD', 'History', 'Advent of Europeans in India', 'HIS_EUROPEANS', '[{"option_text": "The Prime Minister of Britain", "is_correct": false}, {"option_text": "A Cabinet Minister (later the Secretary of State for India)", "is_correct": true}, {"option_text": "The King personally", "is_correct": false}, {"option_text": "The Archbishop of Canterbury", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('180e9cdb-38b0-560a-a060-f3079a3b1aab', 'The Gupta Empire is often called the ''Golden Age'' of India. Who was its founder?', NULL, 'Sri Gupta (c. 240-280 CE) founded the Gupta dynasty but was a minor king. Ghatotkacha (280-319) followed. But the EMPIRE-builder — the first major imperial Gupta — was CHANDRAGUPTA I (r. 319-335 CE), who took the imperial title ''Maharajadhiraja'' and started the GUPTA ERA (319 CE). He married LICCHAVI princess Kumaradevi — a political marriage that greatly enhanced Gupta influence in the Ganga valley. His son SAMUDRAGUPTA (335-375) hugely expanded the empire; called the ''Indian Napoleon'' by V. A. Smith. CHANDRAGUPTA II VIKRAMADITYA (375-414) reached Gupta''s zenith — defeated Western Kshatrapas, Fa-Hien visited, nine gems ''Navaratna'' flourished. Decline after Skandagupta (455-467) who repelled Hun invasions.', 'EASY', 'History', 'Gupta Empire', 'HIS_GUPTA', '[{"option_text": "Chandragupta I", "is_correct": true}, {"option_text": "Samudragupta", "is_correct": false}, {"option_text": "Chandragupta II (Vikramaditya)", "is_correct": false}, {"option_text": "Sri Gupta", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8fe93d15-f611-5ba5-94c3-7d19fdc1f71e', 'Samudragupta''s military achievements are inscribed in which famous prashasti (eulogy)?', NULL, 'The ALLAHABAD PRASHASTI (Prayag Prashasti), inscribed on an ASHOKAN PILLAR at Prayag (Allahabad/Prayagraj) by court poet HARISENA, is the primary source on Samudragupta''s conquests. In Sanskrit, it lists 4 groups of kings defeated: (1) 9 of Aryavarta (uprooted); (2) 12 of Dakshinapatha (defeated and released — the ''Dharma-vijaya'' policy); (3) 5 frontier kingdoms (submission); (4) 9 tribal republics. AIHOLE INSCRIPTION — by Ravikirti for Chalukya Pulakeshin II. MANDSAUR — by Vatsabhatti on Kumaragupta era. JUNAGADH — by Rudradaman (Saka), later appended by Skandagupta recording repair of Sudarshana Lake. Fun fact: the Allahabad pillar originally had Ashoka''s edict; Samudragupta, Jahangir, and the British all added inscriptions.', 'HARD', 'History', 'Gupta Empire', 'HIS_GUPTA', '[{"option_text": "Aihole inscription", "is_correct": false}, {"option_text": "Allahabad Prashasti (Prayag Prashasti), composed by Harisena", "is_correct": true}, {"option_text": "Mandsaur inscription", "is_correct": false}, {"option_text": "Junagadh rock inscription", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('14ad3736-7034-58e1-9733-d0da87d3f49f', 'Which Gupta king is associated with the title ''Vikramaditya'' and whose court hosted the ''Nine Gems'' (Navaratnas)?', NULL, 'CHANDRAGUPTA II VIKRAMADITYA (r. 375-414 CE) — the Gupta zenith. The ''Nine Gems'' (NAVARATNA) at his court (per later tradition) included: KALIDASA (playwright — Abhijnana Shakuntalam, Meghaduta; greatest Sanskrit poet), AMARASIMHA (lexicographer — Amarakosha dictionary), DHANVANTARI (physician), VARAHAMIHIRA (astronomer — Brihat Samhita, Panch Siddhantika), VETALA BHATTA, GHATAKARPARA, SHANKU, KSHAPANAKA, VARARUCHI. FA-HIEN (Chinese Buddhist monk) visited India 405-411 CE, documented Gupta society in ''Fa Guo Ji'' (Record of Buddhist Kingdoms). Chandragupta II defeated the Western Kshatrapas (Sakas) and issued silver coins in their style. Also called ''Sakari'' (slayer of Sakas). His daughter Prabhavatigupta married the Vakataka king (alliance).', 'MEDIUM', 'History', 'Gupta Empire', 'HIS_GUPTA', '[{"option_text": "Chandragupta I", "is_correct": false}, {"option_text": "Samudragupta", "is_correct": false}, {"option_text": "Chandragupta II", "is_correct": true}, {"option_text": "Skandagupta", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('390b7606-ac39-5c1f-a424-6c7e22543a99', 'The IRON PILLAR at Delhi (Mehrauli, near Qutb Complex), famous for its rust-resistant composition over 1600+ years, is from which era?', NULL, 'The Iron Pillar at Mehrauli (Delhi) dates to the Gupta period — inscription on it is in Sanskrit Brahmi script referring to a king ''Chandra'' (generally identified as CHANDRAGUPTA II Vikramaditya). ~7 m tall, ~6 tonnes, 98% wrought iron. Its remarkable rust-resistance is due to a thin protective layer of ''misawite'' (hydrogen phosphate) formed by catalytic action of phosphorus present in the iron (~1%) reacting with air — a marvel of ancient Indian metallurgy. Originally stood at a Vishnu temple in Udayagiri (MP), later moved to Delhi by Anangpal Tomar or Iltutmish. In the Qutb Complex since 1200s. Iltutmish''s Qutb Minar built around it. Another Gupta masterpiece: BHITARI and ERAN pillars, the DASHAVATARA TEMPLE at Deogarh (oldest surviving Hindu stone temple, 500 CE).', 'MEDIUM', 'History', 'Gupta Empire', 'HIS_GUPTA', '[{"option_text": "Maurya period", "is_correct": false}, {"option_text": "Gupta period (attributed to Chandragupta II)", "is_correct": true}, {"option_text": "Delhi Sultanate", "is_correct": false}, {"option_text": "Mughal period", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('48c595ab-b900-58e0-9aad-4186ac2f89bd', 'ARYABHATA, the astronomer-mathematician who proposed heliocentrism and authored ''Aryabhatiya'' in 499 CE, flourished under which dynasty?', NULL, 'ARYABHATA (476-550 CE) — lived during the later Gupta era under Budhagupta — composed the ''ARYABHATIYA'' in 499 CE at age 23 at Kusumapura (Pataliputra). Key contributions: (1) Proposed Earth rotates on its axis (heliocentrism hints); (2) Used place-value notation WITHOUT zero as a written symbol (Brahmagupta, 628 CE, formalised zero and negative numbers); (3) Value of π (pi) ≈ 3.1416, close to modern; (4) Accurate calculation of solar year (365.25858 days); (5) Explained lunar eclipse (moon in Earth''s shadow) and solar eclipse rationally (moon blocks sun) against prevailing demonic theories. Other Gupta-era scientists: VARAHAMIHIRA, BRAHMAGUPTA (7th c. actually Post-Gupta but influenced by Gupta tradition), DHANVANTARI. India''s first satellite (1975) named ''Aryabhata'' in his honour.', 'MEDIUM', 'History', 'Gupta Empire', 'HIS_GUPTA', '[{"option_text": "Maurya", "is_correct": false}, {"option_text": "Gupta", "is_correct": true}, {"option_text": "Chola", "is_correct": false}, {"option_text": "Vakataka", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4056ac35-2905-5eb3-a069-5d67d3741916', 'The decline of the Gupta Empire began mainly due to invasions by which foreign tribe in the 5th-6th century CE?', NULL, 'The HUNAS (White Huns / Hephthalites) — a Central Asian nomadic people — invaded India from the NW in the mid-5th c. CE. Initially REPELLED by SKANDAGUPTA (c. 455-467 CE — hailed as ''Vikramaditya'' for this victory; Bhitari pillar inscription records it). After Skandagupta''s death, subsequent weaker Gupta rulers (Buddhagupta, Narasimhagupta, Vishnugupta) lost ground. Hun chieftains TORAMANA (c. 500 CE, captured Malwa region) and his son MIHIRAKULA (c. 515-540 CE, notorious persecutor of Buddhists — defeated by Yashodharman of Malwa in 528). Gupta fragmentation complete by c. 550 CE. Sakas had been defeated by Chandragupta II earlier (4th c.). Kushans preceded Guptas (1st-3rd c.). Parthians — short-lived 1st c. BCE Indo-Parthian kingdom in NW.', 'MEDIUM', 'History', 'Gupta Empire', 'HIS_GUPTA', '[{"option_text": "Kushans", "is_correct": false}, {"option_text": "Hunas (White Huns / Hephthalites)", "is_correct": true}, {"option_text": "Sakas", "is_correct": false}, {"option_text": "Parthians", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0a706b86-a98a-5e7b-9dac-c072860c2c3d', 'Which of the following is considered the OLDEST surviving Hindu stone temple in India, dating to the Gupta era?', NULL, 'The DASHAVATARA TEMPLE at Deogarh (Lalitpur district, UP), built c. 500 CE — the oldest surviving Hindu STONE temple in its original form. Dedicated to Vishnu (hence ''Dashavatara'' — ten incarnations). Features magnificent relief panels: (1) Gajendra Moksha (rescue of the elephant); (2) Nara-Narayana; (3) Sheshashayi Vishnu (Vishnu on cosmic serpent Ananta). Introduced the SHIKHARA (curvilinear tower) architectural element that became the cornerstone of Nagara temple style. Other early Gupta temples: Tigawa (c. 400 CE) and Sanchi Temple 17 (c. 400 CE) — simpler flat-roof. KAILASA at Ellora (8th c. Rashtrakuta), BRIHADESHWARA (1010 CE Chola), KONARK (13th c. Eastern Ganga) — all much later.', 'HARD', 'History', 'Gupta Empire', 'HIS_GUPTA', '[{"option_text": "Kailasa Temple, Ellora", "is_correct": false}, {"option_text": "Dashavatara Temple, Deogarh (c. 500 CE)", "is_correct": true}, {"option_text": "Brihadeshwara Temple, Thanjavur", "is_correct": false}, {"option_text": "Sun Temple, Konark", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9884f51f-016b-5cb7-b1fc-95d4ad5b193e', 'The Indian National Congress was founded in December 1885 at Bombay. Who was the Scottish-born British civil servant who played the key role in its founding?', NULL, 'Allan Octavian HUME (1829-1912) — retired British ICS officer, called the ''Father of the Indian National Congress'' — organised the first INC session (28-31 Dec 1885 at Gokuldas Tejpal Sanskrit College, Bombay; 72 delegates from across India). Acted as its first General Secretary. Wedderburn, Yule, Cotton were all sympathetic British who served as INC presidents — the only Britons to preside: George YULE (1888, first non-Indian president), William WEDDERBURN (1889 & 1910), Alfred WEBB (1894), Henry COTTON (1904), Annie BESANT (Irish-born, 1917 — first woman). Dadabhai Naoroji''s 1886 presidential address established INC as a national body. INC had 3 phases: MODERATE (1885-1905) → EXTREMIST (1905-1917) → GANDHIAN (1917-1947).', 'EASY', 'History', 'INC Formation & Moderate Phase', 'HIS_INC_MODERATES', '[{"option_text": "William Wedderburn", "is_correct": false}, {"option_text": "Allan Octavian Hume", "is_correct": true}, {"option_text": "George Yule", "is_correct": false}, {"option_text": "Henry Cotton", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fa4ede11-b32f-517e-8f4b-b4aeb5a110dc', 'Dadabhai Naoroji is famously known as the ''Grand Old Man of India'' and presided over the INC three times. Which year did he FIRST articulate the demand for ''SWARAJ'' (self-government) as the political objective of INC?', NULL, 'DADABHAI NAOROJI (1825-1917) — presided over INC 3 times (1886 Calcutta, 1893 Lahore, 1906 CALCUTTA — where in his presidential address he publicly demanded ''SWARAJ'' for the FIRST TIME in a clearly-articulated form). Author of ''Poverty and Un-British Rule in India'' (1901) — pioneer of the DRAIN THEORY showing how Britain bled wealth from India. First Indian elected to the British Parliament — Liberal MP for Finsbury Central, London (1892-95). The 1906 session is also notable for the growing Moderate-Extremist split, which would boil over at the 1907 SURAT SPLIT. Tilak''s ''Swaraj is my birthright'' slogan came in 1916 during the Home Rule Movement.', 'HARD', 'History', 'INC Formation & Moderate Phase', 'HIS_INC_MODERATES', '[{"option_text": "1886 at Calcutta", "is_correct": false}, {"option_text": "1906 at Calcutta session", "is_correct": true}, {"option_text": "1893 at Lahore", "is_correct": false}, {"option_text": "1916 at Lucknow", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a0d9f79c-7063-5429-99e7-f99c77dd042e', 'The famous ''Surat Split'' of the INC in 1907 was a formal division between which two factions?', NULL, 'The SURAT SPLIT (Dec 1907 at Surat, Gujarat) formally divided the Congress into two factions: MODERATES led by Gopal Krishna GOKHALE + Pherozeshah MEHTA + Dadabhai Naoroji — favouring prayer-petition-protest, gradual reforms; EXTREMISTS led by the TRIO ''LAL-BAL-PAL'' (Lala Lajpat Rai, Bal Gangadhar Tilak, Bipin Chandra Pal) + Aurobindo Ghosh — wanting militancy, boycott, swadeshi, Swaraj. Trigger: Surat session presidency choice — Moderates wanted Rashbehari Ghose; Extremists wanted Tilak. Reunion at LUCKNOW 1916 session (under Ambika Charan Mazumdar), which ALSO saw the HC Pact with the Muslim League. The 1905 Bengal Partition had catalysed Extremist rise; Moderates faded post-1916.', 'MEDIUM', 'History', 'INC Formation & Moderate Phase', 'HIS_INC_MODERATES', '[{"option_text": "Hindus vs Muslims", "is_correct": false}, {"option_text": "Moderates (Gokhale, Mehta) vs Extremists (Tilak, Lala Lajpat Rai, Bipin Chandra Pal — ''Lal-Bal-Pal'')", "is_correct": true}, {"option_text": "Gandhians vs Revolutionaries", "is_correct": false}, {"option_text": "Swarajists vs No-changers", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('366ba93e-49a2-5022-b082-816f81cfa6fc', 'Gopal Krishna Gokhale founded which society in 1905, aimed at training Indians to serve the motherland in a self-less manner?', NULL, 'Gopal Krishna GOKHALE (1866-1915) — called Mahatma Gandhi''s ''POLITICAL GURU'' — founded the SERVANTS OF INDIA SOCIETY in 1905 in Pune. Aim: to train national missionaries for the service of India and to promote the interests of the Indian people by constitutional means. Gokhale presided over the 1905 Benares session of INC. Also: Gokhale drafted the ELEMENTARY EDUCATION BILL 1911 (defeated in Council). Other similar societies: Ramakrishna Mission (Swami Vivekananda, 1897), Arya Samaj (Dayanand Saraswati, 1875), Theosophical Society (Blavatsky/Olcott, 1875 US; Annie Besant brought it to prominence in India), Prarthana Samaj (Atmaram Pandurang, 1867 Bombay — Ranade, Bhandarkar active), Brahmo Samaj (Raja Rammohan Roy, 1828), Hindu Mahasabha (Madan Mohan Malaviya, 1915).', 'MEDIUM', 'History', 'INC Formation & Moderate Phase', 'HIS_INC_MODERATES', '[{"option_text": "Servants of India Society", "is_correct": true}, {"option_text": "Hindu Mahasabha", "is_correct": false}, {"option_text": "Ramakrishna Mission", "is_correct": false}, {"option_text": "Arya Samaj", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fc23e604-ad89-5f41-a477-1eb3ed2a894f', 'Bal Gangadhar Tilak popularised the slogan ''Swaraj is my birthright, and I shall have it''. During which movement/occasion was this famously declared?', NULL, 'Bal Gangadhar TILAK (1856-1920, ''Lokmanya'') coined ''SWARAJYA MAZHA JANMA SIDDHA HAKKA AHE ANI TO MI MILAVANARACH'' (Marathi) — ''Swaraj is my birthright and I shall have it'' — during the Home Rule Movement (1916), which he launched from Pune in April 1916. Annie Besant launched a parallel Home Rule League from Madras in Sept 1916. Both Leagues merged with the INC effectively by 1918. Tilak started the newspapers KESARI (Marathi) and MAHRATTA (English) in 1881. Promoted GANESH UTSAV (1893) and SHIVAJI UTSAV (1895) as mass mobilisation tools. Jailed multiple times; wrote ''Gita Rahasya'' (1915) in Mandalay prison. Died on 1 August 1920 — the day Non-Cooperation was formally launched.', 'MEDIUM', 'History', 'INC Formation & Moderate Phase', 'HIS_INC_MODERATES', '[{"option_text": "Non-Cooperation Movement (1920)", "is_correct": false}, {"option_text": "Home Rule Movement (1916)", "is_correct": true}, {"option_text": "Civil Disobedience Movement (1930)", "is_correct": false}, {"option_text": "Quit India Movement (1942)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('41215324-f6ca-5351-b750-2d43ed017318', 'The historic 1929 LAHORE session of the INC, where ''PURNA SWARAJ'' (Complete Independence) was declared as the goal, was presided by:', NULL, 'JAWAHARLAL NEHRU (1889-1964), aged 40, became the YOUNGEST INC President at the LAHORE session (December 1929). At midnight of 31 December 1929, the TRICOLOUR was unfurled on the banks of the Ravi river, and the Purna Swaraj resolution was passed — declaring COMPLETE INDEPENDENCE as the ultimate goal. 26 JANUARY 1930 was observed as the first INDEPENDENCE DAY nationwide (celebrated annually till 1947 as ''Purna Swaraj Day''). Upon independence, 26 Jan 1950 was deliberately chosen as REPUBLIC DAY (when Constitution came into force) to honour this legacy. MOTILAL NEHRU (JLN''s father) had presided INC in 1919 and 1928 (when the Nehru Report was finalised). SC Bose presided in 1938 Haripura and 1939 Tripuri (led to his split with Gandhi).', 'EASY', 'History', 'INC Formation & Moderate Phase', 'HIS_INC_MODERATES', '[{"option_text": "Mahatma Gandhi", "is_correct": false}, {"option_text": "Jawaharlal Nehru", "is_correct": true}, {"option_text": "Motilal Nehru", "is_correct": false}, {"option_text": "Subhas Chandra Bose", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c5d54bf6-b162-511e-a31e-0daef8438d50', 'The Harappan civilisation was discovered in 1921. Who led the initial excavation at Harappa?', NULL, 'Harappa (Punjab, now Pakistan) was excavated in 1921 by Daya Ram Sahni (under ASI). Mohenjo-daro (Sindh, now Pakistan) was excavated in 1922 by R. D. Banerji. Sir JOHN MARSHALL (ASI Director General) announced the discovery of this civilisation in 1924 through a landmark article in The Illustrated London News, giving it the name ''Indus Valley Civilisation''. Mortimer Wheeler excavated in the 1940s, refining chronology. Now called Harappan or Indus-Sarasvati Civilisation. Flourished 2600-1900 BCE (Mature phase). Spread over ~1.25 million sq km — across modern Pakistan, NW India, and eastern Afghanistan.', 'MEDIUM', 'History', 'Indus Valley Civilization', 'HIS_INDUS', '[{"option_text": "Sir John Marshall", "is_correct": false}, {"option_text": "Daya Ram Sahni", "is_correct": true}, {"option_text": "R. D. Banerji", "is_correct": false}, {"option_text": "Mortimer Wheeler", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bd1244a9-00f4-535b-9469-d211b6aabc40', 'Lothal, famous for what specific feature, is an Indus Valley site located in which state?', NULL, 'LOTHAL (Bhal region of Gujarat, near Gulf of Khambhat) is FAMOUS for the world''s oldest known dockyard (c. 2400 BCE) — confirming Harappan maritime trade with Mesopotamia. Also notable: fire altars (7), a bead-making factory, a chess-like board game. Excavated by S. R. Rao (1954-63). Tidal dockyard of 214 × 36 m with sluice gates. Contrast site features: Great Bath = Mohenjo-daro (Sindh, Pakistan); Fire altars = Kalibangan (Rajasthan) AND Lothal; Ploughed field = Kalibangan (oldest-known ploughed field, earthquake evidence); Largest site = Rakhigarhi (Haryana, ~350 ha); Harbour/coastal = Lothal, Dholavira, Surkotada.', 'EASY', 'History', 'Indus Valley Civilization', 'HIS_INDUS', '[{"option_text": "Earliest known dockyard; Gujarat", "is_correct": true}, {"option_text": "Great Bath; Sindh (Pakistan)", "is_correct": false}, {"option_text": "Fire altars; Rajasthan", "is_correct": false}, {"option_text": "Largest size; Haryana", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0da75195-c402-572e-a288-240ad587c702', 'Which Indus Valley site yielded the famous ''Dancing Girl'' bronze statue?', NULL, 'The ''DANCING GIRL'' (10.5 cm tall, bronze, lost-wax casting technique) was excavated from Mohenjo-daro in 1926 by Ernest Mackay. Dated ~2500 BCE. Shows a nude young female with bangles on her left arm, hand on hip in a dance posture. Currently in the National Museum, New Delhi. Other famous Mohenjo-daro artefacts: ''Priest-King'' bust (now in Karachi National Museum, Pakistan — disputed artefact), the Great Bath, the Great Granary. Harappa yielded: the ''Red Jasper Male Torso'' (the ''Harappan Dancing Figure'' or the Red-stone male figure, 10 cm).', 'EASY', 'History', 'Indus Valley Civilization', 'HIS_INDUS', '[{"option_text": "Harappa", "is_correct": false}, {"option_text": "Mohenjo-daro", "is_correct": true}, {"option_text": "Dholavira", "is_correct": false}, {"option_text": "Kalibangan", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fd6b03e1-1d4e-5152-acb2-64427139dcef', 'Rakhigarhi, now considered the LARGEST Harappan site, is in which state?', NULL, 'Rakhigarhi (Hisar district, Haryana) is now recognised as the LARGEST Harappan site (~350 ha — surpassing Mohenjo-daro''s ~250 ha; sometimes called ''Rakhi-Shahpur'' after the twin villages). Excavations by Vasant Shinde (Deccan College) and ASI have uncovered planned streets, drains, burials, seals, a jewellery workshop, and most famously — ANCIENT DNA from a 4500-year-old female skeleton (2018-19 study by Shinde & Niraj Rai), showing Harappan people had NO Steppe/Aryan ancestry — supporting the ''Aryan migration post-Harappa'' theory. Previous ''largest site'' status shifted: Mohenjo-daro > Harappa > Ganweriwala (Pakistan) > Dholavira > Rakhigarhi.', 'MEDIUM', 'History', 'Indus Valley Civilization', 'HIS_INDUS', '[{"option_text": "Punjab", "is_correct": false}, {"option_text": "Haryana", "is_correct": true}, {"option_text": "Rajasthan", "is_correct": false}, {"option_text": "Uttar Pradesh", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e4047664-687a-57ce-9705-16d7cdc8b70d', 'Kalibangan, known for its pre-Harappan ploughed field and fire altars, is located in which state?', NULL, 'Kalibangan (''black bangles'' in Punjabi — named after black terracotta bangles found in abundance) is located on the left bank of the Ghaggar river in Hanumangarh district, Rajasthan. Excavated by B. B. Lal and B. K. Thapar (1961-69). Unique for: (1) the world''s EARLIEST EVIDENCE of a ploughed field (pre-Harappan, c. 2800 BCE — crisscross furrow pattern suggesting two crops grown simultaneously); (2) SEVEN FIRE ALTARS (suggesting fire-worship, a rare religious clue); (3) evidence of the OLDEST recorded EARTHQUAKE (c. 2600 BCE, may have caused abandonment); (4) lower town also fortified (unusual). Kalibangan sits on the now-dry Saraswati river.', 'HARD', 'History', 'Indus Valley Civilization', 'HIS_INDUS', '[{"option_text": "Gujarat", "is_correct": false}, {"option_text": "Rajasthan", "is_correct": true}, {"option_text": "Punjab", "is_correct": false}, {"option_text": "Haryana", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3bb0fc5c-df1f-5450-b4d4-3babcd5ffb25', 'Surkotada, a Harappan site in Gujarat, provided the ONLY conclusive evidence from Indus sites of the presence of:', NULL, 'Surkotada (Kutch, Gujarat), excavated by J. P. Joshi (1964-68), yielded the ONLY confirmed Harappan-era HORSE bones (dated c. 2000 BCE) — a significant finding because the absence of horses in Harappan art/bones was long cited as evidence that the Harappan people were NOT Aryan/Indo-European. The horse remains at Surkotada were verified by archaeo-zoologist Sándor Bökönyi (Hungarian expert). Horses are prominent in Vedic Aryan culture, which developed AFTER the Harappan civilisation declined. Iron came much later (c. 1200 BCE PGW culture). Harappans used pictographic seals, not Brahmi. Coinage dates only to ~6th c. BCE (Mahajanapadas).', 'HARD', 'History', 'Indus Valley Civilization', 'HIS_INDUS', '[{"option_text": "Domesticated horses", "is_correct": true}, {"option_text": "Iron smelting", "is_correct": false}, {"option_text": "Writing in Brahmi script", "is_correct": false}, {"option_text": "Coinage", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ae2c8e58-b30d-55ca-9808-1f16f2557312', 'The Harappan civilisation is best known for its town planning. Which of the following is NOT characteristic of a typical Indus city layout?', NULL, 'The HARAPPANS are notable for having NO monumental temples or palaces — unlike contemporary Mesopotamia and Egypt. This puzzles archaeologists: was it an egalitarian society, or was their religion domestic? Characteristic features: (a) GRID-pattern streets; (b) Citadel + Lower Town division (upper western citadel for public/administrative buildings, lower eastern for residences); (c) Standardised burnt bricks (ratio 1:2:4 — length:breadth:height); (d) ADVANCED drainage — covered drains, soak pits, manholes; (e) Granaries; (f) Uniform weights and measures; (g) Seals with pictographic script (~400 characters, undeciphered); (h) No large stone sculptures. Great Bath at Mohenjo-daro is the closest to a ''public'' structure but not a temple.', 'MEDIUM', 'History', 'Indus Valley Civilization', 'HIS_INDUS', '[{"option_text": "Grid pattern streets intersecting at right angles", "is_correct": false}, {"option_text": "A ''Citadel'' (upper town) and ''Lower Town''", "is_correct": false}, {"option_text": "Advanced underground drainage with soak pits", "is_correct": false}, {"option_text": "Monumental temples and royal palaces", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('801ccc37-a48b-5f4c-a820-49bf26010bb3', 'Dholavira, a 2021 UNESCO WHS, uniquely had which advanced engineering feature?', NULL, 'DHOLAVIRA (Khadir Bet, Rann of Kutch, Gujarat) is famed for its INGENIOUS WATER HARVESTING system — 16 stone-lined reservoirs comprising ~10% of the city area, collecting monsoon runoff and water from two seasonal streams (Mansar and Manhar). Also known for: (1) tripartite city plan (Citadel + Middle Town + Lower Town — unique among Indus sites); (2) the DHOLAVIRA SIGNBOARD — a 10-sign inscription above a gateway, possibly the oldest ''signboard'' in history; (3) rock-cut architecture; (4) declining phase shows gradual settlement of a much-reduced population. Inscribed as India''s 40th UNESCO WHS on 27 July 2021.', 'MEDIUM', 'History', 'Indus Valley Civilization', 'HIS_INDUS', '[{"option_text": "Iron smelting furnaces", "is_correct": false}, {"option_text": "Sophisticated water conservation system with 16 reservoirs", "is_correct": true}, {"option_text": "Animal-driven mills", "is_correct": false}, {"option_text": "Underground nuclear shelters", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d4b832b2-a614-5788-b2fe-de1dcc2b83ec', 'Who founded the Mauryan Empire?', NULL, 'Chandragupta Maurya founded the Mauryan Empire in c. 321 BCE by overthrowing the Nanda dynasty with the help of his mentor Chanakya (Kautilya). Bindusara was his son; Ashoka was his grandson. Dasharatha was Ashoka''s grandson (ruled after Ashoka''s son Kunala). Chandragupta abdicated to become a Jain monk at Shravanabelagola.', 'EASY', 'History', 'Mauryan Empire', 'HIS_MAURYA', '[{"option_text": "Bindusara", "is_correct": false}, {"option_text": "Chandragupta Maurya", "is_correct": true}, {"option_text": "Ashoka", "is_correct": false}, {"option_text": "Dasharatha Maurya", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('662c932e-b9d5-5aea-9ab0-dcd282ed6507', 'Who was the Greek ambassador sent by Seleucus Nicator to the court of Chandragupta Maurya?', NULL, 'Megasthenes (c. 350-290 BCE) was sent by Seleucus I Nicator to Chandragupta Maurya''s court at Pataliputra. He wrote ''Indica'' — a detailed account of Mauryan India (only fragments survive in quotations by later writers). Deimachus was a later ambassador sent to Bindusara. Dionysius was sent to an even later Mauryan court. Patrocles was a Seleucid explorer, not an ambassador to the Mauryas.', 'MEDIUM', 'History', 'Mauryan Empire', 'HIS_MAURYA', '[{"option_text": "Deimachus", "is_correct": false}, {"option_text": "Megasthenes", "is_correct": true}, {"option_text": "Dionysius", "is_correct": false}, {"option_text": "Patrocles", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fff63656-3427-5d30-9d6c-9df5328bae99', 'The Arthashastra, a treatise on statecraft, economics, and military strategy, was written by:', NULL, 'The Arthashastra is attributed to Kautilya (also known as Chanakya or Vishnugupta) — the legendary advisor of Chandragupta Maurya. It covers political theory, economics, diplomacy, war, administration, and espionage. Megasthenes wrote Indica. Panini was a Sanskrit grammarian (4th c. BCE) who wrote Ashtadhyayi. Patanjali is associated with the Yoga Sutras. The Arthashastra was rediscovered by R. Shamasastry in 1905.', 'EASY', 'History', 'Mauryan Empire', 'HIS_MAURYA', '[{"option_text": "Megasthenes", "is_correct": false}, {"option_text": "Kautilya (Chanakya)", "is_correct": true}, {"option_text": "Panini", "is_correct": false}, {"option_text": "Patanjali", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1ec3a6b5-2f07-5e5e-bc3f-e74d7f1d5006', 'The Kalinga War, a turning point in Indian history, was fought by Ashoka in:', NULL, 'The Kalinga War was fought c. 261 BCE — the 8th regnal year of Ashoka, who had been crowned c. 269 BCE. The massive casualties (per Ashoka''s own Rock Edict XIII: ''100,000 killed, 150,000 deported, many more died from secondary causes'') led to his remorse and conversion to Buddhism. 232 BCE is Ashoka''s approximate death year; 305 BCE was Chandragupta''s war with Seleucus; 268 BCE is sometimes cited as Ashoka''s coronation year.', 'MEDIUM', 'History', 'Mauryan Empire', 'HIS_MAURYA', '[{"option_text": "261 BCE", "is_correct": true}, {"option_text": "232 BCE", "is_correct": false}, {"option_text": "305 BCE", "is_correct": false}, {"option_text": "268 BCE", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('471171b6-6500-5143-be56-e71d03e4b2e2', 'Ashoka''s edicts were written primarily in which script(s)?', NULL, 'Ashoka''s edicts (Rock, Pillar, Minor Rock, Minor Pillar, Cave) are primarily in Prakrit language using the BRAHMI script (across most of India — this is how the Ashokan edicts were deciphered by James Prinsep in 1837). The northwestern edicts (e.g., Shahbazgarhi, Mansehra) use the KHAROSTHI script. The Kandahar edict (bilingual Greek-Aramaic) uses GREEK and ARAMAIC — reflecting the Hellenistic populations of the frontier. Devanagari evolved much later (from Brahmi around the 7th c. CE).', 'HARD', 'History', 'Mauryan Empire', 'HIS_MAURYA', '[{"option_text": "Devanagari only", "is_correct": false}, {"option_text": "Brahmi (most) + Kharosthi (northwest) + Greek & Aramaic (Kandahar)", "is_correct": true}, {"option_text": "Only Sanskrit-based script", "is_correct": false}, {"option_text": "Grantha only", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e9029ef1-8f41-5cb6-89ea-7246e1137d23', 'The Mauryan capital was located at:', NULL, 'PATALIPUTRA (modern-day Patna, Bihar) was the capital of the Mauryan Empire — inherited from the preceding Nanda dynasty, which had itself inherited it from the Shishunaga dynasty. Megasthenes described Pataliputra as a huge walled city with 64 gates and 570 towers, 15 km long × 2.8 km wide. Ujjain, Taxila, Tosali, and Suvarnagiri were PROVINCIAL capitals under princes/governors. Kalinga (Dhauli/Jaugada region) was conquered by Ashoka.', 'EASY', 'History', 'Mauryan Empire', 'HIS_MAURYA', '[{"option_text": "Ujjain", "is_correct": false}, {"option_text": "Pataliputra", "is_correct": true}, {"option_text": "Taxila", "is_correct": false}, {"option_text": "Kalinga", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ddb9162d-7b93-5330-a657-6ee7c86db7d8', 'Which symbol on the Indian national flag is derived from Ashoka''s Sarnath pillar?', NULL, 'The ASHOKA CHAKRA — a navy-blue 24-spoke wheel — appears at the centre of the Indian tricolour. It is adapted from the ''Dharma Chakra'' on the abacus of Ashoka''s Sarnath Lion Capital. The Lion Capital itself (four lions back-to-back, on an abacus with four animals — lion, bull, horse, elephant — separated by smaller chakras) is India''s State Emblem. Both symbols were adopted on 26 January 1950.', 'EASY', 'History', 'Mauryan Empire', 'HIS_MAURYA', '[{"option_text": "The Ashoka Chakra (24-spoke wheel)", "is_correct": true}, {"option_text": "The seven-horse chariot", "is_correct": false}, {"option_text": "The lotus emblem", "is_correct": false}, {"option_text": "The bull capital", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fc367d0f-90a6-5ed8-b48f-b81241a6be08', 'The Mauryan administration was highly centralized. According to the Arthashastra, the state was divided into provinces, each under:', NULL, 'Mauryan provinces were headed by princes of the royal family (''Kumaras'' or ''Aryaputras'') at the top four provincial capitals: Taxila (Uttarapatha), Ujjain (Avantirashtra), Tosali (Kalinga), Suvarnagiri (south). Other districts were headed by ''Pradesikas'' (governors) with local officials like ''Rajukas'' (revenue) and ''Yuktas'' (secretariat). The king sat at Pataliputra with a Mantri Parishad (Council of Ministers) and a vast bureaucracy — a very centralised, non-republican polity.', 'HARD', 'History', 'Mauryan Empire', 'HIS_MAURYA', '[{"option_text": "An elected council", "is_correct": false}, {"option_text": "A prince (Kumara/Aryaputra) or a governor (Pradesika)", "is_correct": true}, {"option_text": "A republic of elders", "is_correct": false}, {"option_text": "A military commander only", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ebceb370-7181-5859-9b0e-e8a3ae40d2f7', 'The Mauryan Empire declined and fragmented after the death of which ruler?', NULL, 'After Ashoka''s death (c. 232 BCE), the Mauryan Empire declined rapidly. His successors (Dasharatha, Samprati, Shalishuka, Devavarman, Shatadhanvan, Brihadratha) were weaker; administrative costs were huge; provincial governors rebelled. The LAST Mauryan, Brihadratha, was assassinated by his commander-in-chief Pushyamitra Shunga c. 185 BCE, founding the Shunga dynasty. So Ashoka''s death BEGAN the decline; Brihadratha''s assassination ENDED the empire.', 'MEDIUM', 'History', 'Mauryan Empire', 'HIS_MAURYA', '[{"option_text": "Chandragupta Maurya", "is_correct": false}, {"option_text": "Bindusara", "is_correct": false}, {"option_text": "Ashoka", "is_correct": true}, {"option_text": "Brihadratha (the last Mauryan)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8447feab-f5d9-543a-8a08-ece2cec8f904', 'Which of Ashoka''s major rock edicts mentions the Kalinga War and his subsequent remorse?', NULL, 'Major Rock Edict XIII is the most famous — it explicitly mentions the Kalinga War, the massive casualties, and Ashoka''s remorse leading to adoption of Dhamma. The edict is NOT found at the Kalinga sites themselves (Dhauli, Jaugada — diplomatic avoidance). Other key edicts: Rock Edict I (ban on animal sacrifice), II (medical aid to humans and animals), VII (religious tolerance), XII (full religious tolerance to all sects).', 'HARD', 'History', 'Mauryan Empire', 'HIS_MAURYA', '[{"option_text": "Rock Edict II", "is_correct": false}, {"option_text": "Rock Edict VII", "is_correct": false}, {"option_text": "Rock Edict XIII", "is_correct": true}, {"option_text": "Rock Edict I", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('62f2425d-b741-5042-9ebe-4d4562e45b0d', 'Who was the first Governor-General of Bengal under the Regulating Act, 1773?', NULL, 'Warren Hastings (1773-85) was the FIRST Governor-General of Bengal (Fort William) under the Regulating Act 1773 — which subordinated Bombay & Madras Presidencies to Bengal. Robert Clive was Governor of Bengal 1757-60 and 1765-67 (pre-dating the GG office). Key Hastings actions: founded Asiatic Society of Bengal (1784, by William Jones during his tenure), commissioned Charles Wilkins''s Gita translation, First Anglo-Maratha War, Pitt''s India Act 1784 passed during his tenure. Impeached 1787 in UK (acquitted 1795). Lord Cornwallis (1786-93) succeeded him — introduced Permanent Settlement 1793.', 'EASY', 'History', 'Governors-General & Viceroys', 'HIS_VICEROYS', '[{"option_text": "Robert Clive", "is_correct": false}, {"option_text": "Warren Hastings", "is_correct": true}, {"option_text": "Lord Cornwallis", "is_correct": false}, {"option_text": "Lord Wellesley", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fc586c10-2c88-52e5-a738-e0205fc0bf23', 'Who was the first Governor-General of India (of all British territories) under the Charter Act, 1833?', NULL, 'Lord William Bentinck (GG of Bengal 1828-33; then GG of INDIA 1833-35) became the FIRST Governor-General of India (not just Bengal) under the Charter Act 1833 — which centralised legislative power and created the title. Key Bentinck reforms: abolition of SATI (1829, Regulation XVII via Raja Ram Mohan Roy''s advocacy), suppression of THUGGEE (with William Sleeman), abolition of female infanticide, English as medium of higher education (Macaulay''s Minute 1835 under his tenure). Lord Dalhousie (1848-56) — Doctrine of Lapse, annexed Awadh, railway 1853, postal 1854. Lord Canning (1856-58 GG, 1858-62 VICEROY) — straddled the transition when 1857 Revolt ended Company rule.', 'MEDIUM', 'History', 'Governors-General & Viceroys', 'HIS_VICEROYS', '[{"option_text": "Lord William Bentinck", "is_correct": true}, {"option_text": "Lord Dalhousie", "is_correct": false}, {"option_text": "Lord Canning", "is_correct": false}, {"option_text": "Lord Minto", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('03654897-d333-551c-9738-e41182657b33', 'Who was the first VICEROY of India, after the Crown took direct control in 1858?', NULL, 'LORD CANNING (1856-62) was both: (a) the LAST Governor-General of India under the Company (1856-58), and (b) the FIRST VICEROY of India when the Queen''s Proclamation of 1 November 1858 (Government of India Act 1858) transferred power from the East India Company to the British Crown. Known as ''Clemency Canning'' for his comparatively restrained handling of post-1857 reprisals. Ended Doctrine of Lapse. Restored princely states'' rights via Queen''s Proclamation. Lord Dalhousie (1848-56) was the GG BEFORE Canning. Lord Mayo (1869-72) — financial decentralisation, first census 1872, assassinated at Port Blair (only Viceroy killed in office). Lord Lytton (1876-80) — Vernacular Press Act 1878, Arms Act 1878, Royal Titles Act 1876 (Queen Victoria became ''Empress of India'').', 'MEDIUM', 'History', 'Governors-General & Viceroys', 'HIS_VICEROYS', '[{"option_text": "Lord Dalhousie", "is_correct": false}, {"option_text": "Lord Canning", "is_correct": true}, {"option_text": "Lord Mayo", "is_correct": false}, {"option_text": "Lord Lytton", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a21f8118-4cb2-5c02-81c5-f78a63d40b6d', 'Which Viceroy is associated with the Partition of Bengal (1905), its reversal (1911), and the Delhi Darbar?', NULL, 'LORD CURZON (1899-1905) ordered the PARTITION OF BENGAL (October 1905), ostensibly for administrative convenience but actually to divide Hindu-majority West & Muslim-majority East — sparking the Swadeshi Movement. Also: founded ASI under John Marshall, Indian Universities Act 1904, Police Commission 1902, Railway Board 1905. LORD HARDINGE II (1910-16) — ANNULLED the Bengal partition at the DELHI DARBAR of 12 Dec 1911 (where King George V & Queen Mary were present; also shifted capital from Calcutta to Delhi). Survived a bomb attack 1912 by revolutionaries (Chandni Chowk bombing). Lord Minto II (1905-10) = Morley-Minto Reforms 1909 (separate electorates for Muslims, sowing seeds of two-nation theory).', 'MEDIUM', 'History', 'Governors-General & Viceroys', 'HIS_VICEROYS', '[{"option_text": "Lord Curzon ordered partition; Lord Hardinge II reversed it", "is_correct": true}, {"option_text": "Lord Minto ordered partition; Lord Curzon reversed it", "is_correct": false}, {"option_text": "Lord Lytton ordered partition; Lord Ripon reversed it", "is_correct": false}, {"option_text": "Lord Mayo ordered partition; Lord Elgin reversed it", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f597c564-841b-55e4-abfd-d04070c049bb', 'The Jallianwala Bagh massacre (13 April 1919) took place during the tenure of which Viceroy?', NULL, 'LORD CHELMSFORD (1916-21) was Viceroy during the Jallianwala Bagh massacre (Baisakhi day, 13 April 1919) at Amritsar — Brig-Gen Reginald Dyer ordered firing on unarmed crowd protesting the Rowlatt Act (passed March 1919). 379+ killed (official), ~1000+ (unofficial). Hunter Commission (1920) denounced Dyer. Tagore renounced his knighthood in protest. Chelmsford''s tenure also saw: Montagu-Chelmsford Reforms 1919 (Dyarchy in provinces, Govt of India Act 1919), Rowlatt Act 1919, Non-Cooperation Movement launched Aug 1920. Lord Reading (1921-26) followed — Chauri Chaura 1922 and Non-Coop suspension. Lord Irwin (1926-31) — Simon Commission, Nehru Report, Dandi March, Gandhi-Irwin Pact 1931.', 'MEDIUM', 'History', 'Governors-General & Viceroys', 'HIS_VICEROYS', '[{"option_text": "Lord Hardinge II", "is_correct": false}, {"option_text": "Lord Chelmsford", "is_correct": true}, {"option_text": "Lord Reading", "is_correct": false}, {"option_text": "Lord Irwin", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2bd43044-0657-5104-993b-67b90e965119', 'Lord Mountbatten was the last British Viceroy of India (March-August 1947). Who succeeded him as the FIRST (and only) Governor-General of INDEPENDENT India?', NULL, 'Lord Louis Mountbatten (March 1947 — the LAST British Viceroy) continued as the FIRST Governor-General of INDEPENDENT India (15 Aug 1947 — 21 June 1948). He was succeeded by CHAKRAVARTI RAJAGOPALACHARI (C. Rajagopalachari, ''Rajaji'') — the only INDIAN Governor-General of India (21 June 1948 — 26 Jan 1950). The office was ABOLISHED on 26 January 1950 when the Constitution came into force; Dr. Rajendra Prasad became the first PRESIDENT of India. In Pakistan: Mohammad Ali Jinnah was the first Governor-General (1947-48). Rajaji was also awarded the Bharat Ratna in 1954 — one of the first three recipients.', 'EASY', 'History', 'Governors-General & Viceroys', 'HIS_VICEROYS', '[{"option_text": "Dr. Rajendra Prasad", "is_correct": false}, {"option_text": "C. Rajagopalachari", "is_correct": true}, {"option_text": "Dr. S. Radhakrishnan", "is_correct": false}, {"option_text": "Vallabhbhai Patel", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cd74bfa8-e0db-576d-80e7-18dcbbf5e12d', 'Which Viceroy introduced the ''Local Self-Government'' principle through the Resolution of 1882, earning the title ''Father of Local Self-Government in India''?', NULL, 'LORD RIPON (1880-84) is called the ''Father of Local Self-Government in India'' for his Resolution of 18 May 1882 — expanding elected municipal and rural boards. Also: Hunter Commission 1882 (education — Indian Education Commission, the first on education policy), Ilbert Bill 1883 (allowing Indian judges to try Europeans — opposition led to its dilution and sparked political awakening), Factory Act 1881, repealed Vernacular Press Act. Lord Lytton (1876-80) preceded — the repressive predecessor (Delhi Durbar 1877 declaring Queen Victoria Empress of India, Arms Act 1878, Vernacular Press Act 1878, Afghan War 1878-80). Lord Dufferin (1884-88) followed — INC founded 1885 during his tenure. Lord Mayo (1869-72) — financial decentralisation, assassinated Port Blair.', 'HARD', 'History', 'Governors-General & Viceroys', 'HIS_VICEROYS', '[{"option_text": "Lord Lytton", "is_correct": false}, {"option_text": "Lord Ripon", "is_correct": true}, {"option_text": "Lord Mayo", "is_correct": false}, {"option_text": "Lord Dufferin", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fb0414c4-4557-58e0-bb10-f07490a83a8d', 'The Indian Councils Act of 1892 and Gopal Krishna Gokhale''s political emergence occurred during the tenure of which Viceroy?', NULL, 'LORD LANSDOWNE (1888-94) was Viceroy during the Indian Councils Act 1892 (increased number of non-official members + limited indirect election — the seed of representative government). Also: creation of the Imperial Library (now National Library, Kolkata); Age of Consent Act 1891. LORD ELGIN II (1894-99) — the Plague of Bombay 1896, assassination of the Rand brothers by Chapekar Brothers (Pune 1897), famine 1896-97. LORD DUFFERIN (1884-88) — INC founded 1885 (A.O. Hume), 3rd Anglo-Burmese War 1885, annexation of Upper Burma. LORD CURZON (1899-1905) — later, as noted, partition of Bengal.', 'HARD', 'History', 'Governors-General & Viceroys', 'HIS_VICEROYS', '[{"option_text": "Lord Dufferin", "is_correct": false}, {"option_text": "Lord Lansdowne", "is_correct": true}, {"option_text": "Lord Elgin II", "is_correct": false}, {"option_text": "Lord Curzon", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4c9b4b2d-4e31-5405-909e-186ea7e13152', 'Newton''s FIRST Law of Motion is also known by which of the following names?', NULL, 'Newton''s First Law states: ''Every body continues in its state of rest or of uniform motion in a straight line unless acted upon by an external force.'' This is the LAW OF INERTIA — inertia being the property by which a body resists change in its state of rest or motion. Option A refers loosely to the Second Law (F = dp/dt). Option C is the Third Law (every action has an equal and opposite reaction). Option D is a separate Newton contribution — nothing to do with the three laws of motion.', 'EASY', 'Physics', 'Newton''s Laws of Motion & Friction', 'PHY_LAWS', '[{"option_text": "Law of Momentum", "is_correct": false}, {"option_text": "Law of Inertia", "is_correct": true}, {"option_text": "Law of Action-Reaction", "is_correct": false}, {"option_text": "Law of Universal Gravitation", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2a2d7227-3496-565d-aeeb-f60aa44efd92', 'A force of 20 N is applied to a body of mass 4 kg on a frictionless surface. What is the acceleration produced?', NULL, 'By Newton''s Second Law, F = ma, so a = F/m = 20/4 = 5 m/s². Worked step by step: given F = 20 N, m = 4 kg. Rearranging F = ma → a = F/m = 20 ÷ 4 = 5 m/s². Distractor 2 m/s² would be (force − mass)/something — pure error; 80 m/s² comes from 20×4 (multiplying instead of dividing — a common slip); 24 m/s² comes from 20+4 (adding instead of dividing — less common but tracks a student who has forgotten the formula entirely).', 'EASY', 'Physics', 'Newton''s Laws of Motion & Friction', 'PHY_LAWS', '[{"option_text": "2 m/s²", "is_correct": false}, {"option_text": "5 m/s²", "is_correct": true}, {"option_text": "80 m/s²", "is_correct": false}, {"option_text": "24 m/s²", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bfa20da0-fa24-5098-b001-ef3b7446f8a4', 'When a rifle is fired, the rifle RECOILS backward. This illustrates which of Newton''s laws?', NULL, 'The forward force exerted on the bullet by the rifle PRODUCES an equal and opposite backward force on the rifle — pure Newton''s Third Law (''every action has an equal and opposite reaction''). Rocket propulsion uses the same principle. Other common Third Law illustrations: walking (feet push ground back, ground pushes us forward), swimming (arms push water back, water pushes swimmer forward), a bird flying (wings push air down, air pushes bird up). The First Law explains why a stationary rifle stays stationary until fired. The Second Law quantifies the recoil velocity using momentum conservation.', 'EASY', 'Physics', 'Newton''s Laws of Motion & Friction', 'PHY_LAWS', '[{"option_text": "First Law", "is_correct": false}, {"option_text": "Second Law", "is_correct": false}, {"option_text": "Third Law", "is_correct": true}, {"option_text": "Law of Gravitation", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('86b9bc7c-a896-5f24-ae10-e71c150a6e4c', 'A bus moving at 20 m/s suddenly brakes and comes to rest in 4 seconds. If its mass is 2000 kg, what is the magnitude of the AVERAGE braking force?', NULL, 'Step-by-step: (1) Acceleration a = (v − u)/t = (0 − 20)/4 = −5 m/s² — magnitude 5 m/s². (2) By Newton''s Second Law, F = ma = 2000 × 5 = 10 000 N (taking magnitudes). The direction is opposite to the motion (braking). Distractor 5 000 N drops the mass by a factor of 2 (common slip: thinking mass = 1000 kg). 40 000 N mistakenly multiplies by 4 (the time) instead of dividing. 2 500 N divides the mass by the time (nonsensical dimensionally). Always unit-check: N = kg·m/s² — so 2000 × 5 = 10 000 N checks out.', 'MEDIUM', 'Physics', 'Newton''s Laws of Motion & Friction', 'PHY_LAWS', '[{"option_text": "5 000 N", "is_correct": false}, {"option_text": "10 000 N", "is_correct": true}, {"option_text": "40 000 N", "is_correct": false}, {"option_text": "2 500 N", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('930afd7c-1bd1-58ef-8e6a-be47b9ae2a63', 'The momentum of a body is defined as:', NULL, 'Momentum p = m·v. Since velocity is a vector, momentum is a vector. Unit: kg·m/s (or N·s). Newton''s Second Law in its ORIGINAL form: F = dp/dt (rate of change of momentum = force). When mass is constant, this simplifies to F = ma. Option B is force F = ma (not momentum). Option C has wrong units and definition. Option D confuses with kinetic energy which is (1/2)mv² (a scalar).', 'EASY', 'Physics', 'Newton''s Laws of Motion & Friction', 'PHY_LAWS', '[{"option_text": "Mass × velocity (a vector)", "is_correct": true}, {"option_text": "Mass × acceleration (a vector)", "is_correct": false}, {"option_text": "Mass ÷ velocity (a scalar)", "is_correct": false}, {"option_text": "(Mass × velocity)² (a scalar)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4a506cdc-906f-5775-9b6f-cf7739b2ff6c', 'Two bodies of masses 4 kg and 6 kg moving in the same direction with velocities 10 m/s and 5 m/s respectively collide. If they STICK TOGETHER after collision, their common velocity is (assume perfectly inelastic collision, no external forces):', NULL, 'By conservation of momentum: m₁v₁ + m₂v₂ = (m₁ + m₂)V. Plugging in: 4(10) + 6(5) = (4+6)V → 40 + 30 = 10V → 70 = 10V → V = 7 m/s. (Derivation shown step-by-step; answer matches option B exactly.) Distractor 5 m/s is simply the slower body''s speed (ignoring the collision); 15 m/s is the sum of speeds (nonsense); 10 m/s is the faster body''s speed. Momentum conservation — not energy conservation — is what always holds in collisions without external force. Energy is NOT conserved in inelastic collisions (some becomes heat/deformation).', 'MEDIUM', 'Physics', 'Newton''s Laws of Motion & Friction', 'PHY_LAWS', '[{"option_text": "5 m/s", "is_correct": false}, {"option_text": "7 m/s", "is_correct": true}, {"option_text": "15 m/s", "is_correct": false}, {"option_text": "10 m/s", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('22993723-5aa1-5904-b736-7570f039cd57', 'Which statement about the three types of friction — STATIC, KINETIC, and ROLLING — is CORRECT?', NULL, 'The CORRECT ordering (for the same surfaces and normal force): μ_s (static, maximum) > μ_k (kinetic) > μ_r (rolling). This is why: (i) it takes more force to START pushing a box than to keep it sliding (static > kinetic); (ii) wheels and ball-bearings are used because rolling friction is FAR smaller than sliding/kinetic friction. For typical steel-on-steel: μ_s ≈ 0.74, μ_k ≈ 0.57, μ_r (rolling) ≈ 0.002. This vast gap between kinetic and rolling friction is why the wheel is one of humanity''s most impactful inventions.', 'EASY', 'Physics', 'Newton''s Laws of Motion & Friction', 'PHY_LAWS', '[{"option_text": "Kinetic friction > Static friction > Rolling friction", "is_correct": false}, {"option_text": "Static friction (maximum) > Kinetic friction > Rolling friction", "is_correct": true}, {"option_text": "All three are always equal in magnitude", "is_correct": false}, {"option_text": "Rolling friction > Kinetic friction > Static friction", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1dedbba2-1942-5d55-846c-be6c48a07225', 'A block of mass 5 kg is kept on a horizontal surface with coefficient of static friction μ_s = 0.4. What is the MINIMUM horizontal force needed to JUST START moving the block? (Take g = 10 m/s²)', NULL, 'The block JUST starts moving when applied force equals the maximum static friction. Step 1: Normal force N = mg = 5 × 10 = 50 N (the block rests on a horizontal surface, so N balances weight). Step 2: Maximum static friction f_s_max = μ_s · N = 0.4 × 50 = 20 N. Step 3: Applied force needed = 20 N (just enough to overcome static friction). Distractor 10 N is half — maybe from μ_s · mg/2 confusion. 50 N is just N (student forgot to multiply by μ). 2 N is μ_s · m without g — dimensional error.', 'MEDIUM', 'Physics', 'Newton''s Laws of Motion & Friction', 'PHY_LAWS', '[{"option_text": "10 N", "is_correct": false}, {"option_text": "20 N", "is_correct": true}, {"option_text": "50 N", "is_correct": false}, {"option_text": "2 N", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('58b773ed-df08-5c1b-a7ef-8e34f2576e4b', 'Which of the following is a practical application of Newton''s FIRST Law of Motion?', NULL, 'When a car suddenly brakes, the PASSENGERS'' upper bodies continue moving forward at the original velocity (by inertia / First Law) — the seat belt applies the external force that brings them to rest, preventing collision with the windshield. Classic First-Law application. Option A demonstrates the Third Law (action-reaction). Option C is based on Pascal''s principle (fluid pressure transmission), not Newton''s laws directly. Option D uses the Second Law (F = ma, with F = mg). Other everyday First-Law examples: dust flying off a shaken carpet, a fruit falling from a tree when its branch is shaken, a standing passenger in a bus jerking backward when the bus accelerates forward.', 'EASY', 'Physics', 'Newton''s Laws of Motion & Friction', 'PHY_LAWS', '[{"option_text": "Firing a bullet from a gun producing recoil", "is_correct": false}, {"option_text": "Seat belts in cars preventing passengers from continuing forward when the car suddenly stops", "is_correct": true}, {"option_text": "Using a hydraulic lift to raise heavy objects", "is_correct": false}, {"option_text": "Calculating the acceleration of a falling body", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9cef7a30-38de-5166-9087-4e3ef3bf59f4', 'In the expression F = ma, all units are SI. Which of the following is the CORRECT SI unit breakdown of the newton (N)?', NULL, '1 newton = 1 kg · m / s² (unit of mass × unit of acceleration). This is the standard SI unit check for any physics problem involving force. Option A omits the meter (wrong dimension). Option C has the wrong time-exponent (time should be in the denominator with exponent 2). Option D is the unit of ENERGY — the joule (1 J = 1 kg·m²/s²) — not force. Always unit-check answers: if your final numeric result has dimensions that don''t match what the question asks, the computation is wrong.', 'MEDIUM', 'Physics', 'Newton''s Laws of Motion & Friction', 'PHY_LAWS', '[{"option_text": "1 N = 1 kg/s²", "is_correct": false}, {"option_text": "1 N = 1 kg·m/s²", "is_correct": true}, {"option_text": "1 N = 1 kg·m·s", "is_correct": false}, {"option_text": "1 N = 1 kg·m²/s²", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('97bf3835-69ba-547c-9264-17bec4eb7133', 'Two astronauts in space — far from any gravitational body and initially at rest — push off from each other. If astronaut A (60 kg) moves off at 2 m/s, what is the velocity of astronaut B (80 kg)?', NULL, 'Conservation of momentum: initial total momentum = 0 (both at rest). After pushing off, momenta must still sum to zero → m_A · v_A + m_B · v_B = 0. So v_B = −(m_A / m_B) · v_A = −(60/80) × 2 = −1.5 m/s. The negative sign means OPPOSITE direction — so B moves at 1.5 m/s in the opposite direction. Distractor C (2.67) swaps the mass ratio: v_B = −(80/60) × 2 = −2.67 — a very common error. A is nonsensical (violates momentum conservation). D forgets that conservation applies to the system, not to a single body alone.', 'MEDIUM', 'Physics', 'Newton''s Laws of Motion & Friction', 'PHY_LAWS', '[{"option_text": "2.0 m/s in the same direction as A", "is_correct": false}, {"option_text": "1.5 m/s in the opposite direction to A", "is_correct": true}, {"option_text": "2.67 m/s in the opposite direction to A", "is_correct": false}, {"option_text": "0 m/s — A''s velocity alone satisfies momentum conservation", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4a60683e-9a3b-5766-8efe-af643ff1dcda', 'The coefficient of friction between two surfaces is a DIMENSIONLESS number because:', NULL, 'μ = f / N where f is the friction force and N the normal force — both in newtons. Ratio of two quantities with identical units is DIMENSIONLESS. Typical values: rubber on dry concrete ≈ 1.0; steel on steel ≈ 0.57 (kinetic); ice on ice ≈ 0.03; rolling friction for ball-bearings ≈ 0.001. Although μ is typically between 0 and 1, μ > 1 IS possible (e.g. some rubber-on-rubber can reach ~1.2-1.5). Option B is a conceptual misconception — μ is NOT a probability. Option C is wrong — it''s a real-valued ratio. Option D is wrong — it varies widely.', 'MEDIUM', 'Physics', 'Newton''s Laws of Motion & Friction', 'PHY_LAWS', '[{"option_text": "It is defined as the ratio of two forces (friction / normal), so the units cancel", "is_correct": true}, {"option_text": "It is a probability value between 0 and 1", "is_correct": false}, {"option_text": "It is computed using only integer counting", "is_correct": false}, {"option_text": "It is always exactly equal to 1 in SI", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('26383dd5-cf68-5dbb-a9cc-dc1ec4d15b4e', 'When a body slides down an INCLINED plane at a constant velocity, the relationship between the angle of inclination θ and the coefficient of kinetic friction μ_k is:', NULL, 'At CONSTANT velocity down an incline, net force = 0. Forces along the incline: component of gravity down the slope = mg sin θ; friction up the slope = μ_k · N = μ_k · mg cos θ. Setting them equal: mg sin θ = μ_k · mg cos θ → μ_k = sin θ / cos θ = TAN θ. The angle at which this happens is called the ''angle of friction'' or ''angle of repose''. Typical engineering: a steel coil on a wooden ramp slides at ~30° → μ ≈ tan 30° ≈ 0.58. The distractors sin θ and cos θ reflect common slips (student forgets to take both components).', 'HARD', 'Physics', 'Newton''s Laws of Motion & Friction', 'PHY_LAWS', '[{"option_text": "μ_k = cos θ", "is_correct": false}, {"option_text": "μ_k = tan θ", "is_correct": true}, {"option_text": "μ_k = sin θ", "is_correct": false}, {"option_text": "μ_k = 1/sin θ", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('11d7fce4-30ec-5fc7-806c-42a65771efa3', 'Which of the following is the CORRECT description of Galileo''s contribution to the study of motion, later formalised by Newton?', NULL, 'Galileo''s famous (possibly apocryphal) Leaning Tower of Pisa experiment and his inclined-plane experiments showed that heavier and lighter bodies fall with the SAME acceleration when air resistance is negligible — refuting the Aristotelian view that heavier bodies fall faster (option A, which Galileo DISPROVED). This was foundational for Newton''s First and Second Laws. Newton and Leibniz independently invented calculus (not Galileo). Newton''s universal law of gravitation came later in Principia (1687). A classic 1971 demonstration: Apollo 15 astronaut Dave Scott dropped a hammer and feather on the airless Moon — they hit the surface simultaneously.', 'MEDIUM', 'Physics', 'Newton''s Laws of Motion & Friction', 'PHY_LAWS', '[{"option_text": "Galileo proved that heavier bodies fall faster than lighter ones", "is_correct": false}, {"option_text": "Galileo showed that in the ABSENCE of air resistance, all bodies fall with the same acceleration", "is_correct": true}, {"option_text": "Galileo invented the calculus used to derive F = ma", "is_correct": false}, {"option_text": "Galileo discovered the universal law of gravitation", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('32450131-7d0a-57fa-94e3-f77afcf11628', 'Which of the following scenarios INCREASES friction, useful in many practical applications?', NULL, 'Treaded tyres and soled shoes INCREASE friction — critical for vehicle braking/cornering and for walking without slipping on wet surfaces. Options A (lubrication), B (polishing), and D (ball-bearings — which convert sliding to rolling friction) all DECREASE friction. A balanced understanding of friction recognises both: we WANT friction for driving/walking, BUT also want to REDUCE it in moving engine parts and bearings. Treads work by channeling water away from the contact patch, preventing hydroplaning. Racing slicks (no treads) have MORE rubber-on-road contact in dry conditions — a specialized case — but are illegal in rain.', 'EASY', 'Physics', 'Newton''s Laws of Motion & Friction', 'PHY_LAWS', '[{"option_text": "Lubrication of machine parts with oil", "is_correct": false}, {"option_text": "Polishing a surface to be smooth", "is_correct": false}, {"option_text": "Using treaded tyres on vehicles and grooves on shoe soles", "is_correct": true}, {"option_text": "Using ball-bearings in the wheels of a car", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0089e30d-b135-52f5-99be-e6352cbaf50f', 'A car starts from rest and accelerates uniformly at 2 m/s² for 10 seconds. What is the distance covered by the car in this time?', NULL, 'Use s = ut + ½at². Given: u = 0 (rest), a = 2 m/s², t = 10 s. So s = 0·10 + ½·(2)·(10)² = ½·2·100 = 100 m. Distractor 50 m comes from forgetting the ''half'' factor; 200 m from omitting the ½ and doubling; 150 m from adding an extra velocity term.', 'EASY', 'Physics', 'Motion in 1D & 2D', 'PHY_MOTION', '[{"option_text": "50 m", "is_correct": false}, {"option_text": "100 m", "is_correct": true}, {"option_text": "150 m", "is_correct": false}, {"option_text": "200 m", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e4ac6819-2144-5e9a-a7aa-ce9f35d7a07c', 'A body thrown vertically upward with an initial velocity of 20 m/s reaches a maximum height of (g = 10 m/s²):', NULL, 'At max height, final velocity v = 0. Using v² = u² − 2gh: 0 = (20)² − 2·10·h → h = 400/20 = 20 m. A classic shortcut: h_max = u²/(2g) = 400/20 = 20 m. 40 m comes from forgetting the factor of 2; 10 m from dividing by 40 instead of 20; 100 m from using the wrong formula.', 'EASY', 'Physics', 'Motion in 1D & 2D', 'PHY_MOTION', '[{"option_text": "10 m", "is_correct": false}, {"option_text": "20 m", "is_correct": true}, {"option_text": "40 m", "is_correct": false}, {"option_text": "100 m", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a93d7838-b229-5dfb-bbd3-d0e09e0cb0b6', 'A train moving at 72 km/h comes to rest in 20 seconds. What is its deceleration?', NULL, 'Convert 72 km/h to m/s: 72 × (5/18) = 20 m/s. Use v = u + at: 0 = 20 + a·20 → a = −1 m/s². So the deceleration is 1 m/s². Key trap: if you forgot to convert km/h to m/s, you''d get 72/20 = 3.6 (distractor D). 0.5 m/s² arises from a sign/arithmetic error.', 'EASY', 'Physics', 'Motion in 1D & 2D', 'PHY_MOTION', '[{"option_text": "0.5 m/s²", "is_correct": false}, {"option_text": "1 m/s²", "is_correct": true}, {"option_text": "2 m/s²", "is_correct": false}, {"option_text": "3.6 m/s²", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('509623be-86a2-56af-855d-2874bce3fe49', 'A body falls freely from the top of a tower. If it covers 45 m in the last second of its fall, the height of the tower is (g = 10 m/s²):', NULL, 'Distance covered in the n-th second (from rest): s_n = u + (a/2)(2n−1). With u = 0, a = g = 10: s_n = 5(2n−1). Given s_n = 45: 5(2n−1) = 45 → 2n−1 = 9 → n = 5 s (total fall time). Total height: H = ½·g·t² = ½·10·25 = 125 m. 180 m results if you wrongly add an extra 5; 80 m comes from miscounting seconds; 245 m from using t = 7.', 'HARD', 'Physics', 'Motion in 1D & 2D', 'PHY_MOTION', '[{"option_text": "80 m", "is_correct": false}, {"option_text": "125 m", "is_correct": true}, {"option_text": "180 m", "is_correct": false}, {"option_text": "245 m", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ff9796fa-64a5-5a96-9c67-1d375c442105', 'A projectile is launched at an angle of 45° with a velocity of 20 m/s. What is the horizontal range? (g = 10 m/s²)', NULL, 'Range formula: R = (u² sin 2θ)/g. With u = 20, θ = 45° (so sin 90° = 1), g = 10: R = (400·1)/10 = 40 m. The maximum range for a given speed occurs at 45°, so this formula peaks here. 20 m would correspond to θ = 15° or 75°; 50 m comes from mis-substituting u = 25; 80 m from doubling erroneously.', 'MEDIUM', 'Physics', 'Motion in 1D & 2D', 'PHY_MOTION', '[{"option_text": "20 m", "is_correct": false}, {"option_text": "40 m", "is_correct": true}, {"option_text": "50 m", "is_correct": false}, {"option_text": "80 m", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ad231e83-6623-51e0-aa23-6e0b3dc35593', 'Two cars start from the same point. Car A travels 40 km north and then 30 km east. Car B travels directly to A''s final position. What distance does Car B travel?', NULL, 'Car A''s displacement from origin: 40 km N + 30 km E. Net displacement = √(40² + 30²) = √(1600 + 900) = √2500 = 50 km. Car B travels this straight-line distance. 70 km is Car A''s TOTAL path distance (40 + 30) — a common distance vs. displacement trap. 35 km and 60 km result from incorrect Pythagorean arithmetic.', 'EASY', 'Physics', 'Motion in 1D & 2D', 'PHY_MOTION', '[{"option_text": "35 km", "is_correct": false}, {"option_text": "50 km", "is_correct": true}, {"option_text": "60 km", "is_correct": false}, {"option_text": "70 km", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('021da1d2-541e-5cef-9bcd-acb44f6d5270', 'The velocity-time graph of a body shows a straight line with a positive slope passing through the origin. This means:', NULL, 'Slope of v-t graph = acceleration. A constant positive slope means uniform acceleration (a = constant). Passing through origin means at t = 0, v = 0 (started from rest). Uniform velocity would give a horizontal line (slope = 0). Increasing acceleration gives a CURVE with increasing slope, not a straight line. Deceleration gives a negative slope.', 'MEDIUM', 'Physics', 'Motion in 1D & 2D', 'PHY_MOTION', '[{"option_text": "The body moves with uniform velocity", "is_correct": false}, {"option_text": "The body moves with uniform acceleration starting from rest", "is_correct": true}, {"option_text": "The body moves with increasing acceleration", "is_correct": false}, {"option_text": "The body decelerates uniformly", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('dd5f09c2-e27e-5fab-80b3-864b718348db', 'A stone is thrown horizontally from the top of a 45-m-high cliff with a velocity of 20 m/s. How far from the base of the cliff does it land? (g = 10 m/s²)', NULL, 'Horizontal projectile. Time to fall: use h = ½g·t² → 45 = ½·10·t² → t² = 9 → t = 3 s. Horizontal distance = u·t = 20·3 = 60 m. 30 m is u/g·h = wrong formula mix; 90 m comes from t = 4.5 (wrong); 120 m from t = 6 (wrong). Horizontal velocity stays 20 m/s throughout; only vertical motion is accelerated.', 'MEDIUM', 'Physics', 'Motion in 1D & 2D', 'PHY_MOTION', '[{"option_text": "30 m", "is_correct": false}, {"option_text": "60 m", "is_correct": true}, {"option_text": "90 m", "is_correct": false}, {"option_text": "120 m", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('740e087f-5144-52b5-81c5-7d01338a1454', 'A body moving in a circle of radius r with constant speed v has:', NULL, 'In uniform circular motion, speed is constant but velocity (a vector) constantly changes DIRECTION. This requires acceleration — specifically centripetal (center-seeking) acceleration a = v²/r directed radially inward. Tangential acceleration would exist only if speed were changing. Magnitude of velocity constant ≠ zero acceleration; zero acceleration would require straight-line motion.', 'MEDIUM', 'Physics', 'Motion in 1D & 2D', 'PHY_MOTION', '[{"option_text": "Zero acceleration", "is_correct": false}, {"option_text": "Centripetal acceleration v²/r directed towards the center", "is_correct": true}, {"option_text": "Tangential acceleration v²/r", "is_correct": false}, {"option_text": "Linear acceleration that increases with time", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('429ab884-9c96-5097-89da-4fe1b58d8f2f', 'A car covers the first half of a journey at 40 km/h and the second half at 60 km/h. The average speed for the whole journey is:', NULL, 'For equal DISTANCES at different speeds, average speed = harmonic mean = 2v₁v₂/(v₁+v₂) = (2·40·60)/(40+60) = 4800/100 = 48 km/h. Common mistake: computing arithmetic mean (40+60)/2 = 50 km/h — WRONG because time spent at each speed is different (slower leg takes longer). The harmonic mean handles this correctly.', 'MEDIUM', 'Physics', 'Motion in 1D & 2D', 'PHY_MOTION', '[{"option_text": "48 km/h", "is_correct": true}, {"option_text": "50 km/h", "is_correct": false}, {"option_text": "52 km/h", "is_correct": false}, {"option_text": "55 km/h", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('accd63d1-38dc-5939-ac2d-d770b8d6440f', 'A ball is dropped from a height of 20 m. With what velocity does it hit the ground? (g = 10 m/s²)', NULL, 'Use v² = u² + 2gh with u = 0, g = 10, h = 20: v² = 0 + 2·10·20 = 400 → v = √400 = 20 m/s. 400 m/s is the FORGETTING-THE-SQUARE-ROOT trap. 40 m/s comes from v = √(2gh) computed as v = 2gh. 10 m/s is the velocity after 1 s of free fall, a partial calculation.', 'EASY', 'Physics', 'Motion in 1D & 2D', 'PHY_MOTION', '[{"option_text": "10 m/s", "is_correct": false}, {"option_text": "20 m/s", "is_correct": true}, {"option_text": "40 m/s", "is_correct": false}, {"option_text": "400 m/s", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('49cf94f6-4a2d-5987-b306-8ace0d3fd647', 'Which of the following is a scalar quantity?', NULL, 'Scalar = magnitude only; vector = magnitude + direction. Speed is the magnitude of velocity — a scalar. Displacement, velocity, and acceleration are all vectors (they have direction). Other scalars: distance, mass, time, energy, temperature. Other vectors: force, momentum, torque, electric field.', 'EASY', 'Physics', 'Motion in 1D & 2D', 'PHY_MOTION', '[{"option_text": "Displacement", "is_correct": false}, {"option_text": "Velocity", "is_correct": false}, {"option_text": "Speed", "is_correct": true}, {"option_text": "Acceleration", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0ad8f45c-947b-57f0-8df3-88feac6019e7', 'Under which Article of the Indian Constitution is the office of the Attorney General of India established?', NULL, 'Article 76 of the Constitution provides for the appointment of the Attorney General of India — the highest law officer of the country. Article 75 deals with the appointment of the PM and Council of Ministers; Article 148 deals with the CAG; Article 165 establishes the office of the Advocate General for States — the three most common distractors for this question.', 'EASY', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "Article 75", "is_correct": false}, {"option_text": "Article 76", "is_correct": true}, {"option_text": "Article 148", "is_correct": false}, {"option_text": "Article 165", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('def658c1-7f70-5f9d-880d-b558453e1ced', 'Who appoints the Attorney General of India?', NULL, 'Under Article 76(1), the Attorney General is appointed by the President — who, per Article 74, acts on the aid and advice of the Union Council of Ministers (effectively the Cabinet). The CJI has no role; Parliament does not elect the AG; the PM recommends through the Cabinet rather than independently.', 'EASY', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "The Chief Justice of India", "is_correct": false}, {"option_text": "The Parliament by a special majority", "is_correct": false}, {"option_text": "The President of India on the advice of the Union Cabinet", "is_correct": true}, {"option_text": "The Prime Minister in consultation with the Law Minister", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f627f2f1-4744-5a4f-ac71-dc0e85e31e9b', 'What qualification is required for appointment as the Attorney General of India, as per Article 76?', NULL, 'Article 76(1) requires that a person must be qualified to be appointed a judge of the Supreme Court — i.e., be a citizen of India, and either have been a HC judge for 5 years, an HC advocate for 10 years, or be a distinguished jurist in the President''s opinion. The AG need not currently be a judge, and there is no fixed year requirement for practice.', 'MEDIUM', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "Must be qualified for appointment as a judge of a High Court", "is_correct": false}, {"option_text": "Must be qualified for appointment as a judge of the Supreme Court", "is_correct": true}, {"option_text": "Must have at least 15 years of practice in the Supreme Court", "is_correct": false}, {"option_text": "Must be a sitting or retired judge of the Supreme Court", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('dbb94e48-3e97-5701-9d26-bfe371bd4d77', 'What is the term of office of the Attorney General of India?', NULL, 'The Constitution does not fix a term for the AG. Article 76(4) states the AG holds office ''during the pleasure of the President''. In practice, the AG resigns when the government that appointed them changes. Fixed 6-year/65-year terms apply to the CAG, not the AG. The AG''s tenure is NOT tied to the Lok Sabha.', 'MEDIUM', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "6 years or till 65 years of age, whichever is earlier", "is_correct": false}, {"option_text": "5 years, co-terminus with the Lok Sabha", "is_correct": false}, {"option_text": "Not fixed by the Constitution; holds office during the pleasure of the President", "is_correct": true}, {"option_text": "Till 62 years of age", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8e1f0340-e8d6-5afe-bbfc-1daddee3aacb', 'Which of the following is NOT a duty of the Attorney General of India under Article 76?', NULL, 'Article 76(2) lists three duties — legal advice, assigned legal duties, and constitutional/statutory functions. Prosecution of government servants in corruption cases is handled by the CBI under the Prevention of Corruption Act, not by the AG. The AG is counsel for the government, not a prosecutor of its employees.', 'MEDIUM', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "Give advice to the Government of India on legal matters referred to him", "is_correct": false}, {"option_text": "Perform such other duties of a legal character as assigned by the President", "is_correct": false}, {"option_text": "Discharge the functions conferred on him by or under the Constitution or any other law", "is_correct": false}, {"option_text": "Prosecute government servants in criminal cases of corruption", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0d9adba4-545d-5fad-920c-04fa365447c6', 'Which of the following rights does the Attorney General of India enjoy with respect to Parliament?', NULL, 'Article 88 gives the Attorney General the right to speak in and take part in the proceedings of either House of Parliament, any joint sitting, and any parliamentary committee of which he may be named a member — WITHOUT the right to vote. This parallels the same right extended to Ministers (Article 88). The AG is NOT a Member of Parliament.', 'MEDIUM', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "Right to vote in both Houses", "is_correct": false}, {"option_text": "Right to speak and take part in proceedings of both Houses and their committees, but not to vote", "is_correct": true}, {"option_text": "Right to introduce bills in the Lok Sabha only", "is_correct": false}, {"option_text": "No rights — AG is an executive officer only", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('07ba73b2-ff52-5f7e-8e57-91ef350a2624', 'Which of the following statements about the Attorney General of India''s private practice is correct?', NULL, 'The AG is NOT a full-time salaried government servant. He retains the right to private practice but — as per conventions and the 1987 Law Commission note — cannot advise or hold brief against the Government of India, or against any PSU/statutory body where the GoI is also a party, or defend an accused in criminal proceedings without government permission. This distinguishes the AG from full-time officers like the Solicitor General of earlier decades.', 'HARD', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "The AG is barred from all private practice during the term of office", "is_correct": false}, {"option_text": "The AG can engage in private practice, but cannot advise or brief against the Government of India", "is_correct": true}, {"option_text": "The AG can appear against the Government of India but cannot accept private corporate work", "is_correct": false}, {"option_text": "The AG can take only international arbitration work privately", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fb5729a4-bfb2-5677-80f2-0ec25e26a50e', 'Who, among the following, ranks immediately below the Attorney General in the hierarchy of Government law officers?', NULL, 'The order is: Attorney General → Solicitor General → Additional Solicitors General → Standing/Panel counsels. The Solicitor General (and the Additional SGs) are statutory posts, unlike the AG which is constitutional. The Secretary of Legal Affairs is an administrative post in the Ministry of Law & Justice, not a ''law officer''.', 'EASY', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "Additional Solicitor General", "is_correct": false}, {"option_text": "Solicitor General of India", "is_correct": true}, {"option_text": "Standing Counsel for the Government", "is_correct": false}, {"option_text": "Secretary, Department of Legal Affairs", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0fcd014c-6927-5be7-9f7b-fdd3e645003a', 'Under Article 143 of the Constitution, the President may refer a question of law to the Supreme Court for its advisory opinion. In such a reference, who typically represents the Government of India?', NULL, 'Presidential References under Article 143 are argued before the Supreme Court, and the Government of India is represented by the Attorney General as its chief law officer. Examples: Berubari Union Reference (1960), Kerala Education Bill Reference (1958), 2G Spectrum Reference (2012), Ayodhya Reference (1993) — AG led submissions in each. The CJI presides; he doesn''t represent a party.', 'MEDIUM', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "The Prime Minister''s Office''s Legal Cell", "is_correct": false}, {"option_text": "The Attorney General of India", "is_correct": true}, {"option_text": "The Law Minister personally", "is_correct": false}, {"option_text": "The Chief Justice of India", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6a8af5f2-2fa2-576e-8d3f-05b8c5f8eeac', 'Who was the first Attorney General of India after the Constitution came into force on 26 January 1950?', NULL, 'Motilal Chimanlal Setalvad — commonly written as M. C. Setalvad — served as the first Attorney General of India from 1950 to 1963, the longest tenure in the history of the office (13 years). ''Motilal Setalvad'' (option C) is a redundant phrasing of the same name and is treated as a distractor. C. K. Daphtary succeeded him in 1963. H. M. Seervai was a jurist and Advocate General of Maharashtra, never AG of India.', 'MEDIUM', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "C. K. Daphtary", "is_correct": false}, {"option_text": "M. C. Setalvad", "is_correct": true}, {"option_text": "Motilal Setalvad", "is_correct": false}, {"option_text": "H. M. Seervai", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('33d58239-515a-583d-96b0-acc388fa6564', 'The Advocate General of a State is provided for under which Article of the Constitution?', NULL, 'Article 165 establishes the office of the Advocate General for each State — the highest law officer at the State level, paralleling the Attorney General at the Union level. Article 76 is for the AG (Union). Article 148 covers the CAG. Article 213 empowers the Governor to promulgate ordinances, not a law-officer position.', 'EASY', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "Article 76", "is_correct": false}, {"option_text": "Article 148", "is_correct": false}, {"option_text": "Article 165", "is_correct": true}, {"option_text": "Article 213", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('14c7f4e4-c957-55f7-8363-4bdd68f21407', 'Who appoints the Advocate General of a State, and whose pleasure does he hold office during?', NULL, 'Under Article 165, the Governor appoints the Advocate General for the State, who holds office during the Governor''s pleasure. The Governor acts on the advice of the State Council of Ministers (Article 163). Unlike the CAG, there is no fixed retirement age for the Advocate General. The President has no role — this is a State-level office.', 'EASY', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "Appointed by the President; holds office at the pleasure of the President", "is_correct": false}, {"option_text": "Appointed by the Governor; holds office during the pleasure of the Governor", "is_correct": true}, {"option_text": "Appointed by the Chief Minister; holds office till 65 years of age", "is_correct": false}, {"option_text": "Elected by the State Legislature for a 5-year term", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('261ba009-0ae3-5b29-9da3-9da3563523f5', 'What is the qualification required for appointment as Advocate General of a State?', NULL, 'Article 165(1) states the Advocate General must be qualified to be appointed a judge of a High Court — i.e., a citizen of India who has held a judicial office for 10 years or been an advocate of an HC for 10 years. This is a LESSER threshold than that for the Attorney General (who needs SC judge eligibility — 5 years HC judge or 10 years HC advocate). The AG role is never political.', 'MEDIUM', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "Must be qualified to be appointed a judge of the Supreme Court", "is_correct": false}, {"option_text": "Must be qualified to be appointed a judge of a High Court", "is_correct": true}, {"option_text": "Must have at least 20 years of legal practice in the State", "is_correct": false}, {"option_text": "Must be a sitting MP/MLA of the ruling party in the State", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('93232685-ec04-51ad-8839-40a3abe51233', 'Which of the following rights does the Advocate General of a State enjoy under the Constitution?', NULL, 'Article 177 gives the Advocate General the right to speak in and take part in proceedings of both Houses of the State Legislature (where bicameral) and their committees — WITHOUT voting. This parallels Article 88 for the AG at the Union level. He has no role in Parliament (Union), no voting rights, and cannot introduce any bill.', 'MEDIUM', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "Right to speak in both Houses of Parliament and vote on bills affecting his State", "is_correct": false}, {"option_text": "Right to speak and take part in proceedings of the State Legislature and its committees, without voting", "is_correct": true}, {"option_text": "Right to vote in the State Legislative Assembly on Money Bills", "is_correct": false}, {"option_text": "Right to introduce Finance Bills in the Legislative Assembly", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2b552d7f-0d1f-5f87-9697-5b62bd9e99b4', 'Who among the following is called the ''second law officer'' of the Government of India?', NULL, 'The Solicitor General of India is conventionally referred to as the ''second law officer'' after the Attorney General. The SG is a statutory post (under the Law Officers (Conditions of Service) Rules, 1987), unlike the constitutional AG. ''Additional Attorney General'' is not an office that exists — Additional Solicitors General do exist, ranked below the SG. There is no ''Advocate General of Delhi'' post for the Union.', 'EASY', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "Additional Attorney General", "is_correct": false}, {"option_text": "Solicitor General of India", "is_correct": true}, {"option_text": "Advocate General of Delhi", "is_correct": false}, {"option_text": "Secretary, Department of Justice", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('919f8df7-7e2a-520b-a5f4-c6e4f3be5668', 'The remuneration of the Attorney General of India is determined by which authority?', NULL, 'Article 76(4) states the Attorney General shall receive ''such remuneration as the President may determine''. Unlike CAG or judges — whose salaries are fixed by Parliament by law — the AG''s remuneration is fixed administratively by the President (in practice, through the Ministry of Law & Justice). It is charged on the Consolidated Fund of India (so not subject to legislative vote).', 'MEDIUM', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "It is fixed by the Constitution under Article 76", "is_correct": false}, {"option_text": "It is determined by the President", "is_correct": true}, {"option_text": "It is fixed by the Parliament through a law", "is_correct": false}, {"option_text": "It is fixed by the Supreme Court rules", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d0f513e6-a728-507f-8497-76a3f9f2492c', 'Which of the following statements about the Attorney General is INCORRECT?', NULL, 'The AG is NOT a member of the Union Cabinet. The Cabinet consists only of Ministers. The AG is a legal officer of the government — he can attend Cabinet meetings by invitation on legal matters, but is not a Minister. The other three statements are correct: the AG has pan-India audience rights, can represent the Union in any court, and his salary is charged (non-votable) on the CFI.', 'HARD', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "The AG has the right of audience in all courts of India", "is_correct": false}, {"option_text": "The AG is a member of the Union Cabinet", "is_correct": true}, {"option_text": "The AG can be called upon to represent the Union in any court in India", "is_correct": false}, {"option_text": "The AG''s salary is charged on the Consolidated Fund of India", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('86a03628-9a75-5557-91b4-ca9674c62d03', 'Who was the Attorney General of India who served during the Emergency (1975–77) and signed the controversial ADM Jabalpur case affidavit on behalf of the government?', NULL, 'Niren De served as AG of India from 1968 to 1977 (under Indira Gandhi). He is best remembered for his controversial submission in the ADM Jabalpur v. Shivkant Shukla (1976) habeas corpus case during the Emergency, where he argued that a person whose fundamental right to life (Article 21) was suspended had no remedy — a position the SC later overruled in Puttaswamy (2017). M. C. Setalvad was the FIRST AG; S. V. Gupte (1977–79) succeeded De after Janata Party took office; L. N. Sinha served 1979–83.', 'HARD', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "M. C. Setalvad", "is_correct": false}, {"option_text": "Niren De", "is_correct": true}, {"option_text": "S. V. Gupte", "is_correct": false}, {"option_text": "L. N. Sinha", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('296a6e66-966e-5919-8d4f-75bfc806fe58', 'Consider the following statements about the Attorney General of India: 1) He can appear on behalf of the Government of India in any court, including a State High Court. 2) He can be removed only by a two-thirds majority of Parliament. 3) He is ex-officio member of certain Committees of Parliament. Which of the above is/are correct?', NULL, 'Statement 1 is CORRECT — the AG has audience rights in every court in India (Article 76(3)). Statement 2 is WRONG — the AG holds office ''during the pleasure of the President'' (Article 76(4)); there is no two-thirds removal procedure (that''s for judges under Article 124/217). Statement 3 is WRONG — the AG is NOT an ex-officio member of any Parliamentary Committee unless specifically nominated under Rule 255 of the Rules of Procedure. Hence only Statement 1.', 'HARD', 'Polity', 'Attorney & Advocate General', 'POL_AG', '[{"option_text": "1 only", "is_correct": true}, {"option_text": "1 and 2 only", "is_correct": false}, {"option_text": "2 and 3 only", "is_correct": false}, {"option_text": "1, 2 and 3", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('55730c82-6226-5bb7-8169-d3f50265bbcf', 'Under which Article of the Constitution is the office of the Comptroller and Auditor General (CAG) of India established?', NULL, 'Article 148 establishes the office of the Comptroller and Auditor General of India. Article 124 deals with the Supreme Court; Article 280 with the Finance Commission; Article 324 with the Election Commission. The CAG is a CONSTITUTIONAL authority, described by Dr. Ambedkar as ''the most important officer under the Constitution of India''.', 'EASY', 'Polity', 'Comptroller and Auditor General (CAG)', 'POL_CAG', '[{"option_text": "Article 124", "is_correct": false}, {"option_text": "Article 148", "is_correct": true}, {"option_text": "Article 280", "is_correct": false}, {"option_text": "Article 324", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6d4d33ee-471d-56fe-89af-c74a74741656', 'The CAG is appointed by which of the following?', NULL, 'Article 148(1): The CAG is appointed by the President by warrant under his hand and seal. The President acts on the advice of the Cabinet. There is no collegium or Parliamentary selection involved — making it an executive appointment, though the removal procedure provides judicial-level security of tenure.', 'EASY', 'Polity', 'Comptroller and Auditor General (CAG)', 'POL_CAG', '[{"option_text": "The Prime Minister", "is_correct": false}, {"option_text": "The President of India by warrant under his hand and seal", "is_correct": true}, {"option_text": "A collegium of Supreme Court judges", "is_correct": false}, {"option_text": "The Parliament by a special majority", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2b876826-142f-5c3d-8ac3-cf9fe1ab325a', 'What is the term of office of the CAG?', NULL, 'Per the CAG''s (Duties, Powers and Conditions of Service) Act, 1971: term is 6 years or until 65 years of age, whichever is earlier. He can resign at any time by addressing the letter to the President. After retirement, he is NOT eligible for any further office under the Union or State governments — a safeguard for independence.', 'MEDIUM', 'Polity', 'Comptroller and Auditor General (CAG)', 'POL_CAG', '[{"option_text": "5 years or 65 years of age, whichever is earlier", "is_correct": false}, {"option_text": "6 years or 65 years of age, whichever is earlier", "is_correct": true}, {"option_text": "7 years or 67 years of age, whichever is earlier", "is_correct": false}, {"option_text": "Until retirement at 62 years", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a360938e-243d-546a-acff-22d99a0c667c', 'How can the CAG be removed from office?', NULL, 'Article 148(1) + 124(4): The CAG can be removed in the same manner as a Supreme Court judge — on grounds of proved misbehaviour or incapacity, by an order of the President, after an address by each House of Parliament supported by a majority of the total membership AND a two-thirds majority of members present & voting. This stringent procedure ensures independence. He does NOT hold office at the President''s pleasure.', 'MEDIUM', 'Polity', 'Comptroller and Auditor General (CAG)', 'POL_CAG', '[{"option_text": "By the President at his pleasure", "is_correct": false}, {"option_text": "In the same manner and on the same grounds as a Supreme Court judge", "is_correct": true}, {"option_text": "By a simple majority in Parliament", "is_correct": false}, {"option_text": "By the Prime Minister with the President''s approval", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('00ce6f0e-e948-547c-bea9-fe9ce997f179', 'The salary and conditions of service of the CAG are:', NULL, 'Article 148(3): Salary and other conditions of service of the CAG shall be such as may be determined by Parliament by law. Under the CAG Act 1971, the CAG receives a salary equal to that of a Supreme Court judge. Importantly, the salary is CHARGED on the Consolidated Fund of India — meaning it is not subject to vote in Parliament (a safeguard against legislative pressure).', 'MEDIUM', 'Polity', 'Comptroller and Auditor General (CAG)', 'POL_CAG', '[{"option_text": "Determined by the President", "is_correct": false}, {"option_text": "Determined by Parliament; charged on the Consolidated Fund of India", "is_correct": true}, {"option_text": "Determined by the Finance Commission", "is_correct": false}, {"option_text": "Linked to the pay scale of a Union Minister", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('385b9577-fffa-57d0-adc2-17876be20a38', 'The CAG submits his audit reports relating to Union accounts to:', NULL, 'Article 151(1): CAG''s reports relating to the accounts of the Union are submitted to the President, who causes them to be laid before each House of Parliament. State reports go to the respective Governor. The Public Accounts Committee (PAC) of Parliament then examines the reports — making the CAG''s work a fundamental pillar of Parliament''s financial accountability over the executive.', 'MEDIUM', 'Polity', 'Comptroller and Auditor General (CAG)', 'POL_CAG', '[{"option_text": "The Prime Minister", "is_correct": false}, {"option_text": "The President, who causes them to be laid before each House of Parliament", "is_correct": true}, {"option_text": "The Lok Sabha Speaker directly", "is_correct": false}, {"option_text": "The Finance Minister", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2374306f-8607-5b37-b106-86ebb7ce273a', 'Dr. B. R. Ambedkar described the CAG as:', NULL, 'During the Constituent Assembly debates, Dr. Ambedkar famously said the CAG ''is probably the most important officer under the Constitution of India'', ranking the office alongside the Supreme Court and the Election Commission for safeguarding constitutional democracy. ''Guardian of the public purse'' is a description often used for the PAC, not specifically by Ambedkar for the CAG.', 'MEDIUM', 'Polity', 'Comptroller and Auditor General (CAG)', 'POL_CAG', '[{"option_text": "''The financial conscience of the nation''", "is_correct": false}, {"option_text": "''The most important officer under the Constitution of India''", "is_correct": true}, {"option_text": "''The guardian of the public purse''", "is_correct": false}, {"option_text": "''The eye of Parliament''", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1bac8162-ebce-5648-a6cf-26b118fef62d', 'Which of the following types of audit does the CAG perform?', NULL, 'CAG''s audits include: (1) FINANCIAL/REGULARITY audit — whether money was spent in accordance with the budget and rules; (2) COMPLIANCE audit — whether expenditure followed legal/constitutional provisions; (3) PERFORMANCE audit — whether government programmes achieved intended objectives with economy, efficiency, and effectiveness (examples: 2G Spectrum, CWG, CoalGate audits). All three are integral parts of CAG''s mandate.', 'MEDIUM', 'Polity', 'Comptroller and Auditor General (CAG)', 'POL_CAG', '[{"option_text": "Only financial (regularity) audit", "is_correct": false}, {"option_text": "Only compliance audit", "is_correct": false}, {"option_text": "Financial/Regularity audit, Compliance audit, AND Performance audit", "is_correct": true}, {"option_text": "Only performance audit", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6c8093e8-488a-5408-bd5f-4ca0f00732c6', 'After retirement, which of the following offices is the CAG prohibited from holding?', NULL, 'Article 148(4) / CAG Act 1971: After retirement, the CAG shall not be eligible for any further office either under the Government of India or under any State Government. This is intended to prevent the incumbent from being influenced during tenure by post-retirement job prospects. International/UN posts, private academic posts, and private arbitration are NOT prohibited (e.g., former CAG Vinod Rai became chair of the BCCI''s Committee of Administrators, appointed by the SC, not the government).', 'MEDIUM', 'Polity', 'Comptroller and Auditor General (CAG)', 'POL_CAG', '[{"option_text": "Any post under the Government of India or any State", "is_correct": true}, {"option_text": "Any academic post in a private university", "is_correct": false}, {"option_text": "Any position in an international organisation like the UN", "is_correct": false}, {"option_text": "Any role as an arbitrator in civil disputes", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e6726e3b-3d2c-56da-b5d9-1ec02d3e4719', 'The audit of accounts of Public Sector Undertakings (PSUs) is conducted by the CAG under which provision?', NULL, 'CAG''s audit role for PSUs varies by structure: (a) for DEPARTMENTAL COMMERCIAL UNDERTAKINGS (e.g., Railways), CAG is the SOLE auditor; (b) for STATUTORY CORPORATIONS (e.g., LIC pre-2000, ONGC pre-1976), CAG''s role depends on the enabling Act — sole, supplementary, or by arrangement; (c) for GOVERNMENT COMPANIES under Companies Act 2013 (Section 143(5)), CAG appoints the CA auditor and can conduct supplementary/test audits. So CAG''s role is nuanced, not a one-size-fits-all.', 'HARD', 'Polity', 'Comptroller and Auditor General (CAG)', 'POL_CAG', '[{"option_text": "Sole auditor under Section 139 of the Companies Act 2013", "is_correct": false}, {"option_text": "Sole auditor, Supplementary auditor, or Auditor by arrangement, depending on the PSU''s structure", "is_correct": true}, {"option_text": "Only an advisor to the private auditors of PSUs", "is_correct": false}, {"option_text": "No role — PSUs are audited only by chartered-accountant firms", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('06d992b9-e465-57bc-9565-ad1df5a8a8df', 'Who was the first Comptroller and Auditor General of India after independence?', NULL, 'V. Narahari Rao served as the first CAG of independent India from 1948 to 1954. He was instrumental in setting up the Indian Audit and Accounts Service structure. A. K. Roy succeeded him (1954–60). K. Sankar Aiyar served later (1960–66). The current CAG (as of 2026) is Girish Chandra Murmu, who took office in August 2020 for a 6-year term.', 'HARD', 'Polity', 'Comptroller and Auditor General (CAG)', 'POL_CAG', '[{"option_text": "V. Narahari Rao", "is_correct": true}, {"option_text": "A. K. Roy", "is_correct": false}, {"option_text": "K. Sankar Aiyar", "is_correct": false}, {"option_text": "T. V. Ramanathan", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ce140345-f9c2-5259-bdb2-5b973c87e662', 'Which Part and Articles of the Indian Constitution deal with Citizenship?', NULL, 'Citizenship is covered in Part II of the Constitution, comprising Articles 5 to 11. Part I (Articles 1–4) deals with the Union and its territories; Part III (Articles 12–35) covers Fundamental Rights; Part IV covers the Directive Principles of State Policy — common distractor choices students mix up.', 'EASY', 'Polity', 'Citizenship', 'POL_CITIZENSHIP', '[{"option_text": "Part I, Articles 1–4", "is_correct": false}, {"option_text": "Part II, Articles 5–11", "is_correct": true}, {"option_text": "Part III, Articles 12–35", "is_correct": false}, {"option_text": "Part IV, Articles 36–51", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cdb5dfda-0cd1-5052-9584-84de9404abf1', 'Under the Citizenship Act, 1955, which of the following is NOT a recognised mode of acquiring Indian citizenship?', NULL, 'The 1955 Act recognises FIVE modes of acquisition: by birth, by descent, by registration, by naturalisation, and by incorporation of territory. ''Citizenship by investment'' (a concept used by some Caribbean states) has NO place in Indian law. This is the intended ''exception'' framing — the distractors name real modes.', 'EASY', 'Polity', 'Citizenship', 'POL_CITIZENSHIP', '[{"option_text": "Citizenship by birth", "is_correct": false}, {"option_text": "Citizenship by descent", "is_correct": false}, {"option_text": "Citizenship by investment", "is_correct": true}, {"option_text": "Citizenship by naturalisation", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('35433993-465f-5f07-9da3-602369b339f4', 'Arrange the following Citizenship Amendment Acts in the correct chronological order of enactment: (I) 2019, (II) 2003, (III) 1986, (IV) 1992', NULL, 'Correct chronology: 1986 (III, tightened citizenship-by-birth requirements after the Assam Accord) → 1992 (IV, permitted citizenship by descent through mothers, not only fathers) → 2003 (II, introduced the concept of Overseas Citizen of India and National Register of Citizens) → 2019 (I, CAA providing expedited citizenship to persecuted religious minorities from Afghanistan/Bangladesh/Pakistan). The distractors shuffle these.', 'HARD', 'Polity', 'Citizenship', 'POL_CITIZENSHIP', '[{"option_text": "III → IV → II → I", "is_correct": true}, {"option_text": "IV → III → II → I", "is_correct": false}, {"option_text": "III → II → IV → I", "is_correct": false}, {"option_text": "II → III → IV → I", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3ee02feb-1217-57cd-9af7-e9af27a8303e', 'Which Article of the Indian Constitution empowers Parliament to make any provision with respect to the acquisition, termination and all other matters relating to citizenship?', NULL, 'Article 11 grants Parliament plenary power over citizenship matters — the Citizenship Act 1955 and all subsequent amendments draw their authority from this provision. Article 5 lays down criteria for citizenship at the Constitution''s commencement. Article 9 says persons voluntarily acquiring foreign citizenship cease to be Indian citizens. Article 13 deals with laws inconsistent with Fundamental Rights — unrelated.', 'MEDIUM', 'Polity', 'Citizenship', 'POL_CITIZENSHIP', '[{"option_text": "Article 5", "is_correct": false}, {"option_text": "Article 9", "is_correct": false}, {"option_text": "Article 11", "is_correct": true}, {"option_text": "Article 13", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2b3b767d-f884-5357-a196-58142f06ea7b', 'India follows the principle of single citizenship, unlike the United States which has dual citizenship (federal and state). Which of the following statements regarding Indian single citizenship is CORRECT?', NULL, 'The single-citizenship principle means every Indian is a citizen of India only — NOT of any particular state. This was a deliberate design choice by the framers to strengthen national unity (contrast with the US 14th Amendment''s dual citizenship). Domicile-based benefits (like state university quotas) exist, but these are administrative — not separate ''state citizenship''. Option A is factually wrong; B contradicts Part III which applies uniformly; D is fiction.', 'MEDIUM', 'Polity', 'Citizenship', 'POL_CITIZENSHIP', '[{"option_text": "Indian states can independently grant citizenship for residence-based purposes", "is_correct": false}, {"option_text": "A citizen of one Indian state enjoys fewer Fundamental Rights in another state", "is_correct": false}, {"option_text": "All Indians are citizens of India alone; no separate state citizenship exists", "is_correct": true}, {"option_text": "The President may grant separate state citizenship in emergencies", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('00c48a52-0c1f-5c3c-9786-67ed71667594', 'Match the following modes of acquiring Indian citizenship with their primary requirement and select the correct pairing:
(i) Citizenship by Birth  — born in India and at least one parent is an Indian citizen (post-2003 rule)
(ii) Citizenship by Descent — born outside India with at least one Indian parent at the time of birth
(iii) Citizenship by Registration — 7 years of ordinary residence in India (for persons of Indian origin)
(iv) Citizenship by Naturalisation — 12 years of ordinary residence in India for a foreign national', NULL, 'ALL four pairings are correct. (i) Post-2003 amendment: born in India after 03-Dec-2004 AND at least one parent is a citizen — more restrictive than the original 1955 rule. (ii) Descent: Indian parent at time of birth; since 1992 both parents (not just father) qualify. (iii) Registration: generally 7 years ordinary residence in India for persons of Indian origin (plus other grounds like marriage to a citizen). (iv) Naturalisation requires 12 years — 11 out of 14 preceding years, with the 12th year continuous.', 'HARD', 'Polity', 'Citizenship', 'POL_CITIZENSHIP', '[{"option_text": "Only (ii) and (iii) are correctly paired", "is_correct": false}, {"option_text": "Only (i), (ii) and (iv) are correctly paired", "is_correct": false}, {"option_text": "All four (i), (ii), (iii), and (iv) are correctly paired", "is_correct": true}, {"option_text": "Only (i) and (iv) are correctly paired", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6e7e199d-5b0b-55c3-a045-e5be0cd61c88', 'Which of the following statements about the Overseas Citizen of India (OCI) scheme is INCORRECT?', NULL, 'Statement B is INCORRECT — OCI card-holders do NOT have voting rights in India. They are classified as ''foreign nationals'' and cannot vote, contest elections, hold constitutional posts (President/VP/Judges of SC/HC), or own agricultural land. Statement A is correct (introduced 2003 Amendment). Statement C correctly lists disqualifications. Statement D is also correct: the Government of India merged PIO cards into OCI cards through a gazette notification in January 2015.', 'MEDIUM', 'Polity', 'Citizenship', 'POL_CITIZENSHIP', '[{"option_text": "OCI status was introduced by the Citizenship (Amendment) Act, 2003", "is_correct": false}, {"option_text": "An OCI card-holder enjoys the right to vote in Indian elections", "is_correct": true}, {"option_text": "OCI card-holders cannot hold constitutional posts like President, Vice-President or Judge", "is_correct": false}, {"option_text": "The PIO card was merged with the OCI card in 2015", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9ac5f2fd-4142-5280-93f7-a7ad1080919f', 'The Citizenship (Amendment) Act, 2019 (CAA) provides an expedited path to Indian citizenship for members of certain religious communities from three specified countries. Which of the following is NOT among those specified countries?', NULL, 'CAA 2019 covers migrants from Afghanistan, Pakistan, and Bangladesh who belong to Hindu, Sikh, Buddhist, Jain, Parsi, or Christian communities and entered India on or before 31-Dec-2014. Myanmar is NOT included — a frequent confusion given the Rohingya refugee crisis. The reasoning-distractor framing tests whether students confuse CAA''s scope with general South-Asian refugee contexts.', 'MEDIUM', 'Polity', 'Citizenship', 'POL_CITIZENSHIP', '[{"option_text": "Afghanistan", "is_correct": false}, {"option_text": "Pakistan", "is_correct": false}, {"option_text": "Bangladesh", "is_correct": false}, {"option_text": "Myanmar", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2c58edc5-d2f3-5ad2-9997-f636eb3b41b1', 'Under Article 9 of the Indian Constitution, a person who voluntarily acquires citizenship of a foreign state:', NULL, 'Article 9 is self-executing: the moment a person voluntarily acquires foreign citizenship, Indian citizenship ceases automatically — no order, no Parliamentary action needed. This is distinct from termination under the Citizenship Act Section 9 (which covers the same ground statutorily). Option D describes no actual provision — India rejects dual citizenship; the OCI card is not citizenship. The 5-year option is pure fiction designed to trap students familiar with India''s renunciation timelines for other regimes.', 'MEDIUM', 'Polity', 'Citizenship', 'POL_CITIZENSHIP', '[{"option_text": "Retains Indian citizenship unless Parliament terminates it", "is_correct": false}, {"option_text": "Automatically ceases to be an Indian citizen", "is_correct": true}, {"option_text": "Must obtain Presidential assent to retain Indian citizenship", "is_correct": false}, {"option_text": "Can hold both citizenships for up to 5 years", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6a7f8436-747b-5e1b-ad88-78ab07672cc6', 'Which ministry is the nodal authority for matters relating to Indian citizenship, including CAA implementation, OCI card issuance, and the National Register of Citizens?', NULL, 'The Ministry of Home Affairs (MHA) is the nodal ministry for all citizenship matters — it administers the Citizenship Act 1955, issues OCI cards through the Foreigners Division, and oversees the NRC. External Affairs handles passports and overseas Indian affairs but NOT citizenship grants. Law & Justice drafts statutes; Social Justice deals with SC/ST/OBC welfare — unrelated.', 'EASY', 'Polity', 'Citizenship', 'POL_CITIZENSHIP', '[{"option_text": "Ministry of External Affairs", "is_correct": false}, {"option_text": "Ministry of Home Affairs", "is_correct": true}, {"option_text": "Ministry of Law and Justice", "is_correct": false}, {"option_text": "Ministry of Social Justice and Empowerment", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d1d500d2-db50-5051-bb28-c80102ea0549', 'The Citizenship (Amendment) Act, 1986 raised the requirement for citizenship by birth. Under this amendment, a person born in India between 1 July 1987 and 2 December 2004 is an Indian citizen by birth ONLY IF:', NULL, 'The 1986 Amendment (effective 1 July 1987) tightened the original jus soli rule: for births between 1 July 1987 and 2 Dec 2004, citizenship by birth required AT LEAST ONE parent to be an Indian citizen. The 2003 Amendment (effective 3 Dec 2004) tightened it further: at least one parent Indian AND the other not an illegal migrant. Option A is the post-2004 stricter rule incorrectly applied. Options C and D invent residence/registration conditions that don''t exist.', 'HARD', 'Polity', 'Citizenship', 'POL_CITIZENSHIP', '[{"option_text": "Both parents are Indian citizens at the time of birth", "is_correct": false}, {"option_text": "At least one parent is an Indian citizen at the time of birth", "is_correct": true}, {"option_text": "Either parent is an Indian citizen and has resided in India for 10 years", "is_correct": false}, {"option_text": "The child is registered within 90 days at the Registrar of Births", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d598bb9a-289f-5ed9-8cfd-ac1fd99981f2', 'Under the Indian citizenship regime, the ''termination'' of citizenship (by order of the Central Government) is DISTINCT from ''deprivation'' of citizenship. Which of the following is the primary distinction?', NULL, 'CORRECT distinction: TERMINATION (Section 9 of the 1955 Act) kicks in AUTOMATICALLY when an Indian voluntarily acquires foreign citizenship — no investigation, no order needed. DEPRIVATION (Section 10) is an order BY the Central Government on specific grounds: (a) citizenship obtained by fraud/misrepresentation, (b) unlawful communication with the enemy during war, (c) disloyalty to the Constitution, (d) a 2-year imprisonment within 5 years of naturalisation, or (e) 7 years of continuous residence abroad. A and D are pure fabrications; C conflates two legally-distinct mechanisms.', 'HARD', 'Polity', 'Citizenship', 'POL_CITIZENSHIP', '[{"option_text": "Termination applies only to women; deprivation applies to men", "is_correct": false}, {"option_text": "Termination is automatic on foreign-citizenship acquisition; deprivation is an order by government on grounds like fraud, disloyalty, or imprisonment abroad", "is_correct": true}, {"option_text": "Both terms mean the same thing — mere drafting variations", "is_correct": false}, {"option_text": "Termination requires Parliamentary approval; deprivation is Presidential discretion", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('781aa4fc-422f-51a6-a467-1b79f58e2ae6', 'Under which Article of the Constitution is the Finance Commission of India established?', NULL, 'Article 280 provides for the constitution of a Finance Commission. Article 263 covers the Inter-State Council; Article 324 deals with the Election Commission; Article 350 concerns language rights. The Finance Commission is a CONSTITUTIONAL body — constituted by the President every 5 years (or earlier if needed).', 'EASY', 'Polity', 'Finance Commission', 'POL_FINANCE_COM', '[{"option_text": "Article 263", "is_correct": false}, {"option_text": "Article 280", "is_correct": true}, {"option_text": "Article 324", "is_correct": false}, {"option_text": "Article 350", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('738fa8ed-a40f-5008-bb19-3ad754e5ee8b', 'Who constitutes the Finance Commission?', NULL, 'Article 280(1): The President constitutes the Finance Commission every 5 years or at such earlier time as he considers necessary. The commission consists of a chairman and four other members. The PM/FM/NITI Aayog have no role in constitution — the function is squarely with the President (acting on Cabinet advice).', 'EASY', 'Polity', 'Finance Commission', 'POL_FINANCE_COM', '[{"option_text": "The Prime Minister", "is_correct": false}, {"option_text": "The President of India", "is_correct": true}, {"option_text": "The Parliament through a special law", "is_correct": false}, {"option_text": "The Union Finance Minister after NITI Aayog approval", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7b257f46-12e1-5d02-bfdc-a76e9b4f7ad3', 'How many members does the Finance Commission have?', NULL, 'Article 280(1): ''a Finance Commission which shall consist of a Chairman and four other Members''. The Finance Commission Act, 1951 lays down qualifications for appointment of members. Chairman is usually a person with public-affairs experience; members include a HC-eligible person, a finance expert, a public finance specialist, and an economics expert.', 'EASY', 'Polity', 'Finance Commission', 'POL_FINANCE_COM', '[{"option_text": "3 (one Chairman + two members)", "is_correct": false}, {"option_text": "5 (one Chairman + four members)", "is_correct": true}, {"option_text": "7 (one Chairman + six members)", "is_correct": false}, {"option_text": "Variable, determined by the Parliament each term", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b18a91ad-8ff0-574d-b476-4ebb5c5e1b3f', 'Which of the following is NOT a function of the Finance Commission under Article 280?', NULL, 'Article 280(3) lists functions: (a) distribution of tax proceeds between Union and States; (b) principles for grants-in-aid; (c) measures to augment State Consolidated Fund for local bodies (added by 73rd & 74th Amendments); (d) any other matter referred by the President. MSP for agricultural commodities is fixed by the Cabinet Committee on Economic Affairs on CACP recommendation — not the Finance Commission''s role.', 'MEDIUM', 'Polity', 'Finance Commission', 'POL_FINANCE_COM', '[{"option_text": "Distribution of net proceeds of taxes between Union and States", "is_correct": false}, {"option_text": "Principles governing grants-in-aid to States out of the Consolidated Fund of India", "is_correct": false}, {"option_text": "Recommendations to augment Consolidated Fund of a State to supplement resources of Panchayats & Municipalities", "is_correct": false}, {"option_text": "Regulating prices of agricultural commodities (MSP)", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1352f481-a5cb-5ef2-85a4-2657a3183d79', 'Who was the chairman of the First Finance Commission of India, constituted in 1951?', NULL, 'K. C. Neogy chaired the First Finance Commission (1951–57). He was a senior economist and political leader. K. Santhanam chaired the 2nd FC (1956–62). Y. B. Chavan chaired the 8th FC (1984–89). Brahmanand Reddy never chaired an FC. The First FC''s tenure covered April 1952 to March 1957.', 'HARD', 'Polity', 'Finance Commission', 'POL_FINANCE_COM', '[{"option_text": "Dr. K. Santhanam", "is_correct": false}, {"option_text": "K. C. Neogy", "is_correct": true}, {"option_text": "Y. B. Chavan", "is_correct": false}, {"option_text": "Brahmanand Reddy", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6d4f7277-0375-54a1-88da-6330bdf34d82', 'Which Finance Commission introduced the concept of ''performance-based grants'' for local bodies (Panchayats and Municipalities)?', NULL, 'The 13th FC (Chairman: Dr. Vijay Kelkar, 2010–15) was the first to introduce performance-based grants for local bodies, conditional on compliance with e.g., putting up audited accounts and establishing a local-level grievance redressal system. Earlier FCs (11th & 12th) gave only basic grants to local bodies. The 14th & 15th FCs continued the performance-grant structure with updated conditions.', 'HARD', 'Polity', 'Finance Commission', 'POL_FINANCE_COM', '[{"option_text": "11th Finance Commission", "is_correct": false}, {"option_text": "13th Finance Commission", "is_correct": true}, {"option_text": "14th Finance Commission", "is_correct": false}, {"option_text": "15th Finance Commission", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('dfe591c7-c88e-5a23-a772-6a535f2df171', 'Which Finance Commission increased the States'' share in the divisible pool of central taxes from 32% to 42%?', NULL, 'The 14th FC (Chairman: Dr. Y. V. Reddy, covering 2015–20) made a landmark recommendation raising States'' share of divisible central taxes from 32% (under the 13th FC) to 42% — the single largest jump in FC history, reflecting a new commitment to fiscal federalism. The 15th FC (N. K. Singh) slightly reduced it to 41% (on account of the J&K reorganisation into UTs).', 'MEDIUM', 'Polity', 'Finance Commission', 'POL_FINANCE_COM', '[{"option_text": "12th Finance Commission", "is_correct": false}, {"option_text": "13th Finance Commission", "is_correct": false}, {"option_text": "14th Finance Commission", "is_correct": true}, {"option_text": "15th Finance Commission", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('58a03f88-0d38-5625-82f7-a00381070124', 'What is the usual tenure of a Finance Commission''s recommendations?', NULL, 'The Finance Commission is constituted every 5 years and its recommendations apply for the following 5-year period. E.g., 15th FC''s recommendations covered 2021–26 (extended by 1 year due to COVID). This 5-year horizon matches the typical economic/planning cycle. The FC is NOT a permanent body; it is constituted afresh each time.', 'EASY', 'Polity', 'Finance Commission', 'POL_FINANCE_COM', '[{"option_text": "2 years", "is_correct": false}, {"option_text": "3 years", "is_correct": false}, {"option_text": "5 years", "is_correct": true}, {"option_text": "10 years", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b50763d7-b0de-5daa-a41e-462c37b868bb', 'The recommendations of the Finance Commission are:', NULL, 'The FC''s recommendations are purely ADVISORY (Article 281). The President places the report before both Houses of Parliament along with an Explanatory Memorandum stating the government''s action taken on each recommendation. The government can partially or fully reject recommendations — though in practice, the major recommendations (vertical devolution %, horizontal formula) are accepted. A famous case: the 14th FC raised devolution to 42%, which was fully accepted.', 'MEDIUM', 'Polity', 'Finance Commission', 'POL_FINANCE_COM', '[{"option_text": "Binding on the Government of India", "is_correct": false}, {"option_text": "Advisory / recommendatory in nature; the government can modify or reject them", "is_correct": true}, {"option_text": "Binding on States but advisory for the Union", "is_correct": false}, {"option_text": "Binding only after Parliamentary ratification", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a9753559-3ed5-5ee9-a629-a13fd6f960ad', 'Which of the following criteria has been used by Finance Commissions for horizontal distribution (inter-State distribution) of tax proceeds?', NULL, 'Horizontal devolution uses multiple criteria with different weights. The 15th FC used: Income distance (45%), Area (15%), Population 2011 (15%), Demographic Performance (12.5%), Forest & Ecology (10%), Tax & Fiscal Efforts (2.5%). Earlier FCs had different weights and slightly different criteria (e.g., the 14th FC didn''t use Forest & Ecology or Demographic Performance). The formula is designed to balance equity (give more to poorer States) and efficiency.', 'HARD', 'Polity', 'Finance Commission', 'POL_FINANCE_COM', '[{"option_text": "Income distance, population, area, forest & ecology, demographic performance, and tax & fiscal efforts", "is_correct": true}, {"option_text": "GDP growth rate of each State only", "is_correct": false}, {"option_text": "Only population and tax collection capacity", "is_correct": false}, {"option_text": "Number of Lok Sabha seats held by each State", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('27d0a37d-b33d-5533-9b90-fff6b708be0a', 'Which Article of the Constitution deals with the State Finance Commission (constituted by the Governor every 5 years)?', NULL, 'The State Finance Commission is a STATE-level body constituted by the Governor under Article 243-I (for Panchayats) AND Article 243-Y (for Municipalities) — both added by the 73rd and 74th Constitutional Amendments (1992). It reviews the financial position of local bodies every 5 years and recommends distribution of State taxes. Article 280 is for the UNION FC, not the State FC.', 'MEDIUM', 'Polity', 'Finance Commission', 'POL_FINANCE_COM', '[{"option_text": "Article 243-I (for Panchayats)", "is_correct": false}, {"option_text": "Article 243-Y (for Municipalities)", "is_correct": false}, {"option_text": "Both Article 243-I and Article 243-Y", "is_correct": true}, {"option_text": "Article 280 (same as Union FC)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5cf7f292-3d52-5278-aa81-5a8874c65825', 'Who chaired the 15th Finance Commission, whose recommendations cover the period 2021–2026?', NULL, 'Nand Kishore Singh (N. K. Singh), former IAS officer and Chairman of the FRBM Review Committee, chaired the 15th FC (2017–21, report period 2021–26). Dr. Y. V. Reddy chaired the 14th FC; Dr. C. Rangarajan chaired the 12th FC (2005–10); Dr. Vijay Kelkar chaired the 13th FC.', 'MEDIUM', 'Polity', 'Finance Commission', 'POL_FINANCE_COM', '[{"option_text": "Dr. Y. V. Reddy", "is_correct": false}, {"option_text": "Dr. C. Rangarajan", "is_correct": false}, {"option_text": "N. K. Singh", "is_correct": true}, {"option_text": "Dr. Vijay Kelkar", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a39065f2-5994-57de-af48-f2aa6337de96', 'Fundamental Rights are enshrined in which Part of the Indian Constitution?', NULL, 'Part III (Articles 12-35) of the Constitution is the ''Fundamental Rights'' section — enforceable against the State. Part II (Arts 5-11) is Citizenship. Part IV (Arts 36-51) is DPSP (non-justiciable). Part IV-A (Art 51-A) is Fundamental Duties (added by 42nd Amendment, 1976).', 'EASY', 'Polity', 'Fundamental Rights', 'POL_FR', '[{"option_text": "Part II", "is_correct": false}, {"option_text": "Part III", "is_correct": true}, {"option_text": "Part IV", "is_correct": false}, {"option_text": "Part IV-A", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('db3767a3-2853-5abd-b0de-59486c01ab63', 'The Right to Constitutional Remedies (Article 32) was described by Dr. B. R. Ambedkar as:', NULL, 'Dr. Ambedkar called Article 32 the ''heart and soul of the Constitution'' because without it, the Fundamental Rights would be unenforceable. Article 32 grants citizens the right to move the Supreme Court for enforcement of FRs via writs (habeas corpus, mandamus, prohibition, certiorari, quo warranto). Article 32 itself IS a Fundamental Right. ''The conscience of the Constitution'' is sometimes used for the DPSP+FR combination; ''crown'' is used loosely for the Preamble.', 'MEDIUM', 'Polity', 'Fundamental Rights', 'POL_FR', '[{"option_text": "''The conscience of the Constitution''", "is_correct": false}, {"option_text": "''The heart and soul of the Constitution''", "is_correct": true}, {"option_text": "''The crown of the Constitution''", "is_correct": false}, {"option_text": "''The backbone of federalism''", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5f219a07-ebe7-5411-8072-6dba7c7ba58c', 'Which Fundamental Right was removed from the list by the 44th Constitutional Amendment (1978)?', NULL, 'The Right to Property (originally Article 19(1)(f) and Article 31) was removed from the list of Fundamental Rights by the 44th Amendment (1978) during the Janata Party government. It was relocated as a LEGAL right under Article 300-A (Part XII). This reduced the number of FRs from 7 to 6. The other FRs have never been removed, though their scope has been modified.', 'MEDIUM', 'Polity', 'Fundamental Rights', 'POL_FR', '[{"option_text": "Right to Equality", "is_correct": false}, {"option_text": "Right to Freedom of Religion", "is_correct": false}, {"option_text": "Right to Property", "is_correct": true}, {"option_text": "Right to Constitutional Remedies", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('60c0d3b3-f3f1-527c-a601-4251fa84486b', 'The ''Right to Education'' was added as a Fundamental Right (Article 21-A) by which Constitutional Amendment?', NULL, 'The 86th Constitutional Amendment (2002) inserted Article 21-A guaranteeing the right to free and compulsory education for children aged 6-14 years. Implementing legislation: Right of Children to Free and Compulsory Education (RTE) Act, 2009 — came into force on 1 April 2010. 73rd=Panchayati Raj; 93rd=OBC reservation in educational institutions; 101st=GST.', 'MEDIUM', 'Polity', 'Fundamental Rights', 'POL_FR', '[{"option_text": "73rd Amendment, 1992", "is_correct": false}, {"option_text": "86th Amendment, 2002", "is_correct": true}, {"option_text": "93rd Amendment, 2005", "is_correct": false}, {"option_text": "101st Amendment, 2016", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1b984fa3-bc88-523a-a593-35f526ee73aa', 'Which of the following is NOT one of the six Fundamental Rights in the current Indian Constitution?', NULL, 'Six FRs today: (1) Right to Equality (Arts. 14-18); (2) Right to Freedom (Arts. 19-22); (3) Right against Exploitation (Arts. 23-24); (4) Right to Freedom of Religion (Arts. 25-28); (5) Cultural & Educational Rights (Arts. 29-30); (6) Right to Constitutional Remedies (Arts. 32-35). Right to Property was DEMOTED to a legal right (Art. 300-A) by the 44th Amendment (1978) — so it is NOT a Fundamental Right anymore.', 'EASY', 'Polity', 'Fundamental Rights', 'POL_FR', '[{"option_text": "Right to Equality (Arts. 14-18)", "is_correct": false}, {"option_text": "Right to Freedom (Arts. 19-22)", "is_correct": false}, {"option_text": "Right to Property (Art. 300-A)", "is_correct": true}, {"option_text": "Right against Exploitation (Arts. 23-24)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7d2c4337-4d43-5356-9980-420b1da96098', 'Article 14 of the Indian Constitution guarantees:', NULL, 'Article 14: ''The State shall not deny to any person equality BEFORE the law or the equal PROTECTION of the laws within the territory of India.'' Note two distinct guarantees: (1) ''equality before law'' — British/Dicey concept, negative — no one is above the law; (2) ''equal protection of the laws'' — American concept, positive — equal treatment under equal circumstances. Article 21 is life/liberty. Article 19(1)(a) is speech. Article 21-A is education.', 'EASY', 'Polity', 'Fundamental Rights', 'POL_FR', '[{"option_text": "Right to life and personal liberty", "is_correct": false}, {"option_text": "Equality before law AND equal protection of laws", "is_correct": true}, {"option_text": "Freedom of speech and expression", "is_correct": false}, {"option_text": "Right to education", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('26149a62-eee2-5623-8d3c-f653e8e0c159', 'The Right to Privacy was declared a Fundamental Right by the Supreme Court in which landmark case?', NULL, 'The 9-judge bench in K. S. Puttaswamy v. Union of India (August 2017) unanimously held that the Right to Privacy is an intrinsic part of the Right to Life and Personal Liberty under Article 21, and is protected under Part III of the Constitution. This case was a reference from the Aadhaar challenges. Kesavananda (1973) = basic structure doctrine. Maneka Gandhi (1978) = expanded Article 21 (''procedure established by law'' → must be just, fair, reasonable). Navtej Johar (2018) = decriminalised consensual same-sex relations (Sec 377).', 'MEDIUM', 'Polity', 'Fundamental Rights', 'POL_FR', '[{"option_text": "Kesavananda Bharati v. State of Kerala (1973)", "is_correct": false}, {"option_text": "Maneka Gandhi v. Union of India (1978)", "is_correct": false}, {"option_text": "K. S. Puttaswamy v. Union of India (2017)", "is_correct": true}, {"option_text": "Navtej Singh Johar v. Union of India (2018)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e77f3183-8bc9-5f55-a532-e2cd3a7d6c38', 'The writ of ''Habeas Corpus'' is used to:', NULL, 'HABEAS CORPUS (Latin: ''let you have the body'') — the court directs the detaining authority to PRODUCE the detained person and justify the detention. If the detention is illegal, the person is released. Used primarily against illegal police detention, preventive detention, etc. Other writs: CERTIORARI = challenge lower court/tribunal order; QUO WARRANTO = challenge authority to hold office; MANDAMUS = command to public authority; PROHIBITION = prevent lower court from exceeding jurisdiction.', 'EASY', 'Polity', 'Fundamental Rights', 'POL_FR', '[{"option_text": "Direct a lower court to produce records of a case", "is_correct": false}, {"option_text": "Challenge the legality of a person''s detention and demand their production before court", "is_correct": true}, {"option_text": "Prevent a public servant from exercising an office they have no right to", "is_correct": false}, {"option_text": "Direct a public authority to perform its statutory duty", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1d2bf2e7-d63c-5066-b77b-f0d425e7ce00', 'Article 17 of the Constitution deals with:', NULL, 'Article 17: ''Untouchability is abolished and its practice in any form is forbidden.'' Its enforcement was operationalised through the Protection of Civil Rights Act, 1955 and the SC/ST (Prevention of Atrocities) Act, 1989. Article 18 abolishes titles (hereditary honours); Article 23 prohibits human trafficking and forced labour; Article 24 prohibits child labour under 14 in factories, mines, and hazardous employment.', 'EASY', 'Polity', 'Fundamental Rights', 'POL_FR', '[{"option_text": "Abolition of titles", "is_correct": false}, {"option_text": "Abolition of untouchability", "is_correct": true}, {"option_text": "Prohibition of human trafficking", "is_correct": false}, {"option_text": "Prohibition of child labour", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c9b934d0-1264-54f7-8a12-6c402530d68f', 'During a National Emergency (Article 352), which of the following Fundamental Rights CANNOT be suspended?', NULL, 'Article 359 (as amended by 44th Amendment, 1978) specifies that during Emergency, the enforcement of FRs (except Articles 20 and 21) may be suspended by Presidential order. Art 20 = protection against ex post facto laws, double jeopardy, self-incrimination. Art 21 = life and personal liberty. After the ADM Jabalpur (1976) fiasco — where the SC held Art 21 COULD be suspended — the 44th Amendment explicitly immunised Arts 20 and 21. Today these two rights are NEVER suspendable.', 'HARD', 'Polity', 'Fundamental Rights', 'POL_FR', '[{"option_text": "Right to Freedom under Article 19", "is_correct": false}, {"option_text": "Rights under Articles 20 and 21 (Protection in respect of conviction; Life & Liberty)", "is_correct": true}, {"option_text": "Right to Equality under Article 14", "is_correct": false}, {"option_text": "Right against Exploitation", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fe030fd9-23e2-5b24-adec-a00a9e508880', 'Article 14 of the Indian Constitution guarantees two distinct rights. Identify them correctly.', NULL, 'Article 14 guarantees TWO distinct-but-related ideas: (1) ''Equality before law'' — a British/Dicey concept meaning nobody is above the law, all are equally subject to it; (2) ''Equal protection of laws'' — an American 14th-Amendment concept meaning like should be treated alike (reasonable classification allowed). Option B refers to the Preamble''s phrasing of equality; C mixes Art 14 with Art 19; D injects the now-repealed right to property.', 'EASY', 'Polity', 'Fundamental Rights — Right to Equality (Arts 14-18)', 'POL_FR_EQUALITY', '[{"option_text": "Equality before law AND equal protection of laws", "is_correct": true}, {"option_text": "Equality of status AND equality of opportunity", "is_correct": false}, {"option_text": "Equality before law AND freedom of speech", "is_correct": false}, {"option_text": "Equal protection of laws AND right to property", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4144e086-81be-5b10-a45d-cad3a54a1527', 'Which Supreme Court case established that ''arbitrariness is antithetical to Article 14'' and thereby introduced the doctrine of non-arbitrariness into equality jurisprudence?', NULL, 'E.P. Royappa (1974, per Bhagwati J.) introduced the revolutionary ''arbitrariness test'': where a state action is arbitrary, it is by nature unequal and violates Article 14 — even without needing to find a comparator. This freed Article 14 from the strict ''classification'' test alone. Maneka Gandhi (1978) BUILT on Royappa, famously linking Articles 14-19-21 into the ''golden triangle''. Kesavananda is the basic-structure case (unrelated). A.K. Gopalan is the pre-Maneka case whose narrow reading was later overruled.', 'HARD', 'Polity', 'Fundamental Rights — Right to Equality (Arts 14-18)', 'POL_FR_EQUALITY', '[{"option_text": "Maneka Gandhi v. Union of India (1978)", "is_correct": false}, {"option_text": "E.P. Royappa v. State of Tamil Nadu (1974)", "is_correct": true}, {"option_text": "Kesavananda Bharati v. State of Kerala (1973)", "is_correct": false}, {"option_text": "A.K. Gopalan v. State of Madras (1950)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e5e1c741-8856-5e9a-b90b-bfabd759bfcb', 'Article 15 of the Indian Constitution prohibits discrimination on five specific grounds. Which of the following is NOT one of those grounds?', NULL, 'Article 15(1) prohibits discrimination by the State on grounds ONLY of religion, race, caste, sex, or place of birth. ''Language'' is notably ABSENT — this surprises many students given India''s linguistic sensitivity. Language-based safeguards exist elsewhere (Articles 29-30 for minorities, the Eighth Schedule), but Article 15''s enumerated list is these five alone. Memorising the 5 (religion-race-caste-sex-birthplace) is a high-ROI drill.', 'MEDIUM', 'Polity', 'Fundamental Rights — Right to Equality (Arts 14-18)', 'POL_FR_EQUALITY', '[{"option_text": "Religion", "is_correct": false}, {"option_text": "Race", "is_correct": false}, {"option_text": "Language", "is_correct": true}, {"option_text": "Caste", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a13321d0-f354-5748-acd6-3ca4e2dadf61', 'The 50 % ceiling on reservations (with exceptions for extraordinary circumstances) was laid down in which landmark judgment?', NULL, 'The Indra Sawhney (or ''Mandal'') judgment of 1992 is the leading case fixing the 50 % ceiling on reservations under Article 16, introducing the ''creamy layer'' doctrine for OBCs, and upholding reservations for socially-and-educationally-backward classes in public employment. M.R. Balaji (1963) DID suggest a 50 % cap earlier but in the context of educational institutions and had limited force; Indra Sawhney is the authoritative ruling. Champakam Dorairajan led to the 1st Constitutional Amendment adding Article 15(4). Kesavananda is the basic-structure case.', 'MEDIUM', 'Polity', 'Fundamental Rights — Right to Equality (Arts 14-18)', 'POL_FR_EQUALITY', '[{"option_text": "M.R. Balaji v. State of Mysore (1963)", "is_correct": false}, {"option_text": "Indra Sawhney v. Union of India (1992)", "is_correct": true}, {"option_text": "Champakam Dorairajan v. State of Madras (1951)", "is_correct": false}, {"option_text": "Kesavananda Bharati v. State of Kerala (1973)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('58f27cb6-fa32-55f2-8ad8-117f0fd3cecc', 'Article 18 of the Constitution deals with abolition of titles. Which of the following is CORRECTLY permitted under Article 18?', NULL, 'Article 18 abolishes titles EXCEPT academic and military distinctions — so ''Dr.'', ''Professor'', ''Major'', ''Colonel'' etc. are all permitted and widely used. Article 18(1) bars the State from conferring any title other than military/academic; 18(2) bars citizens from accepting foreign titles; 18(3)-(4) regulate non-citizens holding office under the State and citizens holding office under foreign States. Crucially, civilian awards like Bharat Ratna and Padma awards are NOT considered ''titles'' per the Supreme Court (Balaji Raghavan, 1996) — they''re just recognitions and cannot be used as prefixes/suffixes to names.', 'HARD', 'Polity', 'Fundamental Rights — Right to Equality (Arts 14-18)', 'POL_FR_EQUALITY', '[{"option_text": "Accepting a foreign title without Presidential consent", "is_correct": false}, {"option_text": "A State conferring a hereditary title of nobility on a citizen", "is_correct": false}, {"option_text": "A citizen accepting an academic or military distinction (e.g. ''Dr.'', ''Lt. Col.'')", "is_correct": true}, {"option_text": "An Indian national holding office of profit under a foreign State without Presidential consent", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('82661234-86d8-5bb2-a695-1128594af61f', 'Article 16 deals with equality of opportunity in matters of public employment. Which clause of Article 16 specifically enables reservations in PROMOTIONS for SCs and STs?', NULL, 'Article 16(4A) — added by the 77th Constitutional Amendment Act 1995 — empowers the State to make reservations in PROMOTIONS in favour of SCs/STs (not OBCs). Subsequent amendments (81st, 82nd, 85th) refined this: carry-forward of unfilled vacancies, relaxation in qualifying marks, consequential seniority. Article 16(2) prohibits discrimination in employment on grounds like religion/sex; Article 16(4) enables reservations in INITIAL appointments (not promotions); Article 16(5) allows religious-denomination-specific posts. Distinguishing 16(4) from 16(4A) is a classic exam trap.', 'HARD', 'Polity', 'Fundamental Rights — Right to Equality (Arts 14-18)', 'POL_FR_EQUALITY', '[{"option_text": "Article 16(2)", "is_correct": false}, {"option_text": "Article 16(4)", "is_correct": false}, {"option_text": "Article 16(4A)", "is_correct": true}, {"option_text": "Article 16(5)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d87f054f-54f1-5ffe-a815-9d0dd13df5b1', 'The ''reasonable classification'' test under Article 14 requires two conditions to be satisfied simultaneously. These are:', NULL, 'The classical test — laid down in State of West Bengal v. Anwar Ali Sarkar (1952) and refined across cases — has exactly two limbs: (1) INTELLIGIBLE DIFFERENTIA: the group created by the classification is distinguishable on some clear basis from those excluded, and (2) RATIONAL NEXUS: the differentia has a reasonable connection with the purpose of the law. Both MUST be satisfied. Absolute equality (D) is neither required nor possible. Options A and C invent criteria. Note: post-Royappa, arbitrariness is a parallel test.', 'HARD', 'Polity', 'Fundamental Rights — Right to Equality (Arts 14-18)', 'POL_FR_EQUALITY', '[{"option_text": "(i) the classification must advance public policy AND (ii) it must be approved by Parliament", "is_correct": false}, {"option_text": "(i) intelligible differentia distinguishing the group from others AND (ii) rational nexus between that differentia and the objective of the law", "is_correct": true}, {"option_text": "(i) the classification must have been upheld by a previous Supreme Court judgment AND (ii) it must not cost the state exchequer beyond 2% of GDP", "is_correct": false}, {"option_text": "(i) absolute equality in outcome AND (ii) absolute equality in treatment", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('66e3045d-581e-5518-9d5f-cebb69c463c5', 'Article 17 abolishes ''untouchability'' and makes its practice in any form a punishable offence. The relevant enforcement legislation is:', NULL, 'The enabling legislation for Article 17 is the Untouchability (Offences) Act 1955 — renamed Protection of Civil Rights Act via a 1976 amendment. The SC/ST Atrocities Act 1989 (option B) is supplementary and deals with broader atrocities, but Article 17''s direct enforcement statute is option A. IPC Chapter XIV covers offences related to religion (not untouchability specifically). The Equal Remuneration Act (1976) deals with wage equality on gender lines — completely different domain.', 'MEDIUM', 'Polity', 'Fundamental Rights — Right to Equality (Arts 14-18)', 'POL_FR_EQUALITY', '[{"option_text": "The Protection of Civil Rights Act, 1955 (originally the Untouchability (Offences) Act, 1955)", "is_correct": true}, {"option_text": "The Scheduled Castes and Scheduled Tribes (Prevention of Atrocities) Act, 1989 only", "is_correct": false}, {"option_text": "The Indian Penal Code, Chapter XIV only", "is_correct": false}, {"option_text": "The Equal Remuneration Act, 1976", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('43d1d37a-53d9-5eea-a8cc-bedefc6c4fa6', 'The ''creamy layer'' doctrine — which excludes the more affluent members of Other Backward Classes (OBCs) from the benefit of reservations — was judicially crafted in Indra Sawhney (1992). Which of the following statements regarding its subsequent application is CORRECT?', NULL, 'Correct nuance: Indra Sawhney mandated creamy-layer exclusion for OBCs but explicitly SAID the concept did NOT apply to SC/STs. HOWEVER, in Jarnail Singh v. Lachhmi Narain Gupta (2018) the Supreme Court extended creamy-layer exclusion to SC/ST PROMOTIONS (not to initial appointments). So the rule today is: OBC initial appointments — creamy layer applies; SC/ST initial appointments — creamy layer does NOT apply; SC/ST promotions — creamy layer DOES apply (Jarnail Singh). Options C and D are fiction.', 'HARD', 'Polity', 'Fundamental Rights — Right to Equality (Arts 14-18)', 'POL_FR_EQUALITY', '[{"option_text": "The creamy layer doctrine applies to SCs and STs in the same manner as to OBCs", "is_correct": false}, {"option_text": "The creamy layer doctrine applies to OBCs for reservations, and — per Jarnail Singh (2018) — also to SC/ST PROMOTIONS", "is_correct": true}, {"option_text": "The creamy layer concept was abolished by the 117th Amendment", "is_correct": false}, {"option_text": "The creamy layer threshold is automatically pegged to 50% of per-capita GDP", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a007ab9c-538f-53f9-9eec-04b4c6e43119', 'The 103rd Constitutional Amendment Act (2019) introduced a NEW clause enabling reservations for ''Economically Weaker Sections'' (EWS). Which Articles were amended?', NULL, 'The 103rd Amendment Act 2019 inserted Article 15(6) and Article 16(6) to enable up to 10 % reservation for EWS in educational institutions AND in public employment, EXCLUSIVE of existing SC/ST/OBC reservations. The Supreme Court in Janhit Abhiyan v. Union of India (Nov 2022, 3-2 majority) upheld the constitutional validity of the amendment. Articles 14 and 17 were untouched. Knowing 15(6) AND 16(6) both were inserted — not just one — is the high-ROI distinction.', 'MEDIUM', 'Polity', 'Fundamental Rights — Right to Equality (Arts 14-18)', 'POL_FR_EQUALITY', '[{"option_text": "Articles 14 and 17", "is_correct": false}, {"option_text": "Articles 15 and 16", "is_correct": true}, {"option_text": "Articles 16 and 17", "is_correct": false}, {"option_text": "Articles 14 and 18", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4f983ffc-39d6-5b0a-afab-459ea24b2621', 'A school in Delhi maintains separate entry gates for boys and girls. A parent challenges this as violating Article 15. Which of the following is the most legally accurate assessment?', NULL, 'Article 15(1) forbids discrimination ONLY when the prohibited ground is the SOLE operative reason and one party is disadvantaged. The Supreme Court has recognised ''sex plus'' classifications — sex combined with another neutral factor that doesn''t disadvantage either gender — as constitutionally permissible (compare Anuj Garg v. Hotel Association, 2008). Separate entry gates alone don''t disadvantage either group, so they generally pass muster. Article 17 is untouchability — irrelevant. Article 18 deals with titles — also irrelevant. Option A oversimplifies.', 'HARD', 'Polity', 'Fundamental Rights — Right to Equality (Arts 14-18)', 'POL_FR_EQUALITY', '[{"option_text": "It certainly violates Article 15(1) because sex is an enumerated ground of prohibited discrimination", "is_correct": false}, {"option_text": "It does not violate Article 15(1) if the classification is based on ''sex plus'' (sex combined with a reasonable rationale) and does NOT subject either gender to disadvantage", "is_correct": true}, {"option_text": "It violates Article 17", "is_correct": false}, {"option_text": "It is covered by Article 18 — the State cannot confer gendered titles", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ee798385-425d-5d22-af16-86e4261cb23e', 'Which of the following is an enabling provision that PERMITS the State to make special provisions for women and children, despite the general non-discrimination rule of Article 15?', NULL, 'Article 15(3) is the specific carve-out: ''Nothing in this article shall prevent the State from making any special provision for women and children.'' This is the basis for laws like reservations for women in local bodies, maternity benefits, child-protection legislation. 15(2) prohibits discrimination by private actors in access to shops/restaurants/wells. 15(4) enables special provisions for SEBCs/SC/ST (added by the 1st Amendment 1951 after the Champakam Dorairajan judgment). 15(5) enables reservations in educational institutions (added by the 93rd Amendment 2005).', 'MEDIUM', 'Polity', 'Fundamental Rights — Right to Equality (Arts 14-18)', 'POL_FR_EQUALITY', '[{"option_text": "Article 15(2)", "is_correct": false}, {"option_text": "Article 15(3)", "is_correct": true}, {"option_text": "Article 15(4)", "is_correct": false}, {"option_text": "Article 15(5)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f9e9696b-0201-5c5d-b08d-2d2476f99da4', 'Article 19 of the Constitution originally enumerated SEVEN freedoms. The ''right to acquire, hold and dispose of property'' [Article 19(1)(f)] was DELETED by which Constitutional Amendment, thereby reducing the freedoms to the current SIX?', NULL, 'The 44th Amendment Act 1978 — passed by the Janata Government after the 1977 elections — deleted Article 19(1)(f) and Article 31 (right to property). Property is now only a LEGAL right under Article 300A, not a Fundamental Right. The 42nd Amendment (1976, ''mini-Constitution'') added Fundamental Duties and expanded DPSP — but it was actually the 44th that corrected several of its excesses and made this specific property change. 61st Amendment lowered the voting age from 21 to 18. 73rd added Panchayati Raj (Part IX).', 'MEDIUM', 'Polity', 'Fundamental Rights — Freedoms, Life & Liberty (Arts 19-22)', 'POL_FR_FREEDOMS', '[{"option_text": "42nd Amendment Act, 1976", "is_correct": false}, {"option_text": "44th Amendment Act, 1978", "is_correct": true}, {"option_text": "61st Amendment Act, 1988", "is_correct": false}, {"option_text": "73rd Amendment Act, 1992", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('544b9339-686c-52c9-a6fa-c69ede4d8197', 'The doctrine of ''due process of law'' was imported into Indian jurisprudence — via a creative reading of Article 21 — in which landmark judgment?', NULL, 'A.K. Gopalan (1950) read Article 21 narrowly — ''procedure established by law'' meant ANY procedure Parliament laid down, however arbitrary. MANEKA GANDHI (1978) overruled this: ''procedure established by law'' now means fair, just, and reasonable procedure — effectively importing American-style ''due process''. It also linked Articles 14-19-21 into the ''golden triangle'' — any law restricting personal liberty must pass all three tests simultaneously. Kesavananda is the basic-structure case (Fundamental Rights vs amendment power). Minerva Mills protected basic structure against 42nd Amendment''s over-reach.', 'HARD', 'Polity', 'Fundamental Rights — Freedoms, Life & Liberty (Arts 19-22)', 'POL_FR_FREEDOMS', '[{"option_text": "A.K. Gopalan v. State of Madras (1950)", "is_correct": false}, {"option_text": "Maneka Gandhi v. Union of India (1978)", "is_correct": true}, {"option_text": "Keshavananda Bharati v. State of Kerala (1973)", "is_correct": false}, {"option_text": "Minerva Mills v. Union of India (1980)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('137f92a0-ea74-5fef-9223-400f56e480b5', 'The Right to Privacy was finally declared a Fundamental Right in K.S. Puttaswamy v. Union of India (2017). Under which Article(s) does the Supreme Court primarily anchor this right?', NULL, 'The 9-judge bench in Puttaswamy (24 Aug 2017) unanimously held that the right to privacy is intrinsic to Article 21 (right to life and personal liberty), necessarily linked to Article 19''s freedoms, and informed by Article 14''s equality principle. The judgment explicitly overruled earlier precedents (M.P. Sharma 1954, Kharak Singh 1962) that had denied privacy as an FR. The ''golden triangle'' (Arts 14-19-21) framework — from Maneka Gandhi — was applied here. Note: while the DEFAULT anchor is Article 21, the multi-Article framing in option C captures the complete doctrinal basis.', 'HARD', 'Polity', 'Fundamental Rights — Freedoms, Life & Liberty (Arts 19-22)', 'POL_FR_FREEDOMS', '[{"option_text": "Article 14 alone", "is_correct": false}, {"option_text": "Article 19 alone", "is_correct": false}, {"option_text": "Article 21 read with the freedoms under Article 19 and equality under Article 14", "is_correct": true}, {"option_text": "Article 25 (freedom of religion)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d7ded5d0-c774-569b-8a5f-676b289ad714', 'Which of the following is NOT one of the six freedoms currently guaranteed under Article 19(1)?', NULL, 'The six CURRENT freedoms under Article 19(1): (a) speech and expression, (b) peaceable assembly, (c) form associations/unions, (d) move freely throughout the territory of India, (e) reside and settle in any part of India, (g) practise any profession/occupation/trade/business. Note: 19(1)(f) — the right to acquire/hold/dispose of property — was DELETED by the 44th Amendment 1978 and sub-clause (g) now follows directly after (e). So option C is NOT a current FR (though it was pre-1978).', 'EASY', 'Polity', 'Fundamental Rights — Freedoms, Life & Liberty (Arts 19-22)', 'POL_FR_FREEDOMS', '[{"option_text": "Freedom of speech and expression", "is_correct": false}, {"option_text": "Freedom to assemble peaceably and without arms", "is_correct": false}, {"option_text": "Freedom to acquire, hold and dispose of property", "is_correct": true}, {"option_text": "Freedom to practise any profession, or to carry on any occupation, trade or business", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('572f466b-92bc-5946-bb5c-6b1183431914', 'Article 20(3) guarantees protection against SELF-INCRIMINATION — ''no person accused of any offence shall be compelled to be a witness against himself''. Which of the following is NOT protected under this provision, as interpreted by the Supreme Court?', NULL, 'In State of Bombay v. Kathi Kalu Oghad (1961), the Supreme Court clarified that Article 20(3) protects against compelled TESTIMONIAL evidence — NOT against the giving of PHYSICAL evidence. Fingerprints, handwriting samples, blood samples, voice samples, specimen signatures etc. are physical/objective evidence and CAN be legally compelled (e.g. under Section 73 of the Evidence Act or Section 311A CrPC). Options A, C, and D are protected: oral statements under coercion (Kartar Singh, Selvi), forced decryption (emerging doctrine), narco/polygraph without consent (Selvi v. Karnataka 2010) all violate 20(3).', 'HARD', 'Polity', 'Fundamental Rights — Freedoms, Life & Liberty (Arts 19-22)', 'POL_FR_FREEDOMS', '[{"option_text": "Giving oral statements under duress to the police", "is_correct": false}, {"option_text": "Giving fingerprints, handwriting samples, or voice samples", "is_correct": true}, {"option_text": "Being forced to decrypt a personal mobile-phone passcode", "is_correct": false}, {"option_text": "Subjecting the accused to narco-analysis, polygraph, or brain-mapping tests without consent", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('70f00161-aff5-56b8-9bba-86b59237c0fd', 'The Right to Education (Article 21A) was inserted into the Constitution by which Amendment Act, and for which age group?', NULL, 'The 86th Amendment Act 2002 inserted Article 21A — ''The State shall provide free and compulsory education to ALL children of the age of SIX to FOURTEEN years in such manner as the State may, by law, determine.'' The enabling legislation is the Right of Children to Free and Compulsory Education (RTE) Act 2009. The 73rd Amendment (1992) dealt with Panchayati Raj, NOT education. The 93rd Amendment (2005) inserted Article 15(5) enabling reservations in educational institutions. The 101st Amendment (2016) introduced GST — unrelated.', 'MEDIUM', 'Polity', 'Fundamental Rights — Freedoms, Life & Liberty (Arts 19-22)', 'POL_FR_FREEDOMS', '[{"option_text": "73rd Amendment (1992), ages 0-14", "is_correct": false}, {"option_text": "86th Amendment (2002), ages 6-14", "is_correct": true}, {"option_text": "93rd Amendment (2005), ages 3-18", "is_correct": false}, {"option_text": "101st Amendment (2016), ages 5-16", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3d674b06-3342-56a0-9c24-05c5a09ceb67', 'Under Article 22(4), a person can be detained under a preventive detention law for more than THREE MONTHS only if:', NULL, 'Article 22(4)(a) specifies that preventive detention beyond THREE MONTHS requires a report from an Advisory Board (members: persons who are, have been, or are qualified to be High Court judges) finding sufficient cause. Alternatively, 22(4)(b) permits longer detention without Board review IF Parliament prescribes it by law (e.g. under the original 1950 Preventive Detention Act). The Advisory Board mechanism is the key procedural safeguard — weakening it undermines preventive-detention accountability. Options A, C, and D invent mechanisms that don''t exist in 22(4).', 'HARD', 'Polity', 'Fundamental Rights — Freedoms, Life & Liberty (Arts 19-22)', 'POL_FR_FREEDOMS', '[{"option_text": "The Prime Minister personally reviews the case", "is_correct": false}, {"option_text": "An Advisory Board — consisting of persons qualified to be High Court judges — has reported sufficient cause for such detention", "is_correct": true}, {"option_text": "Parliament passes a special resolution", "is_correct": false}, {"option_text": "The President approves the extension under emergency powers", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e8d553fd-0228-5786-8378-af3878689fbb', 'Which of the following rights has the Supreme Court explicitly READ INTO Article 21 (Right to Life and Personal Liberty)?', NULL, 'Post-Maneka Gandhi (1978), the Court has expansively read Article 21 to include: right to shelter (Chameli Singh 1995); right to speedy trial (Hussainara Khatoon 1979); right to clean environment (MC Mehta, Rural Litigation & Entitlement Kendra 1985); right to privacy (Puttaswamy 2017); right to livelihood (Olga Tellis 1985); right to health; right to education (Mohini Jain 1992, later codified as 21A); right to die with dignity (Common Cause 2018 on passive euthanasia); right to food; right against sexual harassment at workplace (Vishaka 1997). This expansionist jurisprudence is called the ''golden thread'' of Article 21.', 'MEDIUM', 'Polity', 'Fundamental Rights — Freedoms, Life & Liberty (Arts 19-22)', 'POL_FR_FREEDOMS', '[{"option_text": "Right to shelter", "is_correct": false}, {"option_text": "Right to speedy trial", "is_correct": false}, {"option_text": "Right to a clean environment", "is_correct": false}, {"option_text": "All of the above", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a6eb404d-63fc-5a0f-95c0-2507a276284f', 'Article 20(1) prohibits EX POST FACTO criminal laws. Which of the following falls OUTSIDE the protection of this clause?', NULL, 'Article 20(1) protects against retroactive SUBSTANTIVE criminal law — creating offences or increasing penalties after the act. It does NOT protect against retroactive procedural changes. Courts routinely apply new procedural rules (evidence, trial procedure, sentencing guidelines) to ongoing cases. A classic 2010 Supreme Court case reiterated this: the accused has no right to be tried under the specific procedural law that existed at the moment of the offence. Options A, B, and D are all within the protection.', 'HARD', 'Polity', 'Fundamental Rights — Freedoms, Life & Liberty (Arts 19-22)', 'POL_FR_FREEDOMS', '[{"option_text": "Conviction for an act that was not an offence at the time it was committed", "is_correct": false}, {"option_text": "Imposing a penalty greater than what was prescribed at the time the act was committed", "is_correct": false}, {"option_text": "Applying a PROCEDURAL change retroactively (e.g. rules of evidence, trial procedure)", "is_correct": true}, {"option_text": "Imposing a BRAND-NEW retroactive criminal liability on conduct that was previously legal", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3335cac0-b5b5-5d68-aaac-9bb54b2c87da', 'Article 19(2) permits ''reasonable restrictions'' on the freedom of speech and expression. Which of the following grounds is NOT enumerated in Article 19(2)?', NULL, 'Article 19(2) enumerates EIGHT grounds for reasonable restrictions on speech: (1) sovereignty and integrity of India, (2) security of the State, (3) friendly relations with foreign States, (4) public order, (5) decency or morality, (6) contempt of court, (7) defamation, (8) incitement to an offence. ''Scientific accuracy'' is NOT among them — and has never been a constitutional ground to restrict speech. The ''sovereignty and integrity'' ground was added by the 16th Amendment 1963 in the wake of the China war and secessionist movements.', 'MEDIUM', 'Polity', 'Fundamental Rights — Freedoms, Life & Liberty (Arts 19-22)', 'POL_FR_FREEDOMS', '[{"option_text": "Security of the State", "is_correct": false}, {"option_text": "Contempt of court", "is_correct": false}, {"option_text": "Scientific accuracy", "is_correct": true}, {"option_text": "Defamation", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d58bf91c-3303-52f1-b813-d8c750fb72f1', 'The safeguards in Article 22 distinguish between ''punitive'' and ''preventive'' detention. Which of the following safeguards applies to PUNITIVE detention (arrest under ordinary criminal law) but NOT to preventive detention?', NULL, 'Article 22(1)-(2) lays safeguards for PUNITIVE (criminal) arrests: right to be informed of grounds of arrest, right to consult a lawyer of one''s choice, AND right to be produced before a magistrate within 24 hours (excluding travel time). These do NOT apply to preventive detention — Article 22(3) explicitly excludes preventive detention from 22(1)-(2). Preventive detention gets its own safeguards under 22(4)-(7): Advisory Board for detention beyond 3 months, maximum period fixed by Parliament, grounds to be communicated (but confidential grounds may be withheld in the public interest).', 'HARD', 'Polity', 'Fundamental Rights — Freedoms, Life & Liberty (Arts 19-22)', 'POL_FR_FREEDOMS', '[{"option_text": "Right to be informed of grounds of arrest", "is_correct": false}, {"option_text": "Right to be produced before a magistrate within 24 hours", "is_correct": true}, {"option_text": "Right against double jeopardy", "is_correct": false}, {"option_text": "Right to freedom of movement", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9abe678d-538b-5c8a-bf31-f5c23fa3e0f7', 'The ''double jeopardy'' clause under Article 20(2) — ''no person shall be prosecuted and punished for the same offence more than once'' — is NARROWER than the American Fifth Amendment version. The key narrowness is that Article 20(2) applies ONLY when:', NULL, 'Article 20(2) requires BOTH: (i) the earlier proceeding was before a court of competent jurisdiction (quasi-judicial bodies, departmental enquiries don''t count); and (ii) the earlier proceeding resulted in conviction AND punishment — a mere acquittal (without the accused having been ''punished'') does NOT trigger the bar. Contrast with the US Fifth Amendment which bars RE-TRIAL after acquittal too. The Supreme Court confirmed this narrow reading in Maqbool Hussain v. State of Bombay (1953) — customs confiscation followed by criminal trial was permissible since customs was administrative, not judicial.', 'HARD', 'Polity', 'Fundamental Rights — Freedoms, Life & Liberty (Arts 19-22)', 'POL_FR_FREEDOMS', '[{"option_text": "The previous proceeding was before a competent court AND resulted in either conviction OR acquittal with punishment", "is_correct": true}, {"option_text": "Even a mere departmental enquiry has concluded, regardless of outcome", "is_correct": false}, {"option_text": "The previous proceeding was only civil in nature", "is_correct": false}, {"option_text": "The accused was merely summoned without trial", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('77f06a64-f99e-52f8-bf92-c7d685db4ead', 'Which Article of the Constitution protects a person against the law that makes an act punishable that was legal at the time it was committed?', NULL, 'Article 20(1): ''No person shall be convicted of any offence except for violation of a law IN FORCE at the time of the commission of the Act charged as an offence, nor be subjected to a penalty greater than that which might have been inflicted under the law in force at the time of the commission of the offence.'' This is the ex-post-facto protection. 20(2) is double jeopardy; 21 is life/liberty; 22 deals with arrest/detention. All four articles fall in the same constitutional neighbourhood — hence the common exam trap of confusing them.', 'EASY', 'Polity', 'Fundamental Rights — Freedoms, Life & Liberty (Arts 19-22)', 'POL_FR_FREEDOMS', '[{"option_text": "Article 20(1)", "is_correct": true}, {"option_text": "Article 20(2)", "is_correct": false}, {"option_text": "Article 21", "is_correct": false}, {"option_text": "Article 22", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7276787c-de8f-561d-a512-9ab5626d1eab', 'Article 19(1)(g) grants the freedom to practise any profession or carry on any occupation, trade, or business. The ''reasonable restrictions'' permitted under Article 19(6) include:', NULL, 'Article 19(6) explicitly permits TWO categories of restriction: (i) laws requiring professional or technical qualifications for carrying on an occupation/trade (e.g. Medical Council requirements, Bar Council rules, Chartered Accountant regulations); (ii) laws allowing the State to carry on any trade, business, industry, or service — wholly or partly — TO THE EXCLUSION of citizens (this is the ''State monopoly'' provision, used for things like the Indian Posts, certain nationalised industries). Public order is a 19(2) ground for speech restrictions, not a dominant 19(6) ground. Option D would violate Article 300A (right to property as a legal right).', 'MEDIUM', 'Polity', 'Fundamental Rights — Freedoms, Life & Liberty (Arts 19-22)', 'POL_FR_FREEDOMS', '[{"option_text": "Only restrictions imposed in the interest of public order", "is_correct": false}, {"option_text": "Prescribing professional/technical qualifications AND carrying on business by the State to the exclusion of citizens", "is_correct": true}, {"option_text": "Restrictions only against non-citizens", "is_correct": false}, {"option_text": "Complete nationalisation of private property without compensation", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('29bd480c-9d0a-5a9f-b2a5-fc88cb86bd0c', 'The Supreme Court in SELVI v. State of Karnataka (2010) ruled that which investigative techniques — when administered WITHOUT consent of the accused — violate Article 20(3) and Article 21?', NULL, 'In Selvi (2010), a 3-judge bench of the Supreme Court (Balakrishnan CJ, Ganguly, Kapadia JJ) held that INVOLUNTARY administration of narco-analysis, polygraph, and Brain Electrical Activation Profile (BEAP/brain-mapping) tests violates Article 20(3) (self-incrimination), Article 21 (personal liberty, mental privacy), and general standards of ''substantive due process''. HOWEVER, with free and voluntary informed consent, these tests may be used — the RESULTS aren''t admissible as direct evidence but may be used for investigation leads. Fingerprinting (option A) is permissible (physical evidence per Kathi Kalu Oghad). Options C and D describe ordinary criminal procedure — unrelated.', 'HARD', 'Polity', 'Fundamental Rights — Freedoms, Life & Liberty (Arts 19-22)', 'POL_FR_FREEDOMS', '[{"option_text": "Fingerprinting and DNA sampling", "is_correct": false}, {"option_text": "Narco-analysis, polygraph, and brain-mapping (BEAP) tests", "is_correct": true}, {"option_text": "Interrogation by a magistrate after arrest", "is_correct": false}, {"option_text": "Search of personal belongings with a warrant", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b193015d-6780-594d-8299-3cf1003ccac2', 'Which Article of the Constitution provides for the establishment of a High Court for each State?', NULL, 'Article 214: ''There shall be a High Court for each State.'' Article 124 deals with the Supreme Court. Article 226 grants HCs power to issue writs. Article 241 provides for HCs in Union Territories. Parliament can, under Article 231, establish a common HC for two or more states (e.g., Punjab & Haryana HC at Chandigarh).', 'EASY', 'Polity', 'High Courts', 'POL_HC', '[{"option_text": "Article 124", "is_correct": false}, {"option_text": "Article 214", "is_correct": true}, {"option_text": "Article 226", "is_correct": false}, {"option_text": "Article 241", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4c06adcd-f2b6-507a-8cf0-9874d41a9bff', 'What is the retirement age for a judge of the High Court in India?', NULL, 'Article 217(1): HC judges retire at 62 years (originally 60; raised to 62 by the 15th Amendment, 1963). SUPREME COURT judges retire at 65 (Article 124). A key difference to remember: HC=62, SC=65. The CAG also retires at 65. These retirement ages are CONSTITUTIONAL and cannot be changed except by constitutional amendment.', 'EASY', 'Polity', 'High Courts', 'POL_HC', '[{"option_text": "60 years", "is_correct": false}, {"option_text": "62 years", "is_correct": true}, {"option_text": "65 years", "is_correct": false}, {"option_text": "70 years", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('23a2570e-f905-5c4b-a83d-f0869acb61a2', 'Who appoints the Chief Justice of a High Court?', NULL, 'Article 217(1): High Court judges (including the Chief Justice) are appointed by the PRESIDENT by warrant under his hand and seal, after consultation with the Chief Justice of India, the Governor of the State, and (for other judges) the Chief Justice of that HC. Per the Second & Third Judges Cases (SC), the CJI''s ''consultation'' is effectively CONCURRENCE via the COLLEGIUM (CJI + 4 senior-most SC judges). The government proposed to replace this with the NJAC in 2014, but the SC struck down the NJAC Act in 2015.', 'MEDIUM', 'Polity', 'High Courts', 'POL_HC', '[{"option_text": "The Governor of the State", "is_correct": false}, {"option_text": "The Chief Minister of the State in consultation with the Governor", "is_correct": false}, {"option_text": "The President of India, in consultation with the CJI and the Governor", "is_correct": true}, {"option_text": "The Chief Justice of India alone, based on seniority", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('dbdb30ea-24e7-573e-88d4-01a1fe2db793', 'Which of the following is NOT a type of writ that a High Court can issue under Article 226?', NULL, 'Article 226 empowers HCs to issue FIVE types of writs: (1) HABEAS CORPUS — ''produce the body'' (illegal detention); (2) MANDAMUS — ''we command'' (direct public authority to perform duty); (3) PROHIBITION — prevent lower court/tribunal from exceeding jurisdiction; (4) CERTIORARI — quash lower court/tribunal order; (5) QUO WARRANTO — ''by what authority'' (challenge a person''s right to hold office). ''Summary judgment'' is a civil-procedure concept (Order 37 CPC), NOT a constitutional writ.', 'MEDIUM', 'Polity', 'High Courts', 'POL_HC', '[{"option_text": "Habeas Corpus", "is_correct": false}, {"option_text": "Mandamus", "is_correct": false}, {"option_text": "Quo Warranto", "is_correct": false}, {"option_text": "Summary judgment", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d8b876ae-c0d9-58fe-9cc3-f18cfe13b2f2', 'Which of the following is the oldest High Court in India?', NULL, 'CALCUTTA HIGH COURT was established on 2 July 1862 under the Indian High Courts Act 1861 — making it the oldest HC in India. Bombay HC was established on 14 August 1862 (same year, 6 weeks later). Madras HC on 15 August 1862. Allahabad HC came later (1866). These three — Calcutta, Bombay, Madras — are the original ''Chartered High Courts'' of British India.', 'MEDIUM', 'Polity', 'High Courts', 'POL_HC', '[{"option_text": "Bombay High Court", "is_correct": false}, {"option_text": "Calcutta High Court", "is_correct": true}, {"option_text": "Madras High Court", "is_correct": false}, {"option_text": "Allahabad High Court", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5070c4ac-fe1a-5c63-a01c-54d1f61377e1', 'As of 2024, how many High Courts are there in India?', NULL, 'India has 25 High Courts (as of 2024). The most recent additions: (1) Telangana HC separated from the common Andhra Pradesh HC in 2019; (2) common HC for Assam, Nagaland, Mizoram, and Arunachal Pradesh is the ''Gauhati HC'' (so four NE states share one HC). Other groupings: Punjab & Haryana (at Chandigarh); HC of J&K and Ladakh (after 2019 reorganisation). The number ticks up as states split or reorganise.', 'MEDIUM', 'Polity', 'High Courts', 'POL_HC', '[{"option_text": "21", "is_correct": false}, {"option_text": "25", "is_correct": true}, {"option_text": "28", "is_correct": false}, {"option_text": "29", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e32e8126-37fe-5370-913f-eed4c66da65c', 'The jurisdiction of a High Court under Article 226 to issue writs extends to:', NULL, 'Article 226 is BROADER than Article 32 of the Supreme Court. While SC''s writ jurisdiction under Art 32 is limited to enforcing FUNDAMENTAL RIGHTS, the HC under Art 226 can issue writs for: (1) enforcement of fundamental rights, AND (2) for any other purpose (e.g., statutory, common-law, or ordinary legal rights). This is why more cases go to HCs than directly to the SC under Art 32. HCs can also reach persons/authorities outside their territorial limits if the cause of action arose within.', 'HARD', 'Polity', 'High Courts', 'POL_HC', '[{"option_text": "Only to protect Fundamental Rights", "is_correct": false}, {"option_text": "To protect both Fundamental Rights AND for any other purpose", "is_correct": true}, {"option_text": "Only against State authorities", "is_correct": false}, {"option_text": "Only within the territorial boundaries of the State", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8a491c50-cb15-5f1d-9648-497bd50d4a03', 'Judges of a High Court can be transferred from one HC to another under which Article?', NULL, 'Article 222(1): The PRESIDENT may, after consultation with the Chief Justice of India, TRANSFER a Judge from one High Court to any other High Court. In the Third Judges case (1998), the SC held that the CJI''s opinion is based on the collegium''s consensus, and the judge is entitled to a statement of reasons. A transferred judge retains his seniority but has to re-take oath in the new HC. Article 217 deals with APPOINTMENT.', 'MEDIUM', 'Polity', 'High Courts', 'POL_HC', '[{"option_text": "Article 124", "is_correct": false}, {"option_text": "Article 217", "is_correct": false}, {"option_text": "Article 222", "is_correct": true}, {"option_text": "Article 124A", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f5e1111a-f983-5b67-b633-a14cc940c57a', 'On what date was NITI Aayog established, replacing the Planning Commission?', NULL, 'The NITI (National Institution for Transforming India) Aayog was established on 1 January 2015 via a Union Cabinet resolution, replacing the 65-year-old Planning Commission (1950–2014). Unlike the Planning Commission, NITI Aayog was created NOT by an Act of Parliament — it is an executive body, making it easier to restructure but also legally weaker.', 'EASY', 'Polity', 'NITI Aayog & Non-Constitutional Bodies', 'POL_NITI', '[{"option_text": "15 August 2014", "is_correct": false}, {"option_text": "1 January 2015", "is_correct": true}, {"option_text": "26 January 2015", "is_correct": false}, {"option_text": "1 April 2015", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c76d3cb3-a6e2-51ed-ae77-dfa564e8f086', 'Which of the following is NOT a component of NITI Aayog''s structure?', NULL, 'NITI Aayog''s structure: (1) Chairperson — PM; (2) Vice Chairperson — appointed by PM; (3) Full-time members; (4) Part-time members (max 2, from universities/research bodies); (5) Ex-officio members (max 4 Union Ministers); (6) Governing Council — CMs + LGs; (7) Regional Councils — for specific issues; (8) Special Invitees — experts nominated by PM; (9) CEO — Secretary-rank officer. There is NO legislative or elected component — it''s wholly executive.', 'MEDIUM', 'Polity', 'NITI Aayog & Non-Constitutional Bodies', 'POL_NITI', '[{"option_text": "Chairperson (Prime Minister)", "is_correct": false}, {"option_text": "Governing Council (Chief Ministers of States + Lt Governors of UTs)", "is_correct": false}, {"option_text": "Regional Councils (for specific cross-State issues)", "is_correct": false}, {"option_text": "Legislative Council (elected by State Legislatures)", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d71430a9-289d-5fcf-8d0f-a8d9e21df461', 'Which of the following distinguishes NITI Aayog from the erstwhile Planning Commission?', NULL, 'The biggest functional difference: the Planning Commission (1950–2014) had discretionary power to allocate central funds to States under Plan schemes. NITI Aayog explicitly has NO allocation powers — it is a think-tank, advising the Finance Ministry & the Cabinet. This removed a key source of Centre-State bargaining leverage from the Planning Commission era. Neither body was/is constitutional; both are executive creations. The PM chairs both.', 'HARD', 'Polity', 'NITI Aayog & Non-Constitutional Bodies', 'POL_NITI', '[{"option_text": "NITI Aayog has financial/budgetary allocation powers; Planning Commission did not", "is_correct": false}, {"option_text": "NITI Aayog is a ''think tank'' WITHOUT fund-allocation powers; Planning Commission had fund-allocation powers", "is_correct": true}, {"option_text": "NITI Aayog is a constitutional body; Planning Commission was statutory", "is_correct": false}, {"option_text": "NITI Aayog''s Chairman is elected by Parliament; Planning Commission''s was appointed by the President", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3c6f4147-27d6-5e9f-83a6-86f54bd7969c', 'Who was the first Vice-Chairperson of NITI Aayog?', NULL, 'Arvind Panagariya (economist, Columbia University) was the first Vice-Chairperson of NITI Aayog (January 2015 – August 2017). He was succeeded by Rajiv Kumar (2017–22), and then Suman Bery (2022–present). Amitabh Kant served as CEO of NITI Aayog, NOT as Vice-Chairperson.', 'HARD', 'Polity', 'NITI Aayog & Non-Constitutional Bodies', 'POL_NITI', '[{"option_text": "Rajiv Kumar", "is_correct": false}, {"option_text": "Arvind Panagariya", "is_correct": true}, {"option_text": "Suman Bery", "is_correct": false}, {"option_text": "Amitabh Kant", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ea3b7405-7c8f-5c2a-b23a-fa2dde9e6ca1', 'Which of the following indices is NOT published by NITI Aayog?', NULL, 'NITI Aayog publishes several ranking reports: SDG India Index, MPI-India, Health Index, School Education Quality Index, Composite Water Management Index, India Innovation Index, Export Preparedness Index. The Ease of Doing Business Index is published by the World Bank (it was discontinued in 2021, replaced by the B-READY project) — not NITI Aayog. Though NITI has a role in popularising DBR rankings domestically via DPIIT''s Business Reform Action Plan.', 'HARD', 'Polity', 'NITI Aayog & Non-Constitutional Bodies', 'POL_NITI', '[{"option_text": "SDG India Index", "is_correct": false}, {"option_text": "Multidimensional Poverty Index (MPI) - India", "is_correct": false}, {"option_text": "Health Index (State/UT ranking on health outcomes)", "is_correct": false}, {"option_text": "World Bank''s Ease of Doing Business Index", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ff5e9050-be77-5880-8adb-8327637100cf', 'Which among the following is a Constitutional Body and NOT a non-Constitutional/Statutory body?', NULL, 'The Finance Commission is a CONSTITUTIONAL body — Article 280. NITI Aayog is non-constitutional, non-statutory (executive resolution only). CBI is non-constitutional; it is based on the Delhi Special Police Establishment Act, 1946 — so it''s a STATUTORY body. NHRC is a STATUTORY body under the Protection of Human Rights Act, 1993. Important categorisation for exams.', 'MEDIUM', 'Polity', 'NITI Aayog & Non-Constitutional Bodies', 'POL_NITI', '[{"option_text": "NITI Aayog", "is_correct": false}, {"option_text": "CBI (Central Bureau of Investigation)", "is_correct": false}, {"option_text": "Finance Commission", "is_correct": true}, {"option_text": "NHRC (National Human Rights Commission)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0cb721db-5501-5300-a0ab-ae20ccb6d445', 'Which of the following bodies was part of the Planning Commission''s structure but has NOT been carried over to NITI Aayog?', NULL, 'The National Development Council (NDC), chaired by the PM and including all CMs, was the highest body reviewing Five-Year Plans under the Planning Commission. NDC was NOT formally abolished, but it has been effectively replaced by NITI Aayog''s Governing Council. The PEO continues under NITI''s Development Monitoring & Evaluation Office. IAMR was renamed as NILERD (National Institute of Labour Economics Research & Development) in 2014 and continues.', 'HARD', 'Polity', 'NITI Aayog & Non-Constitutional Bodies', 'POL_NITI', '[{"option_text": "Programme Evaluation Organisation (PEO) — evaluates central schemes", "is_correct": false}, {"option_text": "National Development Council (NDC)", "is_correct": true}, {"option_text": "Institute of Applied Manpower Research (IAMR)", "is_correct": false}, {"option_text": "The Planning Commission office in Yojana Bhavan (now NITI Bhawan)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fb7fd246-c93f-539e-b5e0-2896ab0650f7', 'The ''Aspirational Districts Programme'' is run by which of the following bodies?', NULL, 'The Aspirational Districts Programme (ADP), launched in January 2018, is coordinated by NITI Aayog. It ranks 112 of India''s most-backward districts on 49 KPIs across 5 sectors (Health & Nutrition, Education, Agriculture, Financial Inclusion & Skill Dev., Basic Infrastructure) and incentivises improvement. It is one of NITI Aayog''s flagship governance initiatives. The Ministry of Rural Development''s flagship is MGNREGA, not ADP.', 'MEDIUM', 'Polity', 'NITI Aayog & Non-Constitutional Bodies', 'POL_NITI', '[{"option_text": "Ministry of Rural Development", "is_correct": false}, {"option_text": "NITI Aayog", "is_correct": true}, {"option_text": "Finance Ministry''s Department of Expenditure", "is_correct": false}, {"option_text": "Ministry of Home Affairs", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6da58a5c-c43b-5910-8c2f-3815041ca721', 'Which of the following is a STATUTORY (not constitutional) body?', NULL, 'SEBI was set up in 1988 as an administrative body; it became a STATUTORY body with the SEBI Act, 1992. UPSC (Article 315), CAG (Article 148), and ECI (Article 324) are all CONSTITUTIONAL bodies. Distinguishing statutory vs. constitutional is a common exam trap — statutory bodies are created by an Act of Parliament; constitutional bodies are named in the Constitution itself.', 'MEDIUM', 'Polity', 'NITI Aayog & Non-Constitutional Bodies', 'POL_NITI', '[{"option_text": "Union Public Service Commission (UPSC)", "is_correct": false}, {"option_text": "Securities and Exchange Board of India (SEBI)", "is_correct": true}, {"option_text": "Comptroller and Auditor General", "is_correct": false}, {"option_text": "Election Commission of India", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7adf3a8f-fb19-5054-bd16-70bcfec3caa5', 'Consider the following statements about NITI Aayog''s Governing Council: 1) It is the apex body of NITI Aayog. 2) All Chief Ministers + Lieutenant Governors of Union Territories with legislatures are members. 3) The Finance Minister of the Union is an ex-officio member. Which of the above is/are correct?', NULL, 'Statement 1 CORRECT — the Governing Council IS the apex body of NITI Aayog. Statement 2 CORRECT — all CMs of States + LGs of UTs are members (UTs WITHOUT legislatures are represented by Administrators, but the classic composition is CMs + LGs). Statement 3 WRONG — Union Ministers are ex-officio members of NITI Aayog (not specifically the Governing Council in this way); the PM chairs the Governing Council with CMs/LGs as its members; Union Ministers attend as special invitees.', 'HARD', 'Polity', 'NITI Aayog & Non-Constitutional Bodies', 'POL_NITI', '[{"option_text": "1 only", "is_correct": false}, {"option_text": "1 and 2 only", "is_correct": true}, {"option_text": "2 and 3 only", "is_correct": false}, {"option_text": "1, 2 and 3", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('39c2f5b1-3b0a-542d-ac2b-af64b9953bcc', 'How many Schedules does the Indian Constitution contain as of the latest amendment, and which Amendment added the most recent one?', NULL, 'The Constitution originally had 8 Schedules. The 9th Schedule was added by the 1st Amendment (1951), the 10th by the 52nd Amendment (1985, anti-defection law), the 11th by the 73rd Amendment (1992, Panchayats), and the 12th — the most recent — by the 74th Amendment (1992, Municipalities). Option C confuses the 11th and 12th; option A stops short; option D cites the wrong amendment year.', 'MEDIUM', 'Polity', 'Schedules & Parts of Constitution', 'POL_SCHEDULES', '[{"option_text": "10 Schedules; the 10th added by the 52nd Amendment (1985)", "is_correct": false}, {"option_text": "12 Schedules; the 12th added by the 74th Amendment (1992)", "is_correct": true}, {"option_text": "11 Schedules; the 11th added by the 73rd Amendment (1992)", "is_correct": false}, {"option_text": "12 Schedules; the 12th added by the 86th Amendment (2002)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8eb308df-4e6e-578e-b0c8-eb79a7b96b9d', 'Which Schedule of the Indian Constitution distributes legislative subjects between the Union and the States, and how many lists does it contain?', NULL, 'The Seventh Schedule allocates legislative subjects across THREE lists: Union List (currently 97 subjects), State List (currently 59 subjects), and Concurrent List (52 subjects). The Sixth Schedule deals with tribal areas of Assam, Meghalaya, Tripura and Mizoram — unrelated. The Concurrent List was retained in the 1950 Constitution, so option C is wrong. The Eleventh Schedule lists 29 subjects of Panchayats, not Union-State distribution.', 'EASY', 'Polity', 'Schedules & Parts of Constitution', 'POL_SCHEDULES', '[{"option_text": "Sixth Schedule — 3 lists (Union, State, Concurrent)", "is_correct": false}, {"option_text": "Seventh Schedule — 3 lists (Union, State, Concurrent)", "is_correct": true}, {"option_text": "Seventh Schedule — 2 lists (Union, State only)", "is_correct": false}, {"option_text": "Eleventh Schedule — 3 lists (Union, State, Concurrent)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4f4cf56c-157b-5521-ae9d-02724acfcf4e', 'The Tenth Schedule of the Indian Constitution is commonly referred to as the:', NULL, 'The Tenth Schedule, inserted by the 52nd Amendment Act of 1985, contains provisions relating to disqualification of members of Parliament and State Legislatures on grounds of defection — hence the nickname ''Anti-Defection Law''. Language matters are in the Eighth Schedule; Panchayats are in the Eleventh; Union-State distribution is in the Seventh.', 'EASY', 'Polity', 'Schedules & Parts of Constitution', 'POL_SCHEDULES', '[{"option_text": "Anti-Defection Law Schedule", "is_correct": true}, {"option_text": "Language Schedule", "is_correct": false}, {"option_text": "Panchayati Raj Schedule", "is_correct": false}, {"option_text": "Union-State List Schedule", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e62d6851-19ca-5a81-90d0-97d4d26830d4', 'How many languages are currently recognised in the Eighth Schedule of the Indian Constitution, and which Amendment last added four languages — Bodo, Dogri, Maithili and Santhali?', NULL, 'Original Eighth Schedule had 14 languages. The 21st Amendment (1967) added Sindhi (→ 15). The 71st Amendment (1992) added Konkani, Manipuri and Nepali (→ 18). The 92nd Amendment (2003) added Bodo, Dogri, Maithili and Santhali, taking the total to 22. Option A conflates the amendments; option D overstates the current count.', 'MEDIUM', 'Polity', 'Schedules & Parts of Constitution', 'POL_SCHEDULES', '[{"option_text": "20 languages; added by the 71st Amendment (1992)", "is_correct": false}, {"option_text": "22 languages; added by the 92nd Amendment (2003)", "is_correct": true}, {"option_text": "22 languages; added by the 71st Amendment (1992)", "is_correct": false}, {"option_text": "24 languages; added by the 92nd Amendment (2003)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f13a2ae6-b49c-5a05-bffb-ad3b55b6a50f', 'Match the Schedule with its subject and select the correct pairing:
(i) Second Schedule — Salaries and emoluments of constitutional officials
(ii) Third Schedule — Oath forms for officeholders
(iii) Ninth Schedule — Acts protected from judicial review
(iv) Sixth Schedule — Centre-State distribution of powers', NULL, 'Pairings (i), (ii) and (iii) are CORRECT. The Second Schedule lists salaries/emoluments of the President, Governors, Speakers, Judges etc. The Third Schedule contains the oath/affirmation forms. The Ninth Schedule (added by 1st Amendment) shields laws from judicial review — though Kesavananda Bharati and I.R. Coelho limit this. Pairing (iv) is WRONG: Centre-State distribution is in the SEVENTH Schedule, not the Sixth. The Sixth deals with tribal areas in north-eastern states.', 'HARD', 'Polity', 'Schedules & Parts of Constitution', 'POL_SCHEDULES', '[{"option_text": "Only (i) and (ii) are correctly paired", "is_correct": false}, {"option_text": "Only (i), (ii) and (iii) are correctly paired", "is_correct": true}, {"option_text": "Only (iii) and (iv) are correctly paired", "is_correct": false}, {"option_text": "All four are correctly paired", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a7df950b-67df-58b4-b8b2-4828f52740de', 'Which of the following statements about Parts of the Indian Constitution is INCORRECT?', NULL, 'Statement C is INCORRECT. Fundamental Duties (Part IV-A, Article 51A) were inserted by the 42nd Amendment Act of 1976 based on the Swaran Singh Committee recommendations, NOT the 44th Amendment (the 44th, 1978, restored several pre-Emergency safeguards but didn''t add FDs). All other statements are correct: Part III covers FRs, Part IV covers DPSP, and Part IX-A (Municipalities) was inserted by the 74th Amendment (1992) alongside Part IX (Panchayats) via the 73rd.', 'HARD', 'Polity', 'Schedules & Parts of Constitution', 'POL_SCHEDULES', '[{"option_text": "Part III contains Fundamental Rights (Articles 12–35)", "is_correct": false}, {"option_text": "Part IV contains Directive Principles of State Policy (Articles 36–51)", "is_correct": false}, {"option_text": "Part IV-A — Fundamental Duties — was inserted by the 44th Amendment", "is_correct": true}, {"option_text": "Part IX-A dealing with Municipalities was added by the 74th Amendment", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('81c07714-2da2-5c69-9b6d-deb9e1f6abec', 'The Fifth Schedule of the Indian Constitution deals with the administration of:', NULL, 'The Fifth Schedule provides for the administration of Scheduled Areas and Scheduled Tribes in states OTHER THAN Assam, Meghalaya, Tripura and Mizoram — the latter four are governed by the Sixth Schedule''s autonomous-district-council model. States covered by the Fifth Schedule include Andhra Pradesh, Chhattisgarh, Gujarat, Himachal Pradesh, Jharkhand, Madhya Pradesh, Maharashtra, Odisha, Rajasthan and Telangana. Option B describes the Sixth Schedule, option C describes the Eleventh, option D describes the Second.', 'MEDIUM', 'Polity', 'Schedules & Parts of Constitution', 'POL_SCHEDULES', '[{"option_text": "Scheduled Areas and Scheduled Tribes in states OTHER than the north-eastern states covered by the Sixth Schedule", "is_correct": true}, {"option_text": "Tribal areas in Assam, Meghalaya, Tripura and Mizoram", "is_correct": false}, {"option_text": "Panchayati Raj Institutions across all states", "is_correct": false}, {"option_text": "Salaries of High Court judges", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ac05607c-a8b4-591e-84fe-51a008178022', 'Which Schedule originally contained provisions concerning the territories of the Indian Union, and what did the 7th Amendment (1956) change about it?', NULL, 'The First Schedule contains the names of States and Union Territories of India along with their territorial extent. Pre-1956, the Constitution classified states into Part A (former governors'' provinces), Part B (former princely states), Part C (chief-commissioner provinces) and Part D (other territories). The 7th Amendment Act 1956 — following the States Reorganisation Act — abolished this A/B/C/D classification and reorganised India into 14 States and 6 Union Territories (the current structure has since evolved to 28 States + 8 UTs). Option A describes the pre-1956 layout but mis-attributes the change. Options C and D describe different Schedules.', 'HARD', 'Polity', 'Schedules & Parts of Constitution', 'POL_SCHEDULES', '[{"option_text": "The First Schedule; the 7th Amendment reorganised states on linguistic lines into Part A, B, C, D states", "is_correct": false}, {"option_text": "The First Schedule; the 7th Amendment abolished the Part A/B/C/D classification and created the present States and Union Territories listing", "is_correct": true}, {"option_text": "The Fourth Schedule; the 7th Amendment re-allocated Rajya Sabha seats", "is_correct": false}, {"option_text": "The Second Schedule; the 7th Amendment changed salaries of governors", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('93f55f68-1a19-5276-82a5-481705076fd1', 'Under which Article of the Constitution is the office of the Vice-President of India established?', NULL, 'Article 63 states: ''There shall be a Vice-President of India.'' Article 61 deals with impeachment of the President; Article 65 lays down the VP''s role when the Presidency is vacant; Article 68 deals with the timing of elections to fill vacancies — all related but distinct articles.', 'EASY', 'Polity', 'Vice-President', 'POL_VP', '[{"option_text": "Article 61", "is_correct": false}, {"option_text": "Article 63", "is_correct": true}, {"option_text": "Article 65", "is_correct": false}, {"option_text": "Article 68", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5710aaf3-be2c-5eef-a99a-6e42b80a12e1', 'Who elects the Vice-President of India?', NULL, 'Article 66(1): The Vice-President is elected by an electoral college consisting of the members of BOTH Houses of Parliament — including both elected and nominated members. State legislators have no role. This is a narrower electoral college than the President''s (which includes State Legislative Assembly members). Nominated members of RS/LS DO vote in VP elections (unlike in Presidential elections where only elected members vote).', 'MEDIUM', 'Polity', 'Vice-President', 'POL_VP', '[{"option_text": "An electoral college consisting of elected members of both Houses of Parliament and elected members of State Legislative Assemblies", "is_correct": false}, {"option_text": "An electoral college consisting of members of both Houses of Parliament (both elected AND nominated)", "is_correct": true}, {"option_text": "Only the elected members of the Rajya Sabha", "is_correct": false}, {"option_text": "Direct election by universal adult franchise", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5aae22f5-d245-5df1-abd0-f14321a5f578', 'Which of the following methods is used to elect the Vice-President of India?', NULL, 'Per Article 66(1), the VP is elected by proportional representation with single transferable vote by secret ballot. The same system (STV) is used for the President (Article 55) — this ensures a broad consensus; a candidate must secure a quota of first + transferred preferences to win.', 'MEDIUM', 'Polity', 'Vice-President', 'POL_VP', '[{"option_text": "First-past-the-post in a single round", "is_correct": false}, {"option_text": "Proportional representation by means of the single transferable vote, with voting by secret ballot", "is_correct": true}, {"option_text": "Open voting by show of hands", "is_correct": false}, {"option_text": "Voice vote in a joint session of Parliament", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2e915b69-80ac-5c8a-9fc4-db3c675028d1', 'Which of the following is NOT a qualification for election as Vice-President of India?', NULL, 'Article 66(3) lays down four qualifications: (a) citizen of India; (b) at least 35 years; (c) qualified for election as RS member; (d) not holding any office of profit under Union/State/local authority. There is no requirement of ministerial experience. Note the contrast with the President — a Presidential candidate must be qualified for election to the LOK Sabha, not the RS.', 'MEDIUM', 'Polity', 'Vice-President', 'POL_VP', '[{"option_text": "Must be a citizen of India", "is_correct": false}, {"option_text": "Must have completed 35 years of age", "is_correct": false}, {"option_text": "Must be qualified for election as a member of the Rajya Sabha", "is_correct": false}, {"option_text": "Must have held Ministerial office for at least 5 years before becoming eligible", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cc5fe320-d25b-51c6-963c-2eef2b73219b', 'What is the term of office of the Vice-President of India?', NULL, 'Article 67: The VP holds office for a term of 5 years from the date he enters upon office. He is eligible for re-election any number of times. The tenure is NOT tied to the Lok Sabha. Note: 6 years is the term of Rajya Sabha members and CAG — a common distractor.', 'EASY', 'Polity', 'Vice-President', 'POL_VP', '[{"option_text": "4 years", "is_correct": false}, {"option_text": "5 years", "is_correct": true}, {"option_text": "6 years", "is_correct": false}, {"option_text": "Co-terminus with the Lok Sabha", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('25ead65a-e06e-5ae3-a172-4c456ae06811', 'The Vice-President of India is the ex-officio:', NULL, 'Article 64: The VP is the ex-officio Chairman of the Rajya Sabha. He presides over RS sittings, has a casting vote in case of a tie, and draws salary as Chairman of the RS. The Speaker of the LS is a separate elected position (Article 93). The Planning Commission was dissolved in 2014 and replaced by NITI Aayog (chaired by the PM, not the VP).', 'EASY', 'Polity', 'Vice-President', 'POL_VP', '[{"option_text": "Speaker of the Lok Sabha", "is_correct": false}, {"option_text": "Chairman of the Rajya Sabha", "is_correct": true}, {"option_text": "Chairman of the Inter-State Council", "is_correct": false}, {"option_text": "Chairman of the Planning Commission", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0f43c50f-58fc-548e-9e27-b8edf335c838', 'How is the Vice-President of India removed from office?', NULL, 'Article 67(b): The VP can be removed by a resolution of the Rajya Sabha passed by an EFFECTIVE MAJORITY (i.e., a majority of all the then members of the RS) AND agreed to by a simple majority in the Lok Sabha. A 14-day prior notice is required. This is LESS STRINGENT than Presidential impeachment (which requires a two-thirds majority in each House). The VP''s removal has never been invoked in practice.', 'HARD', 'Polity', 'Vice-President', 'POL_VP', '[{"option_text": "By impeachment, following the same procedure as the President", "is_correct": false}, {"option_text": "By a resolution of the Rajya Sabha passed by an effective majority and agreed to by the Lok Sabha", "is_correct": true}, {"option_text": "By the Supreme Court after a reference by the President", "is_correct": false}, {"option_text": "By the Electoral College that elected him, through a recall vote", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6f751b33-cfcd-597f-8557-79b53ee3be44', 'When the office of the President falls vacant due to death, resignation, removal, or otherwise, the Vice-President acts as President. What is the maximum period for which he can do so?', NULL, 'Article 65(1) + Article 62: When the Presidency falls vacant, the VP acts as President. An election to fill the vacancy must be held as soon as possible and, in any case, within 6 months of the vacancy. The VP''s acting tenure is thus capped at 6 months, after which a regularly elected President must take over. V. V. Giri acted as President after Zakir Hussain''s death in 1969 until his own election as President.', 'MEDIUM', 'Polity', 'Vice-President', 'POL_VP', '[{"option_text": "Until a new President is elected, but no more than 6 months", "is_correct": true}, {"option_text": "Until the next general election", "is_correct": false}, {"option_text": "1 year", "is_correct": false}, {"option_text": "Till the remainder of the original President''s term", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bb2eb02b-2667-53a8-abc2-25f728ea382f', 'Who was the first Vice-President of India?', NULL, 'Dr. Sarvepalli Radhakrishnan was the first Vice-President (1952–62) and later became the second President (1962–67). Dr. Rajendra Prasad was the first PRESIDENT, not VP — a classic confusion. Dr. Zakir Hussain was the second VP (1962–67) before becoming the third President. V. V. Giri was the fourth VP.', 'EASY', 'Polity', 'Vice-President', 'POL_VP', '[{"option_text": "Dr. Rajendra Prasad", "is_correct": false}, {"option_text": "Dr. S. Radhakrishnan", "is_correct": true}, {"option_text": "Dr. Zakir Hussain", "is_correct": false}, {"option_text": "V. V. Giri", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d666c5e5-1031-5a20-954d-09b55da800b6', 'Which of the following statements about the salary of the Vice-President is correct?', NULL, 'The Constitution (Article 97) provides the VP receives NO separate salary for being VP — he draws salary in his capacity as Chairman of the Rajya Sabha. This salary is charged on the Consolidated Fund of India (non-votable). This peculiar arrangement is because the VP has no executive duties of his own; his primary role is presiding over the RS.', 'HARD', 'Polity', 'Vice-President', 'POL_VP', '[{"option_text": "He draws a fixed salary as Vice-President that is charged on the Consolidated Fund of India", "is_correct": false}, {"option_text": "He draws no salary as Vice-President; he receives salary as Chairman of the Rajya Sabha, charged on the Consolidated Fund of India", "is_correct": true}, {"option_text": "He draws salary as Vice-President from the Contingency Fund of India", "is_correct": false}, {"option_text": "He draws salary partly from the Rajya Sabha and partly from the President''s fund", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a95879d6-bad5-51fe-a4b4-02580a0dd2f1', 'When the Vice-President is acting as President, who performs the duties of the Chairman of the Rajya Sabha?', NULL, 'Article 91: When the VP acts as or discharges the functions of the President, the Deputy Chairman of the Rajya Sabha (or, in his absence, any other member of the RS authorised by the President) performs the duties of the Chairman of the RS. The VP CANNOT simultaneously chair the RS while acting as President.', 'MEDIUM', 'Polity', 'Vice-President', 'POL_VP', '[{"option_text": "The Prime Minister, as Leader of the House", "is_correct": false}, {"option_text": "The Deputy Chairman of the Rajya Sabha", "is_correct": true}, {"option_text": "The Speaker of the Lok Sabha", "is_correct": false}, {"option_text": "A member elected by the Rajya Sabha for this purpose", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('563161f9-5435-5fed-a598-e53d189dd589', 'The oath of office to the Vice-President is administered by:', NULL, 'Article 69: The VP''s oath is administered by the President or some person appointed in that behalf by him. This is distinct from the President''s oath — which is administered by the Chief Justice of India (Article 60). Many students confuse the two; the CJI administers the oath of the President, NOT the Vice-President.', 'MEDIUM', 'Polity', 'Vice-President', 'POL_VP', '[{"option_text": "The Speaker of the Lok Sabha", "is_correct": false}, {"option_text": "The Chief Justice of India", "is_correct": false}, {"option_text": "The President of India (or in his absence, a person appointed in that behalf by him)", "is_correct": true}, {"option_text": "The Deputy Chairman of the Rajya Sabha", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('807870d0-5b6d-5fee-9886-fc3d25612ecd', 'If a dispute arises regarding the election of the Vice-President, to which body does the Constitution assign jurisdiction to decide it?', NULL, 'Article 71(1): All doubts and disputes arising out of or in connection with the election of the President or the Vice-President shall be inquired into and decided by the Supreme Court, whose decision is FINAL. The ECI conducts the election but doesn''t decide disputes. Note that even if the election is later declared void, acts done by the VP in the meantime are NOT invalidated (Article 71(2)).', 'MEDIUM', 'Polity', 'Vice-President', 'POL_VP', '[{"option_text": "The Election Commission of India", "is_correct": false}, {"option_text": "The President, after consultation with the Council of Ministers", "is_correct": false}, {"option_text": "The Supreme Court of India, with its decision being final", "is_correct": true}, {"option_text": "The joint sitting of Parliament", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b588a611-c455-5ed1-85cc-ad6eec34b64b', 'Which of the following is a difference between the election of the President and the Vice-President of India?', NULL, 'Key difference: The Presidential electoral college includes elected MPs + elected MLAs of State Assemblies (Article 54). The VP electoral college includes ONLY MPs (elected + nominated) of both Houses of Parliament — no MLAs (Article 66). Both use STV with secret ballot; both use proportional representation. Majority requirements are computed by quota, not by simple/two-thirds.', 'HARD', 'Polity', 'Vice-President', 'POL_VP', '[{"option_text": "Members of State Legislative Assemblies vote in the Presidential election but not in the Vice-Presidential election", "is_correct": true}, {"option_text": "The President is elected by secret ballot, but the VP is elected by open ballot", "is_correct": false}, {"option_text": "The VP is elected by a simple majority, the President by a two-thirds majority", "is_correct": false}, {"option_text": "Only the President''s election is held by proportional representation", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5ab0dfca-5622-5b1b-819b-c5d1f493a076', 'Which among the following Vice-Presidents did NOT go on to become the President of India?', NULL, 'Krishan Kant served as the 10th Vice-President (1997–2002) and died in office before being elevated. He is the only VP to die while in office. Dr. Radhakrishnan, Dr. Zakir Hussain, V. V. Giri, R. Venkataraman, Shankar Dayal Sharma, and K. R. Narayanan all went on to become President. Seven of India''s first thirteen Presidents were previously VPs — making this a historical pattern the question tests.', 'HARD', 'Polity', 'Vice-President', 'POL_VP', '[{"option_text": "Dr. S. Radhakrishnan", "is_correct": false}, {"option_text": "Dr. Zakir Hussain", "is_correct": false}, {"option_text": "Krishan Kant", "is_correct": true}, {"option_text": "R. Venkataraman", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
